import { defineStore } from "pinia";
import { pinia } from "../../../state/pinia";
import { computed, ref } from "vue";
import { createEffectBuilderDraft } from "../functions/catalogue";
import { validateEffectDraft } from "../functions/build";
import type { EffectBuilderBridge, EffectBuilderKind } from "../../../../types/effect-builders";
import type { GrantItemReference } from "../../../../types/item-grants";

export function useEffectBuilderStore(id: string) {
  return defineStore(`effect-builder:${id}`, () => {
    const draft = ref(createEffectBuilderDraft("wounds"));
    const destination = ref<GrantItemReference | null>(null);
    const error = ref("");
    const message = ref("");
    const busy = ref(false);
    const created = ref(false);
    const initialized = ref(false);
    let bridge: EffectBuilderBridge;
    const problems = computed(() => validateEffectDraft(draft.value));
    const ready = computed(
      () => Boolean(destination.value) && !problems.value.length && !busy.value && !created.value,
    );

    function configure(
      kind: EffectBuilderKind,
      value: EffectBuilderBridge,
      initial: GrantItemReference | null,
    ): void {
      bridge = value;
      if (initialized.value) return;
      draft.value = createEffectBuilderDraft(kind);
      destination.value = initial;
      initialized.value = true;
    }

    async function attempt(action: () => Promise<void>): Promise<void> {
      if (busy.value || created.value) return;
      error.value = "";
      busy.value = true;
      try {
        await action();
      } catch (cause) {
        error.value = cause instanceof Error ? cause.message : String(cause);
      } finally {
        busy.value = false;
      }
    }

    async function dropDestination(data: string): Promise<void> {
      await attempt(async () => {
        destination.value = await bridge.resolveItem(data, true);
      });
    }
    async function dropItem(data: string, group?: number): Promise<void> {
      await attempt(async () => {
        const item = await bridge.resolveItem(data);
        if (item.uuid === destination.value?.uuid) throw new Error("An Item cannot grant itself.");
        const items = group === undefined ? draft.value.items : draft.value.groups[group]!.items;
        if (items.some((entry) => entry.uuid === item.uuid))
          throw new Error("That Item is already in this option.");
        items.push(item);
      });
    }
    async function dropTable(data: string): Promise<void> {
      await attempt(async () => {
        draft.value.table = await bridge.resolveTable(data);
      });
    }
    function addGroup(): void {
      draft.value.groups.push({ name: `Option ${draft.value.groups.length + 1}`, items: [] });
    }
    function removeItem(uuid: string, group?: number): void {
      const items = group === undefined ? draft.value.items : draft.value.groups[group]!.items;
      const index = items.findIndex((item) => item.uuid === uuid);
      if (index !== -1) items.splice(index, 1);
    }
    function setLifetime(value: "detached" | "linked-to-effect"): void {
      draft.value.recipe.lifetime = value;
      if (value === "linked-to-effect") draft.value.recipe.ownerAction = "keep";
    }
    async function create(): Promise<void> {
      if (!ready.value) return;
      await attempt(async () => {
        await bridge.create(destination.value!.uuid, JSON.parse(JSON.stringify(draft.value)));
        created.value = true;
        message.value = `Added “${draft.value.name.trim()}” to ${destination.value!.name}.`;
      });
    }
    async function openDestination(): Promise<void> {
      if (!destination.value) return;
      try {
        await bridge.openItem(destination.value.uuid);
      } catch (cause) {
        error.value = cause instanceof Error ? cause.message : String(cause);
      }
    }
    return {
      draft,
      destination,
      error,
      message,
      busy,
      created,
      problems,
      ready,
      configure,
      dropDestination,
      dropItem,
      dropTable,
      addGroup,
      removeItem,
      setLifetime,
      create,
      openDestination,
    };
  })(pinia);
}
