import { defineStore } from "pinia";
import { computed, ref } from "vue";
import { pinia } from "../../../state/pinia";
import {
  createEmptySpeciesTableDraft,
  summarizeSpeciesTableRows,
} from "../../../functions/species-table/source";
import { addSpeciesTableDrop, speciesTableProblems } from "../functions/draft";
import type {
  SpeciesTableBridge,
  SpeciesTableDraft,
  SpeciesTableOption,
  SpeciesTableState,
} from "../../../../types/species/table";

export function useSpeciesTableStore(id: string) {
  return defineStore(`species-table:${id}`, () => {
    const draft = ref<SpeciesTableDraft>({ ...createEmptySpeciesTableDraft(), rows: [] });
    const options = ref<SpeciesTableOption[]>([]);
    const revision = ref("");
    const busy = ref(false);
    const loaded = ref(false);
    const error = ref("");
    const message = ref("");
    const register = ref(true);
    const selected = ref("");
    let bridge: SpeciesTableBridge;
    const problems = computed(() => speciesTableProblems(draft.value, options.value));
    const summaries = computed(() => summarizeSpeciesTableRows(draft.value.rows));
    const total = computed(() =>
      draft.value.rows.reduce((sum, row) => sum + Number(row.weight || 0), 0),
    );
    const available = computed(() =>
      options.value.filter(
        (option) => !draft.value.rows.some((row) => row.speciesKey === option.key),
      ),
    );
    const ready = computed(() => loaded.value && !busy.value && !problems.value.length);

    function configure(value: SpeciesTableBridge): void {
      bridge = value;
    }
    function accept(state: SpeciesTableState): void {
      draft.value = state.draft;
      options.value = state.options;
      revision.value = state.revision;
      loaded.value = true;
      selected.value = "";
    }
    async function attempt(action: () => Promise<void>): Promise<void> {
      if (busy.value) return;
      busy.value = true;
      error.value = "";
      message.value = "";
      try {
        await action();
      } catch (cause) {
        error.value = cause instanceof Error ? cause.message : String(cause);
      } finally {
        busy.value = false;
      }
    }
    async function load(): Promise<void> {
      await attempt(async () => {
        accept(await bridge.load());
      });
    }
    async function drop(data: string): Promise<void> {
      if (!loaded.value) return;
      await attempt(async () => {
        const result = await bridge.resolveDrop(data);
        addSpeciesTableDrop(draft.value, result);
        const existing = options.value.findIndex((option) => option.key === result.option.key);
        if (existing === -1) options.value.push(result.option);
        else options.value[existing] = result.option;
        message.value = result.message;
      });
    }
    async function addSelected(): Promise<void> {
      const option = options.value.find((entry) => entry.key === selected.value);
      if (!option) return;
      if (option.itemUuid) await drop(JSON.stringify({ uuid: option.itemUuid }));
      else addSpeciesTableDrop(draft.value, { option, sources: [], message: "" });
      selected.value = "";
    }
    function remove(index: number): void {
      draft.value.rows.splice(index, 1);
      message.value = "";
    }
    async function save(): Promise<void> {
      if (!ready.value) return;
      await attempt(async () => {
        const result = await bridge.save(
          JSON.parse(JSON.stringify(draft.value)),
          revision.value,
          register.value,
        );
        accept(result);
        error.value = result.registrationError
          ? `Table saved, but WFRP registration failed: ${result.registrationError} Save again to retry.`
          : "";
        message.value = result.draft.isRegistered
          ? "Saved the world's Species table."
          : "Saved the Species table.";
      });
    }
    return {
      draft,
      options,
      busy,
      loaded,
      error,
      message,
      register,
      selected,
      problems,
      summaries,
      total,
      available,
      ready,
      configure,
      load,
      drop,
      addSelected,
      remove,
      save,
    };
  })(pinia);
}
