import type { Ref } from "vue";

import type {
  NpcBaseActorDraftData,
  NpcBaseActorSummary,
  NpcBuilderSettings,
  NpcFolderSummary,
  NpcQuickTraitSummary,
  NpcTraitDraftConfig,
  NpcTrappingResolution,
} from "../../../../types/npc-builder";

interface HydrationStoreSliceContext {
  actorFolders: Ref<NpcFolderSummary[]>;
  baseActorDraftData: Ref<NpcBaseActorDraftData>;
  baseActors: Ref<NpcBaseActorSummary[]>;
  ignoredBaseTraitKeys: Ref<Record<string, boolean>>;
  itemFolders: Ref<NpcFolderSummary[]>;
  manualAdvancementDeltas: Ref<Record<string, number>>;
  quickTraits: Ref<NpcQuickTraitSummary[]>;
  selectedBaseActorUuid: Ref<string>;
  settings: Ref<NpcBuilderSettings>;
  traitConfigOverrides: Ref<Record<string, Partial<NpcTraitDraftConfig>>>;
  trappingOverrides: Ref<Record<string, { ignored?: boolean; quantity?: number }>>;
  trappingResolutionOverrides: Ref<Record<string, NpcTrappingResolution>>;
}

export function createHydrationStoreSlice(context: HydrationStoreSliceContext) {
  const {
    actorFolders,
    baseActorDraftData,
    baseActors,
    ignoredBaseTraitKeys,
    itemFolders,
    manualAdvancementDeltas,
    quickTraits,
    selectedBaseActorUuid,
    settings,
    traitConfigOverrides,
    trappingOverrides,
    trappingResolutionOverrides,
  } = context;

  function clearBaseDraftData(): void {
    baseActorDraftData.value = {
      advancements: [],
      optionalTraits: [],
      traits: [],
      trappings: [],
    };
    manualAdvancementDeltas.value = {};
    ignoredBaseTraitKeys.value = {};
    traitConfigOverrides.value = {};
    trappingOverrides.value = {};
    trappingResolutionOverrides.value = {};
  }

  function hydrateBaseActorDraftData(data: NpcBaseActorDraftData): void {
    baseActorDraftData.value = {
      advancements: [...data.advancements],
      optionalTraits: [...data.optionalTraits],
      traits: [...data.traits],
      trappings: [...data.trappings],
    };
    manualAdvancementDeltas.value = {};
    ignoredBaseTraitKeys.value = {};
    traitConfigOverrides.value = {};
    trappingOverrides.value = {};
  }

  function hydrateBaseActors(actors: NpcBaseActorSummary[]): void {
    baseActors.value = [...actors].sort((left, right) => left.name.localeCompare(right.name));

    if (
      selectedBaseActorUuid.value &&
      !baseActors.value.some((actor) => actor.uuid === selectedBaseActorUuid.value)
    ) {
      selectedBaseActorUuid.value = "";
      clearBaseDraftData();
    }
  }

  function hydrateSettings(nextSettings: NpcBuilderSettings): void {
    settings.value = { ...nextSettings };
  }

  function hydrateActorFolders(folders: NpcFolderSummary[]): void {
    actorFolders.value = [...folders].sort((left, right) => left.name.localeCompare(right.name));

    if (
      settings.value.baseActorFolderUuid &&
      !actorFolders.value.some((folder) => folder.uuid === settings.value.baseActorFolderUuid)
    ) {
      settings.value.baseActorFolderUuid = "";
    }

    if (
      settings.value.outputActorFolderUuid &&
      !actorFolders.value.some((folder) => folder.uuid === settings.value.outputActorFolderUuid)
    ) {
      settings.value.outputActorFolderUuid = "";
    }
  }

  function hydrateItemFolders(folders: NpcFolderSummary[]): void {
    itemFolders.value = [...folders].sort((left, right) => left.name.localeCompare(right.name));

    if (
      settings.value.quickTraitFolderUuid &&
      !itemFolders.value.some((folder) => folder.uuid === settings.value.quickTraitFolderUuid)
    ) {
      settings.value.quickTraitFolderUuid = "";
    }
  }

  function hydrateQuickTraits(traits: NpcQuickTraitSummary[]): void {
    quickTraits.value = [...traits].sort((left, right) => left.name.localeCompare(right.name));
  }

  return {
    clearBaseDraftData,
    hydrateActorFolders,
    hydrateBaseActorDraftData,
    hydrateBaseActors,
    hydrateItemFolders,
    hydrateQuickTraits,
    hydrateSettings,
  };
}
