import type {
  NpcAdvancementDraftEntry,
  NpcAdvancementSourceSummary,
  NpcBaseActorDraftData,
  NpcSkillCharacteristicSummary,
  NpcTalentMaximumSummary,
} from "../../../../../types/npc-builder";

import {
  WFRP_CHARACTERISTIC_KEY_BY_NAME,
  WFRP_CHARACTERISTIC_NAMES,
  type WfrpCharacteristicKey,
} from "../../../../../types/wfrp4e/characteristics";
import { advancementKey, namesMatch, normalizeName } from "../draft-helpers";
import { getTalentMaximum, resolveTalentMaximum } from "./talent-maximums";

interface AdvancementContextInput {
  baseActorDraftData: NpcBaseActorDraftData;
  manualAdvancementDeltas: Record<string, number>;
  skillCharacteristics: Record<string, NpcSkillCharacteristicSummary>;
  talentMaximums: Record<string, NpcTalentMaximumSummary>;
}

export function getCharacteristicTotals(
  entries: Map<string, NpcAdvancementDraftEntry>,
  manualAdvancementDeltas: Record<string, number>,
): Partial<Record<WfrpCharacteristicKey, number>> {
  const totals: Partial<Record<WfrpCharacteristicKey, number>> = {};

  for (const entry of entries.values()) {
    if (entry.kind !== "characteristic") {
      continue;
    }

    const key = WFRP_CHARACTERISTIC_KEY_BY_NAME[normalizeName(entry.name)];

    if (!key) {
      continue;
    }

    const manualDelta = manualAdvancementDeltas[advancementKey(entry.kind, entry.name)] ?? 0;
    const current = Math.max(entry.minimumCurrent, Math.floor(entry.careerValue + manualDelta));

    totals[key] = Math.max(0, entry.baseValue + current);
  }

  return totals;
}

export function applyEntryContext(
  entry: NpcAdvancementDraftEntry,
  characteristicTotals: Partial<Record<WfrpCharacteristicKey, number>>,
  context: AdvancementContextInput,
): NpcAdvancementDraftEntry {
  if (entry.kind === "skill") {
    return applySkillCharacteristicContext(entry, characteristicTotals, context);
  }

  if (entry.kind === "talent") {
    return applyTalentMaximumContext(entry, characteristicTotals, context);
  }

  return entry;
}

function applySkillCharacteristicContext(
  entry: NpcAdvancementDraftEntry,
  characteristicTotals: Partial<Record<WfrpCharacteristicKey, number>>,
  context: AdvancementContextInput,
): NpcAdvancementDraftEntry {
  const characteristic =
    getEntrySkillCharacteristic(entry) ??
    getStoredSkillCharacteristic(entry.name, context.skillCharacteristics) ??
    getBaseSkillCharacteristic(entry.name, context.baseActorDraftData);

  if (!characteristic) {
    return {
      ...entry,
      minimumCurrent: -entry.baseValue,
      minimumTotal: 0,
    };
  }

  const characteristicValue = characteristicTotals[characteristic.characteristicKey] ?? 0;
  const baseSkillAdvances = Math.max(0, entry.baseAdvances);
  const baseSkillModifier = Math.floor(entry.baseModifier ?? 0);
  const baseSources: NpcAdvancementSourceSummary[] = [
    {
      count: characteristicValue,
      kind: "characteristic",
      label: characteristic.characteristicName,
    },
  ];

  if (baseSkillAdvances > 0) {
    baseSources.push({
      count: baseSkillAdvances,
      kind: "base",
      label: "Base skill advances",
    });
  }

  if (baseSkillModifier !== 0) {
    baseSources.push({
      count: baseSkillModifier,
      kind: "base",
      label: "Stored modifier",
    });
  }

  return {
    ...entry,
    baseValue: characteristicValue + baseSkillAdvances + baseSkillModifier,
    characteristicKey: characteristic.characteristicKey,
    characteristicName: characteristic.characteristicName,
    characteristicValue,
    minimumCurrent: -baseSkillAdvances,
    minimumTotal: characteristicValue,
    sources: [...baseSources, ...entry.sources],
  };
}

function applyTalentMaximumContext(
  entry: NpcAdvancementDraftEntry,
  characteristicTotals: Partial<Record<WfrpCharacteristicKey, number>>,
  context: AdvancementContextInput,
): NpcAdvancementDraftEntry {
  const maximum = getTalentMaximum(entry, context.talentMaximums);
  const resolvedMaximum = resolveTalentMaximum(maximum, characteristicTotals);

  return {
    ...entry,
    minimumCurrent: -entry.baseAdvances,
    minimumTotal: 0,
    talentMaximumFormula: maximum.maximumFormula,
    talentMaximumKey: maximum.maximumKey,
    talentMaximumLabel: resolvedMaximum.label,
    talentMaximumValue: resolvedMaximum.value,
  };
}

function getEntrySkillCharacteristic(
  entry: NpcAdvancementDraftEntry,
): NpcSkillCharacteristicSummary | null {
  if (!entry.characteristicKey || !entry.characteristicName) {
    return null;
  }

  return {
    characteristicKey: entry.characteristicKey,
    characteristicName: entry.characteristicName,
    skillName: entry.name,
  };
}

function getStoredSkillCharacteristic(
  skillName: string,
  skillCharacteristics: Record<string, NpcSkillCharacteristicSummary>,
): NpcSkillCharacteristicSummary | null {
  return skillCharacteristics[normalizeName(skillName)] ?? null;
}

function getBaseSkillCharacteristic(
  skillName: string,
  baseActorDraftData: NpcBaseActorDraftData,
): NpcSkillCharacteristicSummary | null {
  const advancement = baseActorDraftData.advancements.find(
    (entry) => entry.kind === "skill" && namesMatch(entry.name, skillName),
  );

  if (!advancement?.characteristicKey) {
    return null;
  }

  return {
    characteristicKey: advancement.characteristicKey,
    characteristicName:
      advancement.characteristicName ?? WFRP_CHARACTERISTIC_NAMES[advancement.characteristicKey],
    skillName,
  };
}
