import type { SpeciesItemReference } from "../../../types/species/item";
import { isRecord } from "../../functions/shared/object-readers";
import { findImportedReference } from "../species-item/documents/imported-references";

const temporaryTables = new Map<string, FoundryRollTableDocument>();
let installed = false;

function tableSlot(key: string, column?: string): string {
  return `${key.toLowerCase()}|${column ?? ""}`;
}

export function installChargenTableLookup(): void {
  if (installed) return;
  const tables = game.wfrp4e?.tables;
  if (!tables?.findTable) throw new Error("WFRP table lookup is unavailable.");
  const original = tables.findTable;
  tables.findTable = function (key, column) {
    return temporaryTables.get(tableSlot(key, column)) ?? original.call(this, key, column);
  };
  installed = true;
}

export async function resolveChargenTable(
  reference: SpeciesItemReference,
): Promise<FoundryRollTableDocument | undefined> {
  if (!reference.uuid && !reference.id) return undefined;
  const document =
    findImportedReference(reference, game.tables?.contents ?? []) ??
    (await fromUuid(reference.uuid || `RollTable.${reference.id}`));
  if (!isRecord(document) || document["documentName"] !== "RollTable")
    throw new Error(
      `Cannot resolve Species RollTable ${reference.name || reference.uuid || reference.id}.`,
    );
  return document as unknown as FoundryRollTableDocument;
}

export function setChargenTables(
  key: string,
  career?: FoundryRollTableDocument,
  talents?: FoundryRollTableDocument,
  eye?: FoundryRollTableDocument,
  hair?: FoundryRollTableDocument,
): void {
  installChargenTableLookup();
  clearChargenTables(key);
  if (eye) temporaryTables.set(tableSlot("eyes", key), eye);
  if (hair) temporaryTables.set(tableSlot("hair", key), hair);
  if (career) temporaryTables.set(tableSlot("career", key), career);
  if (talents) temporaryTables.set(tableSlot(`${key}-talents`), talents);
}

export function clearChargenTables(key: string): void {
  temporaryTables.delete(tableSlot("eyes", key));
  temporaryTables.delete(tableSlot("hair", key));
  temporaryTables.delete(tableSlot("career", key));
  temporaryTables.delete(tableSlot(`${key}-talents`));
}
