import type { NpcCareerSummary } from "../../../../../types/npc-builder";
import type {
  PendingCareerAddEntry,
  PendingSkillResolutionPrompt,
  SkillResolutionLinkedRow,
  SkillResolutionPromptRow,
} from "../../../../../types/npc-builder";

import {
  formatSpecializedSkillName,
  getAmbiguousSkillGrant,
  getConcreteSkillGrant,
  getSkillGrantOccurrences,
  normalizeSkillGrantText,
} from "../skill-specialization";

export function createSkillResolutionPrompt(
  entries: PendingCareerAddEntry[],
  options: { enableLinkedSkillResolution: boolean; message: string },
): PendingSkillResolutionPrompt {
  const linkableKeysByGrant = new Map<string, string[]>();
  const linkedRows: SkillResolutionLinkedRow[] = [];
  const rows: SkillResolutionPromptRow[] = [];

  for (const entry of entries) {
    const occurrenceIndexByGrant = new Map<string, number>();

    // Career chains often repeat broad skills. Link the first repeat across
    // inferred tiers, but keep true duplicates in one tier as separate choices.
    for (const occurrence of getSkillGrantOccurrences(
      entry.career.uuid,
      entry.career.grants.skills,
    )) {
      const ambiguousGrant = getAmbiguousSkillGrant(occurrence.originalName);

      if (!ambiguousGrant) {
        continue;
      }

      const normalizedGrant = normalizeSkillGrantText(occurrence.originalName);
      const linkableKeys = linkableKeysByGrant.get(normalizedGrant) ?? [];
      const occurrenceIndex = occurrenceIndexByGrant.get(normalizedGrant) ?? 0;
      const linkedFromKey =
        options.enableLinkedSkillResolution && linkableKeys[occurrenceIndex]
          ? linkableKeys[occurrenceIndex]
          : "";

      occurrenceIndexByGrant.set(normalizedGrant, occurrenceIndex + 1);

      if (linkedFromKey) {
        linkedRows.push({ linkedFromKey, resolutionKey: occurrence.resolutionKey });
        continue;
      }

      rows.push({
        alreadyGrantedSpecializations: getAlreadyGrantedSpecializations(
          entry.career.grants.skills,
          ambiguousGrant.baseName,
        ),
        baseName: ambiguousGrant.baseName,
        careerLabel: getCareerLabel(entry.career),
        isLoadingSuggestions: false,
        occurrence: occurrence.occurrence,
        options: ambiguousGrant.options,
        originalName: ambiguousGrant.originalName,
        resolvedSpecialization: getDefaultSkillSpecialization(ambiguousGrant),
        resolutionKey: occurrence.resolutionKey,
        specialization: ambiguousGrant.specialization,
        suggestedSpecializations: [],
      });

      linkableKeys[occurrenceIndex] = occurrence.resolutionKey;
      linkableKeysByGrant.set(normalizedGrant, linkableKeys);
    }
  }

  return { entries, linkedRows, message: options.message, rows };
}

export function getResolvedSkillName(row: SkillResolutionPromptRow): string {
  return row.resolvedSpecialization.trim()
    ? formatSpecializedSkillName(row.baseName, row.resolvedSpecialization)
    : "";
}

export function getSkillResolutionLabel(row: SkillResolutionPromptRow): string {
  return row.occurrence > 0
    ? `${row.originalName}, choice ${row.occurrence + 1}`
    : row.originalName;
}

export function usesFreeformSkillSpecialization(row: SkillResolutionPromptRow): boolean {
  return row.options.length <= 1 && row.specialization.trim().toLocaleLowerCase() === "any";
}

export function isSkillSpecializationAlreadyGranted(
  row: SkillResolutionPromptRow,
  specialization: string,
): boolean {
  const normalizedSpecialization = normalizeSkillGrantText(specialization);

  return row.alreadyGrantedSpecializations.some(
    (grantedSpecialization) =>
      normalizeSkillGrantText(grantedSpecialization) === normalizedSpecialization,
  );
}

function getAlreadyGrantedSpecializations(skillNames: string[], baseName: string): string[] {
  const normalizedBaseName = normalizeSkillGrantText(baseName);
  const seenSpecializations = new Set<string>();
  const specializations: string[] = [];

  for (const skillName of skillNames) {
    const concreteGrant = getConcreteSkillGrant(skillName);

    if (!concreteGrant || normalizeSkillGrantText(concreteGrant.baseName) !== normalizedBaseName) {
      continue;
    }

    const normalizedSpecialization = normalizeSkillGrantText(concreteGrant.specialization);

    if (!seenSpecializations.has(normalizedSpecialization)) {
      seenSpecializations.add(normalizedSpecialization);
      specializations.push(concreteGrant.specialization);
    }
  }

  return specializations;
}

function getCareerLabel(career: NpcCareerSummary): string {
  return career.level === null ? career.name : `${career.name}, tier ${career.level}`;
}

function getDefaultSkillSpecialization(grant: {
  options: string[];
  specialization: string;
}): string {
  return grant.specialization.trim().toLocaleLowerCase() === "any" ? "" : (grant.options[0] ?? "");
}
