import { computed, type Ref } from "vue";

import type {
  NpcAdvancementDraftEntry,
  NpcBaseActorDraftData,
  NpcBuilderSettings,
  NpcCareerQueueEntry,
  NpcAutoAdvanceStrategyDefinition,
  NpcCustomAdvancementSummary,
  NpcSkillCharacteristicSummary,
  NpcTalentMaximumSummary,
} from "../../../../../types/npc-builder";

import {
  calculateManualAdvancementDelta,
  calculateManualAdvancementDeltaFromTotal,
  deriveNpcAdvancements,
  indexSkillCharacteristics,
  indexTalentMaximums,
} from "../../functions/advancements/derive-advancements";
import {
  findAdvancement,
  getAdjustedAdvancementTotal,
  getMaximizedTalentTotals,
  reconcileAdvancementCurrents,
} from "../../functions/advancements/advancement-actions";
import { advancementKey } from "../../functions/draft-helpers";
import { calculateEstimatedNpcXp } from "../../functions/xp-cost";

interface AdvancementStoreSliceContext {
  baseActorDraftData: Ref<NpcBaseActorDraftData>;
  careers: Ref<NpcCareerQueueEntry[]>;
  customAdvancements: Ref<NpcCustomAdvancementSummary[]>;
  manualAdvancementDeltas: Ref<Record<string, number>>;
  settings: Ref<NpcBuilderSettings>;
  skillCharacteristics: Ref<Record<string, NpcSkillCharacteristicSummary>>;
  skillGrantResolutions: Ref<Record<string, string>>;
  talentMaximums: Ref<Record<string, NpcTalentMaximumSummary>>;
}

export function createAdvancementStoreSlice(context: AdvancementStoreSliceContext) {
  const {
    baseActorDraftData,
    careers,
    customAdvancements,
    manualAdvancementDeltas,
    settings,
    skillCharacteristics,
    skillGrantResolutions,
    talentMaximums,
  } = context;

  const advancements = computed<NpcAdvancementDraftEntry[]>(() =>
    deriveNpcAdvancements({
      baseActorDraftData: baseActorDraftData.value,
      careers: careers.value,
      customAdvancements: customAdvancements.value,
      manualAdvancementDeltas: manualAdvancementDeltas.value,
      settings: settings.value,
      skillCharacteristics: skillCharacteristics.value,
      skillGrantResolutions: skillGrantResolutions.value,
      talentMaximums: talentMaximums.value,
    }),
  );

  const estimatedNpcXp = computed(() => calculateEstimatedNpcXp(advancements.value));
  const maximizableTalentCount = computed(
    () => getMaximizedTalentTotals(advancements.value).length,
  );

  function addCustomAdvancement(advancement: NpcCustomAdvancementSummary): void {
    const key = advancementKey(advancement.kind, advancement.name);

    if (customAdvancements.value.some((entry) => advancementKey(entry.kind, entry.name) === key)) {
      return;
    }

    customAdvancements.value.push(advancement);
  }

  function removeCustomAdvancement(advancement: NpcAdvancementDraftEntry): void {
    const key = advancementKey(advancement.kind, advancement.name);

    customAdvancements.value = customAdvancements.value.filter((entry) => {
      return advancementKey(entry.kind, entry.name) !== key;
    });
    delete manualAdvancementDeltas.value[key];
  }

  function adjustAdvancementCurrent(
    advancement: NpcAdvancementDraftEntry,
    direction: -1 | 1,
  ): void {
    setAdvancementTotal(advancement, getAdjustedAdvancementTotal(advancement, direction));
  }

  function maximizeTalents(): void {
    for (const change of getMaximizedTalentTotals(advancements.value)) {
      const advancement = findAdvancement(advancements.value, change);

      if (advancement) {
        setAdvancementTotal(advancement, change.total);
      }
    }
  }

  function applyAutoAdvance(strategy: NpcAutoAdvanceStrategyDefinition, targetXp: number): void {
    const target = Math.max(0, Math.floor(Number.isFinite(targetXp) ? targetXp : 0));
    const advancedNpc = strategy.run({ advancements: advancements.value }, target);
    const changes = reconcileAdvancementCurrents(advancements.value, advancedNpc.advancements);

    for (const change of changes) {
      const advancement = findAdvancement(advancements.value, change);

      if (advancement) {
        setAdvancementCurrent(advancement, change.current);
      }
    }
  }

  function getSkillGrantResolution(key: string): string {
    return skillGrantResolutions.value[key] ?? "";
  }

  function hydrateSkillCharacteristics(characteristics: NpcSkillCharacteristicSummary[]): void {
    skillCharacteristics.value = indexSkillCharacteristics(
      skillCharacteristics.value,
      characteristics,
    );
  }

  function hydrateTalentMaximums(maximums: NpcTalentMaximumSummary[]): void {
    talentMaximums.value = indexTalentMaximums(talentMaximums.value, maximums);
  }

  function setAdvancementCurrent(advancement: NpcAdvancementDraftEntry, current: number): void {
    const key = advancementKey(advancement.kind, advancement.name);
    manualAdvancementDeltas.value[key] = calculateManualAdvancementDelta(advancement, current);
  }

  function setAdvancementTotal(advancement: NpcAdvancementDraftEntry, total: number): void {
    const key = advancementKey(advancement.kind, advancement.name);

    manualAdvancementDeltas.value[key] = calculateManualAdvancementDeltaFromTotal(
      advancement,
      total,
    );
  }

  function resetAdvancementCurrent(advancement: NpcAdvancementDraftEntry): void {
    const key = advancementKey(advancement.kind, advancement.name);

    delete manualAdvancementDeltas.value[key];
  }

  function resetAllAdvancementCurrents(): void {
    manualAdvancementDeltas.value = {};
  }

  function setSkillGrantResolution(key: string, resolvedName: string): void {
    const trimmedName = resolvedName.trim();

    if (!trimmedName) {
      delete skillGrantResolutions.value[key];
      return;
    }

    skillGrantResolutions.value[key] = trimmedName;
  }

  function removeSkillGrantResolutionsForCareer(careerUuid: string): void {
    const prefix = `${careerUuid}:`;

    for (const key of Object.keys(skillGrantResolutions.value)) {
      if (key.startsWith(prefix)) {
        delete skillGrantResolutions.value[key];
      }
    }
  }

  return {
    addCustomAdvancement,
    adjustAdvancementCurrent,
    applyAutoAdvance,
    advancements,
    estimatedNpcXp,
    getSkillGrantResolution,
    hydrateSkillCharacteristics,
    hydrateTalentMaximums,
    maximizableTalentCount,
    maximizeTalents,
    removeCustomAdvancement,
    removeSkillGrantResolutionsForCareer,
    resetAdvancementCurrent,
    resetAllAdvancementCurrents,
    setAdvancementCurrent,
    setAdvancementTotal,
    setSkillGrantResolution,
  };
}
