import type {
  PortraitCandidate,
  PortraitSearchPhase,
  PortraitSearchProgressHandler,
} from "../../../types/portrait-gallery";
import type { PortraitDocumentSource, PortraitSearchState } from "./types";

import {
  doesPortraitCandidateMatchFilters,
  doesPortraitTextMatch,
} from "../../functions/portrait-gallery";
import { readStringPath } from "../../functions/shared/object-readers";

export const portraitAssetExtensions = [".webp", ".png", ".jpg", ".jpeg", ".gif"];
const portraitAssetExtensionSet = new Set(portraitAssetExtensions);

export function addPortraitCandidate(
  state: PortraitSearchState,
  candidate: PortraitCandidate,
): void {
  const normalizedPath = candidate.img.trim().toLocaleLowerCase();

  if (!normalizedPath || state.seenPaths.has(normalizedPath)) {
    return;
  }

  state.seenPaths.add(normalizedPath);
  state.candidates.push(candidate);
}

export function collectDocumentPortraitCandidates(
  state: PortraitSearchState,
  document: PortraitDocumentSource,
): void {
  const imagePaths = document.imagePaths.filter(({ path }) => Boolean(path));

  if (!documentMatchesSearchTerms(document.name, imagePaths, state.searchTerms)) {
    return;
  }

  for (const imagePath of imagePaths) {
    const candidate: PortraitCandidate = {
      img: imagePath.path,
      key: `foundry-asset:${document.sourceKey}:${imagePath.label}`,
      label: `${document.name || getPortraitFileName(imagePath.path)} ${imagePath.label} (${document.sourceLabel})`,
      source: "foundry-asset",
      sourceGroup: document.sourceGroup,
      sourceLabel: document.sourceLabel,
    };

    if (doesCandidateMatchStateFilters(candidate, state)) {
      addPortraitCandidate(state, candidate);
    }
  }
}

export function emitPortraitSearchProgress(
  onProgress: PortraitSearchProgressHandler | undefined,
  state: PortraitSearchState,
  options: {
    currentLocation: string;
    maxDirectories: number;
    phase: PortraitSearchPhase;
  },
): void {
  onProgress?.({
    candidatesFound: state.candidates.length,
    currentLocation: options.currentLocation,
    directoriesVisited: state.visitedDirectories,
    maxDirectories: options.maxDirectories,
    phase: options.phase,
  });
}

export function getActorPrototypeTokenImage(actor: FoundryActorDocument): string {
  return (
    readStringPath(actor, ["prototypeToken", "texture", "src"]) ||
    readStringPath(actor.toObject(), ["prototypeToken", "texture", "src"])
  );
}

export function getPortraitAssetLabel(path: string, source: string): string {
  const filename = getPortraitFileName(path);

  return `${filename} (${source})`;
}

export function getPortraitFileName(path: string): string {
  return path.split(/[/\\]/).at(-1) ?? path;
}

export function isPortraitAssetPath(path: string): boolean {
  const extension = `.${path.split(/[#?]/u)[0]?.split(".").pop() ?? ""}`;

  return portraitAssetExtensionSet.has(extension.toLocaleLowerCase());
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

export function isStringArrayRecord(value: unknown): value is Record<string, string[]> {
  return (
    isRecord(value) &&
    Object.values(value).every(
      (paths) => Array.isArray(paths) && paths.every((path) => typeof path === "string"),
    )
  );
}

function documentMatchesSearchTerms(
  name: string,
  imagePaths: Array<{ path: string }>,
  searchTerms: string[],
): boolean {
  return (
    doesPortraitTextMatch(name, searchTerms) ||
    imagePaths.some(({ path }) => doesPortraitTextMatch(path, searchTerms))
  );
}

export function doesCandidateMatchStateFilters(
  candidate: PortraitCandidate,
  state: PortraitSearchState,
): boolean {
  return doesPortraitCandidateMatchFilters(candidate, {
    mustExcludeSources: [],
    mustExcludeTerms: state.mustExcludeTerms,
    mustIncludeSources: [],
    mustIncludeTerms: state.mustIncludeTerms,
  });
}
