import {
  canSwapWfrpCharacteristicRollFormulas,
  getWfrpCharacteristicRollExpression,
} from "../../functions/species-chargen/characteristic-roll-formulas";
import { isRecord } from "../../functions/shared/object-readers";
import { MODULE_ID } from "../../constants";
import { logInfo, logWarning } from "../../foundry/logging";
import { installChargenRollSwapFeedback } from "./roll-swap-feedback";

interface WfrpChargenApplication {
  replaceStage?: (key: string, stage: WfrpAttributesStageConstructor) => void;
  stages?: unknown[];
}

interface WfrpChargenStageDescriptor {
  class: WfrpAttributesStageConstructor;
  key: string;
}

interface WfrpAttributesStage {
  activateListeners(html: unknown): unknown;
  context?: unknown;
  swap(firstCharacteristic: string, secondCharacteristic: string): unknown;
}

type WfrpAttributesStageConstructor = new (...args: unknown[]) => WfrpAttributesStage;

const guardedAttributesStageMarker = Symbol("wfrp4e-customizer-guarded-attributes-stage");

interface GuardedAttributesStageConstructor extends WfrpAttributesStageConstructor {
  [guardedAttributesStageMarker]?: true;
}

export function registerSpeciesChargenSwapGuard(): void {
  Hooks.on("wfrp4e:chargen", (chargen) => {
    installSpeciesChargenSwapGuard(chargen);
  });
}

function installSpeciesChargenSwapGuard(chargen: unknown): void {
  const chargenApplication = readChargenApplication(chargen);

  if (!chargenApplication) {
    logWarning(`${MODULE_ID} | Could not inspect WFRP character generation stages.`);
    return;
  }

  const attributesStage = findAttributesStage(chargenApplication);

  if (!attributesStage) {
    logWarning(`${MODULE_ID} | Could not find the WFRP Attributes character generation stage.`);
    return;
  }

  if (isGuardedAttributesStage(attributesStage.class)) {
    return;
  }

  const guardedAttributesStage = createGuardedAttributesStage(attributesStage.class);

  if (typeof chargenApplication.replaceStage === "function") {
    chargenApplication.replaceStage("attributes", guardedAttributesStage);
  } else {
    attributesStage.class = guardedAttributesStage;
  }

  logInfo(`${MODULE_ID} | Guarded WFRP characteristic roll swapping for custom species.`);
}

function readChargenApplication(value: unknown): undefined | WfrpChargenApplication {
  if (!isRecord(value)) {
    return undefined;
  }

  const chargenApplication: WfrpChargenApplication = {};

  const replaceStage = value["replaceStage"];

  if (typeof replaceStage === "function") {
    chargenApplication.replaceStage = (key, stage) => {
      replaceStage.call(value, key, stage);
    };
  }

  if (Array.isArray(value["stages"])) {
    chargenApplication.stages = value["stages"];
  }

  return chargenApplication;
}

function findAttributesStage(
  chargenApplication: WfrpChargenApplication,
): undefined | WfrpChargenStageDescriptor {
  for (const stage of chargenApplication.stages ?? []) {
    if (!isRecord(stage)) {
      continue;
    }

    if (stage["key"] !== "attributes") {
      continue;
    }

    if (typeof stage["class"] !== "function") {
      return undefined;
    }

    return stage as unknown as WfrpChargenStageDescriptor;
  }

  return undefined;
}

function isGuardedAttributesStage(
  stageClass: WfrpAttributesStageConstructor,
): stageClass is GuardedAttributesStageConstructor {
  return Boolean((stageClass as GuardedAttributesStageConstructor)[guardedAttributesStageMarker]);
}

function createGuardedAttributesStage(
  BaseAttributesStage: WfrpAttributesStageConstructor,
): GuardedAttributesStageConstructor {
  class GuardedAttributesStage extends BaseAttributesStage {
    static [guardedAttributesStageMarker] = true as const;

    override activateListeners(html: unknown): unknown {
      const result = super.activateListeners(html);
      installChargenRollSwapFeedback(html, (firstCharacteristic, secondCharacteristic) => {
        const firstFormula = readCharacteristicFormula(this, firstCharacteristic);
        const secondFormula = readCharacteristicFormula(this, secondCharacteristic);

        return canSwapWfrpCharacteristicRollFormulas(firstFormula, secondFormula);
      });

      return result;
    }

    override swap(firstCharacteristic: string, secondCharacteristic: string): unknown {
      const firstFormula = readCharacteristicFormula(this, firstCharacteristic);
      const secondFormula = readCharacteristicFormula(this, secondCharacteristic);

      if (canSwapWfrpCharacteristicRollFormulas(firstFormula, secondFormula)) {
        return super.swap(firstCharacteristic, secondCharacteristic);
      }

      notifyBlockedSwap(firstCharacteristic, firstFormula, secondCharacteristic, secondFormula);
      return undefined;
    }
  }

  return GuardedAttributesStage;
}

function readCharacteristicFormula(
  stage: WfrpAttributesStage,
  characteristic: string,
): string | undefined {
  const context = isRecord(stage.context) ? stage.context : undefined;
  const characteristics = isRecord(context?.["characteristics"])
    ? context["characteristics"]
    : undefined;
  const characteristicData = isRecord(characteristics?.[characteristic])
    ? characteristics[characteristic]
    : undefined;
  const formula = characteristicData?.["formula"];

  return typeof formula === "string" ? formula : undefined;
}

function notifyBlockedSwap(
  firstCharacteristic: string,
  firstFormula: string | undefined,
  secondCharacteristic: string,
  secondFormula: string | undefined,
): void {
  const firstLabel = characteristicLabel(firstCharacteristic);
  const secondLabel = characteristicLabel(secondCharacteristic);
  const firstRoll = getWfrpCharacteristicRollExpression(firstFormula);
  const secondRoll = getWfrpCharacteristicRollExpression(secondFormula);

  ui.notifications?.warn?.(
    `Cannot swap ${firstLabel} and ${secondLabel}: ${firstLabel} uses ${firstRoll}, while ${secondLabel} uses ${secondRoll}.`,
  );
}

function characteristicLabel(characteristic: string): string {
  const labels = game.wfrp4e?.config?.["characteristics"];

  if (!isRecord(labels)) {
    return characteristic;
  }

  const label = labels[characteristic];

  return typeof label === "string" ? label : characteristic;
}
