import { applicationElement } from "../../foundry/application-element";
import type { LegacyDetailsStageConstructor } from "../../../types/species/chargen";
import { isRecord } from "../../functions/shared/object-readers";
import type { SpeciesChargenSession } from "./session";

type Generator = "rollName" | "rollAge" | "rollHeight";
const detailRolls = [
  "rollName",
  "rollAge",
  "rollHeight",
  "rollEyes",
  "rollHair",
  "rollMotivation",
] as const;

/** Effect formulas use the session key; installed generators remain a fallback. */
export function detailsGeneratorKey(
  session: SpeciesChargenSession,
  method: Generator,
): string | undefined {
  if (!session.selection) return undefined;
  const keys = session.selection.record.system.keys;
  return (method === "rollName" ? keys : [session.key, ...keys]).find((key) => {
    if (method === "rollName") {
      const generator = game.wfrp4e?.names?.[key];
      return (
        isRecord(generator) &&
        typeof generator["forename"] === "function" &&
        typeof generator["surname"] === "function"
      );
    }
    const config = game.wfrp4e?.config?.[method === "rollAge" ? "speciesAge" : "speciesHeight"];
    const value = isRecord(config) ? config[key] : undefined;
    if (method === "rollAge") return typeof value === "string" && !!value.trim();
    return (
      isRecord(value) &&
      typeof value["die"] === "string" &&
      typeof value["feet"] === "number" &&
      typeof value["inches"] === "number"
    );
  });
}

export function createItemDetailsStage(
  Base: LegacyDetailsStageConstructor,
  session: SpeciesChargenSession,
) {
  return class ItemDetailsStage extends Base {
    private generatorContext(method: Generator): this {
      const key = detailsGeneratorKey(session, method);
      if (!key)
        throw new Error("This Species has no generator for this detail. Enter it manually.");
      // The native methods need a generator key, without changing shared chargen state.
      return Object.assign(Object.create(this) as this, { data: { ...this.data, species: key } });
    }

    override rollName(): string {
      return super.rollName.call(this.generatorContext("rollName"));
    }

    override rollAge(): Promise<number> {
      return super.rollAge.call(this.generatorContext("rollAge"));
    }

    override rollHeight(): Promise<string> {
      return super.rollHeight.call(this.generatorContext("rollHeight"));
    }

    private async rollDetailTable(key: string, column?: string): Promise<string> {
      const tables = game.wfrp4e?.tables;
      if (!tables?.findTable?.(key, column))
        throw new Error("No table is available for this detail.");
      const result = await tables.rollTable?.(key, {}, column);
      // Official migrated text rows have empty names; authored v14 rows may have only names.
      const label = isRecord(result)
        ? [result["text"], result["name"]].find(
            (value) => typeof value === "string" && value.trim(),
          )
        : undefined;
      if (typeof label !== "string")
        throw new Error("The details table returned no result. Your current entry was kept.");
      return label;
    }

    override rollEyes(): Promise<string> {
      return this.rollDetailTable("eyes", session.key);
    }
    override rollHair(): Promise<string> {
      return this.rollDetailTable("hair", session.key);
    }
    override rollMotivation(): Promise<string> {
      return this.rollDetailTable("motivation");
    }

    override activateListeners(html: unknown): void {
      super.activateListeners(html);
      const element = applicationElement(html);
      if (!element) return;
      let manual = false;
      for (const method of detailRolls) {
        const button = element.querySelector<HTMLElement>(`[data-type="${method}"]`);
        if (!button) continue;
        const available =
          method === "rollName" || method === "rollAge" || method === "rollHeight"
            ? !!detailsGeneratorKey(session, method)
            : method === "rollMotivation" ||
              !!session.selection?.record.system.tables[method === "rollEyes" ? "eye" : "hair"]
                .uuid ||
              !!session.selection?.record.system.tables[method === "rollEyes" ? "eye" : "hair"].id;
        if (!available) {
          button.remove();
          manual = true;
          continue;
        }
        button.addEventListener(
          "click",
          (event) => {
            event.preventDefault();
            event.stopImmediatePropagation();
            void Promise.resolve()
              .then(async () => await this[method]())
              .then((value) => {
                const input = button.closest(".detail-form")?.querySelector("input");
                if (input) input.value = String(value);
              })
              .catch((error: unknown) => {
                ui.notifications?.error(error instanceof Error ? error.message : String(error));
              });
          },
          { capture: true },
        );
      }
      if (manual) {
        const help = document.createElement("p");
        help.textContent =
          "Enter details manually where this Species has no generator. Check its description for any age or height guidance.";
        element.querySelector(".chargen-content")?.prepend(help);
      }
    }
  };
}
