<script setup lang="ts">
import { computed, ref } from "vue";

import type {
  PortraitFilterSection,
  PortraitFilterTag,
} from "../../../../../../types/portrait-gallery";

import {
  createPortraitFilterTagDragData,
  portraitFilterTagDragMimeType,
  readPortraitFilterTagDragId,
} from "../../../../../functions/portrait-gallery";

const props = defineProps<{
  resultCount: number;
  tags: PortraitFilterTag[];
}>();

const emit = defineEmits<{
  createSearchTerm: [value: string];
  filterTagSectionChange: [tag: PortraitFilterTag, section: PortraitFilterSection];
}>();

const tagInput = ref("");
const draggedTag = ref<PortraitFilterTag | null>(null);
const activeDropSection = ref<PortraitFilterSection | null>(null);
const sections: Array<{
  icon: string;
  id: Exclude<PortraitFilterSection, "removed">;
  title: string;
}> = [
  { icon: "fa-magnifying-glass", id: "search", title: "Search" },
  { icon: "fa-check", id: "must-include", title: "Must Include" },
  { icon: "fa-ban", id: "must-exclude", title: "Mustn't Include" },
];

const tagsBySection = computed(() => {
  return Object.fromEntries(
    sections.map((section) => [section.id, props.tags.filter((tag) => tag.section === section.id)]),
  ) as Record<Exclude<PortraitFilterSection, "removed">, PortraitFilterTag[]>;
});

function createSearchTerm(): void {
  const value = tagInput.value;

  emit("createSearchTerm", value);
  tagInput.value = "";
}

function startTagDrag(tag: PortraitFilterTag, event: DragEvent): void {
  event.stopPropagation();
  draggedTag.value = tag;
  event.dataTransfer?.setData("text/plain", createPortraitFilterTagDragData(tag.id));
  event.dataTransfer?.setData(portraitFilterTagDragMimeType, tag.id);

  if (event.dataTransfer) {
    event.dataTransfer.effectAllowed = "move";
  }
}

function dragTagOver(section: PortraitFilterSection, event: DragEvent): void {
  event.preventDefault();
  event.stopPropagation();
  activeDropSection.value = section;

  if (event.dataTransfer) {
    event.dataTransfer.dropEffect = canDropTag(draggedTag.value, section) ? "move" : "none";
  }
}

function leaveDropSection(section: PortraitFilterSection, event: DragEvent): void {
  event.stopPropagation();

  if (
    event.currentTarget instanceof Node &&
    event.relatedTarget instanceof Node &&
    event.currentTarget.contains(event.relatedTarget)
  ) {
    return;
  }

  if (activeDropSection.value === section) {
    activeDropSection.value = null;
  }
}

function dropTag(section: PortraitFilterSection, event: DragEvent): void {
  event.preventDefault();
  event.stopPropagation();

  const dragId =
    event.dataTransfer?.getData(portraitFilterTagDragMimeType) ||
    readPortraitFilterTagDragId(event.dataTransfer?.getData("text/plain") ?? "");
  const tag = draggedTag.value ?? props.tags.find((entry) => entry.id === dragId) ?? null;

  resetTagDrag();

  if (!canDropTag(tag, section)) {
    return;
  }

  emit("filterTagSectionChange", tag, section);
}

function moveTagToNextSection(tag: PortraitFilterTag): void {
  const currentIndex = sections.findIndex((section) => section.id === tag.section);
  const nextSection = sections[(currentIndex + 1) % sections.length];

  if (nextSection) {
    emit("filterTagSectionChange", tag, nextSection.id);
  }
}

function removeTag(tag: PortraitFilterTag): void {
  if (tag.canRemove) {
    emit("filterTagSectionChange", tag, "removed");
  }
}

function resetTagDrag(): void {
  draggedTag.value = null;
  activeDropSection.value = null;
}

function canDropTag(
  tag: PortraitFilterTag | null,
  section: PortraitFilterSection,
): tag is PortraitFilterTag {
  return Boolean(tag && (section !== "removed" || tag.canRemove));
}

function getDropZoneStatus(section: PortraitFilterSection): string {
  if (activeDropSection.value !== section) {
    return "";
  }

  if (section === "removed" && !draggedTag.value?.canRemove) {
    return "Protected";
  }

  return draggedTag.value?.section === section ? "Already here" : "Drop here";
}

const trashDropLabel = computed(() => {
  if (activeDropSection.value !== "removed") {
    return "Trash";
  }

  return draggedTag.value?.canRemove ? "Drop to remove this tag" : "Source tags stay available";
});
</script>

<template>
  <section class="app:grid app:gap-2">
    <div class="app:flex app:flex-wrap app:items-center app:gap-2">
      <div class="dui-join app:min-w-64 app:flex-1">
        <label class="dui-input dui-input-sm dui-join-item app:flex-1">
          <i aria-hidden="true" class="fa-solid fa-magnifying-glass" />
          <input
            v-model="tagInput"
            aria-label="Add a portrait search term"
            class="app:grow"
            placeholder="Add a search term"
            type="search"
            @keydown.enter.prevent="createSearchTerm"
          />
        </label>
        <button class="dui-btn dui-btn-sm dui-join-item" type="button" @click="createSearchTerm">
          <i aria-hidden="true" class="fa-solid fa-plus" />
          Add
        </button>
      </div>
      <span class="dui-badge dui-badge-sm dui-badge-outline">{{ resultCount }} images</span>
    </div>

    <div class="app:grid app:gap-2 md:app:grid-cols-3">
      <section
        v-for="section in sections"
        :key="section.id"
        class="dui-card dui-card-border dui-card-sm app:min-h-20 app:border-base-content/30 app:bg-base-200 app:shadow-sm"
        :class="{
          'app:border-info app:bg-info/10 app:ring-2 app:ring-info':
            activeDropSection === section.id,
        }"
        @dragenter="dragTagOver(section.id, $event)"
        @dragleave="leaveDropSection(section.id, $event)"
        @dragover="dragTagOver(section.id, $event)"
        @drop="dropTag(section.id, $event)"
      >
        <div class="dui-card-body app:gap-2 app:p-2">
          <header class="app:flex app:items-center app:gap-2">
            <h3 class="dui-card-title app:m-0 app:text-sm">
              <i aria-hidden="true" class="fa-solid" :class="section.icon" />
              {{ section.title }}
            </h3>
            <span class="dui-badge dui-badge-sm">{{ tagsBySection[section.id].length }}</span>
            <span
              v-if="activeDropSection === section.id"
              aria-live="polite"
              class="dui-badge dui-badge-info dui-badge-sm app:ml-auto"
            >
              {{ getDropZoneStatus(section.id) }}
            </span>
          </header>
          <div class="app:flex app:min-h-8 app:flex-wrap app:items-center app:gap-2">
            <button
              v-for="tag in tagsBySection[section.id]"
              :key="tag.id"
              class="dui-badge dui-badge-sm app:h-auto app:cursor-grab app:whitespace-normal app:py-1"
              :class="[
                tag.kind === 'source' ? 'dui-badge-outline' : 'dui-badge-primary',
                draggedTag?.id === tag.id ? 'app:opacity-50' : '',
              ]"
              draggable="true"
              :title="`Drag ${tag.label} to another group, or select it to move it to the next group.`"
              type="button"
              @click="moveTagToNextSection(tag)"
              @dragend="resetTagDrag"
              @dragstart="startTagDrag(tag, $event)"
              @keydown.delete.prevent="removeTag(tag)"
            >
              {{ tag.label }}
            </button>
            <small v-if="!tagsBySection[section.id].length" class="app:text-base-content/60">
              Drop tags here
            </small>
          </div>
        </div>
      </section>
    </div>

    <div
      aria-label="Remove search tag"
      class="dui-card dui-card-border dui-card-sm app:border-dashed app:border-base-content/30 app:bg-base-200"
      :class="{
        'app:border-error app:bg-error/10 app:ring-2 app:ring-error':
          activeDropSection === 'removed' && !draggedTag?.canRemove,
        'app:border-warning app:bg-warning/10 app:ring-2 app:ring-warning':
          activeDropSection === 'removed' && draggedTag?.canRemove,
      }"
      @dragenter="dragTagOver('removed', $event)"
      @dragleave="leaveDropSection('removed', $event)"
      @dragover="dragTagOver('removed', $event)"
      @drop="dropTag('removed', $event)"
    >
      <div class="dui-card-body app:flex-row app:items-center app:justify-center app:gap-2 app:p-2">
        <i aria-hidden="true" class="fa-solid fa-trash" />
        <span aria-live="polite">{{ trashDropLabel }}</span>
      </div>
    </div>
  </section>
</template>
