import { compileWoundFormula } from "../../../functions/effect-builders/wound-formula/compiler";

export function validateEffectFormula(formula: string): void {
  if (!formula.trim()) throw new Error("Enter a wound formula.");
  const compiled = compileWoundFormula(formula);
  const variables = [
    ...compiled.usedKeywords,
    ...compiled.references.map((reference) => reference.variableName),
  ];
  const expression = compiled.expression.replace(
    /Math\.(floor|ceil|round|min|max|abs|sqrt|pow)\b/g,
    "0",
  );
  const identifiers = expression.match(/[A-Za-z_$][\w$]*/g) ?? [];
  if (
    identifiers.some((identifier) => !variables.includes(identifier)) ||
    /[^\w\s.+*/%(),-]/.test(expression)
  )
    throw new Error("Use arithmetic, formula tokens, and Math functions in the wound formula.");
  try {
    // Compile without executing: this catches malformed arithmetic before authoring an effect.
    new Function(...variables, `"use strict"; return (${compiled.expression});`);
  } catch {
    throw new Error("The wound formula has invalid arithmetic or unmatched brackets.");
  }
}
