import type { NpcCareerSummary } from "../../../../../types/npc-builder";
import type {
  PendingCareerAddEntry,
  PendingLowerCareerPrompt,
} from "../../../../../types/npc-builder";

export function groupLowerCareerCandidates(
  prompt: null | PendingLowerCareerPrompt,
): Array<{ candidates: NpcCareerSummary[]; level: number }> {
  if (!prompt) {
    return [];
  }

  const groups = new Map<number, NpcCareerSummary[]>();

  for (const candidate of prompt.candidates) {
    const level = candidate.level ?? 0;
    const entries = groups.get(level) ?? [];

    entries.push(candidate);
    groups.set(level, entries);
  }

  return [...groups.entries()]
    .sort(([leftLevel], [rightLevel]) => leftLevel - rightLevel)
    .map(([level, candidates]) => ({
      candidates: [...candidates].sort((left, right) => left.name.localeCompare(right.name)),
      level,
    }));
}

export function createDroppedCareerBatch(career: NpcCareerSummary): PendingCareerAddEntry[] {
  return [{ career, mode: "add-or-increment" }];
}

export function createSelectedLowerCareerBatch(
  prompt: PendingLowerCareerPrompt,
): PendingCareerAddEntry[] {
  const selectedCandidates = prompt.candidates.filter((candidate) =>
    prompt.selectedUuids.includes(candidate.uuid),
  );

  return [
    ...selectedCandidates.map((candidate) => ({
      career: candidate,
      mode: "add-if-missing" as const,
    })),
    { career: prompt.droppedCareer, mode: "add-or-increment" as const },
  ];
}

export function getSelectedLowerCareerMessage(prompt: PendingLowerCareerPrompt): string {
  const selectedCount = prompt.candidates.filter((candidate) =>
    prompt.selectedUuids.includes(candidate.uuid),
  ).length;

  return selectedCount === 0
    ? ""
    : `Added ${selectedCount} lower-tier career candidate${selectedCount === 1 ? "" : "s"}.`;
}

export function isLowerCareerSelected(
  prompt: null | PendingLowerCareerPrompt,
  uuid: string,
): boolean {
  return prompt?.selectedUuids.includes(uuid) ?? false;
}

export function updateLowerCareerSelection(options: {
  candidateUuid: string;
  isAlreadyQueued: boolean;
  prompt: null | PendingLowerCareerPrompt;
  selected: boolean;
}): string[] | null {
  const { candidateUuid, isAlreadyQueued, prompt, selected } = options;

  if (!prompt || isAlreadyQueued) {
    return null;
  }

  return selected
    ? [...new Set([...prompt.selectedUuids, candidateUuid])]
    : prompt.selectedUuids.filter((uuid) => uuid !== candidateUuid);
}
