import type {
  ActorPortraitGalleryContext,
  PortraitCandidate,
} from "../../../types/portrait-gallery";
import type { NpcBuilderSettings } from "../../../types/npc-builder";

import {
  createPriorityPortraitFolderPaths,
  createPortraitSearchTerms,
  uniquePortraitCandidates,
} from "../../functions/portrait-gallery";
import { readStringPath } from "../../functions/shared/object-readers";
import { getActorPrototypeTokenImage } from "../../foundry/portrait-search/candidate-utils";

export function createActorPortraitGalleryContext(
  actor: FoundryActorDocument,
  settings: NpcBuilderSettings,
): ActorPortraitGalleryContext {
  const currentPortraitPath = actor.img?.trim() ?? "";
  const currentTokenPath = getActorPrototypeTokenImage(actor);
  const careerItems = (actor.items?.contents ?? []).filter((item) => item.type === "career");
  const preparedCareerName = readStringPath(actor.system, ["details", "career", "name"]);
  const searchValues = [
    actor.name,
    readStringPath(actor, ["Species"]),
    readStringPath(actor.system, ["details", "species", "value"]),
    readStringPath(actor.system, ["details", "species", "subspecies"]),
    preparedCareerName,
    readStringPath(actor.system, ["details", "career", "careergroup", "value"]),
    readStringPath(actor.system, ["details", "career", "class", "value"]),
    ...careerItems.flatMap(getCareerSearchValues),
  ];

  return {
    actorName: actor.name,
    actorUuid: actor.uuid,
    currentPortraitPath,
    currentTokenPath,
    excludeFullyTransparentImages: settings.excludeFullyTransparentPortraitAssets,
    excludedReferenceImagePaths: [...settings.excludedPortraitReferenceImages],
    immediateCandidates: createActorCandidates(actor, currentPortraitPath, currentTokenPath),
    includeCompendiumAssets: settings.searchCompendiumPortraitAssets,
    includeFilePickerAssets: settings.searchFoundryPortraitAssets,
    priorityFolderPaths: createPriorityPortraitFolderPaths({
      configuredFolders: settings.prioritizedPortraitFolders,
      hasCareer: Boolean(preparedCareerName) || careerItems.length > 0,
    }),
    searchTerms: createPortraitSearchTerms(searchValues),
    selectedPortraitPath: currentPortraitPath || currentTokenPath,
  };
}

function createActorCandidates(
  actor: FoundryActorDocument,
  portraitPath: string,
  tokenPath: string,
): PortraitCandidate[] {
  const candidates: PortraitCandidate[] = [];

  if (portraitPath) {
    candidates.push({
      img: portraitPath,
      key: `base-actor:${actor.uuid}`,
      label: `${actor.name} portrait`,
      source: "base-actor",
      sourceGroup: "world",
      sourceLabel: "Actor Portrait",
    });
  }

  if (tokenPath && tokenPath !== portraitPath) {
    candidates.push({
      img: tokenPath,
      key: `base-token:${actor.uuid}`,
      label: `${actor.name} prototype token`,
      source: "base-token",
      sourceGroup: "world",
      sourceLabel: "Prototype Token",
    });
  }

  return uniquePortraitCandidates(candidates);
}

function getCareerSearchValues(career: FoundryItemDocument): string[] {
  return [
    career.name,
    readStringPath(career.system, ["careergroup", "value"]),
    readStringPath(career.system, ["class", "value"]),
  ];
}
