<script setup lang="ts">
import { computed } from "vue";

import type { NpcBuilderMegaMenuGroup, NpcBuilderMegaMenuItem } from "./megamenu-types";
import type { NpcBuilderActivePage } from "./types";

import NpcBuilderMegaMenuContent from "./NpcBuilderMegaMenuContent.vue";

const props = defineProps<{
  activePage: NpcBuilderActivePage;
  canBuild: boolean;
  finalActorName: string;
  hasSpellPage: boolean;
  selectedBaseActorName: string;
}>();

const emit = defineEmits<{
  buildNpc: [];
  pageChange: [page: NpcBuilderActivePage];
}>();

const buildPages: NpcBuilderMegaMenuItem[] = [
  { page: "build-quick", summary: "Actor, one Career chain, quick Traits" },
  { page: "build-actor", summary: "Base Actor selection and summary" },
  { page: "build-careers", summary: "Ordered Career queue" },
];

const detailedPages: NpcBuilderMegaMenuItem[] = [
  { page: "detail-characteristics", summary: "Characteristic totals and advances" },
  { page: "detail-skills", summary: "Skill advances and specializations" },
  { page: "detail-talents", summary: "Talent ranks and maximums" },
  { page: "traits", summary: "Creature and NPC Trait tuning" },
  { page: "trappings", summary: "Equipment resolution and quantities" },
  { page: "mount", summary: "Combined rider and mount profile" },
];

const spellPage: NpcBuilderMegaMenuItem = {
  page: "detail-spells",
  summary: "Magic grants and dropped spells",
};

const settingsPages: NpcBuilderMegaMenuItem[] = [
  { page: "settings-folders", summary: "Base, output, and source folders" },
  { page: "settings-suggestions", summary: "Names and portrait suggestions" },
  { page: "settings-resolution", summary: "Career, trapping, and magic defaults" },
  { page: "settings-advancement", summary: "Base Actor advancement inclusion" },
];

const pageGroups = computed<NpcBuilderMegaMenuGroup[]>(() => [
  {
    columnsClass: "",
    isActive: props.activePage.startsWith("build-"),
    key: "build",
    label: "Build NPC",
    pages: buildPages,
    popoverId: "npc-builder-megamenu-build",
  },
  {
    columnsClass: "",
    isActive:
      props.activePage.startsWith("detail-") ||
      props.activePage === "traits" ||
      props.activePage === "trappings" ||
      props.activePage === "mount",
    key: "detailed",
    label: "Detailed Build",
    pages: props.hasSpellPage ? [...detailedPages, spellPage] : detailedPages,
    popoverId: "npc-builder-megamenu-detailed",
  },
  {
    isActive: props.activePage === "automatic-xp",
    key: "automatic-xp",
    label: "Automatic XP Advancement",
    page: "automatic-xp",
  },
  {
    columnsClass: "",
    isActive: props.activePage.startsWith("settings-"),
    key: "settings",
    label: "Settings",
    pages: settingsPages,
    popoverId: "npc-builder-megamenu-settings",
  },
]);

function selectPage(page: NpcBuilderActivePage, event: MouseEvent): void {
  emit("pageChange", page);
  closeOpenNavigation(event.currentTarget);
}

function closeOpenNavigation(target: EventTarget | null): void {
  if (!(target instanceof HTMLElement)) {
    return;
  }

  hidePopoverElement(target.closest("[popover]"));
  hidePopoverElement(target.closest(".dui-megamenu"));
}

function hidePopoverElement(element: Element | null): void {
  if (element instanceof HTMLElement && element.matches(":popover-open")) {
    element.hidePopover();
  }
}
</script>

<template>
  <header
    class="dui-navbar app:sticky app:top-0 app:z-20 app:flex-wrap app:gap-2 app:bg-base-200 app:px-3 app:py-2"
  >
    <div class="dui-navbar-start app:min-w-64 app:flex-1">
      <div class="app:min-w-0">
        <span class="dui-badge dui-badge-outline">WFRP4e Customizer</span>
        <h1 class="app:m-0 app:text-xl app:leading-tight">NPC Builder</h1>
        <small class="app:text-base-content/70">
          <template v-if="selectedBaseActorName">
            {{ selectedBaseActorName }} base · {{ finalActorName }}
          </template>
          <template v-else>Choose a base character, then shape the final NPC.</template>
        </small>
      </div>
    </div>

    <nav
      aria-label="NPC Builder pages"
      class="app:order-3 app:flex app:w-full app:flex-wrap app:items-center app:justify-start app:gap-2"
    >
      <button
        aria-label="Open NPC Builder navigation"
        class="dui-btn dui-btn-sm sm:app:hidden"
        popovertarget="npc-builder-megamenu"
        type="button"
      >
        Menu
      </button>

      <div
        id="npc-builder-megamenu"
        class="dui-megamenu max-sm:dui-megamenu-vertical dui-megamenu-sm app:ml-0 app:mr-auto app:border app:border-base-300 app:bg-base-100 app:p-2"
        popover
      >
        <NpcBuilderMegaMenuContent
          :active-page="activePage"
          :groups="pageGroups"
          @page-select="selectPage"
        />
      </div>
    </nav>

    <div class="dui-navbar-end app:w-auto app:shrink-0">
      <button
        class="dui-btn dui-btn-primary"
        :disabled="!canBuild"
        type="button"
        @click="emit('buildNpc')"
      >
        Build NPC
      </button>
    </div>
  </header>
</template>
