import type { NpcSpellDraftEntry } from "../../../../../types/npc-builder";

import { namesMatch } from "../draft-helpers";

export function deriveNpcSpells(options: {
  autoSelectDetectedSpells: boolean;
  customSpells: NpcSpellDraftEntry[];
  detectedSpells: NpcSpellDraftEntry[];
  selectionOverrides: Record<string, boolean>;
}): NpcSpellDraftEntry[] {
  const entries = new Map<string, NpcSpellDraftEntry>();

  for (const spell of options.detectedSpells) {
    entries.set(spell.key, {
      ...spell,
      selected: options.selectionOverrides[spell.key] ?? options.autoSelectDetectedSpells,
    });
  }

  for (const spell of options.customSpells) {
    entries.set(spell.key, {
      ...spell,
      selected: options.selectionOverrides[spell.key] ?? spell.selected,
    });
  }

  return [...entries.values()].sort(compareSpells);
}

export function getSelectedNpcSpells(spells: NpcSpellDraftEntry[]): NpcSpellDraftEntry[] {
  return spells.filter((spell) => spell.selected);
}

export function hydrateDetectedNpcSpells(options: {
  autoSelectDetectedSpells: boolean;
  selectionOverrides: Record<string, boolean>;
  spells: NpcSpellDraftEntry[];
}): NpcSpellDraftEntry[] {
  return options.spells.map((spell) => ({
    ...spell,
    selected: options.selectionOverrides[spell.key] ?? options.autoSelectDetectedSpells,
  }));
}

export function planCustomSpellAddition(options: {
  customSpells: NpcSpellDraftEntry[];
  detectedSpells: NpcSpellDraftEntry[];
  spell: NpcSpellDraftEntry;
}): { customSpells: NpcSpellDraftEntry[]; selectedDetectedSpellKey: string } {
  const matchingDetectedSpell = options.detectedSpells.find((entry) =>
    namesAndSourcesMatch(entry, options.spell),
  );

  if (matchingDetectedSpell) {
    return {
      customSpells: options.customSpells,
      selectedDetectedSpellKey: matchingDetectedSpell.key,
    };
  }

  if (options.customSpells.some((entry) => entry.key === options.spell.key)) {
    return {
      customSpells: options.customSpells,
      selectedDetectedSpellKey: "",
    };
  }

  return {
    customSpells: [...options.customSpells, { ...options.spell, selected: true }],
    selectedDetectedSpellKey: "",
  };
}

function namesAndSourcesMatch(left: NpcSpellDraftEntry, right: NpcSpellDraftEntry): boolean {
  if (left.sourceUuid && left.sourceUuid === right.sourceUuid) {
    return true;
  }

  return namesMatch(left.name, right.name);
}

function compareSpells(left: NpcSpellDraftEntry, right: NpcSpellDraftEntry): number {
  if (left.loreName !== right.loreName) {
    return left.loreName.localeCompare(right.loreName);
  }

  return left.name.localeCompare(right.name);
}
