import { isRecord } from "../../functions/shared/object-readers";
import { isFoundryActor } from "../../foundry/document-guards";
import { isSpeciesItem } from "./documents/adapter";
import { hasNativeSpeciesSupport } from "./documents/migration";
import { installSpeciesNameGetter, installSpeciesSheet } from "./actor/integration";

/** The legacy actor sheet has no Species inventory category; keep the owned Item accessible. */
export function registerSpeciesActorSheet(): void {
  if (!hasNativeSpeciesSupport()) {
    Hooks.once("setup", () => {
      const runtime = game.wfrp4e as unknown as {
        documents: { ActorWFRP4e: { prototype: object } };
      };
      installSpeciesNameGetter(runtime.documents.ActorWFRP4e.prototype);
    });
    Hooks.on("renderApplicationV2", installSpeciesSheet);
  }
  for (const type of ["Character", "NPC", "Creature", "Vehicle"]) {
    Hooks.on(`getHeaderControlsActorSheetWFRP4e${type}`, (application, controls) => {
      if (!isRecord(application) || !Array.isArray(controls)) return;
      const actor = application["document"];
      if (!isFoundryActor(actor)) return;
      const options = application["options"];
      if (!isRecord(options) || !isRecord(options["actions"])) return;
      for (const item of actor.items?.contents.filter(isSpeciesItem) ?? []) {
        const action = `openSpecies${item.id}`;
        controls.push({ action, icon: "fa-solid fa-people-group", label: `Species: ${item.name}` });
        options["actions"][action] = () => item.sheet?.render(true);
        if (actor.isOwner) {
          const remove = `removeSpecies${item.id}`;
          controls.push({
            action: remove,
            icon: "fa-solid fa-trash",
            label: `Remove Species: ${item.name}`,
          });
          options["actions"][remove] = () => item.deleteDialog();
        }
      }
    });
  }
}
