import type { SpeciesItemSystem } from "../../../../types/species/item";
import { speciesRandomizationFormulas } from "../../../functions/species-item/actor-profile";
import { decodeTalentChoices } from "../../../functions/species-item/choices";
import { isRecord } from "../../../functions/shared/object-readers";
import { assertFoundryItem } from "../../../foundry/document-guards";
import { readSpeciesItem } from "../documents/adapter";
import { randomSpeciesTalent } from "./talent-table";
import { findSpeciesGrant } from "./grant";
import { actorCharacteristicInitials } from "./profile";

export async function randomizeActorSpecies(
  actor: FoundryActorDocument,
  item: FoundryItemDocument,
  type: string,
): Promise<void> {
  if (!actor.isOwner) throw new Error("You cannot change this Actor.");
  // Dropping/chargen freezes the effective profile on the owned Item; no parent/config is needed.
  const { system } = readSpeciesItem(item);
  if (type === "characteristics") await randomizeCharacteristics(actor, system);
  else if (type === "skills") await randomizeSkills(actor, system);
  else if (type === "talents") await randomizeTalents(actor, system);
}

async function randomizeCharacteristics(actor: FoundryActorDocument, system: SpeciesItemSystem) {
  const initial = actorCharacteristicInitials(actor);
  const formulas = speciesRandomizationFormulas(system, initial);
  const update: Record<string, number> = {};
  for (const [path, formula] of Object.entries(formulas)) update[path] = await roll(formula);
  await actor.update(update);
}

async function randomizeSkills(actor: FoundryActorDocument, system: SpeciesItemSystem) {
  const pool = [...new Set(system.skills.list.filter((name) => name.trim()))];
  if (!pool.length) throw new Error("This Species Item has no Skills.");
  const selected: string[] = [];
  while (selected.length < 6 && pool.length) {
    const index = await roll(`1d${pool.length}-1`);
    selected.push(pool.splice(index, 1)[0]!);
  }
  const items = [];
  for (const [index, name] of selected.entries()) {
    const existing = actor.items?.contents.find(
      (item) => item.type === "skill" && item.name === name,
    );
    const source = (existing ?? (await findSpeciesGrant(name, "skill"))).toObject();
    const data = source["system"];
    if (!isRecord(data) || !isRecord(data["advances"]))
      throw new Error(`Skill ${name} has no advances data.`);
    const advances = data["advances"]["value"];
    if (typeof advances !== "number") throw new Error(`Skill ${name} has invalid advances.`);
    data["advances"]["value"] = Math.max(advances, index < 3 ? 5 : 3);
    items.push(source);
  }
  // Native actor.update merges existing embedded Skills and adds new ones in one operation.
  await actor.update({ items });
}

async function randomizeTalents(actor: FoundryActorDocument, system: SpeciesItemSystem) {
  const grants = decodeTalentChoices(system.talents.choices);
  const talents: FoundryItemSource[] = [];
  for (const grant of grants) {
    const choice = grant.choices[await roll(`1d${grant.choices.length}-1`)]!;
    const item = choice.item?.uuid
      ? assertFoundryItem(await fromUuid(choice.item.uuid), `Talent ${choice.name} is unavailable.`)
      : await findSpeciesGrant(choice.name, "talent");
    if (item.type !== "talent") throw new Error(`${choice.name} is not a Talent.`);
    talents.push(item.toObject());
  }
  for (let index = 0; index < (system.talents.random ?? 0); index++)
    talents.push((await randomSpeciesTalent(system.tables.talents)).toObject());
  if (!talents.length) throw new Error("This Species Item has no Talents.");
  await actor.createEmbeddedDocuments("Item", talents);
}

async function roll(formula: string): Promise<number> {
  return (await new Roll(formula).roll({ allowInteractive: false })).total;
}
