import type {
  NpcBaseActorSummary,
  NpcBuilderSettings,
  NpcCareerGrantTotals,
  NpcCareerQueueEntry,
} from "../../../../types/npc-builder";

export function findSelectedBaseActor(
  baseActors: NpcBaseActorSummary[],
  selectedUuid: string,
): NpcBaseActorSummary | null {
  return baseActors.find((actor) => actor.uuid === selectedUuid) ?? null;
}

export function getFinalCareer(careers: NpcCareerQueueEntry[]): NpcCareerQueueEntry | null {
  return careers.at(-1) ?? null;
}

export function getSuggestedActorName(options: {
  finalCareer: NpcCareerQueueEntry | null;
  selectedBaseActor: NpcBaseActorSummary | null;
  settings: NpcBuilderSettings;
}): string {
  const careerName = options.finalCareer?.name;
  const speciesName =
    options.settings.includeSpeciesInName && options.selectedBaseActor?.species
      ? options.selectedBaseActor.species
      : "";

  if (careerName && speciesName) {
    return `${speciesName} ${careerName}`;
  }

  if (careerName) {
    return careerName;
  }

  return options.selectedBaseActor ? `${options.selectedBaseActor.name} NPC` : "New NPC";
}

export function getFinalActorName(actorName: string, suggestedActorName: string): string {
  return actorName.trim() || suggestedActorName;
}

export function getDefaultPortraitPath(options: {
  finalCareer: NpcCareerQueueEntry | null;
  selectedBaseActor: NpcBaseActorSummary | null;
}): string {
  return (
    options.finalCareer?.img ||
    options.selectedBaseActor?.prototypeTokenImg ||
    options.selectedBaseActor?.img ||
    ""
  );
}

export function getFinalPortraitPath(selectedPortraitPath: string, defaultPortraitPath: string) {
  return selectedPortraitPath || defaultPortraitPath;
}

export function calculateCareerGrantTotals(careers: NpcCareerQueueEntry[]): NpcCareerGrantTotals {
  const totals: NpcCareerGrantTotals = {
    characteristics: 0,
    skills: 0,
    talents: 0,
    trappings: 0,
  };

  for (const career of careers) {
    totals.characteristics += career.grants.characteristics.length * career.quantity;
    totals.skills += career.grants.skills.length * career.quantity;
    totals.talents += career.grants.talents.length * career.quantity;
    totals.trappings += career.grants.trappings.length * career.quantity;
  }

  return totals;
}
