<script setup lang="ts">
import { storeToRefs } from "pinia";
import { computed, ref, useId } from "vue";

import type { NpcBuilderBridge } from "../../../../types/npc-builder";
import type { NpcBuilderActiveTab } from "./NpcBuilderApp/types";

import { useNpcBuilderStore } from "../state";
import LowerCareerPromptContent from "./components/LowerCareerPromptContent.vue";
import NpcBuilderDialog from "./components/NpcBuilderDialog.vue";
import NpcBuilderAdvancementsTab from "./components/NpcBuilderAdvancementsTab.vue";
import NpcBuilderBuildTab from "./components/NpcBuilderBuildTab.vue";
import NpcBuilderMountTab from "./components/NpcBuilderMountTab.vue";
import NpcBuilderSettingsTab from "./components/NpcBuilderSettingsTab.vue";
import NpcBuilderSpellsTab from "./components/NpcBuilderSpellsTab.vue";
import NpcBuilderTraitsTab from "./components/NpcBuilderTraitsTab.vue";
import NpcBuilderTrappingsTab from "./components/NpcBuilderTrappingsTab.vue";
import SkillResolutionPromptContent from "./components/SkillResolutionPromptContent.vue";
import NpcBuilderMegaMenu from "./NpcBuilderApp/NpcBuilderMegaMenu.vue";
import {
  getPageLabel,
  isAdvancementPage,
  isBuildPage,
  isSettingsPage,
} from "./NpcBuilderApp/types";
import { useNpcBuilderApplicationDrop } from "./NpcBuilderApp/useNpcBuilderApplicationDrop";
import { useNpcBuilderBuild } from "./NpcBuilderApp/useNpcBuilderBuild";
import { useNpcBuilderCareerDropWorkflow } from "./NpcBuilderApp/useNpcBuilderCareerDropWorkflow";
import { useNpcBuilderInitialData } from "./NpcBuilderApp/useNpcBuilderInitialData";
import { useNpcBuilderMetadataLookups } from "./NpcBuilderApp/useNpcBuilderMetadataLookups";

const props = defineProps<{
  bridge: NpcBuilderBridge;
}>();

const store = useNpcBuilderStore();
const { finalActorName, hasMagicAccess, selectedBaseActor, selectedSpells } = storeToRefs(store);

const activeTab = ref<NpcBuilderActiveTab>("build-quick");
const tabIdPrefix = useId();
const hasSpellPage = computed(() => hasMagicAccess.value || selectedSpells.value.length > 0);
const {
  addCareerSummaryWithLowerCareerMode,
  buildMessage,
  chooseSkillSpecialization,
  confirmLowerCareerPrompt,
  confirmSkillResolutionPrompt,
  dismissLowerCareerPrompt,
  dismissSkillResolutionPrompt,
  errorMessage,
  getSkillResolutionLabel,
  isCareerQueued,
  isFindingLowerCareers,
  isLowerCareerSelected,
  lowerCareerCandidateGroups,
  pendingLowerCareerPrompt,
  pendingSkillResolutionPrompt,
  setLowerCareerSelected,
  usesFreeformSkillSpecialization,
} = useNpcBuilderCareerDropWorkflow(props.bridge);

const { buildNpc, canBuild } = useNpcBuilderBuild(
  props.bridge,
  activeTab,
  buildMessage,
  errorMessage,
  isFindingLowerCareers,
);

const { isLoadingActors, isLoadingBaseDraft, traitDifficultyOptions } = useNpcBuilderInitialData(
  props.bridge,
  errorMessage,
);

const { metadataLookupError, metadataLookupStatus, retryMetadataLookups } =
  useNpcBuilderMetadataLookups(props.bridge);

const {
  handleApplicationDragEnter,
  handleApplicationDragLeave,
  handleApplicationDragOver,
  handleApplicationDrop,
  isApplicationDragOver,
} = useNpcBuilderApplicationDrop(
  props.bridge,
  activeTab,
  addCareerSummaryWithLowerCareerMode,
  errorMessage,
);
</script>

<template>
  <section
    aria-label="NPC Builder"
    class="app:flex app:min-h-full app:flex-col"
    :class="{ 'app:ring-2 app:ring-info': isApplicationDragOver }"
    @dragenter="handleApplicationDragEnter"
    @dragleave="handleApplicationDragLeave"
    @dragover="handleApplicationDragOver"
    @drop="handleApplicationDrop"
  >
    <NpcBuilderMegaMenu
      :active-page="activeTab"
      :can-build="canBuild"
      :final-actor-name="finalActorName"
      :has-spell-page="hasSpellPage"
      :selected-base-actor-name="selectedBaseActor?.name ?? ''"
      @build-npc="buildNpc"
      @page-change="activeTab = $event"
    />

    <NpcBuilderDialog
      :open="pendingLowerCareerPrompt !== null"
      title="Add Lower-Tier Careers?"
      @close="dismissLowerCareerPrompt"
    >
      <LowerCareerPromptContent
        v-if="pendingLowerCareerPrompt"
        :candidate-groups="lowerCareerCandidateGroups"
        :is-career-queued="isCareerQueued"
        :is-lower-career-selected="isLowerCareerSelected"
        :prompt="pendingLowerCareerPrompt"
        @add-dropped-only="dismissLowerCareerPrompt"
        @add-selected="confirmLowerCareerPrompt"
        @lower-career-selected="setLowerCareerSelected"
      />
    </NpcBuilderDialog>

    <NpcBuilderDialog
      :open="pendingSkillResolutionPrompt !== null"
      title="Resolve Skill Specializations"
      @close="dismissSkillResolutionPrompt"
    >
      <SkillResolutionPromptContent
        v-if="pendingSkillResolutionPrompt"
        :get-skill-resolution-label="getSkillResolutionLabel"
        :prompt="pendingSkillResolutionPrompt"
        :uses-freeform-skill-specialization="usesFreeformSkillSpecialization"
        @add-without-resolving="dismissSkillResolutionPrompt"
        @apply-specializations="confirmSkillResolutionPrompt"
        @choose-skill-specialization="chooseSkillSpecialization"
      />
    </NpcBuilderDialog>

    <section
      :id="`${tabIdPrefix}-panel`"
      :aria-label="getPageLabel(activeTab)"
      class="app:grid app:flex-1 app:content-start app:gap-3 app:p-3"
    >
      <p v-if="errorMessage" class="dui-alert dui-alert-error" role="alert">
        {{ errorMessage }}
      </p>
      <p v-else-if="buildMessage" aria-live="polite" class="dui-alert dui-alert-info" role="status">
        {{ buildMessage }}
      </p>
      <p
        v-else-if="isApplicationDragOver"
        aria-live="polite"
        class="dui-alert dui-alert-info"
        role="status"
      >
        Release to add this document to the NPC draft.
      </p>

      <div
        v-if="metadataLookupStatus === 'degraded'"
        aria-live="polite"
        class="dui-alert dui-alert-warning"
        role="status"
      >
        <span>{{ metadataLookupError }}</span>
        <span>Advancement rows remain editable with reduced metadata.</span>
        <button class="dui-btn dui-btn-sm" type="button" @click="retryMetadataLookups">
          Retry Metadata
        </button>
      </div>

      <NpcBuilderSettingsTab
        v-if="isSettingsPage(activeTab)"
        :bridge="props.bridge"
        :page="activeTab"
      />

      <NpcBuilderAdvancementsTab v-else-if="isAdvancementPage(activeTab)" :page="activeTab" />

      <NpcBuilderTrappingsTab v-else-if="activeTab === 'trappings'" :bridge="props.bridge" />

      <NpcBuilderTraitsTab
        v-else-if="activeTab === 'traits'"
        :difficulty-options="traitDifficultyOptions"
      />

      <NpcBuilderSpellsTab v-else-if="activeTab === 'detail-spells'" :bridge="props.bridge" />

      <NpcBuilderMountTab v-else-if="activeTab === 'mount'" :bridge="props.bridge" />

      <NpcBuilderBuildTab
        v-else-if="isBuildPage(activeTab)"
        :bridge="props.bridge"
        :is-loading-actors="isLoadingActors"
        :is-loading-base-draft="isLoadingBaseDraft"
        :page="activeTab"
      />
    </section>
  </section>
</template>
