import type { EffectBuilderDraft } from "../../../../types/effect-builders";

export function detailFormulaProblems(draft: EffectBuilderDraft): string[] {
  const formulas = [draft.ageFormula.trim(), draft.heightFormula.trim()];
  if (!formulas.some(Boolean)) return ["Enter an age formula, a height formula, or both."];
  if (formulas.some((formula) => formula.includes("@")))
    return ["Use self-contained formulas without Actor data references (@)."];
  for (const [index, formula] of formulas.entries()) {
    if (formula && !Number.isNaN(Number(formula))) {
      const value = Number(formula);
      if (!Number.isSafeInteger(value) || value < (index === 0 ? 0 : 1))
        return [
          index === 0
            ? "Age must be a whole number of zero or more."
            : "Height must be a positive whole number of inches.",
        ];
    }
  }
  return [];
}

export function buildAgeHeightEffect(draft: EffectBuilderDraft): Record<string, unknown> {
  const name = draft.name.trim();
  return {
    name,
    img: "icons/svg/clockwork.svg",
    disabled: false,
    transfer: true,
    description:
      "<p>Species age is measured in years and height in total inches. When added to an actor, fills only missing values. Existing values are preserved.</p>",
    system: {
      transferData: { type: "document", documentType: "Actor" },
      changes: (["age", "height"] as const).flatMap((field) => {
        const value = draft[field === "age" ? "ageFormula" : "heightFormula"].trim();
        return value
          ? [
              {
                key: `flags.drowsy.${field}Formula`,
                value,
                type: "override",
                phase: "initial",
                mode: 5,
                priority: 50,
              },
            ]
          : [];
      }),
      scriptData: [
        {
          label: name,
          trigger: "immediate",
          script: DETAIL_DEFAULTS_SCRIPT,
          options: { deleteEffect: false },
        },
      ],
    },
  };
}

// Keep this portable script aligned with the shipped Species effects; covered by a parity test.
const DETAIL_DEFAULTS_SCRIPT = [
  "const actor = this.actor;",
  "if (!actor || this.effect.disabled) return;",
  "",
  "const updates = {};",
  'for (const field of ["age", "height"]) {',
  "  const detail = actor.system.details?.[field];",
  '  if (!detail || (detail.value != null && String(detail.value).trim() !== "")) continue;',
  "",
  "  const change = this.effect.changes.find((entry) => entry.key === `flags.drowsy.${field}Formula`);",
  "  if (!change) continue;",
  "  const value = change.value;",
  "  const formula =",
  '    typeof value === "string"',
  "      ? value",
  '      : typeof value === "number" && Number.isFinite(value)',
  "        ? String(value)",
  '        : "";',
  "  const override =",
  "    change.type !== undefined",
  '      ? change.type === "override"',
  "      : change.mode === CONST.ACTIVE_EFFECT_MODES.OVERRIDE;",
  "  if (!override || !Roll.validate(formula)) {",
  "    this.script.notification(",
  "      `Invalid ${field} formula. Use an Override change with a dice formula.`,",
  '      "error",',
  "    );",
  "    return;",
  "  }",
  "  const roll = await new Roll(formula).roll({ allowInteractive: false });",
  '  if (!Number.isSafeInteger(roll.total) || roll.total < (field === "height" ? 1 : 0)) {',
  "    this.script.notification(",
  "      `${field} formula returned an invalid value. Existing details were kept.`,",
  '      "error",',
  "    );",
  "    return;",
  "  }",
  "  updates[`system.details.${field}.value`] =",
  '    field === "age" ? String(roll.total) : `${Math.floor(roll.total / 12)}\'${roll.total % 12}`;',
  "}",
  "",
  "if (Object.keys(updates).length) await actor.update(updates);",
].join("\n");
