import type { NpcBuilderBuildRequest, NpcBuilderBuildResult } from "../../../../types/npc-builder";

import { readStringPath } from "../../../functions/shared/object-readers";
import { assertFoundryActor } from "../../../foundry/document-guards";
import { getActorSpecies } from "./actors";
import { applyAdvancements } from "./advancements";
import { embedCompletedCareers, prepareCompletedCareerSources } from "./careers";
import { getFolderByUuid } from "./folders";
import { applySpells } from "./magic";
import { applyCombinedProfile } from "./mounts";
import { applyTraits, removeDisabledTraitSources } from "./traits";
import { applyTrappings } from "./trappings";

export async function buildNpc(request: NpcBuilderBuildRequest): Promise<NpcBuilderBuildResult> {
  if (request.mountActorUuid && request.mountActorUuid === request.baseActorUuid) {
    throw new Error("The rider and mount must be different Actors.");
  }

  const careerSources = await prepareCompletedCareerSources(request.careers);
  const createdActor = await createActorFromBase(request);

  if (!createdActor) {
    throw new Error("Foundry did not create the NPC Actor.");
  }

  const actorName = getBuildActorName(request);
  const finalCareer = request.careers.at(-1);
  const actorUpdate: Record<string, unknown> = {
    "name": actorName,
    "prototypeToken.name": actorName,
  };
  const existingNotes = readStringPath(createdActor.system, ["details", "gmnotes", "value"]);
  const cleanedNotes = removeExistingEstimatedXpNote(existingNotes);

  if (cleanedNotes !== existingNotes) {
    actorUpdate["system.details.gmnotes.value"] = cleanedNotes;
  }

  const portraitPath = request.portraitPath || finalCareer?.img || "";

  if (portraitPath) {
    actorUpdate["img"] = portraitPath;
    actorUpdate["prototypeToken.texture.src"] = portraitPath;
  }

  await createdActor.update(actorUpdate);
  await embedCompletedCareers(createdActor, careerSources);
  await applyAdvancements(createdActor, request.advancements);
  await applyTraits(createdActor, request.traits);

  if (request.mountActorUuid) {
    await applyCombinedProfile(createdActor, request.mountActorUuid);
  }

  await applyTrappings(createdActor, request.trappings);
  await applySpells(createdActor, request.spells);

  createdActor.sheet?.render(true);
  ui.notifications?.info(`Created NPC "${actorName}".`);

  return {
    name: actorName,
    uuid: createdActor.uuid,
  };
}

function removeExistingEstimatedXpNote(notes: string): string {
  return notes
    .replaceAll(
      /(?:<hr\s*\/?>)?<section data-wfrp-customizer-npc-xp="true">[\S\s]*?<\/section>/g,
      "",
    )
    .trim();
}

async function createActorFromBase(
  request: NpcBuilderBuildRequest,
): Promise<FoundryActorDocument | null | undefined> {
  const baseActor = assertFoundryActor(await fromUuid(request.baseActorUuid));
  const actorData = baseActor.toObject();
  const outputFolder = getFolderByUuid(request.settings.outputActorFolderUuid);

  // Foundry document sources keep their database identity in `_id` and folder
  // placement in `folder`. Both must be reset before creating a new Actor.
  delete actorData._id;
  delete actorData.folder;
  actorData["type"] = "npc";
  removeDisabledTraitSources(actorData);

  if (outputFolder) {
    actorData.folder = outputFolder.id;
  }

  return await Actor.create(actorData);
}

function getBuildActorName(request: NpcBuilderBuildRequest): string {
  if (!request.settings.includeSpeciesInName) {
    return request.actorName;
  }

  const baseActor = game.actors.contents.find((actor) => actor.uuid === request.baseActorUuid);
  const species = baseActor ? getActorSpecies(baseActor) : "";

  if (!species || request.actorName.toLocaleLowerCase().includes(species.toLocaleLowerCase())) {
    return request.actorName;
  }

  return `${species} ${request.actorName}`;
}
