import type { NpcPortraitSearchAvailability } from "../../../../../types/npc-builder";

export function getPortraitSearchStatusLabel(
  availability: NpcPortraitSearchAvailability | null,
): string {
  if (!availability) {
    return "Checking Dig Down integration.";
  }

  if (!availability.digDownActive) {
    return "Install and enable Dig Down to search local files for portrait suggestions.";
  }

  if (!availability.digDownDeepFileSearchEnabled) {
    return "Dig Down is active, but its Deep File Search setting is disabled.";
  }

  if (!availability.digDownCacheReady) {
    return "Dig Down is active; its file cache is still building or unavailable.";
  }

  return `Dig Down cache ready with ${availability.digDownIndexedFileCount} indexed files.`;
}
