import { storeToRefs } from "pinia";
import { computed } from "vue";

import type { NpcQuickTraitSummary } from "../../../../../../types/npc-builder";
import type { BuildTraitOption } from "./types";

import { useNpcBuilderStore } from "../../../state";

export function useBuildTraits() {
  const store = useNpcBuilderStore();
  const { optionalTraits, quickTraits, traits } = storeToRefs(store);

  const selectedTraitNames = computed(() => {
    return new Set(traits.value.map((trait) => normalizeTraitName(trait.name)));
  });

  const optionalTraitOptions = computed(() => {
    return optionalTraits.value.map(createTraitOption);
  });

  const displayedQuickTraitOptions = computed(() => {
    const optionalTraitNames = new Set(
      optionalTraits.value.map((trait) => normalizeTraitName(trait.name)),
    );

    return quickTraits.value
      .filter((trait) => !optionalTraitNames.has(normalizeTraitName(trait.name)))
      .map(createTraitOption);
  });

  function createTraitOption(trait: NpcQuickTraitSummary): BuildTraitOption {
    return {
      ...trait,
      isSelected: selectedTraitNames.value.has(normalizeTraitName(trait.name)),
    };
  }

  function toggleQuickTrait(trait: NpcQuickTraitSummary): void {
    const isSelected = selectedTraitNames.value.has(normalizeTraitName(trait.name));

    store.setQuickTraitSelected(trait, !isSelected);
  }

  function toggleOptionalTrait(trait: NpcQuickTraitSummary): void {
    const isSelected = selectedTraitNames.value.has(normalizeTraitName(trait.name));

    store.setOptionalTraitSelected(trait, !isSelected);
  }

  return {
    displayedQuickTraitOptions,
    optionalTraitOptions,
    toggleOptionalTrait,
    toggleQuickTrait,
  };
}

function normalizeTraitName(name: string): string {
  return name.trim().toLocaleLowerCase();
}
