import type { GrantItemsEffectRecipe } from "../../../types/item-grants";

export function buildGrantItemsScript(selection: string[], recipe: GrantItemsEffectRecipe): string {
  const createOptions =
    recipe.lifetime === "linked-to-effect" ? "{ fromEffect: this.effect.id }" : "{}";
  return [
    "// Generated by Drowsy's WFRP4e Customizers; runs using native Foundry and WFRP APIs.",
    ...selection,
    "const itemDataToCreate = [];",
    "for (const uuid of itemUuids) {",
    "  const sourceItem = await fromUuid(uuid);",
    '  if (sourceItem?.documentName !== "Item") throw new Error("Could not resolve Item UUID: " + uuid);',
    "  const itemData = sourceItem.toObject();",
    "  delete itemData._id;",
    "  itemDataToCreate.push(itemData);",
    "}",
    "if (!itemDataToCreate.length) return;",
    `await this.actor.createEmbeddedDocuments("Item", itemDataToCreate, ${createOptions});`,
    'this.script.notification("Added " + itemDataToCreate.length + " granted item(s).");',
    ...(recipe.ownerAction === "delete-after-grant"
      ? ["if (this.item) {", "  await this.item.delete({ skipDeletingItems: true });", "}"]
      : []),
  ].join("\n");
}
