<script setup lang="ts">
import type {
  NpcCareerQueueEntry,
  NpcPortraitCandidate,
  NpcPortraitSearchProgress,
} from "../../../../../../types/npc-builder";

import { getPortraitCandidateAriaLabel, getPortraitCandidateTitle, toInitials } from "./labels";

defineProps<{
  compactPortraitCandidates: NpcPortraitCandidate[];
  finalCareer: NpcCareerQueueEntry | null;
  finalPortraitPath: string;
  hiddenPortraitCandidateCount: number;
  isLoadingPortraitCandidates: boolean;
  portraitCandidates: NpcPortraitCandidate[];
  portraitSearchProgress: NpcPortraitSearchProgress | null;
  portraitSearchProgressLabel: string;
  portraitSearchProgressValue: number;
  selectedPortraitCandidate: NpcPortraitCandidate | null;
  selectedPortraitCandidateKey: string;
}>();

const emit = defineEmits<{
  openGallery: [];
  selectPortrait: [candidate: NpcPortraitCandidate];
}>();
</script>

<template>
  <section class="app:grid app:gap-3">
    <div class="app:flex app:flex-wrap app:items-start app:gap-3">
      <button
        :aria-label="portraitCandidates.length ? 'Open portrait gallery' : 'No portraits available'"
        class="dui-btn dui-btn-square app:h-32 app:w-32 app:shrink-0 app:overflow-hidden app:p-1"
        :disabled="!portraitCandidates.length"
        title="Open portrait gallery"
        type="button"
        @click="emit('openGallery')"
      >
        <img
          v-if="finalPortraitPath"
          alt=""
          class="app:h-full app:w-full app:rounded-box app:object-cover"
          height="192"
          :src="finalPortraitPath"
          width="192"
        />
        <strong v-else-if="finalCareer">
          {{ toInitials(finalCareer.name) }}
        </strong>
        <span v-else>No portrait</span>
      </button>

      <div class="app:flex app:min-w-48 app:flex-1 app:flex-col app:items-start app:gap-2">
        <span class="dui-badge dui-badge-outline">Current portrait</span>
        <strong>{{ selectedPortraitCandidate?.label ?? "No portrait selected" }}</strong>
        <small
          v-if="finalPortraitPath"
          class="app:break-all app:text-base-content/70"
          :title="finalPortraitPath"
        >
          {{ finalPortraitPath }}
        </small>
        <span v-else class="app:text-base-content/70">
          A Career or base Actor image will be used when available.
        </span>
        <button
          class="dui-btn dui-btn-outline dui-btn-sm"
          :disabled="!portraitCandidates.length"
          type="button"
          @click="emit('openGallery')"
        >
          Browse {{ portraitCandidates.length }} portraits
        </button>
      </div>
    </div>

    <div
      v-if="isLoadingPortraitCandidates && portraitSearchProgress"
      aria-live="polite"
      role="status"
    >
      <progress
        aria-label="Portrait search progress"
        class="dui-progress dui-progress-info app:w-full"
        :value="portraitSearchProgressValue"
        max="100"
      />
      <small>{{ portraitSearchProgressLabel }}</small>
    </div>

    <fieldset v-if="portraitCandidates.length || isLoadingPortraitCandidates" class="dui-fieldset">
      <legend class="dui-fieldset-legend">
        <span>Quick picks</span>
        <span v-if="isLoadingPortraitCandidates">Updating...</span>
        <span v-else>{{ portraitCandidates.length }} options</span>
      </legend>
      <div class="app:flex app:flex-wrap app:gap-2">
        <button
          v-for="candidate in compactPortraitCandidates"
          :key="candidate.key"
          :aria-label="getPortraitCandidateAriaLabel(candidate)"
          :aria-pressed="candidate.key === selectedPortraitCandidateKey"
          class="dui-btn dui-btn-square app:overflow-hidden app:p-1"
          :class="{
            'dui-btn-active dui-btn-outline': candidate.key === selectedPortraitCandidateKey,
          }"
          :title="getPortraitCandidateTitle(candidate)"
          type="button"
          @click="emit('selectPortrait', candidate)"
        >
          <img
            alt=""
            class="app:h-full app:w-full app:rounded-box app:object-cover"
            height="64"
            loading="lazy"
            :src="candidate.img"
            width="64"
          />
        </button>
        <button
          v-if="hiddenPortraitCandidateCount > 0"
          :aria-label="`Open ${hiddenPortraitCandidateCount} more portrait options`"
          class="dui-btn dui-btn-square"
          type="button"
          @click="emit('openGallery')"
        >
          +{{ hiddenPortraitCandidateCount }}
        </button>
      </div>
    </fieldset>
  </section>
</template>
