import type {
  DocumentDropBridge,
  ManualDocumentEntry,
  ManualDocumentType,
} from "../../types/foundry/document-drop";

type SupportedDocumentType = Exclude<ManualDocumentType, "auto">;

function createDropData(entry: ManualDocumentEntry): string {
  const trimmedValue = entry.value.trim();

  if (!trimmedValue) {
    return "";
  }

  if (isJsonDropPayload(trimmedValue)) {
    return trimmedValue;
  }

  const uuid = extractUuid(trimmedValue);
  const type = inferDocumentTypeFromUuid(uuid, entry.documentType);

  if (!type) {
    return "";
  }

  // Manual entry deliberately produces the same narrow JSON shape emitted by
  // Foundry drag operations so every existing app bridge has one input path.
  if (looksLikeDocumentUuid(uuid)) {
    return JSON.stringify({ type, uuid });
  }

  return JSON.stringify({ id: uuid, type });
}

function startDocumentPick(onDropData: (data: string) => void): () => void {
  let isListening = true;

  function stop(): void {
    if (!isListening) {
      return;
    }

    isListening = false;
    document.removeEventListener("click", handleClick, true);
  }

  function handleClick(event: MouseEvent): void {
    const target = event.target;

    if (!(target instanceof Element)) {
      return;
    }

    const dropData = createDropDataFromElement(target);

    if (!dropData) {
      return;
    }

    // Capture mode lets the picker claim a recognized Foundry row before its
    // normal sheet-opening click runs. Unrecognized clicks remain untouched so
    // the user can keep navigating while the picker waits.
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
    stop();
    onDropData(dropData);
  }

  document.addEventListener("click", handleClick, true);

  return stop;
}

function createDropDataFromElement(target: Element): string {
  // Quick Insert exposes full UUIDs, while Foundry v13 world sidebars expose
  // entry ids plus document context on the row or one of its ancestors.
  const documentElement = target.closest<HTMLElement>(
    "[data-uuid], [data-document-uuid], [data-entry-uuid], [data-document-id], [data-entry-id], [data-pack]",
  );

  if (!documentElement) {
    return "";
  }

  const uuid =
    documentElement.dataset["uuid"] ||
    documentElement.dataset["documentUuid"] ||
    documentElement.dataset["entryUuid"] ||
    "";

  if (uuid) {
    return createDropDataFromUuid(uuid);
  }

  const id = documentElement.dataset["documentId"] || documentElement.dataset["entryId"] || "";
  const type = inferDocumentTypeFromElement(documentElement);

  if (!id || !type) {
    return "";
  }

  const pack =
    documentElement.dataset["pack"] ||
    documentElement.closest<HTMLElement>("[data-pack]")?.dataset["pack"] ||
    compendiumPackForElement(documentElement);

  if (pack) {
    return JSON.stringify({ type, uuid: `Compendium.${pack}.${id}` });
  }

  if (documentElement.closest(".compendium-directory")) return "";

  return JSON.stringify({ type, uuid: `${type}.${id}` });
}

function compendiumPackForElement(element: HTMLElement): string {
  const frame = element.closest<HTMLElement>(".compendium-directory");
  if (!frame) return "";
  // Foundry v14 compendium rows have entry IDs but no data-pack ancestor. The app ID
  // uses its collection name with dots replaced by underscores; match known packs.
  return (
    Array.from(game.packs ?? []).find(
      (pack) => frame.id === `Compendium-${pack.collection?.replaceAll(".", "_")}`,
    )?.collection ?? ""
  );
}

function createDropDataFromUuid(uuid: string): string {
  const type = inferDocumentTypeFromUuid(uuid, "auto");

  return type ? JSON.stringify({ type, uuid }) : "";
}

function extractUuid(value: string): string {
  const uuidMatch = /@UUID\[([^\]]+)]/.exec(value);

  return uuidMatch?.[1]?.trim() ?? value;
}

function inferDocumentTypeFromElement(element: HTMLElement): "" | SupportedDocumentType {
  const documentName =
    element.dataset["documentName"] ||
    element.dataset["type"] ||
    element.closest<HTMLElement>("[data-document-name]")?.dataset["documentName"] ||
    "";

  if (isSupportedDocumentType(documentName)) {
    return documentName;
  }

  if (element.classList.contains("actor")) {
    return "Actor";
  }

  if (element.classList.contains("item")) {
    return "Item";
  }

  if (element.classList.contains("journal")) {
    return "JournalEntry";
  }

  if (element.closest("#actors")) {
    return "Actor";
  }

  if (element.closest("#items")) {
    return "Item";
  }

  if (element.closest("#journal")) {
    return "JournalEntry";
  }

  return "";
}

function inferDocumentTypeFromUuid(
  uuid: string,
  selectedType: ManualDocumentType,
): "" | SupportedDocumentType {
  if (/^actor\./i.test(uuid) || /\.actors(\.|$)/i.test(uuid)) {
    return "Actor";
  }

  if (/^item\./i.test(uuid) || /\.items(\.|$)/i.test(uuid)) {
    return "Item";
  }

  if (/journalentrypage\./i.test(uuid) || /\.journalentrypage\./i.test(uuid)) {
    return "JournalEntryPage";
  }

  if (/^journalentry\./i.test(uuid) || /\.journals(\.|$)/i.test(uuid)) {
    return "JournalEntry";
  }

  return selectedType === "auto" ? "Item" : selectedType;
}

function isSupportedDocumentType(value: string): value is SupportedDocumentType {
  return (
    value === "Actor" ||
    value === "Item" ||
    value === "JournalEntry" ||
    value === "JournalEntryPage"
  );
}

function isJsonDropPayload(value: string): boolean {
  if (!value.startsWith("{")) {
    return false;
  }

  try {
    const parsedValue = JSON.parse(value) as { type?: unknown };

    return typeof parsedValue.type === "string";
  } catch {
    return false;
  }
}

function looksLikeDocumentUuid(value: string): boolean {
  return /^(actor|item|journalentry|journalentrypage|compendium)\./i.test(value);
}

export const foundryDocumentDropBridge: DocumentDropBridge = {
  createDropData,
  startDocumentPick,
};
