<script setup lang="ts">
import { onMounted } from "vue";
import type { SpeciesTableBridge } from "../../../../types/species/table";
import { useSpeciesTableStore } from "../state";
import ApplicationShell from "../../shared/view/components/ApplicationShell.vue";
import DocumentDrop from "../../shared/view/components/DocumentDrop.vue";
import SpeciesTableRows from "./SpeciesTableRows.vue";

const props = defineProps<{ id: string; bridge: SpeciesTableBridge; close: () => void }>();
const store = useSpeciesTableStore(props.id);
store.configure(props.bridge);
onMounted(() => store.load());
</script>

<template>
  <ApplicationShell
    title="Species Table Editor"
    description="Choose which species can be rolled during character creation, and how often."
  >
    <div v-if="store.error" class="dui-alert dui-alert-error" role="alert">{{ store.error }}</div>
    <div v-if="store.message" class="dui-alert dui-alert-info" role="status">
      {{ store.message }}
    </div>
    <p v-if="store.busy" role="status">Working…</p>
    <fieldset v-if="store.loaded" class="dui-fieldset app:min-w-0" :disabled="store.busy">
      <label :for="`${id}-name`" class="dui-label">Table name</label>
      <input
        :id="`${id}-name`"
        v-model="store.draft.name"
        aria-label="Table name"
        class="dui-input app:w-full"
      />
      <p v-if="store.draft.ownership === 'external'">
        Saving creates a Customizer copy of this table. The source table is preserved.
      </p>
      <p v-else-if="store.draft.isRegistered">This is the world's active Species table.</p>
      <DocumentDrop
        title="Species Items"
        description="Drop a Species Item here. World and compendium Items are linked directly."
        variant="compact"
        :disabled="store.busy"
        @drop-data="store.drop"
      />
      <p>A subspecies row selects that subspecies directly.</p>
      <label :for="`${id}-species`" class="dui-label">Add an available species</label>
      <div class="app:flex app:flex-wrap app:gap-2">
        <select
          :id="`${id}-species`"
          v-model="store.selected"
          aria-label="Add an available species"
          class="dui-select app:max-w-full"
        >
          <option value="">Choose a species…</option>
          <option v-for="option in store.available" :key="option.key" :value="option.key">
            {{ option.label }}
          </option>
        </select>
        <button
          type="button"
          class="dui-btn"
          :disabled="!store.selected"
          @click="store.addSelected"
        >
          Add species
        </button>
      </div>
      <SpeciesTableRows :id="id" />
      <label
        v-if="!store.draft.isRegistered || store.draft.ownership === 'external'"
        class="dui-label"
      >
        <input v-model="store.register" type="checkbox" class="dui-checkbox" />
        Use this table for the world's species rolls
      </label>
    </fieldset>
    <ul v-if="store.loaded && store.problems.length" class="dui-list" aria-label="Before saving">
      <li v-for="problem in store.problems" :key="problem">{{ problem }}</li>
    </ul>
    <template #actions>
      <button
        type="button"
        class="dui-btn dui-btn-primary"
        :disabled="!store.ready"
        @click="store.save"
      >
        Save table
      </button>
      <button type="button" class="dui-btn" :disabled="store.busy" @click="store.load">
        Reload saved table
      </button>
      <button type="button" class="dui-btn dui-btn-ghost" :disabled="store.busy" @click="close">
        Close
      </button>
    </template>
  </ApplicationShell>
</template>
