<script setup lang="ts">
import { useSpeciesItemStore } from "../state";
import type { WfrpCharacteristicKey } from "../../../../types/wfrp4e/characteristics";
import SpeciesItemGrants from "./SpeciesItemGrants.vue";
import SpeciesItemTables from "./SpeciesItemTables.vue";
import SpeciesItemReference from "./SpeciesItemReference.vue";
const props = defineProps<{ uuid: string; editable: boolean }>();
const store = useSpeciesItemStore(props.uuid);
const labels = {
  ws: "WS",
  bs: "BS",
  s: "S",
  t: "T",
  i: "I",
  ag: "Ag",
  dex: "Dex",
  int: "Int",
  wp: "WP",
  fel: "Fel",
};
const characteristics = Object.keys(labels) as WfrpCharacteristicKey[];
const pools = [
  { key: "fate", label: "Fate" },
  { key: "resilience", label: "Resilience" },
  { key: "extra", label: "Extra" },
] as const;
</script>

<template>
  <fieldset class="dui-fieldset" :disabled="!editable">
    <legend class="app:sr-only">Species details</legend>
    <SpeciesItemReference
      :uuid="uuid"
      label="Subspecies Of"
      :reference="store.draft.system.subspeciesOf"
      :editable="editable"
      @drop-data="store.drop($event, 'parent')"
      @clear="store.clearParent()"
    />
    <div class="app:max-w-full app:overflow-x-auto">
      <table class="dui-table dui-table-xs app:min-w-[34rem]">
        <caption class="app:sr-only">
          Characteristic bases plus dice
        </caption>
        <thead>
          <tr>
            <th v-for="key in characteristics" :key="key" scope="col" class="app:text-center">
              {{ labels[key] }}
            </th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td v-for="key in characteristics" :key="key" class="app:p-1">
              <label>
                <span class="app:sr-only">{{ labels[key] }} base</span>
                <input
                  class="dui-input dui-input-xs dui-input-ghost app:w-full app:text-center"
                  type="number"
                  min="0"
                  step="any"
                  :aria-label="`${labels[key]} base`"
                  :value="store.draft.system.characteristics[key]?.base"
                  :placeholder="String(store.parent?.characteristics[key]?.base ?? '—')"
                  @input="
                    store.setCharacteristic(key, 'base', ($event.target as HTMLInputElement).value)
                  "
                />
              </label>
            </td>
          </tr>
          <tr aria-hidden="true">
            <td v-for="key in characteristics" :key="key" class="app:text-center">+</td>
          </tr>
          <tr>
            <td v-for="key in characteristics" :key="key" class="app:p-1">
              <label class="dui-input dui-input-xs dui-input-ghost app:w-full app:gap-0 app:px-1">
                <input
                  class="app:text-center"
                  type="number"
                  min="0"
                  step="any"
                  :aria-label="`${labels[key]} dice`"
                  :value="store.draft.system.characteristics[key]?.dice"
                  :placeholder="String(store.parent?.characteristics[key]?.dice ?? '—')"
                  @input="
                    store.setCharacteristic(key, 'dice', ($event.target as HTMLInputElement).value)
                  "
                />
                <span>d10</span>
              </label>
            </td>
          </tr>
        </tbody>
      </table>
    </div>
    <p v-if="store.draft.system.subspeciesOf.uuid">Empty values inherit from the parent species.</p>
    <SpeciesItemGrants :uuid="uuid" :editable="editable" />
    <label class="dui-input dui-input-sm app:w-full">
      <span class="dui-label app:flex-1">Movement</span>
      <input
        :id="`${uuid}-movement`"
        aria-label="Movement"
        class="app:max-w-20 app:text-center"
        type="number"
        min="0"
        step="any"
        :value="store.draft.system.movement"
        :placeholder="String(store.parent?.movement ?? '—')"
        @input="store.setStatistic('movement', ($event.target as HTMLInputElement).value)"
      />
    </label>
    <div class="app:flex app:flex-wrap app:gap-2">
      <label
        v-for="pool in pools"
        :key="pool.key"
        class="dui-input dui-input-sm app:min-w-36 app:flex-1"
      >
        <span class="dui-label app:flex-1">{{ pool.label }}</span>
        <input
          class="app:max-w-12 app:text-center"
          type="number"
          min="0"
          step="any"
          :aria-label="pool.label"
          :value="store.draft.system[pool.key]"
          :placeholder="String(store.parent?.[pool.key] ?? '—')"
          @input="store.setStatistic(pool.key, ($event.target as HTMLInputElement).value)"
        />
      </label>
    </div>
    <div class="app:grid app:grid-cols-[7rem_minmax(0,1fr)] app:items-center app:gap-2">
      <label class="dui-label" :for="`${uuid}-size`">Size</label>
      <select
        :id="`${uuid}-size`"
        v-model="store.draft.system.size"
        class="dui-select dui-select-sm app:w-full"
        aria-label="Size"
      >
        <option value="tiny">Tiny</option>
        <option value="ltl">Little</option>
        <option value="sml">Small</option>
        <option value="avg">Average</option>
        <option value="lrg">Large</option>
        <option value="enor">Enormous</option>
        <option value="mnst">Monstrous</option>
      </select>
    </div>
    <SpeciesItemTables :uuid="uuid" :editable="editable" />
  </fieldset>
</template>
