import type { Component } from "vue";

import ActorPortraitGalleryApp from "./ActorPortraitGalleryApp.vue";
import { MODULE_ID } from "../../../constants";
import { FoundryVueApplication } from "../../../foundry/apps/FoundryVueApplication";
import { loadNpcBuilderSettings } from "../../../wfrp/npc-builder/settings";
import { foundryActorPortraitGalleryBridge } from "../../../wfrp/actor-portrait-gallery/bridge";
import { createActorPortraitGalleryContext } from "../../../wfrp/actor-portrait-gallery/context";

export class ActorPortraitGalleryApplication extends FoundryVueApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-actor-portrait-gallery`,
    classes: [MODULE_ID, "wfrp4e-customizer-actor-portrait-gallery"],
    position: {
      height: 760,
      width: 900,
    },
    window: {
      icon: "fa-solid fa-images",
      resizable: true,
      title: "Choose Actor Portrait & Token",
    },
  };

  constructor(private readonly actor: FoundryActorDocument) {
    super();
  }

  protected override getVueComponent(): Component {
    return ActorPortraitGalleryApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    return {
      bridge: foundryActorPortraitGalleryBridge,
      context: createActorPortraitGalleryContext(this.actor, loadNpcBuilderSettings()),
    };
  }
}
