import { storeToRefs } from "pinia";
import { computed, ref, watch } from "vue";

import type { NpcBuilderBridge } from "../../../../../types/npc-builder";

import {
  completeMetadataRequest,
  createMetadataRequestState,
  failMetadataRequest,
  getMetadataNamesToRequest,
  getUnresolvedSkillCharacteristicNames,
  getUnresolvedTalentMaximumNames,
  startMetadataRequest,
} from "../../functions/metadata-lookups";
import { useNpcBuilderStore } from "..";

export function createNpcBuilderMetadataLookupsWorkflow(bridge: NpcBuilderBridge) {
  const store = useNpcBuilderStore();
  const { advancements } = storeToRefs(store);
  const skillRequestState = ref(createMetadataRequestState());
  const talentRequestState = ref(createMetadataRequestState());
  const skillLookupError = ref("");
  const talentLookupError = ref("");

  const unresolvedSkillNames = computed(() =>
    getUnresolvedSkillCharacteristicNames(advancements.value),
  );
  const unresolvedTalentNames = computed(() => getUnresolvedTalentMaximumNames(advancements.value));
  const metadataLookupError = computed(() =>
    [skillLookupError.value, talentLookupError.value].filter(Boolean).join(" "),
  );
  const metadataLookupStatus = computed<"degraded" | "loading" | "ready">(() => {
    if (metadataLookupError.value) {
      return "degraded";
    }

    const requestCount =
      skillRequestState.value.inFlightNames.length + talentRequestState.value.inFlightNames.length;

    return requestCount > 0 ? "loading" : "ready";
  });

  watch(
    unresolvedSkillNames,
    (names) => {
      void loadSkillCharacteristics(names);
    },
    { immediate: true },
  );

  watch(
    unresolvedTalentNames,
    (names) => {
      void loadTalentMaximums(names);
    },
    { immediate: true },
  );

  async function loadSkillCharacteristics(names: string[]): Promise<void> {
    if (!names.length) {
      skillLookupError.value = "";
      return;
    }

    const namesToLoad = getMetadataNamesToRequest(names, skillRequestState.value);

    if (!namesToLoad.length) {
      return;
    }

    skillRequestState.value = startMetadataRequest(skillRequestState.value, namesToLoad);
    skillLookupError.value = "";

    try {
      const characteristics = await bridge.listSkillCharacteristics(namesToLoad);

      skillRequestState.value = completeMetadataRequest(skillRequestState.value, namesToLoad);
      store.hydrateSkillCharacteristics(characteristics);
    } catch (error) {
      skillRequestState.value = failMetadataRequest(skillRequestState.value, namesToLoad);
      skillLookupError.value = getMetadataLookupError("skill characteristics", error);
    }
  }

  async function loadTalentMaximums(names: string[]): Promise<void> {
    if (!names.length) {
      talentLookupError.value = "";
      return;
    }

    const namesToLoad = getMetadataNamesToRequest(names, talentRequestState.value);

    if (!namesToLoad.length) {
      return;
    }

    talentRequestState.value = startMetadataRequest(talentRequestState.value, namesToLoad);
    talentLookupError.value = "";

    try {
      const maximums = await bridge.listTalentMaximums(namesToLoad);

      talentRequestState.value = completeMetadataRequest(talentRequestState.value, namesToLoad);
      store.hydrateTalentMaximums(maximums);
    } catch (error) {
      talentRequestState.value = failMetadataRequest(talentRequestState.value, namesToLoad);
      talentLookupError.value = getMetadataLookupError("Talent maximums", error);
    }
  }

  async function retryMetadataLookups(): Promise<void> {
    await Promise.all([
      loadSkillCharacteristics(unresolvedSkillNames.value),
      loadTalentMaximums(unresolvedTalentNames.value),
    ]);
  }

  return {
    metadataLookupError,
    metadataLookupStatus,
    retryMetadataLookups,
  };
}

function getMetadataLookupError(label: string, error: unknown): string {
  const detail = error instanceof Error ? ` ${error.message}` : "";

  return `Could not load ${label}.${detail}`;
}
