import type { Component } from "vue";
import type { EffectBuilderKind } from "../../../../types/effect-builders";
import type { GrantItemReference } from "../../../../types/item-grants";
import EffectBuildersApp from "./EffectBuildersApp.vue";
import { MODULE_ID } from "../../../constants";
import { FoundryVueApplication } from "../../../foundry/apps/FoundryVueApplication";
import { EffectBuilderApplication } from "./EffectBuilderApplication";

export class EffectBuildersApplication extends FoundryVueApplication {
  destination: GrantItemReference | null = null;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-effect-builders-{id}`,
    classes: [MODULE_ID],
    position: { height: 550, width: 620 },
    window: { icon: "fa-solid fa-wand-magic-sparkles", title: "Effect Builders", resizable: true },
  };

  protected override getVueComponent(): Component {
    return EffectBuildersApp;
  }
  protected override getVueProps(): Record<string, unknown> {
    return {
      destination: this.destination,
      openBuilder: (kind: EffectBuilderKind) =>
        new EffectBuilderApplication(kind, this.destination).render(true),
    };
  }
}
