import type { SpeciesSelection } from "../../../types/species/chargen";
import { readStringPath } from "../shared/object-readers";
import { isSpeciesItemUuid } from "./selection";

/** Imports keep their source identity; names and bare IDs are not globally unique. */
export function speciesIdentityUuids(uuid: string, source: Record<string, unknown>): string[] {
  return [
    ...new Set(
      [
        uuid,
        readStringPath(source, ["_stats", "compendiumSource"]),
        readStringPath(source, ["flags", "core", "sourceId"]),
      ].filter(isSpeciesItemUuid),
    ),
  ];
}

export function speciesRollBonus(
  selection: SpeciesSelection | undefined,
  rolled: string[],
): number {
  if (!selection) return 0;
  const own = selection.identity?.self ?? speciesIdentityUuids(selection.uuid, selection.source);
  const parent = selection.identity?.parent ?? [selection.record.system.subspeciesOf.uuid];
  return [...own, ...parent].some((uuid) => uuid && rolled.includes(uuid)) ? 20 : 0;
}
