import type {
  NpcAdvancementDraftEntry,
  NpcBaseActorDraftData,
  NpcBuilderSettings,
  NpcCareerQueueEntry,
  NpcCustomAdvancementSummary,
  NpcSkillCharacteristicSummary,
  NpcTalentMaximumSummary,
} from "../../../../../types/npc-builder";
import { WFRP_CHARACTERISTIC_NAMES } from "../../../../../types/wfrp4e/characteristics";

import { advancementKey, isBaseAdvancementAllowed, normalizeName } from "../draft-helpers";
import { addCareerAdvanceStepAdvancements, addCareerTalentAdvancements } from "./career-grants";
import { applyEntryContext, getCharacteristicTotals } from "./entry-context";

export interface NpcAdvancementDerivationInput {
  baseActorDraftData: NpcBaseActorDraftData;
  careers: NpcCareerQueueEntry[];
  customAdvancements: NpcCustomAdvancementSummary[];
  manualAdvancementDeltas: Record<string, number>;
  settings: NpcBuilderSettings;
  skillCharacteristics: Record<string, NpcSkillCharacteristicSummary>;
  skillGrantResolutions: Record<string, string>;
  talentMaximums: Record<string, NpcTalentMaximumSummary>;
}

export function deriveNpcAdvancements(
  input: NpcAdvancementDerivationInput,
): NpcAdvancementDraftEntry[] {
  const entries = createBaseAdvancementEntries(input.baseActorDraftData);
  const careerGrantContext = {
    careers: input.careers,
    entries,
    skillGrantResolutions: input.skillGrantResolutions,
    talentMaximums: input.talentMaximums,
  };

  addCareerAdvanceStepAdvancements(careerGrantContext, "characteristic");
  addCareerAdvanceStepAdvancements(careerGrantContext, "skill");

  const characteristicTotals = getCharacteristicTotals(entries, input.manualAdvancementDeltas);

  addCareerTalentAdvancements({
    ...careerGrantContext,
    characteristicTotals,
  });
  addCustomAdvancementEntries(entries, input.customAdvancements);

  return [...entries.values()]
    .filter(
      (entry) =>
        entry.includedFromCareer ||
        entry.includedFromCustom ||
        isBaseAdvancementAllowed(entry.kind, input.settings),
    )
    .map((entry) => {
      const contextualEntry = applyEntryContext(entry, characteristicTotals, input);
      const key = advancementKey(entry.kind, entry.name);
      const manualDelta = input.manualAdvancementDeltas[key] ?? 0;
      const current = contextualEntry.careerValue + manualDelta;

      return {
        ...contextualEntry,
        current: Math.max(contextualEntry.minimumCurrent, Math.floor(current)),
      };
    })
    .sort(compareAdvancements);
}

export function calculateManualAdvancementDelta(
  advancement: NpcAdvancementDraftEntry,
  current: number,
): number {
  const finiteCurrent = Number.isFinite(current) ? current : 0;

  return Math.max(advancement.minimumCurrent, Math.floor(finiteCurrent)) - advancement.careerValue;
}

export function calculateManualAdvancementDeltaFromTotal(
  advancement: NpcAdvancementDraftEntry,
  total: number,
): number {
  const finiteTotal = Number.isFinite(total) ? total : 0;
  const nextTotal = Math.max(advancement.minimumTotal, Math.floor(finiteTotal));

  return calculateManualAdvancementDelta(advancement, nextTotal - advancement.baseValue);
}

export function indexSkillCharacteristics(
  current: Record<string, NpcSkillCharacteristicSummary>,
  entries: NpcSkillCharacteristicSummary[],
): Record<string, NpcSkillCharacteristicSummary> {
  return {
    ...current,
    ...Object.fromEntries(entries.map((entry) => [normalizeName(entry.skillName), entry])),
  };
}

export function indexTalentMaximums(
  current: Record<string, NpcTalentMaximumSummary>,
  entries: NpcTalentMaximumSummary[],
): Record<string, NpcTalentMaximumSummary> {
  return {
    ...current,
    ...Object.fromEntries(entries.map((entry) => [normalizeName(entry.talentName), entry])),
  };
}

function createBaseAdvancementEntries(
  baseActorDraftData: NpcBaseActorDraftData,
): Map<string, NpcAdvancementDraftEntry> {
  const entries = new Map<string, NpcAdvancementDraftEntry>();

  for (const advancement of baseActorDraftData.advancements) {
    const key = advancementKey(advancement.kind, advancement.name);
    const entry: NpcAdvancementDraftEntry = {
      baseAdvances: advancement.baseAdvances,
      baseValue: advancement.current,
      careerValue: 0,
      current: 0,
      includedFromBase: true,
      includedFromCareer: false,
      includedFromCustom: false,
      kind: advancement.kind,
      minimumCurrent: -advancement.current,
      minimumTotal: 0,
      name: advancement.name,
      sources: [],
    };

    if (advancement.baseModifier !== undefined) {
      entry.baseModifier = advancement.baseModifier;
    }

    if (advancement.characteristicKey) {
      entry.characteristicKey = advancement.characteristicKey;
      entry.characteristicName =
        advancement.characteristicName ?? WFRP_CHARACTERISTIC_NAMES[advancement.characteristicKey];
    }

    if (advancement.kind === "talent" && advancement.baseAdvances > 0) {
      entry.sources.push({
        count: advancement.baseAdvances,
        kind: "base",
        label: "Base",
      });
    }

    if (advancement.talentMaximumFormula) {
      entry.talentMaximumFormula = advancement.talentMaximumFormula;
    }

    if (advancement.talentMaximumKey) {
      entry.talentMaximumKey = advancement.talentMaximumKey;
    }

    entries.set(key, entry);
  }

  return entries;
}

function addCustomAdvancementEntries(
  entries: Map<string, NpcAdvancementDraftEntry>,
  customAdvancements: NpcCustomAdvancementSummary[],
): void {
  for (const advancement of customAdvancements) {
    const key = advancementKey(advancement.kind, advancement.name);
    const source = {
      count: advancement.advances,
      kind: "custom" as const,
      label: "Dropped",
    };
    const existing = entries.get(key);

    if (existing) {
      existing.careerValue += advancement.advances;
      existing.includedFromCustom = true;
      existing.sources.push(source);
      existing.sourceUuid = existing.sourceUuid ?? advancement.sourceUuid;
      continue;
    }

    entries.set(key, {
      baseAdvances: 0,
      baseValue: 0,
      careerValue: advancement.advances,
      ...(advancement.characteristicKey
        ? { characteristicKey: advancement.characteristicKey }
        : {}),
      ...(advancement.characteristicName
        ? { characteristicName: advancement.characteristicName }
        : {}),
      current: advancement.advances,
      includedFromBase: false,
      includedFromCareer: false,
      includedFromCustom: true,
      kind: advancement.kind,
      minimumCurrent: 0,
      minimumTotal: 0,
      name: advancement.name,
      sourceUuid: advancement.sourceUuid,
      sources: [source],
      ...(advancement.talentMaximumFormula
        ? { talentMaximumFormula: advancement.talentMaximumFormula }
        : {}),
      ...(advancement.talentMaximumKey ? { talentMaximumKey: advancement.talentMaximumKey } : {}),
    });
  }
}

function compareAdvancements(
  left: NpcAdvancementDraftEntry,
  right: NpcAdvancementDraftEntry,
): number {
  if (left.kind !== right.kind) {
    return left.kind.localeCompare(right.kind);
  }

  return left.name.localeCompare(right.name);
}
