import type {
  SpeciesItemRecord,
  SpeciesItemReference,
  SpeciesItemSystem,
  SpeciesTalentChoiceNode,
} from "../../../../types/species/item";
import { WfrpCharacteristicKey } from "../../../../types/wfrp4e/characteristics";
import { isRecord } from "../../../functions/shared/object-readers";
import { createSpeciesItemSystem } from "../../../functions/species-item/system";
import { MODULE_ID } from "../../../constants";
import { readSpeciesEffectSources } from "./effect-sources";

export const SPECIES_ITEM_TYPE = `${MODULE_ID}.species`;

export function isSpeciesItem(item: Pick<FoundryItemDocument, "type">): boolean {
  return item.type === SPECIES_ITEM_TYPE || item.type === "species";
}

export function readSpeciesItem(item: FoundryItemDocument): SpeciesItemRecord {
  const source = item.toObject();
  return {
    id: item.id,
    uuid: item.uuid,
    name: item.name,
    img: item.img || "icons/svg/mystery-man.svg",
    system: readSpeciesItemSystem(source["system"]),
    effects: readSpeciesEffectSources(source["effects"]),
  };
}

export function readSpeciesItemSystem(value: unknown): SpeciesItemSystem {
  if (!isRecord(value)) throw new Error("Species Item system data is missing.");
  const defaults = createSpeciesItemSystem();
  const characteristics = object(value["characteristics"]);
  const talents = object(value["talents"]);
  const choices = object(talents["choices"]);
  const tables = object(value["tables"]);
  return {
    description: { value: string(object(value["description"])["value"]) },
    gmdescription: { value: string(object(value["gmdescription"])["value"]) },
    characteristics: Object.fromEntries(
      Object.values(WfrpCharacteristicKey).map((key) => {
        const entry = object(characteristics[key]);
        return [key, { base: number(entry["base"]), dice: number(entry["dice"]) }];
      }),
    ),
    extra: number(value["extra"]),
    fate: number(value["fate"]),
    movement: number(value["movement"]),
    resilience: number(value["resilience"]),
    keys: strings(value["keys"]),
    size: string(value["size"]) || "avg",
    skills: { list: strings(object(value["skills"])["list"]) },
    talents: {
      random: number(talents["random"]),
      choices: {
        structure:
          choices["structure"] === undefined
            ? defaults.talents.choices.structure
            : readChoiceNode(choices["structure"]),
        options: array(choices["options"]).map((entry) => {
          const option = object(entry);
          return {
            type: string(option["type"]),
            id: string(option["id"]),
            name: string(option["name"]),
            documentId: string(option["documentId"]),
            idType: string(option["idType"]),
            diff: object(option["diff"]),
            filters: array(option["filters"]).map((value) => {
              const filter = object(value);
              return {
                path: string(filter["path"]),
                operation: string(filter["operation"]),
                value: string(filter["value"]),
              };
            }),
          };
        }),
        script: string(choices["script"]),
      },
    },
    subspeciesOf: readReference(value["subspeciesOf"]),
    tables: {
      talents: readReference(tables["talents"]),
      eye: readReference(tables["eye"]),
      hair: readReference(tables["hair"]),
      career: readReference(tables["career"]),
    },
  };
}

function readChoiceNode(value: unknown): SpeciesTalentChoiceNode {
  const node = object(value);
  const type = node["type"];
  if (type !== "and" && type !== "or" && type !== "option")
    throw new Error("Species Talent choice structure is invalid.");
  return {
    type,
    id: string(node["id"]),
    ...(type === "option" ? {} : { options: array(node["options"]).map(readChoiceNode) }),
  };
}

function readReference(value: unknown): SpeciesItemReference {
  const ref = object(value);
  return { uuid: string(ref["uuid"]), id: string(ref["id"]), name: string(ref["name"]) };
}
function number(value: unknown): number | null {
  if (value === null || value === undefined) return null;
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0)
    throw new Error("Species statistics must be non-negative numbers or empty inheritance values.");
  return value;
}
function string(value: unknown): string {
  return typeof value === "string" ? value : "";
}
function array(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}
function strings(value: unknown): string[] {
  return array(value).map((entry) => {
    if (typeof entry !== "string")
      throw new Error("Species keys and skills must contain text values.");
    return entry;
  });
}
function object(value: unknown): Record<string, unknown> {
  return isRecord(value) ? value : {};
}
