import type { SpeciesItemRecord } from "../../../../types/species/item";

/** Strip source identity and freeze inheritance on the actor's independent copy. */
export function speciesActorSource(item: FoundryItemDocument, record: SpeciesItemRecord) {
  const source = item.toObject();
  for (const key of ["_id", "folder", "ownership", "_stats"]) delete source[key];
  source["system"] = record.system;
  source["effects"] = record.effects;
  return source;
}
