<script setup lang="ts">
import { useSpeciesItemStore } from "../state";
import SpeciesTalentEditor from "./details/SpeciesTalentEditor.vue";
import DocumentDrop from "../../shared/view/components/DocumentDrop.vue";
const props = defineProps<{ uuid: string; editable: boolean }>();
const store = useSpeciesItemStore(props.uuid);
</script>

<template>
  <fieldset class="dui-fieldset" :disabled="!editable">
    <legend class="app:sr-only">Skills and Talents</legend>
    <DocumentDrop
      title="Skills"
      variant="bare"
      :show-prompt="false"
      manual-entry-trigger="none"
      :disabled="!editable"
      @drop-data="store.drop($event, 'skills')"
    >
      <div class="dui-divider">Skills</div>
      <div class="app:flex app:flex-wrap app:items-center app:gap-1">
        <div
          v-for="(_, index) in store.draft.system.skills.list"
          :key="index"
          class="dui-join app:max-w-full"
        >
          <input
            v-model="store.draft.system.skills.list[index]"
            :aria-label="`Skill ${index + 1} name`"
            :size="Math.max(6, store.draft.system.skills.list[index]!.length)"
            class="dui-input dui-input-xs dui-join-item app:w-auto app:min-w-0"
            required
          />
          <button
            type="button"
            class="dui-btn dui-btn-xs dui-btn-square dui-join-item"
            :aria-label="`Remove Skill ${index + 1}`"
            @click="store.draft.system.skills.list.splice(index, 1)"
          >
            <i class="fa-solid fa-xmark" aria-hidden="true" />
          </button>
        </div>
        <button
          type="button"
          class="dui-btn dui-btn-xs dui-btn-ghost"
          @click="store.draft.system.skills.list.push('New Skill')"
        >
          <i class="fa-solid fa-plus" aria-hidden="true" /> Skill
        </button>
      </div>
    </DocumentDrop>
    <div v-if="store.choiceWarning" class="dui-alert dui-alert-warning" role="status">
      {{ store.choiceWarning }} The stored choices are preserved.
    </div>
    <DocumentDrop
      title="Talents"
      variant="bare"
      :show-prompt="false"
      manual-entry-trigger="none"
      :disabled="!editable || !!store.choiceWarning"
      @drop-data="store.drop($event, 'talents')"
    >
      <div class="app:flex app:items-center app:gap-2">
        <span class="dui-label app:flex-1">Talents</span>
        <button
          type="button"
          class="dui-btn dui-btn-xs dui-btn-ghost"
          :disabled="!editable || !!store.choiceWarning"
          :aria-expanded="store.editingTalents"
          :aria-controls="`${uuid}-talent-editor`"
          @click="store.editingTalents = !store.editingTalents"
        >
          <i class="fa-solid fa-gear" aria-hidden="true" />
          {{ store.editingTalents ? "Done" : "Edit Talents" }}
        </button>
      </div>
      <p class="app:my-1">
        {{
          store.choiceWarning
            ? "Native Talent choices preserved"
            : store.talentSummary ||
              (store.draft.system.subspeciesOf.uuid ? "Inherit parent Talents" : "None")
        }}
      </p>
    </DocumentDrop>
    <SpeciesTalentEditor v-if="store.editingTalents" :id="`${uuid}-talent-editor`" :uuid="uuid" />
    <label class="dui-input dui-input-sm app:w-full">
      <span class="dui-label app:flex-1">Random Talents</span>
      <input
        :id="`${uuid}-random-talents`"
        aria-label="Random Talents"
        class="app:max-w-20 app:text-center"
        type="number"
        min="0"
        :value="store.draft.system.talents.random"
        :placeholder="String(store.parent?.talents.random ?? '—')"
        @input="
          store.draft.system.talents.random =
            ($event.target as HTMLInputElement).value === ''
              ? null
              : Number(($event.target as HTMLInputElement).value)
        "
      />
    </label>
  </fieldset>
</template>
