<script setup lang="ts">
import { computed, inject, onBeforeUnmount, ref, useSlots, watch } from "vue";

import {
  DOCUMENT_DROP_BRIDGE_KEY,
  type DocumentDropBridge,
  type DocumentDropReference,
  type ManualDocumentType,
} from "../../../../../types/foundry/document-drop";

import DocumentList from "./DocumentDrop/DocumentList.vue";
import ManualEntryForm from "./DocumentDrop/ManualEntryForm.vue";

type DocumentDropManualEntryTrigger = "button" | "none";

const props = withDefaults(
  defineProps<{
    description?: string;
    disabled?: boolean;
    documents?: DocumentDropReference[];
    documentsClickable?: boolean;
    emptyDocumentLabel?: string;
    manualEntryTrigger?: DocumentDropManualEntryTrigger;
    showDocuments?: boolean;
    showPrompt?: boolean;
    title: string;
    variant?: "bare" | "compact" | "default";
  }>(),
  {
    description: "",
    disabled: false,
    documents: () => [],
    documentsClickable: false,
    emptyDocumentLabel: "No document selected.",
    manualEntryTrigger: "button",
    showDocuments: false,
    showPrompt: true,
    variant: "default",
  },
);

const injectedBridge = inject<DocumentDropBridge>(DOCUMENT_DROP_BRIDGE_KEY);

if (!injectedBridge) {
  throw new Error("DocumentDrop requires a document drop bridge from its application host.");
}

const documentDropBridge = injectedBridge;
const slots = useSlots();

const emit = defineEmits<{
  documentClicked: [document: DocumentDropReference];
  dropData: [data: string];
}>();

const isHovering = ref(false);
const isManualEntryOpen = ref(false);
const isPickingDocument = ref(false);
const manualDocumentType = ref<ManualDocumentType>("auto");
const manualDocumentValue = ref("");
let stopDocumentPickCallback: (() => void) | undefined;
const hasCustomPrompt = computed(() => Boolean(slots["prompt"]));
const hasDefaultContent = computed(() => Boolean(slots["default"]));
const hasPrompt = computed(
  () => props.showPrompt && (hasCustomPrompt.value || props.title.length > 0),
);
const shownDocuments = computed(() => (props.showDocuments ? props.documents : []));
const showsManualEntryButton = computed(() => props.manualEntryTrigger === "button");
const containerClasses = computed(() => {
  if (props.variant === "bare") {
    return [];
  }

  const size = props.variant === "compact" ? "dui-card-xs" : "dui-card-sm";

  return ["dui-card", "dui-card-border", size];
});

defineOptions({
  inheritAttrs: false,
});

function handleDragLeave(event: DragEvent): void {
  const target = event.currentTarget;
  const relatedTarget = event.relatedTarget;

  if (target instanceof Node && relatedTarget instanceof Node && target.contains(relatedTarget)) {
    return;
  }

  isHovering.value = false;
}

function handleDragOver(): void {
  if (!props.disabled) {
    isHovering.value = true;
  }
}

function handleDrop(event: DragEvent): void {
  event.preventDefault();
  event.stopPropagation();
  isHovering.value = false;

  if (props.disabled) {
    return;
  }

  emit("dropData", event.dataTransfer?.getData("text/plain") ?? "");
}

function openManualEntry(): void {
  if (props.manualEntryTrigger === "none") {
    return;
  }

  isManualEntryOpen.value = true;
}

function closeManualEntry(): void {
  isManualEntryOpen.value = false;
  stopDocumentPick();
}

function toggleManualEntry(): void {
  if (props.disabled) {
    return;
  }

  if (isManualEntryOpen.value) {
    closeManualEntry();
    return;
  }

  openManualEntry();
}

function submitManualEntry(): void {
  if (props.disabled) {
    return;
  }

  const payload = documentDropBridge.createDropData({
    documentType: manualDocumentType.value,
    value: manualDocumentValue.value,
  });

  if (!payload) {
    return;
  }

  emit("dropData", payload);
  manualDocumentValue.value = "";
  closeManualEntry();
}

function startDocumentPick(): void {
  if (props.disabled || stopDocumentPickCallback) {
    return;
  }

  isPickingDocument.value = true;
  stopDocumentPickCallback = documentDropBridge.startDocumentPick(handlePickedDropData);
}

function stopDocumentPick(): void {
  const stop = stopDocumentPickCallback;

  stopDocumentPickCallback = undefined;
  isPickingDocument.value = false;
  stop?.();
}

function handlePickedDropData(data: string): void {
  emit("dropData", data);
  closeManualEntry();
}

onBeforeUnmount(() => {
  stopDocumentPick();
});

watch(
  () => props.disabled,
  (disabled) => {
    if (disabled) {
      isHovering.value = false;
      closeManualEntry();
    }
  },
);
</script>

<template>
  <div
    v-bind="$attrs"
    :class="containerClasses"
    :aria-label="title"
    :aria-disabled="disabled"
    role="group"
    @dragenter.prevent="handleDragOver"
    @dragover.prevent="handleDragOver"
    @dragleave="handleDragLeave"
    @drop="handleDrop"
  >
    <div :class="variant === 'bare' ? undefined : 'dui-card-body'">
      <div
        v-if="hasPrompt"
        class="dui-alert dui-alert-info"
        :class="{ 'dui-alert-outline': !isHovering }"
      >
        <i aria-hidden="true" class="fa-solid fa-arrow-down" />
        <div>
          <slot name="prompt">
            <strong>{{ title }}</strong>
            <p v-if="description">{{ description }}</p>
          </slot>
        </div>
        <span class="dui-badge" :class="{ 'dui-badge-info': isHovering }">
          {{ isHovering ? "Release to add" : "Drop zone" }}
        </span>
      </div>

      <div v-else-if="isHovering" class="dui-alert dui-alert-info" role="status">
        <i aria-hidden="true" class="fa-solid fa-arrow-down" />
        <span>Release to add {{ title.toLowerCase() }}.</span>
      </div>

      <div v-if="hasDefaultContent">
        <slot />
      </div>

      <DocumentList
        v-if="showDocuments"
        :documents="shownDocuments"
        :empty-label="emptyDocumentLabel"
        :is-clickable="documentsClickable"
        @document-clicked="(document) => emit('documentClicked', document)"
      />

      <div v-if="showsManualEntryButton" class="dui-card-actions">
        <button
          class="dui-btn dui-btn-ghost dui-btn-sm"
          :disabled="disabled"
          type="button"
          @click.stop="toggleManualEntry"
        >
          {{ isManualEntryOpen ? "Close Manual Entry" : "Manual Entry" }}
        </button>
      </div>

      <ManualEntryForm
        v-if="isManualEntryOpen && !disabled"
        :document-type="manualDocumentType"
        :document-value="manualDocumentValue"
        :is-picking-document="isPickingDocument"
        @close="closeManualEntry"
        @start-pick="startDocumentPick"
        @submit="submitManualEntry"
        @update-document-type="(value) => (manualDocumentType = value)"
        @update-document-value="(value) => (manualDocumentValue = value)"
      />
    </div>
  </div>
</template>
