import type {
  SpeciesTableBridge,
  SpeciesTableDraft,
  SpeciesTableState,
} from "../../../types/species/table";
import { speciesTableProblems } from "../../apps/species-table/functions/draft";
import { loadSpeciesTableSource } from "./documents/index";
import { registerSpeciesTable, upsertManagedSpeciesTable } from "./documents/persistence";
import {
  requireSpeciesTableGm,
  resolveSpeciesSource,
  resolveSpeciesTableDrop,
  speciesTableOptions,
} from "./items";

let saving = false;

function tableRevision(tableId?: string): string {
  return JSON.stringify({
    table: tableId ? game.tables?.get(tableId)?.toObject() : null,
    settings: game.settings.get("wfrp4e", "tableSettings"),
  });
}

export async function loadSpeciesTable(): Promise<SpeciesTableState> {
  requireSpeciesTableGm();
  const options = speciesTableOptions();
  const { draft } = await loadSpeciesTableSource(options);
  const rows = [];
  for (const row of draft.rows) {
    const uuid = row.journalUuid;
    const itemReference =
      uuid &&
      (uuid.startsWith("Item.") || uuid.includes(".Item.") || row.speciesKey.startsWith("item:"));
    if (itemReference) {
      const item = await resolveSpeciesSource(uuid);
      const option = { key: `item:${item.uuid}`, label: item.name, itemUuid: item.uuid };
      if (!options.some((entry) => entry.key === option.key)) options.push(option);
      rows.push({
        ...row,
        name: item.name,
        speciesKey: option.key,
        itemUuid: item.uuid,
        sources: [{ uuid: item.uuid, name: item.name }],
      });
    } else rows.push({ ...row, sources: [] });
  }
  return { draft: { ...draft, rows }, options, revision: tableRevision(draft.tableId) };
}

async function assertFresh(revision: string): Promise<void> {
  if ((await loadSpeciesTable()).revision !== revision)
    throw new Error(
      "The world's Species table or table settings changed. Reload the editor before saving.",
    );
}

async function preflight(draft: SpeciesTableDraft): Promise<void> {
  const options = speciesTableOptions();
  for (const row of draft.rows) {
    if (!row.itemUuid) continue;
    const drop = await resolveSpeciesTableDrop(JSON.stringify({ uuid: row.itemUuid }));
    // Item edits while this window is open must not silently change the table being approved.
    if (drop.option.key !== row.speciesKey || drop.option.label !== row.name)
      throw new Error(
        `${row.name} changed. Reload the editor and drop the updated Species Item again.`,
      );
    if (!options.some((entry) => entry.key === drop.option.key)) options.push(drop.option);
  }
  const problems = speciesTableProblems(draft, options);
  if (problems.length) throw new Error(problems.join("\n"));
}

export async function saveSpeciesTable(
  draft: SpeciesTableDraft,
  revision: string,
  register: boolean,
): Promise<SpeciesTableState> {
  requireSpeciesTableGm();
  if (saving)
    throw new Error("Another Species table save is in progress. Try again when it finishes.");
  saving = true;
  try {
    await assertFresh(revision);
    await preflight(draft);
    const prepared = structuredClone(draft);
    for (const row of prepared.rows) {
      if (!row.itemUuid) continue;
      const item = await resolveSpeciesSource(row.itemUuid);
      row.speciesKey = `item:${item.uuid}`;
      row.itemUuid = item.uuid;
      row.journalUuid = item.uuid;
      row.name = item.name;
    }
    await assertFresh(revision);
    const options = speciesTableOptions();
    for (const row of prepared.rows)
      if (row.itemUuid && !options.some((entry) => entry.key === row.speciesKey))
        options.push({ key: row.speciesKey, label: row.name, itemUuid: row.itemUuid });
    const problems = speciesTableProblems(prepared, options);
    if (problems.length) throw new Error(problems.join("\n"));
    const table = await upsertManagedSpeciesTable(prepared);
    let registrationError: string | undefined;
    if (register) {
      try {
        await registerSpeciesTable(table.id);
      } catch (cause) {
        registrationError = cause instanceof Error ? cause.message : String(cause);
      }
    }
    return { ...(await loadSpeciesTable()), ...(registrationError ? { registrationError } : {}) };
  } finally {
    saving = false;
  }
}

export const speciesTableBridge: SpeciesTableBridge = {
  load: loadSpeciesTable,
  resolveDrop: resolveSpeciesTableDrop,
  save: saveSpeciesTable,
};
