import type { NpcFolderSummary } from "../../../../types/npc-builder";

export async function ensureActorFolder(name: string): Promise<NpcFolderSummary> {
  return toFolderSummary(await ensureFolder(name, "Actor"));
}

export async function ensureItemFolder(name: string): Promise<NpcFolderSummary> {
  return toFolderSummary(await ensureFolder(name, "Item"));
}

export function listActorFolders(): NpcFolderSummary[] {
  return game.folders.contents
    .filter((folder) => folder.type === "Actor")
    .map(toFolderSummary)
    .sort((left, right) => left.name.localeCompare(right.name));
}

export function listItemFolders(): NpcFolderSummary[] {
  return game.folders.contents
    .filter((folder) => folder.type === "Item")
    .map(toFolderSummary)
    .sort((left, right) => left.name.localeCompare(right.name));
}

export function getFolderByUuid(uuid: string): FoundryFolderDocument | null {
  if (!uuid) {
    return null;
  }

  return game.folders.contents.find((folder) => folder.uuid === uuid) ?? null;
}

export function getItemFolderByUuid(uuid: string): FoundryFolderDocument | null {
  const folder = getFolderByUuid(uuid);

  return folder?.type === "Item" ? folder : null;
}

async function ensureFolder(
  name: string,
  type: FoundryFolderSource["type"],
): Promise<FoundryFolderDocument> {
  const trimmedName = name.trim();

  if (!trimmedName) {
    throw new Error("Enter a folder name first.");
  }

  const existingFolder = game.folders.contents.find((folder) => {
    return folder.type === type && namesMatch(folder.name, trimmedName);
  });

  if (existingFolder) {
    return existingFolder;
  }

  const folder = await Folder.create({
    name: trimmedName,
    type,
  });

  if (!folder) {
    throw new Error("Foundry did not create the folder.");
  }

  return folder;
}

function toFolderSummary(folder: FoundryFolderDocument): NpcFolderSummary {
  return {
    name: folder.name,
    uuid: folder.uuid,
  };
}

function namesMatch(left: string, right: string): boolean {
  return left.trim().toLocaleLowerCase() === right.trim().toLocaleLowerCase();
}
