import { speciesConfigForSelection } from "../../functions/species-chargen/config";
import type { SpeciesSelection } from "../../../types/species/chargen";
import { isRecord } from "../../functions/shared/object-readers";
import { speciesDetailFormulas } from "../../functions/species-chargen/detail-formulas";
import { clearChargenTables, resolveChargenTable, setChargenTables } from "./tables";

let nextSession = 0;
export const CHARGEN_CONFIG_PREFIX = "customizer-chargen-";

export function createChargenConfigKey(): string {
  return `${CHARGEN_CONFIG_PREFIX}${++nextSession}`;
}

export async function prepareChargenConfig(
  key: string,
  selection: SpeciesSelection,
): Promise<void> {
  const config = game.wfrp4e?.config;
  if (!config) throw new Error("WFRP species config is unavailable.");
  const { record } = selection;
  const formulas = speciesDetailFormulas(record.effects);
  for (const [detail, formula] of Object.entries(formulas)) {
    if (!Roll.validate(formula)) throw new Error(`Invalid Species ${detail} formula: ${formula}`);
  }
  const [career, talents, eye, hair] = await Promise.all([
    resolveChargenTable(record.system.tables.career),
    resolveChargenTable(record.system.tables.talents),
    resolveChargenTable(record.system.tables.eye),
    resolveChargenTable(record.system.tables.hair),
  ]);
  const generated = speciesConfigForSelection(
    key,
    record,
    formulas,
    talents ? `${key}-talents` : "talents",
  );
  // Resolve and validate everything before replacing this session's previous selection.
  clearChargenConfig(key);
  for (const [field, values] of Object.entries(generated)) {
    if (isRecord(values) && Object.hasOwn(values, key)) {
      const target = isRecord(config[field]) ? config[field] : (config[field] = {});
      target[key] = values[key];
    }
  }
  setChargenTables(key, career, talents, eye, hair);
}

export function clearChargenConfig(key: string): void {
  const config = game.wfrp4e?.config;
  for (const [field, value] of Object.entries(config ?? {})) {
    if ((field.startsWith("species") || field === "subspecies") && isRecord(value))
      delete value[key];
  }
  clearChargenTables(key);
}
