<script setup lang="ts">
import { storeToRefs } from "pinia";

import type {
  NpcSelectOption,
  NpcTraitDraftConfig,
  NpcTraitDraftEntry,
} from "../../../../../types/npc-builder";

import { useNpcBuilderStore } from "../../state";
import NpcBuilderSection from "./NpcBuilderSection.vue";

defineProps<{
  difficultyOptions: NpcSelectOption[];
}>();

const store = useNpcBuilderStore();
const { traits } = storeToRefs(store);

function getTraitSourceLabel(trait: NpcTraitDraftEntry): string {
  if (trait.source === "base") {
    return "Base";
  }

  if (trait.source === "quick") {
    return "Quick";
  }

  if (trait.source === "optional") {
    return "Optional";
  }

  return "Custom";
}

function removeTrait(trait: NpcTraitDraftEntry): void {
  if (trait.source === "base") {
    store.setBaseTraitIgnored(trait.key, true);
    return;
  }

  store.removeCustomTrait(trait.key);
}

function setTraitStringConfig(
  trait: NpcTraitDraftEntry,
  field: keyof Pick<NpcTraitDraftConfig, "defaultDifficulty" | "dice" | "specification">,
  event: Event,
): void {
  const input = event.target as HTMLInputElement | HTMLSelectElement | null;

  if (input) {
    store.setTraitConfig(trait.key, { [field]: input.value });
  }
}
</script>

<template>
  <NpcBuilderSection
    description="Open a Trait to review its WFRP configuration before building."
    title="Traits"
  >
    <details
      v-for="trait in traits"
      :key="trait.key"
      class="dui-collapse dui-collapse-arrow dui-card-border"
    >
      <summary class="dui-collapse-title">
        <strong>{{ trait.name }}</strong>
        <span class="dui-badge">{{ getTraitSourceLabel(trait) }}</span>
        <span v-if="trait.config.rollable" class="dui-badge dui-badge-info">Rollable</span>
        <span v-if="trait.config.damage" class="dui-badge dui-badge-warning">Damage</span>
      </summary>
      <div class="dui-collapse-content">
        <fieldset class="dui-fieldset">
          <legend class="dui-fieldset-legend">
            {{ trait.config.damage ? "Damage" : "Specification" }}
          </legend>
          <input
            :aria-label="`${trait.config.damage ? 'Damage' : 'Specification'} for ${trait.name}`"
            class="dui-input dui-input-sm"
            :value="trait.config.specification"
            placeholder="None"
            type="text"
            @input="setTraitStringConfig(trait, 'specification', $event)"
          />
        </fieldset>

        <fieldset v-if="trait.config.rollable && !trait.config.damage" class="dui-fieldset">
          <legend class="dui-fieldset-legend">Difficulty</legend>
          <select
            :aria-label="`Difficulty for ${trait.name}`"
            class="dui-select dui-select-sm"
            :value="trait.config.defaultDifficulty"
            @change="setTraitStringConfig(trait, 'defaultDifficulty', $event)"
          >
            <option v-for="option in difficultyOptions" :key="option.value" :value="option.value">
              {{ option.label }}
            </option>
          </select>
        </fieldset>

        <fieldset v-if="trait.config.damage && trait.config.dice" class="dui-fieldset">
          <legend class="dui-fieldset-legend">Dice</legend>
          <input
            :aria-label="`Dice for ${trait.name}`"
            class="dui-input dui-input-sm"
            :value="trait.config.dice"
            placeholder="Optional"
            type="text"
            @input="setTraitStringConfig(trait, 'dice', $event)"
          />
        </fieldset>
        <button class="dui-btn dui-btn-sm" type="button" @click="removeTrait(trait)">Remove</button>
      </div>
    </details>
    <p v-if="!traits.length" class="dui-alert">No traits are selected yet.</p>
  </NpcBuilderSection>
</template>
