import type { LegacyChargen, LegacyDetailsStageConstructor } from "../../../types/species/chargen";
import { isRecord } from "../../functions/shared/object-readers";
import { hasNativeSpeciesSupport } from "../species-item/documents/migration";
import { SpeciesChargenSession } from "./session";
import { createItemSpeciesStage } from "./stage";
import { createItemDetailsStage } from "./details";

const sessions = new WeakMap<LegacyChargen, SpeciesChargenSession>();

export function registerSpeciesItemChargen(): void {
  Hooks.on("wfrp4e:chargen", (value) => {
    if (!hasNativeSpeciesSupport()) installSpeciesItemChargen(value);
  });
}

export function installSpeciesItemChargen(value: unknown): void {
  if (hasNativeSpeciesSupport())
    throw new Error(
      "The legacy Species bridge is disabled when native Species support is available.",
    );
  if (
    !isRecord(value) ||
    !Array.isArray(value["stages"]) ||
    !isRecord(value["data"]) ||
    typeof value["getData"] !== "function" ||
    typeof value["close"] !== "function"
  )
    throw new Error("WFRP character generation has an unsupported application shape.");
  const app = value as unknown as LegacyChargen;
  const stage = app.stages.find((entry) => entry.key === "species");
  if (!stage || typeof stage.class !== "function")
    throw new Error("WFRP's Species stage is unavailable.");
  if (sessions.has(app)) return;
  const session = new SpeciesChargenSession(app);
  sessions.set(app, session);
  stage.class = createItemSpeciesStage(stage.class, session);
  const details = app.stages.find((entry) => entry.key === "details");
  if (details)
    details.class = createItemDetailsStage(details.class as LegacyDetailsStageConstructor, session);
  const originalGetData = app.getData;
  app.getData = async function () {
    await session.ready;
    return originalGetData.call(this);
  };
  // Restoring a checkpoint may need compendium tables before a stage's constructor reads config.
  let ready = false;
  void session.ready
    .then(() => {
      ready = true;
    })
    .catch((error: unknown) => {
      ui.notifications?.error(
        `Could not restore Species: ${error instanceof Error ? error.message : String(error)}`,
      );
    });
  const originalCanStart = app.canStartStage;
  app.canStartStage = function (entry) {
    return ready && !session.busy && originalCanStart.call(this, entry);
  };
  const originalClose = app.close;
  app.close = async function () {
    session.dispose();
    for (const entry of this.stages) await entry.app?.close();
    return originalClose.call(this);
  };
}

export async function selectChargenSpecies(value: unknown, uuid: string): Promise<void> {
  installSpeciesItemChargen(value);
  const app = value as LegacyChargen;
  const session = sessions.get(app)!;
  await session.ready;
  const index = app.stages.findIndex((entry) => entry.key === "species");
  const stage = app.stages[index]!;
  stage.app ??= new stage.class(app.data, { complete: app.complete.bind(app), index });
  const sheet = stage.app as InstanceType<ReturnType<typeof createItemSpeciesStage>>;
  await sheet.selectSpeciesItem(uuid);
  sheet.render(true);
}
