import { MODULE_ID, MODULE_TITLE } from "../../constants";

export const KEEP_COMPENDIUMS_TIDY_SETTING = "keepCompendiumsTidy";

export function registerCompendiumSidebarSetting(): void {
  if (!game?.user)
    throw new Error("Foundry user is unavailable during Compendium tidy setting registration.");
  game.settings.register(MODULE_ID, KEEP_COMPENDIUMS_TIDY_SETTING, {
    config: game.user.isGM === true,
    default: false,
    hint: "Restore this module's Compendium sidebar folders and pack locations when the active GM opens the world.",
    name: `Keep ${MODULE_TITLE} Compendiums Tidy?`,
    scope: "world",
    type: Boolean,
  });
}
