<script setup lang="ts">
import type { SpeciesItemReference } from "../../../../types/species/item";
import { useSpeciesItemStore } from "../state";
const props = defineProps<{
  uuid: string;
  label: string;
  reference: SpeciesItemReference;
  editable: boolean;
}>();
const emit = defineEmits<{ "clear": []; "drop-data": [data: string] }>();
const store = useSpeciesItemStore(props.uuid);
function drop(event: DragEvent): void {
  if (props.editable && event.dataTransfer)
    emit("drop-data", event.dataTransfer.getData("text/plain"));
}
</script>

<template>
  <div
    class="app:grid app:grid-cols-[7rem_minmax(0,1fr)] app:items-center app:gap-2"
    @dragover.prevent
    @drop.prevent="drop"
  >
    <span class="dui-label">{{ label }}</span>
    <div class="dui-join app:min-w-0">
      <button
        v-if="reference.uuid"
        type="button"
        class="dui-btn dui-btn-sm dui-btn-outline dui-join-item app:h-auto app:min-h-8 app:min-w-0 app:flex-1 app:justify-start app:whitespace-normal"
        @click="store.openReference(reference.uuid)"
      >
        {{ reference.name || label }}
      </button>
      <div
        v-else
        class="dui-input dui-input-sm app:h-auto app:min-h-8 app:w-full app:whitespace-normal"
      >
        Drop {{ label === "Subspecies Of" ? "a Species Item" : "a RollTable" }} here
      </div>
      <button
        v-if="editable && (reference.uuid || reference.id)"
        type="button"
        class="dui-btn dui-btn-sm dui-btn-square dui-join-item"
        :aria-label="`Clear ${label}`"
        @click="emit('clear')"
      >
        <i class="fa-solid fa-xmark" aria-hidden="true" />
      </button>
    </div>
  </div>
</template>
