import type { CustomizerModuleApi } from "../../../types/module/customizer-module-api";

import {
  listNpcAutoAdvanceStrategies,
  registerNpcAutoAdvanceStrategy,
} from "../../apps/npc-builder/functions/auto-advance";
import { openActorPortraitGallery } from "../../wfrp/actor-portrait-gallery/open";
import { NpcBuilderApplication } from "../../apps/npc-builder/view/NpcBuilderApplication";
import { estimateNpcXp } from "../../wfrp/npc-builder/estimated-xp";
import {
  openEffectBuilders,
  openAgeHeightEffectBuilder,
  openWoundFormulaEffectBuilder,
  openItemGrantEffectBuilder,
  openRandomItemEffectBuilder,
  openItemChoiceEffectBuilder,
} from "../../wfrp/effect-builders/open";
import { createBuiltEffect } from "../../wfrp/effect-builders/bridge";
import { selectChargenSpecies } from "../../wfrp/species-chargen";
import { WorkbenchApplication } from "../../apps/workbench/view/WorkbenchApplication";
import { openSpeciesTableEditor } from "../../apps/species-table/view/SpeciesTableApplication";
import { speciesTableBridge } from "../../wfrp/species-table/bridge";

export function createModuleApi(): CustomizerModuleApi {
  return {
    estimateNpcXp,
    listNpcAutoAdvanceStrategies,
    openActorPortraitGallery,
    async openNpcBuilder() {
      await new NpcBuilderApplication().render(true);
    },
    createBuiltEffect,
    openEffectBuilders,
    openAgeHeightEffectBuilder,
    openWoundFormulaEffectBuilder,
    openItemGrantEffectBuilder,
    openRandomItemEffectBuilder,
    openItemChoiceEffectBuilder,
    openSpeciesTableEditor,
    speciesTable: speciesTableBridge,
    async openWorkbench() {
      await new WorkbenchApplication().render(true);
    },
    selectChargenSpecies,
    registerNpcAutoAdvanceStrategy,
  };
}
