import type {
  NpcAdvancementDraftEntry,
  NpcTalentMaximumSummary,
} from "../../../../../types/npc-builder";

import {
  isWfrpCharacteristicKey,
  WFRP_CHARACTERISTIC_NAMES,
  type WfrpCharacteristicKey,
} from "../../../../../types/wfrp4e/characteristics";
import { normalizeName } from "../draft-helpers";

export function getCappedAutomatedTalentRanks(
  entry: NpcAdvancementDraftEntry,
  requestedCareerRanks: number,
  characteristicTotals: Partial<Record<WfrpCharacteristicKey, number>>,
  talentMaximums: Record<string, NpcTalentMaximumSummary>,
): number {
  const resolvedMaximum = resolveTalentMaximum(
    getTalentMaximum(entry, talentMaximums),
    characteristicTotals,
  );

  if (resolvedMaximum.value === null) {
    return requestedCareerRanks;
  }

  return Math.min(requestedCareerRanks, Math.max(0, resolvedMaximum.value - entry.baseAdvances));
}

export function getTalentMaximum(
  entry: NpcAdvancementDraftEntry,
  talentMaximums: Record<string, NpcTalentMaximumSummary>,
): {
  maximumFormula: string;
  maximumKey: string;
} {
  const storedMaximum = talentMaximums[normalizeName(entry.name)];

  return {
    maximumFormula: entry.talentMaximumFormula ?? storedMaximum?.maximumFormula ?? "",
    maximumKey: entry.talentMaximumKey ?? storedMaximum?.maximumKey ?? "",
  };
}

export function resolveTalentMaximum(
  maximum: { maximumFormula: string; maximumKey: string },
  characteristicTotals: Partial<Record<WfrpCharacteristicKey, number>>,
): { label: string; value: null | number } {
  const maximumKey = maximum.maximumKey.trim().toLocaleLowerCase();

  if (!maximumKey) {
    return { label: "Unknown", value: null };
  }

  if (maximumKey === "none") {
    return { label: "-", value: null };
  }

  if (maximumKey === "custom") {
    return resolveCustomTalentMaximum(maximum.maximumFormula, characteristicTotals);
  }

  const numericMaximum = Number(maximumKey);

  if (Number.isFinite(numericMaximum)) {
    const value = Math.max(0, Math.floor(numericMaximum));

    return { label: `${value}`, value };
  }

  if (isWfrpCharacteristicKey(maximumKey)) {
    const characteristicValue = characteristicTotals[maximumKey] ?? 0;
    const value = Math.max(0, Math.floor(characteristicValue / 10));

    return {
      label: `${WFRP_CHARACTERISTIC_NAMES[maximumKey]} Bonus (${value})`,
      value,
    };
  }

  return { label: maximum.maximumKey || "Unknown", value: null };
}

function resolveCustomTalentMaximum(
  formula: string,
  characteristicTotals: Partial<Record<WfrpCharacteristicKey, number>>,
): { label: string; value: null | number } {
  const trimmedFormula = formula.trim();
  const numericMaximum = Number(trimmedFormula);

  if (Number.isFinite(numericMaximum)) {
    const value = Math.max(0, Math.floor(numericMaximum));

    return { label: `${value}`, value };
  }

  const characteristicBonusMatch = /@characteristics\.([a-z]+)\.bonus/i.exec(trimmedFormula);
  const characteristicKey = characteristicBonusMatch?.[1]?.toLocaleLowerCase();

  if (characteristicKey && isWfrpCharacteristicKey(characteristicKey)) {
    const characteristicValue = characteristicTotals[characteristicKey] ?? 0;
    const value = Math.max(0, Math.floor(characteristicValue / 10));

    return {
      label: `${WFRP_CHARACTERISTIC_NAMES[characteristicKey]} Bonus (${value})`,
      value,
    };
  }

  return { label: trimmedFormula || "Custom", value: null };
}
