import type { EffectBuilderKind } from "../../../types/effect-builders";
import { createGrantItemReference } from "../grant/item-documents";
import { editableEffectDestination } from "./documents";
import { EffectBuilderApplication } from "../../apps/effect-builders/view/EffectBuilderApplication";
import { EffectBuildersApplication } from "../../apps/effect-builders/view/EffectBuildersApplication";

export async function openEffectBuilders(destinationUuid?: string): Promise<void> {
  const app = new EffectBuildersApplication();
  if (destinationUuid)
    app.destination = createGrantItemReference(
      editableEffectDestination(await fromUuid(destinationUuid)),
    );
  await app.render(true);
}

export async function openEffectBuilder(
  kind: EffectBuilderKind,
  destinationUuid?: string,
): Promise<void> {
  const destination = destinationUuid
    ? createGrantItemReference(editableEffectDestination(await fromUuid(destinationUuid)))
    : null;
  await new EffectBuilderApplication(kind, destination).render(true);
}

export const openWoundFormulaEffectBuilder = (uuid?: string) => openEffectBuilder("wounds", uuid);
export const openItemGrantEffectBuilder = (uuid?: string) => openEffectBuilder("grant", uuid);
export const openRandomItemEffectBuilder = (uuid?: string) => openEffectBuilder("random", uuid);
export const openItemChoiceEffectBuilder = (uuid?: string) => openEffectBuilder("choice", uuid);

export const openAgeHeightEffectBuilder = (uuid?: string) => openEffectBuilder("age-height", uuid);
