import type {
  ActorPortraitApplyTarget,
  ActorPortraitGalleryBridge,
} from "../../../types/portrait-gallery";

import { assertFoundryActor } from "../../foundry/document-guards";
import {
  filterExcludedPortraitCandidates,
  listFoundryPortraitCandidates,
} from "../../foundry/portrait-search";

export const foundryActorPortraitGalleryBridge: ActorPortraitGalleryBridge = {
  applyActorPortrait,
  filterPortraitCandidates: filterExcludedPortraitCandidates,
  listPortraitCandidates: listFoundryPortraitCandidates,
};

async function applyActorPortrait(
  actorUuid: string,
  portraitPath: string,
  target: ActorPortraitApplyTarget,
): Promise<void> {
  const actor = assertFoundryActor(
    await fromUuid(actorUuid),
    "The Actor for this portrait gallery is no longer available.",
  );

  await actor.update(createActorPortraitUpdate(portraitPath, target));
}

export function createActorPortraitUpdate(
  portraitPath: string,
  target: ActorPortraitApplyTarget,
): Record<string, string> {
  if (target === "portrait") {
    return { img: portraitPath };
  }

  if (target === "token") {
    return { "prototypeToken.texture.src": portraitPath };
  }

  return {
    "img": portraitPath,
    "prototypeToken.texture.src": portraitPath,
  };
}
