import type { NpcBuilderSettings } from "../../../../../types/npc-builder";

export function createSettingsSavePayload(options: {
  canUseDigDownPortraitSearch: boolean;
  settings: NpcBuilderSettings;
}): NpcBuilderSettings {
  const { canUseDigDownPortraitSearch, settings } = options;

  return {
    allowBaseActorCharacteristics: settings.allowBaseActorCharacteristics,
    allowBaseActorSkills: settings.allowBaseActorSkills,
    allowBaseActorTalents: settings.allowBaseActorTalents,
    allowBaseActorTraits: settings.allowBaseActorTraits,
    allowBaseActorTrappings: settings.allowBaseActorTrappings,
    askForLinkedSkillSpecializations: settings.askForLinkedSkillSpecializations,
    autoSelectGrantedSpells: settings.autoSelectGrantedSpells,
    baseActorFolderUuid: settings.baseActorFolderUuid,
    excludeFullyTransparentPortraitAssets: settings.excludeFullyTransparentPortraitAssets,
    excludedPortraitReferenceImages: [...settings.excludedPortraitReferenceImages],
    includeSpeciesInName: settings.includeSpeciesInName,
    lowerCareerMode: settings.lowerCareerMode,
    outputActorFolderUuid: settings.outputActorFolderUuid,
    prioritizedPortraitFolders: [...settings.prioritizedPortraitFolders],
    quickTraitFolderUuid: settings.quickTraitFolderUuid,
    searchCompendiumPortraitAssets: settings.searchCompendiumPortraitAssets,
    searchFoundryPortraitAssets:
      canUseDigDownPortraitSearch && settings.searchFoundryPortraitAssets,
    searchWebPortraitAssets: settings.searchWebPortraitAssets,
  };
}
