import type { NpcTrappingDraftEntry } from "../../../../../../types/npc-builder";

import { blankItemOptionValue } from "./constants";

export function getTrappingSourceLabel(trapping: NpcTrappingDraftEntry): string {
  if (trapping.source === "base") {
    return "Base";
  }

  if (trapping.source === "career") {
    return "Career";
  }

  return "Custom";
}

export function getResolutionLabel(trapping: NpcTrappingDraftEntry): string {
  if (trapping.resolution.status === "matched") {
    return `Matched ${trapping.resolution.selectedName}`;
  }

  if (trapping.resolution.status === "fallback") {
    return `Blank ${trapping.resolution.selectedName || trapping.name}`;
  }

  if (trapping.resolution.candidates.length) {
    return "Choose a match";
  }

  return "Needs resolution";
}

export function getResolutionStatusLabel(trapping: NpcTrappingDraftEntry): string {
  if (trapping.ignored) {
    return "Ignored";
  }

  if (trapping.resolution.status === "matched") {
    return "Matched";
  }

  if (trapping.resolution.status === "fallback") {
    return "Blank item";
  }

  if (trapping.resolution.status === "ambiguous" || trapping.resolution.candidates.length) {
    return "Choose";
  }

  return "Needs resolution";
}

export function getResolutionStatusPillClass(trapping: NpcTrappingDraftEntry): string[] {
  const baseClass = "dui-badge";

  if (trapping.ignored) {
    return [baseClass, "dui-badge-ghost"];
  }

  if (trapping.resolution.status === "matched") {
    return [baseClass, "dui-badge-success"];
  }

  if (trapping.resolution.status === "fallback") {
    return [baseClass, "dui-badge-info"];
  }

  if (trapping.resolution.status === "ambiguous" || trapping.resolution.candidates.length) {
    return [baseClass, "dui-badge-warning"];
  }

  return [baseClass, "dui-badge-error"];
}

export function getResolutionValue(trapping: NpcTrappingDraftEntry): string {
  return trapping.resolution.status === "fallback"
    ? blankItemOptionValue
    : trapping.resolution.selectedCandidateUuid;
}

export function canUseBlankItem(trapping: NpcTrappingDraftEntry): boolean {
  return trapping.source === "career";
}

export function shouldShowResolutionSelect(trapping: NpcTrappingDraftEntry): boolean {
  return trapping.resolution.candidates.length > 0 || canUseBlankItem(trapping);
}

export function getResolutionTermsLabel(trapping: NpcTrappingDraftEntry): string {
  if (trapping.resolution.searchTerms.length <= 1) {
    return "";
  }

  return `Options: ${trapping.resolution.searchTerms.join(" / ")}`;
}
