import { ref } from "vue";

import type { PortraitFilterSection } from "../../../types/portrait-gallery";

import { parsePortraitSearchInput } from "../../functions/portrait-gallery";

export function createPortraitFilterState() {
  const customPortraitSearchTerms = ref<string[]>([]);
  const portraitSourceTagSections = ref<Record<string, Exclude<PortraitFilterSection, "removed">>>(
    {},
  );
  const portraitTermSections = ref<Record<string, PortraitFilterSection>>({});

  function addCustomPortraitSearchTerm(value: string): void {
    const existingTerms = new Set(customPortraitSearchTerms.value);
    const addedTerms = parsePortraitSearchInput(value).filter((term) => !existingTerms.has(term));

    if (addedTerms.length) {
      customPortraitSearchTerms.value = [...customPortraitSearchTerms.value, ...addedTerms];
    }

    for (const term of addedTerms) {
      portraitTermSections.value[term] = "search";
    }
  }

  function resetPortraitFilters(): void {
    customPortraitSearchTerms.value = [];
    portraitSourceTagSections.value = {};
    portraitTermSections.value = {};
  }

  function setPortraitSourceTagSection(sourceLabel: string, section: PortraitFilterSection): void {
    if (section === "removed") {
      return;
    }

    portraitSourceTagSections.value[sourceLabel] = section;
  }

  function setPortraitTermSection(term: string, section: PortraitFilterSection): void {
    if (section === "removed" && customPortraitSearchTerms.value.includes(term)) {
      customPortraitSearchTerms.value = customPortraitSearchTerms.value.filter(
        (entry) => entry !== term,
      );
      delete portraitTermSections.value[term];
      return;
    }

    portraitTermSections.value[term] = section;
  }

  function retainAvailablePortraitFilterTerms(searchTerms: string[]): void {
    const availableTerms = new Set([...searchTerms, ...customPortraitSearchTerms.value]);

    for (const term of Object.keys(portraitTermSections.value)) {
      if (!availableTerms.has(term)) {
        delete portraitTermSections.value[term];
      }
    }
  }

  return {
    addCustomPortraitSearchTerm,
    customPortraitSearchTerms,
    portraitSourceTagSections,
    portraitTermSections,
    resetPortraitFilters,
    retainAvailablePortraitFilterTerms,
    setPortraitSourceTagSection,
    setPortraitTermSection,
  };
}
