import { ref, type Ref } from "vue";

import type { NpcBuilderBridge, NpcPortraitCandidate } from "../../../../../../types/npc-builder";

import { createPortraitCandidatesWorkflow } from "../../../state/workflows/portrait-candidates-workflow";

export function usePortraitCandidates(bridge: NpcBuilderBridge, errorMessage: Ref<string>) {
  const workflow = createPortraitCandidatesWorkflow(bridge, errorMessage);
  const isPortraitGalleryOpen = ref(false);

  function selectPortraitFromGallery(candidate: NpcPortraitCandidate): void {
    workflow.selectPortrait(candidate);
  }

  return {
    ...workflow,
    isPortraitGalleryOpen,
    selectPortraitFromGallery,
  };
}
