import type {
  SpeciesOption,
  SpeciesTableSourceDraft,
  SpeciesTableSourceRow,
} from "../../../types/species/index";

import { readUnknownPath } from "../shared/object-readers";

export const MANAGED_SPECIES_TABLE_FLAG = "managedSpeciesTable";

export interface SpeciesTableRowSummary {
  chance: number;
  range: [number, number];
}

export interface SpeciesTableDescriptionLink {
  label: string;
  uuid: string;
}

export function createEmptySpeciesTableDraft(): SpeciesTableSourceDraft {
  return {
    isRegistered: false,
    name: "Species",
    ownership: "new",
    requiresLinkRepair: false,
    rows: [],
  };
}

export function prepareSpeciesTableDraft(
  draft: SpeciesTableSourceDraft,
  options: SpeciesOption[],
): SpeciesTableSourceDraft {
  const labels = new Map(options.map((option) => [option.key, option.label]));

  return {
    ...draft,
    rows: draft.rows.map((row) => ({
      ...row,
      name: labels.get(row.speciesKey) ?? row.name.trim(),
      speciesKey: row.speciesKey.trim(),
    })),
  };
}

export function validateSpeciesTableDraft(
  draft: SpeciesTableSourceDraft,
  options: SpeciesOption[],
  requireRows: boolean,
): string[] {
  if (draft.rows.length === 0) {
    return requireRows ? ["Add at least one species before saving or registering this table."] : [];
  }

  const knownKeys = new Set(options.map((option) => option.key));
  const seenKeys = new Set<string>();
  const seenNames = new Set<string>();
  const errors: string[] = [];

  draft.rows.forEach((row, index) => {
    const rowNumber = index + 1;

    if (!row.speciesKey || !knownKeys.has(row.speciesKey)) {
      const label = row.name.trim() ? ` “${row.name.trim()}”` : "";
      errors.push(`Row ${rowNumber}${label} must be assigned to a known WFRP species.`);
    } else if (seenKeys.has(row.speciesKey)) {
      errors.push(`Row ${rowNumber} repeats species “${row.name}”.`);
    } else {
      seenKeys.add(row.speciesKey);
    }

    const normalizedName = row.name.trim().toLocaleLowerCase();

    if (!row.speciesKey.startsWith("item:") && normalizedName && seenNames.has(normalizedName)) {
      errors.push(`Row ${rowNumber} repeats species name "${row.name.trim()}".`);
    } else if (!row.speciesKey.startsWith("item:") && normalizedName) {
      seenNames.add(normalizedName);
    }

    if (/[{}]/u.test(row.name)) {
      errors.push(
        `Row ${rowNumber} has a species name containing { or }, which WFRP cannot parse.`,
      );
    }

    if (!Number.isInteger(row.weight) || row.weight < 1) {
      errors.push(`Row ${rowNumber} needs a whole-number weight of at least 1.`);
    }
  });

  return errors;
}

export function summarizeSpeciesTableRows(rows: SpeciesTableSourceRow[]): SpeciesTableRowSummary[] {
  const weights = rows.map((row) =>
    Number.isInteger(row.weight) && row.weight > 0 ? row.weight : 0,
  );
  const total = weights.reduce((sum, weight) => sum + weight, 0);
  let nextRange = 1;

  return weights.map((weight) => {
    const start = nextRange;
    const end = weight > 0 ? start + weight - 1 : start;
    nextRange = end + 1;

    return {
      chance: total > 0 ? weight / total : 0,
      range: [start, end],
    };
  });
}

export function resolveSpeciesTableKey(
  flaggedKey: string,
  name: string,
  options: SpeciesOption[],
): string {
  const matchingName = options.find((option) => option.label === name.trim());

  if (matchingName) {
    return matchingName.key;
  }

  const normalizedFlag = flaggedKey.trim();

  return options.some((option) => option.key === normalizedFlag) ? normalizedFlag : "";
}

export function parseSpeciesTableDescription(
  value: string,
): SpeciesTableDescriptionLink | undefined {
  const match = /@UUID\[([^\]]+)\]\{([^}]*)\}/u.exec(value);
  const uuid = match?.[1]?.trim() ?? "";
  const label = match?.[2]?.trim() ?? "";

  return uuid && label ? { label, uuid } : undefined;
}

export function speciesTableWeightFromSource(source: unknown): number {
  const range = readUnknownPath(source, ["range"]);
  const start = Array.isArray(range) ? Number(range[0]) : 0;
  const end = Array.isArray(range) ? Number(range[1]) : 0;

  if (Number.isInteger(start) && Number.isInteger(end) && end >= start) {
    return end - start + 1;
  }

  const weight = Number(readUnknownPath(source, ["weight"]));

  return Number.isInteger(weight) && weight > 0 ? weight : 1;
}

export function snapshotSpeciesTable(draft: SpeciesTableSourceDraft): string {
  return JSON.stringify(
    draft.rows.map((row) => ({
      name: row.name.trim(),
      speciesKey: row.speciesKey.trim(),
      weight: row.weight,
    })),
  );
}

export function buildSpeciesTableSource(
  draft: SpeciesTableSourceDraft,
  flagScope: string,
): Record<string, unknown> {
  const summaries = summarizeSpeciesTableRows(draft.rows);
  const totalWeight = draft.rows.reduce(
    (sum, row) => sum + (Number.isInteger(row.weight) && row.weight > 0 ? row.weight : 0),
    0,
  );

  return {
    displayRoll: true,
    flags: {
      wfrp4e: { key: "species" },
      [flagScope]: { [MANAGED_SPECIES_TABLE_FLAG]: true },
    },
    formula: `1d${Math.max(totalWeight, 1)}`,
    img: "systems/wfrp4e/ui/buttons/d10.webp",
    name: managedSpeciesTableName(draft),
    replacement: true,
    results: draft.rows.map((row, index) => ({
      description: buildSpeciesTableDescription(row),
      drawn: false,
      flags: { wfrp4e: { species: row.speciesKey } },
      img: "icons/svg/d20-grey.svg",
      name: row.name,
      range: summaries[index]?.range ?? [1, 1],
      ...(row.speciesKey.startsWith("item:")
        ? { type: "document", documentUuid: row.journalUuid }
        : { type: "text" }),
      weight: row.weight,
    })),
  };
}

function buildSpeciesTableDescription(row: SpeciesTableSourceRow): string {
  const journalUuid = row.journalUuid?.trim() ?? "";
  const name = row.name.trim();

  if (!journalUuid) {
    throw new Error(`Species "${name || row.speciesKey}" does not have a document link target.`);
  }
  if (/[{}]/u.test(name)) {
    throw new Error(`Species "${name}" cannot be encoded in WFRP's UUID-link label.`);
  }

  return `@UUID[${journalUuid}]{${name}}`;
}

function managedSpeciesTableName(draft: SpeciesTableSourceDraft): string {
  const name = draft.name.trim() || "Species";

  return draft.ownership === "external" && !name.endsWith("(Customizer)")
    ? `${name} (Customizer)`
    : name;
}
