<script setup lang="ts">
import type { NpcBaseActorSummary } from "../../../../../../types/npc-builder";

import NpcBuilderSection from "../NpcBuilderSection.vue";
import { toInitials } from "./labels";

withDefaults(
  defineProps<{
    actorFilter: string;
    description?: string;
    errorMessage: string;
    filteredActors: NpcBaseActorSummary[];
    isLoadingActors: boolean;
    isLoadingBaseDraft: boolean;
    number?: string;
    selectedBaseActor: NpcBaseActorSummary | null;
    selectedBaseActorUuid: string;
    title?: string;
  }>(),
  {
    description: "Choose a world Actor as the starting statblock.",
    number: "1",
    title: "Base Actor",
  },
);

const emit = defineEmits<{
  actorFilterChange: [value: string];
  baseActorChange: [uuid: string];
}>();

function handleActorFilterInput(event: Event): void {
  const input = event.target as HTMLInputElement | null;

  emit("actorFilterChange", input?.value ?? "");
}

function handleBaseActorChange(event: Event): void {
  const select = event.target as HTMLSelectElement | null;

  emit("baseActorChange", select?.value ?? "");
}
</script>

<template>
  <NpcBuilderSection :description="description" :number="number" :title="title">
    <fieldset class="dui-fieldset">
      <legend class="dui-fieldset-legend">Search world actors</legend>
      <input
        aria-label="Search world actors"
        class="dui-input dui-input-sm"
        :value="actorFilter"
        placeholder="Filter actors"
        type="search"
        @input="handleActorFilterInput"
      />
    </fieldset>

    <fieldset class="dui-fieldset">
      <legend class="dui-fieldset-legend">Base statblock</legend>
      <select
        aria-label="Base statblock"
        class="dui-select dui-select-sm"
        :disabled="isLoadingActors"
        :value="selectedBaseActorUuid"
        @change="handleBaseActorChange"
      >
        <option value="">
          {{ isLoadingActors ? "Loading actors..." : "Choose an actor" }}
        </option>
        <option v-for="actor in filteredActors" :key="actor.uuid" :value="actor.uuid">
          {{ actor.name }}
        </option>
      </select>
    </fieldset>

    <p v-if="errorMessage" class="dui-alert dui-alert-error" role="alert">
      {{ errorMessage }}
    </p>

    <article v-if="selectedBaseActor" class="dui-alert">
      <div v-if="selectedBaseActor.img" class="dui-avatar">
        <div class="app:size-16 app:shrink-0 app:rounded-lg">
          <img
            :src="selectedBaseActor.img"
            alt=""
            class="app:h-full app:w-full app:object-cover"
            height="64"
            width="64"
          />
        </div>
      </div>
      <span v-else class="dui-badge">{{ toInitials(selectedBaseActor.name) }}</span>
      <div>
        <strong>{{ selectedBaseActor.name }}</strong>
        <span>
          {{ selectedBaseActor.species || "Species not found" }}
          <template v-if="selectedBaseActor.type"> - {{ selectedBaseActor.type }}</template>
          <template v-if="isLoadingBaseDraft"> - loading details...</template>
        </span>
      </div>
    </article>
  </NpcBuilderSection>
</template>
