import { isRecord, readStringPath } from "../../functions/shared/object-readers";
import { registerSpeciesTable } from "../species-table/documents/persistence";
import { inspectConfiguredSpeciesTable, inspectSpeciesTable } from "./table-policy";

export const DEFAULT_SPECIES_TABLE_UUID =
  "Compendium.wfrp4e-customizer-apps.species-tables.RollTable.a341d269e7805bc2";

/** Import only the table: its results continue to reference the supplied Species compendium. */
export async function useDefaultSpeciesTable(): Promise<void> {
  if (!game.user?.isGM) throw new Error("Only a GM can change the configured Species table.");
  // A different GM may already have fixed the world while this dialog was open.
  if ((await inspectConfiguredSpeciesTable()).valid) return;
  let table: FoundryRollTableDocument | undefined;
  for (const candidate of game.tables?.contents ?? []) {
    const source = candidate.toObject();
    const origin = readStringPath(source, ["_stats", "compendiumSource"]);
    const legacyOrigin = readStringPath(source, ["flags", "core", "sourceId"]);
    if (origin !== DEFAULT_SPECIES_TABLE_UUID && legacyOrigin !== DEFAULT_SPECIES_TABLE_UUID)
      continue;
    if ((await inspectSpeciesTable(candidate)).valid) {
      table = candidate;
      break;
    }
  }
  if (!table) {
    const shipped = await fromUuid(DEFAULT_SPECIES_TABLE_UUID);
    const validation = await inspectSpeciesTable(shipped);
    if (!validation.valid || !isRecord(shipped) || typeof shipped["toObject"] !== "function")
      throw new Error(`The default Species table is unavailable or invalid. ${validation.reason}`);
    const source: unknown = shipped["toObject"]();
    if (!isRecord(source)) throw new Error("The default Species table has no source data.");
    for (const key of ["_id", "folder", "_stats"]) delete source[key];
    source["_stats"] = { compendiumSource: DEFAULT_SPECIES_TABLE_UUID };
    table = (await RollTable.create(source)) ?? undefined;
    if (!table) throw new Error("Foundry could not import the default Species table.");
  }
  await registerSpeciesTable(table.id);
}
