import type { SpeciesItemSystem } from "../../../../types/species/item";
import { speciesStartingProfile } from "../../../functions/species-item/actor-profile";
import { isRecord } from "../../../functions/shared/object-readers";

export function actorCharacteristicInitials(actor: FoundryActorDocument): Record<string, number> {
  const source = actor.toObject()["system"];
  const characteristics = isRecord(source) ? source["characteristics"] : undefined;
  if (!isRecord(characteristics)) throw new Error("This Actor has no characteristics.");
  const initial: Record<string, number> = {};
  for (const [key, value] of Object.entries(characteristics))
    if (isRecord(value) && typeof value["initial"] === "number") initial[key] = value["initial"];
  return initial;
}

export function actorSpeciesStartingProfile(
  actor: FoundryActorDocument,
  system: SpeciesItemSystem,
) {
  const update = speciesStartingProfile(system);
  const initial = actorCharacteristicInitials(actor);
  // Vehicles have only Toughness. Never introduce characteristics their model does not support.
  for (const key of Object.keys(system.characteristics))
    if (!(key in initial)) delete update[`system.characteristics.${key}.initial`];
  if (actor.type === "vehicle" && system.movement !== null) {
    const source = actor.toObject()["system"];
    const details = isRecord(source) ? source["details"] : undefined;
    const move = isRecord(details) ? details["move"] : undefined;
    if (!isRecord(move)) throw new Error("This Vehicle has no Movement data.");
    const custom = move["custom"];
    const mode =
      isRecord(custom) && custom["label"] && custom["value"] ? "custom" : move["primary"];
    if (mode !== "custom" && mode !== "sail" && mode !== "oars")
      throw new Error("This Vehicle has no active Movement mode.");
    // Vehicle move.value is derived during preparation; update the mode that supplies it.
    delete update["system.details.move.value"];
    update[`system.details.move.${mode}.value`] = system.movement;
  }
  return update;
}
