import type {
  NpcAdvancementDraftEntry,
  NpcBaseAdvancementSummary,
  NpcCustomAdvancementSummary,
} from "../../../../types/npc-builder";

import {
  readNumberFromPaths,
  readStringPath,
  setObjectPath,
} from "../../../functions/shared/object-readers";
import {
  isWfrpCharacteristicKey,
  WFRP_CHARACTERISTIC_KEY_BY_NAME,
  WFRP_CHARACTERISTIC_NAMES,
  type WfrpCharacteristicKey,
} from "../../../../types/wfrp4e/characteristics";
import {
  createItemSourceFromMatch,
  findActorItemByNameAndType,
  findActorItemsByNameAndType,
} from "../../../foundry/item-sources";
import { isFoundryItem } from "../../../foundry/document-guards";
import {
  applyEmbeddedItemChanges,
  createEmptyEmbeddedItemChanges,
  type EmbeddedItemChanges,
} from "../../../foundry/embedded-items";
import { findWfrpItemByNameAndType } from "../../item-lookup";
import { readStoredCharacteristicValue } from "../xp-source-values";

export async function applyAdvancements(
  actor: FoundryActorDocument,
  advancements: NpcAdvancementDraftEntry[],
): Promise<void> {
  const actorUpdates: Record<string, unknown> = {};
  const itemChanges = createEmptyEmbeddedItemChanges();

  for (const advancement of advancements) {
    const additionalValue = Math.floor(advancement.current);

    if (advancement.kind === "talent") {
      await prepareTalentRankChanges(actor, advancement, additionalValue, itemChanges);
      continue;
    }

    const finalValue = advancement.baseAdvances + additionalValue;

    if (advancement.kind === "characteristic") {
      if (additionalValue === 0) {
        continue;
      }

      applyCharacteristicAdvancement(actorUpdates, advancement, finalValue);
      continue;
    }

    const existingItem = findActorItemByNameAndType(actor, advancement.name, advancement.kind);

    if (additionalValue === 0 && !advancement.includedFromCustom && !existingItem) {
      continue;
    }

    if (existingItem) {
      itemChanges.updates.push({
        "_id": existingItem.id,
        "system.advances.value": finalValue,
      });
      continue;
    }

    const sourceItem = await findAdvancementSourceItem(advancement);
    const itemData = createItemSourceFromMatch(sourceItem, advancement.name, advancement.kind);

    itemData["type"] = advancement.kind;
    setObjectPath(itemData, ["system", "advances", "value"], finalValue);
    itemChanges.creates.push(itemData);
  }

  if (Object.keys(actorUpdates).length) {
    await actor.update(actorUpdates);
  }

  await applyEmbeddedItemChanges(actor, itemChanges);
}

export function readDroppedAdvancement(item: FoundryItemDocument): NpcCustomAdvancementSummary {
  const itemSystem = item.toObject()["system"];
  const advances = readNumberFromPaths(itemSystem, [["advances", "value"], ["advances"]]);

  if (item.type === "talent") {
    return {
      advances: Math.max(1, advances),
      kind: "talent",
      name: item.name,
      sourceUuid: item.uuid,
      talentMaximumFormula: readStringPath(itemSystem, ["max", "formula"]),
      talentMaximumKey: readStringPath(itemSystem, ["max", "value"]),
    };
  }

  const characteristicKey = readSkillCharacteristicKey(itemSystem);
  const advancement: NpcCustomAdvancementSummary = {
    advances,
    kind: "skill",
    name: item.name,
    sourceUuid: item.uuid,
  };

  if (characteristicKey) {
    advancement.characteristicKey = characteristicKey;
    advancement.characteristicName = WFRP_CHARACTERISTIC_NAMES[characteristicKey];
  }

  return advancement;
}

export function readCharacteristicAdvancements(
  actor: FoundryActorDocument,
): NpcBaseAdvancementSummary[] {
  const actorSystem = actor.toObject()["system"];
  const advancements: NpcBaseAdvancementSummary[] = [];

  for (const [key, name] of Object.entries(WFRP_CHARACTERISTIC_NAMES)) {
    const baseAdvances = readNumberFromPaths(actorSystem, [
      ["characteristics", key, "advances", "value"],
      ["characteristics", key, "advances"],
    ]);
    const baseModifier = readNumberFromPaths(actorSystem, [
      ["characteristics", key, "modifier", "value"],
      ["characteristics", key, "modifier"],
    ]);
    const initial = readNumberFromPaths(
      actorSystem,
      [
        ["characteristics", key, "initial", "value"],
        ["characteristics", key, "initial"],
      ],
      0,
    );

    advancements.push({
      baseAdvances,
      baseModifier,
      current: initial + baseModifier + baseAdvances,
      kind: "characteristic",
      name,
    });
  }

  return advancements;
}

export function readItemAdvancements(
  actor: FoundryActorDocument,
  kind: "skill" | "talent",
): NpcBaseAdvancementSummary[] {
  if (kind === "talent") {
    return readTalentAdvancements(actor);
  }

  return (
    actor.items?.contents
      .filter((item) => item.type === kind)
      .map((item) => readItemAdvancement(actor, item, kind)) ?? []
  );
}

function readTalentAdvancements(actor: FoundryActorDocument): NpcBaseAdvancementSummary[] {
  const advancements = new Map<string, NpcBaseAdvancementSummary>();

  for (const item of actor.items?.contents.filter((entry) => entry.type === "talent") ?? []) {
    const itemSystem = item.toObject()["system"];
    const key = item.name.trim().toLocaleLowerCase();
    const ranks = readNumberFromPaths(itemSystem, [["advances", "value"], ["advances"]]);
    const existing = advancements.get(key);

    if (existing) {
      existing.baseAdvances += ranks;
      existing.current += ranks;
      continue;
    }

    advancements.set(key, {
      baseAdvances: ranks,
      current: ranks,
      kind: "talent",
      name: item.name,
      talentMaximumFormula: readStringPath(itemSystem, ["max", "formula"]),
      talentMaximumKey: readStringPath(itemSystem, ["max", "value"]),
    });
  }

  return [...advancements.values()];
}

function readItemAdvancement(
  actor: FoundryActorDocument,
  item: FoundryItemDocument,
  kind: "skill" | "talent",
): NpcBaseAdvancementSummary {
  const itemSystem = item.toObject()["system"];
  const explicitAdvances = readNumberFromPaths(itemSystem, [["advances", "value"], ["advances"]]);

  if (kind === "talent") {
    return {
      baseAdvances: explicitAdvances,
      current: explicitAdvances,
      kind,
      name: item.name,
      talentMaximumFormula: readStringPath(itemSystem, ["max", "formula"]),
      talentMaximumKey: readStringPath(itemSystem, ["max", "value"]),
    };
  }

  const baseModifier = readNumberFromPaths(itemSystem, [["modifier", "value"], ["modifier"]]);
  const characteristicKey = readSkillCharacteristicKey(itemSystem);
  const characteristicValue = characteristicKey
    ? readStoredCharacteristicValue(actor.toObject()["system"], characteristicKey)
    : 0;

  const summary: NpcBaseAdvancementSummary = {
    baseAdvances: explicitAdvances,
    baseModifier,
    current: characteristicValue + explicitAdvances + baseModifier,
    kind,
    name: item.name,
  };

  if (characteristicKey) {
    summary.characteristicKey = characteristicKey;
    summary.characteristicName = WFRP_CHARACTERISTIC_NAMES[characteristicKey];
  }

  return summary;
}

function readSkillCharacteristicKey(system: unknown): undefined | WfrpCharacteristicKey {
  const key = readStringPath(system, ["characteristic", "value"]);

  return isWfrpCharacteristicKey(key) ? key : undefined;
}

function applyCharacteristicAdvancement(
  actorUpdates: Record<string, unknown>,
  advancement: NpcAdvancementDraftEntry,
  finalValue: number,
): void {
  const key = WFRP_CHARACTERISTIC_KEY_BY_NAME[advancement.name.trim().toLocaleLowerCase()];

  if (!key) {
    return;
  }

  actorUpdates[`system.characteristics.${key}.advances`] = finalValue;
}

async function prepareTalentRankChanges(
  actor: FoundryActorDocument,
  advancement: NpcAdvancementDraftEntry,
  additionalRanks: number,
  changes: EmbeddedItemChanges,
): Promise<void> {
  const targetRanks = Math.max(0, advancement.baseAdvances + additionalRanks);
  const existingItems = findActorItemsByNameAndType(actor, advancement.name, "talent");
  const sourceItem = existingItems[0] ?? (await findAdvancementSourceItem(advancement));

  changes.deletes.push(...existingItems.map((item) => item.id));

  for (let rank = 0; rank < targetRanks; rank += 1) {
    const itemData = createItemSourceFromMatch(sourceItem, advancement.name, "talent");

    itemData["type"] = "talent";
    setObjectPath(itemData, ["system", "advances", "value"], 1);
    changes.creates.push(itemData);
  }
}

async function findAdvancementSourceItem(
  advancement: NpcAdvancementDraftEntry,
): Promise<FoundryItemDocument | null> {
  if (advancement.sourceUuid) {
    const sourceItem = await fromUuid(advancement.sourceUuid);

    if (isFoundryItem(sourceItem)) {
      return sourceItem;
    }
  }

  return findWfrpItemByNameAndType(advancement.name, [advancement.kind]);
}
