import type { SpeciesItemReference, SpeciesItemSystem } from "../../../types/species/item";
import { isRecord } from "../../functions/shared/object-readers";
import { isSpeciesItem, readSpeciesItemSystem } from "./documents/adapter";
import { findImportedReference } from "./documents/imported-references";
import { worldSpeciesItems } from "./documents/repository";

export async function readSpeciesParent(
  reference: SpeciesItemReference,
): Promise<SpeciesItemSystem | null> {
  if (!reference.uuid && !reference.id) return null;
  const parent =
    findImportedReference(reference, worldSpeciesItems()) ??
    (reference.uuid ? await fromUuid(reference.uuid) : undefined);
  if (
    !isRecord(parent) ||
    typeof parent["type"] !== "string" ||
    !isSpeciesItem({ type: parent["type"] }) ||
    typeof parent["toObject"] !== "function"
  ) {
    throw new Error("The parent Species Item could not be resolved.");
  }
  const source: unknown = parent["toObject"].call(parent);
  if (!isRecord(source)) throw new Error("The parent Species Item has no source data.");
  // Match upstream's immediate-parent placeholders, without recursively compiling ancestors.
  return readSpeciesItemSystem(source["system"]);
}
