import { isRecord } from "../../functions/shared/object-readers";
import type { GrantItemReference } from "../../../types/item-grants";
import { assertFoundryItem } from "../../foundry/document-guards";
import { createGrantItemReference } from "../grant/item-documents";

export async function resolveEffectDrop(data: string): Promise<unknown> {
  const payload: unknown = JSON.parse(data);
  if (!isRecord(payload) || typeof payload["uuid"] !== "string")
    throw new Error("Drop a document or enter its UUID.");
  return fromUuid(payload["uuid"]);
}

export function editableEffectDestination(document: unknown): FoundryItemDocument {
  const item = assertFoundryItem(document, "Choose an Item to receive the effect.");
  if (!game.user || !item.canUserModify(game.user, "update"))
    throw new Error("You do not have permission to edit this Item.");
  if (item.compendium?.locked)
    throw new Error("Unlock the destination compendium or import its Item into the world.");
  return item;
}

export async function resolveEffectItemDrop(
  data: string,
  destination = false,
): Promise<GrantItemReference> {
  const document = await resolveEffectDrop(data);
  const item = destination
    ? editableEffectDestination(document)
    : assertFoundryItem(document, "Choose an Item to grant.");
  return createGrantItemReference(item);
}

export function readTableReference(document: unknown): GrantItemReference {
  if (
    !isRecord(document) ||
    document["documentName"] !== "RollTable" ||
    typeof document["uuid"] !== "string" ||
    typeof document["name"] !== "string"
  )
    throw new Error("Choose a RollTable containing Item document results.");
  return { uuid: document["uuid"], name: document["name"] };
}

export async function validateGrantTable(
  uuid: string,
  destinationUuid: string,
  ancestors: string[] = [],
): Promise<void> {
  if (ancestors.includes(uuid))
    throw new Error("The grant RollTables contain a circular reference.");
  if (ancestors.length > 5) throw new Error("The grant RollTables exceed Foundry's nesting limit.");
  const document = await fromUuid(uuid);
  readTableReference(document);
  const results = isRecord(document) ? document["results"] : undefined;
  const entries = isRecord(results) ? results["contents"] : undefined;
  if (!Array.isArray(entries) || !entries.length) throw new Error("The grant RollTable is empty.");
  for (const entry of entries) {
    const resultUuid = isRecord(entry) ? entry["documentUuid"] : undefined;
    if (typeof resultUuid !== "string" || !resultUuid)
      throw new Error("Grant RollTables must use Item or nested RollTable document results.");
    if (resultUuid === destinationUuid) throw new Error("An Item cannot grant itself.");
    const source = await fromUuid(resultUuid);
    if (isRecord(source) && source["documentName"] === "RollTable")
      await validateGrantTable(resultUuid, destinationUuid, [...ancestors, uuid]);
    else assertFoundryItem(source, `The RollTable result ${resultUuid} is not an available Item.`);
  }
}
