import type { SpellResolutionInput } from "./types";

import { readUnknownPath } from "../../../../functions/shared/object-readers";
import { logWarning } from "../../../../foundry/logging";
import { isItemPack, listSpellInputsFromIndex } from "./compendium-spell-inputs";
import { spellItemType } from "./constants";
import { logSpellLookupDebug, readPackDebugLabel, summarizeSpellInput } from "./debug";
import { toSpellResolutionInput } from "./spell-input-conversion";
import { listSpellInputsFromWarhammerUtility } from "./warhammer-spell-inputs";

export { toSpellResolutionInput } from "./spell-input-conversion";

export async function listSpellResolutionInputs(): Promise<SpellResolutionInput[]> {
  const spells: SpellResolutionInput[] = [];
  const packs = [...(game.packs ?? [])];

  logSpellLookupDebug("Candidate lookup start", {
    itemPacks: packs.filter(isItemPack).length,
    totalPacks: packs.length,
    warhammerUtilityAvailable: Boolean(readUnknownWarhammerFindAllItemsFunction()),
    worldItems: game.items?.contents.length ?? 0,
  });

  const utilityInputs = await listSpellInputsFromWarhammerUtility();

  logSpellLookupDebug("WFRP helper lookup complete", {
    utilityInputs: utilityInputs.length,
    utilitySamples: utilityInputs.slice(0, 10).map(summarizeSpellInput),
  });

  spells.push(...utilityInputs);
  spells.push(...listWorldSpellInputs());

  logSpellLookupDebug("World spell scan complete", {
    worldSpellCount: spells.filter((spell) => spell.sourceLabel === "World").length,
  });

  for (const pack of packs) {
    if (!isItemPack(pack)) {
      continue;
    }

    try {
      const packInputs = await listSpellInputsFromIndex(pack);

      spells.push(...packInputs);
      logSpellLookupDebug("Compendium spell scan complete", {
        inputCount: packInputs.length,
        pack: readPackDebugLabel(pack),
        samples: packInputs.slice(0, 5).map(summarizeSpellInput),
      });
    } catch (error) {
      logWarning(
        `wfrp4e-customizer-apps | Spell lookup skipped compendium "${pack.title ?? pack.collection ?? "unknown"}".`,
        error,
      );
    }
  }

  const uniqueInputs = uniqueSpellInputs(spells);

  logSpellLookupDebug("Candidate lookup complete", {
    rawInputCount: spells.length,
    uniqueInputCount: uniqueInputs.length,
  });

  return uniqueInputs;
}

function listWorldSpellInputs(): SpellResolutionInput[] {
  const spells: SpellResolutionInput[] = [];

  for (const item of game.items?.contents ?? []) {
    if (item.type === spellItemType) {
      spells.push(toSpellResolutionInput(item, "World"));
    }
  }

  return spells;
}

function uniqueSpellInputs(inputs: SpellResolutionInput[]): SpellResolutionInput[] {
  const uniqueInputs = new Map<string, SpellResolutionInput>();

  for (const input of inputs) {
    const key = input.uuid || input.name.trim().toLocaleLowerCase();

    if (!uniqueInputs.has(key)) {
      uniqueInputs.set(key, input);
    }
  }

  return [...uniqueInputs.values()];
}

function readUnknownWarhammerFindAllItemsFunction(): unknown {
  return readUnknownPath(globalThis, ["warhammer", "utility", "findAllItems"]);
}
