import { ref } from "vue";

import { useNpcBuilderStore } from "../../../state";

export function useCareerQueue() {
  const store = useNpcBuilderStore();
  const draggedCareerIndex = ref<null | number>(null);
  const dragOverCareerIndex = ref<null | number>(null);

  function setCareerQuantity(index: number, event: Event): void {
    const input = event.target as HTMLInputElement | null;

    if (input) {
      store.setCareerQuantity(index, Number(input.value));
    }
  }

  function handleCareerDragStart(index: number, event: DragEvent): void {
    draggedCareerIndex.value = index;
    dragOverCareerIndex.value = index;
    event.dataTransfer?.setData("text/plain", `npc-builder-career:${index}`);

    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = "move";
    }
  }

  function handleCareerDragOver(index: number, event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    dragOverCareerIndex.value = index;

    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = "move";
    }
  }

  function handleCareerDrop(index: number, event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();

    if (draggedCareerIndex.value !== null) {
      store.moveCareerToIndex(draggedCareerIndex.value, index);
    }

    clearCareerDragState();
  }

  function clearCareerDragState(): void {
    draggedCareerIndex.value = null;
    dragOverCareerIndex.value = null;
  }

  function setDragOverCareerIndex(index: number): void {
    dragOverCareerIndex.value = index;
  }

  function moveCareer(index: number, direction: -1 | 1): void {
    store.moveCareer(index, direction);
  }

  function removeCareer(index: number): void {
    store.removeCareer(index);
  }

  return {
    clearCareerDragState,
    draggedCareerIndex,
    dragOverCareerIndex,
    handleCareerDragOver,
    handleCareerDragStart,
    handleCareerDrop,
    moveCareer,
    removeCareer,
    setCareerQuantity,
    setDragOverCareerIndex,
  };
}
