import { storeToRefs } from "pinia";
import { computed, ref, type Ref } from "vue";

import type { NpcBuilderBridge, NpcBuilderBuildRequest } from "../../../../../types/npc-builder";
import type { NpcBuilderActiveTab } from "./types";

import { useNpcBuilderStore } from "../../state";
import { toErrorMessage } from "./errors";

export function useNpcBuilderBuild(
  bridge: NpcBuilderBridge,
  activeTab: Ref<NpcBuilderActiveTab>,
  buildMessage: Ref<string>,
  errorMessage: Ref<string>,
  isFindingLowerCareers: Ref<boolean>,
) {
  const store = useNpcBuilderStore();
  const {
    advancements,
    buildTraits,
    careers,
    finalActorName,
    finalPortraitPath,
    selectedMountActorUuid,
    selectedBaseActor,
    selectedSpells,
    settings,
    trappings,
  } = storeToRefs(store);
  const isBusy = ref(false);

  const canBuild = computed(() => {
    return Boolean(
      selectedBaseActor.value &&
      careers.value.length &&
      !isBusy.value &&
      !isFindingLowerCareers.value,
    );
  });

  async function buildNpc(): Promise<void> {
    if (!selectedBaseActor.value || !careers.value.length) {
      return;
    }

    isBusy.value = true;
    errorMessage.value = "";
    buildMessage.value = "Building actor from the selected draft.";

    const request: NpcBuilderBuildRequest = {
      actorName: finalActorName.value,
      advancements: advancements.value,
      baseActorUuid: selectedBaseActor.value.uuid,
      careers: careers.value,
      mountActorUuid: selectedMountActorUuid.value,
      portraitPath: finalPortraitPath.value,
      settings: settings.value,
      spells: selectedSpells.value,
      traits: buildTraits.value,
      trappings: trappings.value,
    };

    try {
      const createdActor = await bridge.buildNpc(request);

      buildMessage.value = `Created ${createdActor.name}.`;
      store.resetDraft();
      activeTab.value = "build-quick";
    } catch (error) {
      errorMessage.value = toErrorMessage(error);
      buildMessage.value = "";
    } finally {
      isBusy.value = false;
    }
  }

  return {
    buildNpc,
    canBuild,
    isBusy,
  };
}
