import { computed, type Ref } from "vue";

import type {
  NpcBaseActorSummary,
  NpcCareerQueueEntry,
  NpcCareerSummary,
  NpcCustomAdvancementSummary,
  NpcSpellDraftEntry,
  NpcTraitDraftEntry,
  NpcTrappingDraftEntry,
} from "../../../../types/npc-builder";
import type { NpcBuilderSettings } from "../../../../types/npc-builder";

import { normalizeQuantity } from "../functions/draft-helpers";
import {
  calculateCareerGrantTotals,
  findSelectedBaseActor,
  getDefaultPortraitPath,
  getFinalActorName,
  getFinalCareer,
  getFinalPortraitPath,
  getSuggestedActorName,
} from "../functions/draft-summary";

interface DraftStoreSliceContext {
  actorName: Ref<string>;
  baseActors: Ref<NpcBaseActorSummary[]>;
  careers: Ref<NpcCareerQueueEntry[]>;
  clearBaseDraftData: () => void;
  clearMountSelection: () => void;
  customAdvancements: Ref<NpcCustomAdvancementSummary[]>;
  customSpells: Ref<NpcSpellDraftEntry[]>;
  customTraits: Ref<NpcTraitDraftEntry[]>;
  customTrappings: Ref<NpcTrappingDraftEntry[]>;
  detectedSpells: Ref<NpcSpellDraftEntry[]>;
  ignoredBaseTraitKeys: Ref<Record<string, boolean>>;
  magicLoreResolutions: Ref<Record<string, string>>;
  removeSkillGrantResolutionsForCareer: (careerUuid: string) => void;
  selectedBaseActorUuid: Ref<string>;
  selectedPortraitPath: Ref<string>;
  settings: Ref<NpcBuilderSettings>;
  skillGrantResolutions: Ref<Record<string, string>>;
  spellSelectionOverrides: Ref<Record<string, boolean>>;
}

export function createDraftStoreSlice(context: DraftStoreSliceContext) {
  const {
    actorName,
    baseActors,
    careers,
    clearBaseDraftData,
    clearMountSelection,
    customAdvancements,
    customSpells,
    customTraits,
    customTrappings,
    detectedSpells,
    ignoredBaseTraitKeys,
    magicLoreResolutions,
    removeSkillGrantResolutionsForCareer,
    selectedBaseActorUuid,
    selectedPortraitPath,
    settings,
    skillGrantResolutions,
    spellSelectionOverrides,
  } = context;

  const selectedBaseActor = computed(() =>
    findSelectedBaseActor(baseActors.value, selectedBaseActorUuid.value),
  );

  const finalCareer = computed(() => getFinalCareer(careers.value));

  const suggestedActorName = computed(() =>
    getSuggestedActorName({
      finalCareer: finalCareer.value,
      selectedBaseActor: selectedBaseActor.value,
      settings: settings.value,
    }),
  );

  const finalActorName = computed(() =>
    getFinalActorName(actorName.value, suggestedActorName.value),
  );

  const defaultPortraitPath = computed(() =>
    getDefaultPortraitPath({
      finalCareer: finalCareer.value,
      selectedBaseActor: selectedBaseActor.value,
    }),
  );

  const finalPortraitPath = computed(() =>
    getFinalPortraitPath(selectedPortraitPath.value, defaultPortraitPath.value),
  );

  const grantTotals = computed(() => calculateCareerGrantTotals(careers.value));

  function addCareer(career: NpcCareerSummary): void {
    const existing = careers.value.find((entry) => entry.uuid === career.uuid);

    if (existing) {
      existing.quantity = normalizeQuantity(existing.quantity + 1);
      return;
    }

    careers.value.push({
      ...career,
      quantity: 1,
    });
  }

  function addCareerIfMissing(career: NpcCareerSummary): boolean {
    if (careers.value.some((entry) => entry.uuid === career.uuid)) {
      return false;
    }

    careers.value.push({
      ...career,
      quantity: 1,
    });

    return true;
  }

  function moveCareer(index: number, direction: -1 | 1): void {
    const nextIndex = index + direction;
    const entry = careers.value[index];

    if (!entry || nextIndex < 0 || nextIndex >= careers.value.length) {
      return;
    }

    careers.value.splice(index, 1);
    careers.value.splice(nextIndex, 0, entry);
  }

  function moveCareerToIndex(fromIndex: number, toIndex: number): void {
    const entry = careers.value[fromIndex];

    if (!entry || fromIndex === toIndex || toIndex < 0 || toIndex >= careers.value.length) {
      return;
    }

    careers.value.splice(fromIndex, 1);
    careers.value.splice(toIndex, 0, entry);
  }

  function removeCareer(index: number): void {
    const [removedCareer] = careers.value.splice(index, 1);

    if (removedCareer) {
      removeSkillGrantResolutionsForCareer(removedCareer.uuid);
    }
  }

  function clearCareers(): void {
    for (const career of careers.value) {
      removeSkillGrantResolutionsForCareer(career.uuid);
    }

    careers.value = [];
  }

  function resetDraft(): void {
    actorName.value = "";
    clearCareers();
    customAdvancements.value = [];
    customTraits.value = [];
    customTrappings.value = [];
    customSpells.value = [];
    detectedSpells.value = [];
    ignoredBaseTraitKeys.value = {};
    magicLoreResolutions.value = {};
    selectedPortraitPath.value = "";
    skillGrantResolutions.value = {};
    spellSelectionOverrides.value = {};
    selectedBaseActorUuid.value = "";
    clearBaseDraftData();
    clearMountSelection();
  }

  function selectBaseActor(actor: NpcBaseActorSummary): void {
    if (!baseActors.value.some((entry) => entry.uuid === actor.uuid)) {
      baseActors.value.push(actor);
    }

    selectBaseActorUuid(actor.uuid);
  }

  function selectBaseActorUuid(uuid: string): void {
    const nextUuid = uuid.trim();

    if (selectedBaseActorUuid.value !== nextUuid) {
      selectedPortraitPath.value = "";
    }

    selectedBaseActorUuid.value = nextUuid;
  }

  function selectPortrait(path: string): void {
    selectedPortraitPath.value = path;
  }

  function setCareerQuantity(index: number, quantity: number): void {
    const entry = careers.value[index];

    if (!entry) {
      return;
    }

    entry.quantity = normalizeQuantity(quantity);
  }

  return {
    addCareer,
    addCareerIfMissing,
    clearCareers,
    finalActorName,
    finalCareer,
    finalPortraitPath,
    grantTotals,
    moveCareer,
    moveCareerToIndex,
    removeCareer,
    resetDraft,
    selectBaseActor,
    selectBaseActorUuid,
    selectedBaseActor,
    selectPortrait,
    setCareerQuantity,
    suggestedActorName,
  };
}
