import { storeToRefs } from "pinia";
import { onMounted, ref, type Ref, watch } from "vue";

import type { NpcBuilderBridge, NpcSelectOption } from "../../../../../types/npc-builder";

import { useNpcBuilderStore } from "../../state";
import { toErrorMessage } from "./errors";

export function useNpcBuilderInitialData(bridge: NpcBuilderBridge, errorMessage: Ref<string>) {
  const store = useNpcBuilderStore();
  const { selectedBaseActorUuid, selectedMountActorUuid, settings } = storeToRefs(store);
  const isLoadingActors = ref(false);
  const isLoadingBaseDraft = ref(false);
  const traitDifficultyOptions = ref<NpcSelectOption[]>([]);

  onMounted(async () => {
    isLoadingActors.value = true;

    try {
      const [savedSettings, actorFolderSummaries, itemFolderSummaries, difficultyOptions] =
        await Promise.all([
          bridge.loadSettings(),
          bridge.listActorFolders(),
          bridge.listItemFolders(),
          bridge.listTraitDifficultyOptions(),
        ]);

      store.hydrateSettings(savedSettings);
      store.hydrateActorFolders(actorFolderSummaries);
      store.hydrateItemFolders(itemFolderSummaries);
      traitDifficultyOptions.value = difficultyOptions;

      await Promise.all([refreshBaseActors(), refreshMountActors(), refreshQuickTraits()]);
    } catch (error) {
      errorMessage.value = toErrorMessage(error);
    } finally {
      isLoadingActors.value = false;
    }
  });

  watch(selectedBaseActorUuid, async (baseActorUuid) => {
    errorMessage.value = "";

    if (!baseActorUuid) {
      store.clearBaseDraftData();
      store.hydrateBaseActorCombatProfile(null);
      return;
    }

    if (baseActorUuid === selectedMountActorUuid.value) {
      store.clearMountSelection();
    }

    store.hydrateBaseActorCombatProfile(null);
    isLoadingBaseDraft.value = true;

    try {
      const [draftData, combatProfile] = await Promise.all([
        bridge.loadBaseActorDraftData(baseActorUuid),
        bridge.loadActorCombatProfile(baseActorUuid),
      ]);

      store.hydrateBaseActorDraftData(draftData);
      store.hydrateBaseActorCombatProfile(combatProfile);
    } catch (error) {
      errorMessage.value = toErrorMessage(error);
      store.clearBaseDraftData();
      store.hydrateBaseActorCombatProfile(null);
    } finally {
      isLoadingBaseDraft.value = false;
    }
  });

  async function refreshBaseActors(): Promise<void> {
    store.hydrateBaseActors(await bridge.listBaseActors(settings.value));
  }

  async function refreshQuickTraits(): Promise<void> {
    store.hydrateQuickTraits(await bridge.listQuickTraits(settings.value));
  }

  async function refreshMountActors(): Promise<void> {
    store.hydrateMountActors(await bridge.listMountActors());
  }

  return {
    isLoadingActors,
    isLoadingBaseDraft,
    refreshBaseActors,
    refreshMountActors,
    refreshQuickTraits,
    traitDifficultyOptions,
  };
}
