import { isRecord } from "../../functions/shared/object-readers";
import { isFoundryItem } from "../../foundry/document-guards";
import { isSpeciesItem } from "../species-item/documents/adapter";

export function speciesDocumentUuid(row: Record<string, unknown>): string | undefined {
  return row["type"] === "document" &&
    typeof row["documentUuid"] === "string" &&
    row["documentUuid"]
    ? row["documentUuid"]
    : undefined;
}

export function configuredSpeciesTable(): unknown {
  return game.wfrp4e?.tables?.findTable?.("species");
}

/** Validate the whole table. A valid subset must never make a mixed table rollable. */
export async function inspectSpeciesTable(table: unknown) {
  const choices: Record<string, string> = {};
  const invalid = (reason: string) => ({ valid: false as const, choices: {}, reason });
  if (
    !isRecord(table) ||
    table["documentName"] !== "RollTable" ||
    typeof table["toObject"] !== "function"
  )
    return invalid("No usable Species table is configured.");
  const source: unknown = table["toObject"]();
  const results = isRecord(source) ? source["results"] : undefined;
  if (!Array.isArray(results) || !results.length) return invalid("The Species table is empty.");
  for (const row of results) {
    const uuid = isRecord(row) ? speciesDocumentUuid(row) : undefined;
    if (!uuid) return invalid("Every Species table result must be a Species Item document result.");
    try {
      const item = await fromUuid(uuid);
      if (!isFoundryItem(item) || !isSpeciesItem(item) || item.actor)
        return invalid("Every Species table result must link a world or compendium Species Item.");
      if (game.user && !game.user.isGM && !item.testUserPermission(game.user, "OBSERVER"))
        return invalid("A Species table Item is not readable by this user.");
      choices[`item:${uuid}`] = item.name;
    } catch {
      return invalid("A Species table Item could not be resolved.");
    }
  }
  return { valid: true as const, choices, reason: "" };
}

export async function inspectConfiguredSpeciesTable() {
  return inspectSpeciesTable(configuredSpeciesTable());
}
