import type {
  NpcActorCombatProfile,
  NpcCombinedProfilePlan,
} from "../../../../../types/npc-builder";

import { isArmourTraitName } from "../../../../apps/npc-builder/functions/combined-profile";
import { readNumberFromPaths, setObjectPath } from "../../../../functions/shared/object-readers";
import { createItemSourceFromMatch } from "../../../../foundry/item-sources";
import { findWfrpItemByNameAndType } from "../../../item-lookup";
import { findMountTrait } from "./trait-sources";

export async function applyCombinedProfileArmour(
  actor: FoundryActorDocument,
  mount: FoundryActorDocument,
  mountProfile: NpcActorCombatProfile,
  plan: NpcCombinedProfilePlan,
): Promise<void> {
  const actorArmourTraits = actor.items?.contents.filter(isArmourTrait) ?? [];
  const mountArmourContributions = plan.traits.filter((trait) => {
    return trait.included && isArmourTraitName(trait.name);
  });
  const existingArmour = strongestActorArmour(actorArmourTraits);
  const mountArmour = strongestMountArmour(mountProfile, mountArmourContributions);
  const targetArmour = Math.max(existingArmour.value, mountArmour.value) + 1;

  if (existingArmour.item && actor.updateEmbeddedDocuments) {
    await actor.updateEmbeddedDocuments("Item", [
      {
        "_id": existingArmour.item.id,
        "system.specification.value": String(targetArmour),
      },
    ]);
    return;
  }

  const mountSource = mountArmour.contribution
    ? findMountTrait(mount, mountArmour.contribution)
    : null;
  const sourceItem = mountSource ?? (await findWfrpItemByNameAndType("Armour", ["trait"]));
  const source = createItemSourceFromMatch(sourceItem, "Armour", "trait");

  source["name"] = "Armour";
  source["type"] = "trait";
  setObjectPath(source, ["system", "disabled"], false);
  setObjectPath(source, ["system", "specification", "value"], String(targetArmour));
  await actor.createEmbeddedDocuments("Item", [source]);
}

function strongestActorArmour(items: FoundryItemDocument[]): {
  item: FoundryItemDocument | null;
  value: number;
} {
  return items.reduce(
    (strongest, item) => {
      const value = readNumberFromPaths(item.system, [["specification", "value"]]);

      return value > strongest.value ? { item, value } : strongest;
    },
    { item: null as FoundryItemDocument | null, value: 0 },
  );
}

function strongestMountArmour(
  profile: NpcActorCombatProfile,
  contributions: NpcCombinedProfilePlan["traits"],
): { contribution: NpcCombinedProfilePlan["traits"][number] | null; value: number } {
  return contributions.reduce(
    (strongest, contribution) => {
      const trait = profile.traits.find((entry) => entry.uuid === contribution.sourceUuid);
      const value = Number(trait?.specification);

      return Number.isFinite(value) && value > strongest.value
        ? { contribution, value }
        : strongest;
    },
    { contribution: null as NpcCombinedProfilePlan["traits"][number] | null, value: 0 },
  );
}

function isArmourTrait(item: FoundryItemDocument): boolean {
  return item.type === "trait" && isArmourTraitName(item.name);
}
