import type { NpcSelectOption } from "../../../../../types/npc-builder";

import { isRecord, readUnknownPath } from "../../../../functions/shared/object-readers";

const fallbackDifficultyOptions: NpcSelectOption[] = [
  { label: "Very Easy", value: "veasy" },
  { label: "Easy", value: "easy" },
  { label: "Average", value: "average" },
  { label: "Challenging", value: "challenging" },
  { label: "Difficult", value: "difficult" },
  { label: "Hard", value: "hard" },
  { label: "Very Hard", value: "vhard" },
  { label: "Futile", value: "futile" },
  { label: "Impossible", value: "impossible" },
];

export async function listTraitDifficultyOptions(): Promise<NpcSelectOption[]> {
  const labels = readUnknownPath(game.wfrp4e?.config, ["difficultyLabels"]);

  if (!isRecord(labels)) {
    return fallbackDifficultyOptions;
  }

  const options = Object.entries(labels)
    .filter((entry): entry is [string, string] => {
      const [value, label] = entry;

      return Boolean(value.trim()) && typeof label === "string";
    })
    .map(([value, label]) => ({ label, value }));

  return options.length ? options : fallbackDifficultyOptions;
}
