import type { SpellResolutionInput } from "./types";

import {
  isRecord,
  readStringPath,
  readUnknownPath,
} from "../../../../functions/shared/object-readers";
import { logInfo, logWarning } from "../../../../foundry/logging";
import { readSpellLoreTerms } from "./lore-profiles";

// Temporary diagnostics for live Foundry spell lookup debugging. Keep all logs
// under one prefix so the noisy parts can be filtered or removed together.
const spellLookupDebugPrefix = "[Drowsy's WFRP4e Customizers][Spell Lookup]";

export function logSpellLookupDebug(message: string, details?: Record<string, unknown>): void {
  if (details) {
    logInfo(`${spellLookupDebugPrefix} ${message}`, details);
    return;
  }

  logInfo(`${spellLookupDebugPrefix} ${message}`);
}

export function warnSpellLookupDebug(message: string, error: unknown): void {
  logWarning(`${spellLookupDebugPrefix} ${message}`, error);
}

export function readPackDebugLabel(pack: FoundryCompendiumCollection): string {
  return [
    pack.title ?? "",
    pack.collection ?? "",
    readStringPath(pack, ["metadata", "type"]),
    readStringPath(pack, ["metadata", "documentName"]),
    pack.documentName,
  ]
    .filter(Boolean)
    .join(" | ");
}

export function summarizeSpellInput(input: SpellResolutionInput): Record<string, unknown> {
  return {
    loreTerms: readSpellLoreTerms(input.system),
    name: input.name,
    sourceLabel: input.sourceLabel,
    uuid: input.uuid,
  };
}

export function summarizeUnknownSpellSource(value: unknown): Record<string, unknown> {
  if (typeof value === "string") {
    return {
      kind: "uuid-string",
      value,
    };
  }

  if (!isRecord(value)) {
    return {
      kind: typeof value,
    };
  }

  return {
    documentName: readStringPath(value, ["documentName"]),
    hasSystem: isRecord(readUnknownPath(value, ["system"])),
    loreTerms: readSpellLoreTerms(readUnknownPath(value, ["system"])),
    name: readStringPath(value, ["name"]),
    type: readStringPath(value, ["type"]),
    uuid: readStringPath(value, ["uuid"]),
  };
}
