import type { NpcBuilderBridge } from "../../../../../types/npc-builder";
import type { PendingSkillResolutionPrompt } from "../../../../../types/npc-builder";

import { usesFreeformSkillSpecialization } from "../../functions/career-workflow/skill-resolution";

export async function hydrateSkillSpecializationSuggestions(
  bridge: NpcBuilderBridge,
  prompt: PendingSkillResolutionPrompt,
): Promise<void> {
  await Promise.all(
    prompt.rows.map(async (row) => {
      if (!usesFreeformSkillSpecialization(row)) {
        return;
      }

      row.isLoadingSuggestions = true;

      try {
        row.suggestedSpecializations = await bridge.listSkillSpecializations(row.baseName);
      } catch {
        row.suggestedSpecializations = [];
      } finally {
        row.isLoadingSuggestions = false;
      }
    }),
  );
}
