import type {
  NpcMagicGrant,
  NpcMagicLoreOption,
  PendingMagicLoreResolutionPrompt,
} from "../../../../types/npc-builder";

import { getMagicLoreOptionsForGrant } from "./magic-grants";

export function createMagicGrantSignature(grants: NpcMagicGrant[]): string {
  return grants
    .map((grant) => `${grant.kind}:${grant.sourceName}:${grant.rawLore}`)
    .sort()
    .join("|");
}

export function getAmbiguousMagicGrants(grants: NpcMagicGrant[]): NpcMagicGrant[] {
  return grants.filter((grant) => grant.isAmbiguous);
}

export function createMagicLoreResolutionPrompt(
  grants: NpcMagicGrant[],
  loreOptions: NpcMagicLoreOption[],
): PendingMagicLoreResolutionPrompt {
  return {
    rows: getAmbiguousMagicGrants(grants).map((grant) => ({
      grantLabel: getMagicGrantResolutionLabel(grant),
      options: getMagicLoreOptionsForGrant(grant, loreOptions),
      rawLore: grant.rawLore,
      resolutionKey: grant.resolutionKey,
      selectedLore: "",
      sourceLabel: getMagicGrantSourceLabel(grant),
    })),
  };
}

export function getMagicGrantKindLabel(grant: NpcMagicGrant): string {
  if (grant.kind === "arcane-magic") {
    return "Arcane Magic";
  }

  if (grant.kind === "petty-magic") {
    return "Petty Magic";
  }

  return "Spellcaster";
}

export function getMagicGrantResolutionLabel(grant: NpcMagicGrant): string {
  return `${getMagicGrantKindLabel(grant)} from ${grant.sourceName}`;
}

export function getMagicGrantSourceLabel(grant: NpcMagicGrant): string {
  return grant.source === "talent" ? "Talent" : "Trait";
}
