import type {
  NpcBaseActorDraftData,
  NpcBaseTraitSummary,
  NpcQuickTraitSummary,
  NpcTraitDraftConfig,
  NpcTraitDraftEntry,
} from "../../../../../types/npc-builder";

import { mergeTraitConfig, namesMatch, normalizeName } from "../draft-helpers";

export function deriveNpcTraits(options: {
  allowBaseActorTraits: boolean;
  baseActorDraftData: NpcBaseActorDraftData;
  customTraits: NpcTraitDraftEntry[];
  ignoredBaseTraitKeys: Record<string, boolean>;
  traitConfigOverrides: Record<string, Partial<NpcTraitDraftConfig>>;
}): NpcTraitDraftEntry[] {
  const entries = new Map<string, NpcTraitDraftEntry>();

  if (options.allowBaseActorTraits) {
    for (const trait of options.baseActorDraftData.traits) {
      const key = getBaseTraitKey(trait);

      if (options.ignoredBaseTraitKeys[key]) {
        continue;
      }

      entries.set(key, createBaseTraitDraft(trait, key, false));
    }
  }

  for (const trait of options.customTraits) {
    if (!hasTraitName([...entries.values()], trait.name)) {
      entries.set(trait.key, { ...trait });
    }
  }

  return [...entries.values()]
    .map((entry) => ({
      ...entry,
      config: mergeTraitConfig(entry.config, options.traitConfigOverrides[entry.key]),
    }))
    .sort(compareTraits);
}

export function deriveNpcBuildTraits(options: {
  allowBaseActorTraits: boolean;
  baseActorDraftData: NpcBaseActorDraftData;
  ignoredBaseTraitKeys: Record<string, boolean>;
  selectedTraits: NpcTraitDraftEntry[];
  traitConfigOverrides: Record<string, Partial<NpcTraitDraftConfig>>;
}): NpcTraitDraftEntry[] {
  if (!options.allowBaseActorTraits) {
    return options.selectedTraits;
  }

  const ignoredBaseTraits = options.baseActorDraftData.traits
    .filter((trait) => options.ignoredBaseTraitKeys[getBaseTraitKey(trait)])
    .map((trait) => {
      const key = getBaseTraitKey(trait);

      return {
        ...createBaseTraitDraft(trait, key, true),
        config: mergeTraitConfig(trait.config, options.traitConfigOverrides[key]),
      };
    });

  return [...ignoredBaseTraits, ...options.selectedTraits];
}

export function deriveOptionalTraits(
  baseActorDraftData: NpcBaseActorDraftData,
): NpcQuickTraitSummary[] {
  return baseActorDraftData.optionalTraits
    .map((trait) => ({
      config: trait.config,
      img: trait.img,
      name: trait.name,
      uuid: trait.uuid,
    }))
    .sort((left, right) => left.name.localeCompare(right.name));
}

export function createSelectedTraitDraft(
  source: "optional" | "quick",
  trait: NpcQuickTraitSummary,
): NpcTraitDraftEntry {
  return {
    config: trait.config,
    ignored: false,
    key: `${source}:${trait.uuid || normalizeName(trait.name)}`,
    name: trait.name,
    source,
    sourceUuid: trait.uuid,
  };
}

export function getBaseTraitKey(trait: NpcBaseTraitSummary): string {
  return `base:${trait.uuid || normalizeName(trait.name)}`;
}

export function findTraitByName<TTrait extends { name: string }>(
  traits: TTrait[],
  name: string,
): TTrait | undefined {
  return traits.find((trait) => namesMatch(trait.name, name));
}

export function hasTraitName(traits: Array<{ name: string }>, name: string): boolean {
  return findTraitByName(traits, name) !== undefined;
}

function createBaseTraitDraft(
  trait: NpcBaseTraitSummary,
  key: string,
  ignored: boolean,
): NpcTraitDraftEntry {
  return {
    config: trait.config,
    ignored,
    key,
    name: trait.name,
    source: "base",
    sourceUuid: trait.uuid,
  };
}

function compareTraits(left: NpcTraitDraftEntry, right: NpcTraitDraftEntry): number {
  if (left.source !== right.source) {
    return left.source.localeCompare(right.source);
  }

  return left.name.localeCompare(right.name);
}
