export async function findSpeciesGrant(name: string, type: "skill" | "talent") {
  const utility = game.wfrp4e?.utility;
  const item =
    type === "skill" ? await utility?.findSkill?.(name) : await utility?.findTalent?.(name);
  if (!item || item.type !== type) throw new Error(`Cannot find ${type} “${name}”.`);
  return item;
}
