import type { NpcBuilderSettings } from "../../../../types/npc-builder";

import { createDefaultNpcBuilderSettings } from "./default-npc-builder-settings";
import { normalizePortraitFolderPaths } from "../../../functions/portrait-gallery";

const legacyPartialSettingsDefaults: NpcBuilderSettings = {
  ...createDefaultNpcBuilderSettings(),
  allowBaseActorCharacteristics: true,
  allowBaseActorSkills: true,
  allowBaseActorTalents: true,
};

/**
 * Normalizes the unknown object read from Foundry's world setting.
 *
 * Older saved objects predate the three base-advancement visibility toggles.
 * Missing toggles on an otherwise valid object remain enabled so existing
 * worlds keep their historical UI. A wholly missing or invalid setting uses
 * the current defaults, where those optional base rows start hidden.
 */
export function normalizeNpcBuilderSettings(value: unknown): NpcBuilderSettings {
  const currentDefaults = createDefaultNpcBuilderSettings();

  if (!isRecord(value)) {
    return currentDefaults;
  }

  return {
    allowBaseActorCharacteristics: readBoolean(
      value["allowBaseActorCharacteristics"],
      legacyPartialSettingsDefaults.allowBaseActorCharacteristics,
    ),
    allowBaseActorSkills: readBoolean(
      value["allowBaseActorSkills"],
      legacyPartialSettingsDefaults.allowBaseActorSkills,
    ),
    allowBaseActorTalents: readBoolean(
      value["allowBaseActorTalents"],
      legacyPartialSettingsDefaults.allowBaseActorTalents,
    ),
    allowBaseActorTraits: readBoolean(
      value["allowBaseActorTraits"],
      legacyPartialSettingsDefaults.allowBaseActorTraits,
    ),
    allowBaseActorTrappings: readBoolean(
      value["allowBaseActorTrappings"],
      legacyPartialSettingsDefaults.allowBaseActorTrappings,
    ),
    askForLinkedSkillSpecializations: readBoolean(
      value["askForLinkedSkillSpecializations"],
      legacyPartialSettingsDefaults.askForLinkedSkillSpecializations,
    ),
    autoSelectGrantedSpells: readBoolean(
      value["autoSelectGrantedSpells"],
      legacyPartialSettingsDefaults.autoSelectGrantedSpells,
    ),
    baseActorFolderUuid: readString(
      value["baseActorFolderUuid"],
      legacyPartialSettingsDefaults.baseActorFolderUuid,
    ),
    excludeFullyTransparentPortraitAssets: readBoolean(
      value["excludeFullyTransparentPortraitAssets"],
      legacyPartialSettingsDefaults.excludeFullyTransparentPortraitAssets,
    ),
    excludedPortraitReferenceImages: normalizePortraitFolderPaths(
      Array.isArray(value["excludedPortraitReferenceImages"])
        ? value["excludedPortraitReferenceImages"]
        : legacyPartialSettingsDefaults.excludedPortraitReferenceImages,
    ),
    includeSpeciesInName: readBoolean(
      value["includeSpeciesInName"],
      legacyPartialSettingsDefaults.includeSpeciesInName,
    ),
    lowerCareerMode: isLowerCareerMode(value["lowerCareerMode"])
      ? value["lowerCareerMode"]
      : legacyPartialSettingsDefaults.lowerCareerMode,
    outputActorFolderUuid: readString(
      value["outputActorFolderUuid"],
      legacyPartialSettingsDefaults.outputActorFolderUuid,
    ),
    prioritizedPortraitFolders: normalizePortraitFolderPaths(value["prioritizedPortraitFolders"]),
    quickTraitFolderUuid: readString(
      value["quickTraitFolderUuid"],
      legacyPartialSettingsDefaults.quickTraitFolderUuid,
    ),
    searchCompendiumPortraitAssets: readBoolean(
      value["searchCompendiumPortraitAssets"],
      legacyPartialSettingsDefaults.searchCompendiumPortraitAssets,
    ),
    searchFoundryPortraitAssets: readBoolean(
      value["searchFoundryPortraitAssets"],
      legacyPartialSettingsDefaults.searchFoundryPortraitAssets,
    ),
    searchWebPortraitAssets: readBoolean(
      value["searchWebPortraitAssets"],
      legacyPartialSettingsDefaults.searchWebPortraitAssets,
    ),
  };
}

function isLowerCareerMode(value: unknown): value is NpcBuilderSettings["lowerCareerMode"] {
  return value === "auto-add-all" || value === "never" || value === "prompt";
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function readBoolean(value: unknown, fallback: boolean): boolean {
  return typeof value === "boolean" ? value : fallback;
}

function readString(value: unknown, fallback: string): string {
  return typeof value === "string" ? value : fallback;
}
