import { storeToRefs } from "pinia";
import { computed } from "vue";

import { getAmbiguousSkillGrant } from "../../../functions/skill-specialization";
import { useNpcBuilderStore } from "../../../state";

export function useBuildPreview() {
  const store = useNpcBuilderStore();
  const { advancements, careers, finalPortraitPath, selectedBaseActor, trappings } =
    storeToRefs(store);

  const careerItemCount = computed(() => {
    let total = 0;

    for (const career of careers.value) {
      total += career.quantity;
    }

    return total;
  });

  const visibleTrappingCount = computed(() => {
    return trappings.value.filter((entry) => !entry.ignored).length;
  });

  const editedAdvanceCount = computed(() => {
    return advancements.value.filter((entry) => entry.current !== entry.careerValue).length;
  });

  const fallbackTrappingCount = computed(() => {
    return trappings.value.filter(
      (entry) => !entry.ignored && entry.resolution.status === "fallback",
    ).length;
  });

  const ignoredTrappingCount = computed(() => {
    return trappings.value.filter((entry) => entry.ignored).length;
  });

  const unresolvedSkillCount = computed(() => {
    return advancements.value.filter(
      (entry) => entry.kind === "skill" && getAmbiguousSkillGrant(entry.name) !== null,
    ).length;
  });

  const unresolvedTrappingCount = computed(() => {
    return trappings.value.filter(
      (entry) => !entry.ignored && entry.resolution.status === "unresolved",
    ).length;
  });

  const buildPreviewWarnings = computed(() => {
    const warnings: string[] = [];

    if (!selectedBaseActor.value) {
      warnings.push("Choose a base Actor before building.");
    }

    if (!careers.value.length) {
      warnings.push("No Careers are queued.");
    }

    if (unresolvedSkillCount.value) {
      warnings.push(`${unresolvedSkillCount.value} skill rows still need a specialization.`);
    }

    if (unresolvedTrappingCount.value) {
      warnings.push(`${unresolvedTrappingCount.value} trappings have no item resolution yet.`);
    }

    if (!finalPortraitPath.value) {
      warnings.push("No portrait is selected.");
    }

    return warnings;
  });

  const buildPreviewStatus = computed(() => {
    return buildPreviewWarnings.value.length ? "Review" : "Ready";
  });

  return {
    buildPreviewStatus,
    buildPreviewWarnings,
    careerItemCount,
    editedAdvanceCount,
    fallbackTrappingCount,
    ignoredTrappingCount,
    visibleTrappingCount,
  };
}
