import type { SpellResolutionInput, WarhammerFindAllItems, WarhammerItemUtility } from "./types";

import { readStringPath, readUnknownPath } from "../../../../functions/shared/object-readers";
import { isFoundryItem } from "../../../../foundry/document-guards";
import { spellItemType } from "./constants";
import { logSpellLookupDebug, summarizeUnknownSpellSource, warnSpellLookupDebug } from "./debug";
import {
  readSpellSourceLabel,
  readSpellSourceLabelFromUuid,
  toSpellResolutionInput,
} from "./spell-input-conversion";

export async function listSpellInputsFromWarhammerUtility(): Promise<SpellResolutionInput[]> {
  const utility = readWarhammerItemUtility();

  if (!utility) {
    logSpellLookupDebug("WFRP helper unavailable");
    return [];
  }

  try {
    // WFRP's own actor tools use this helper for spell selection, and it was
    // observed to find the broadest set of Lore spells in live testing.
    const matches = await utility.findAllItems(spellItemType, "Loading Spells", true, [
      "system.lore.value",
    ]);

    logSpellLookupDebug("WFRP helper raw result", {
      count: matches.length,
      samples: matches.slice(0, 10).map(summarizeUnknownSpellSource),
    });

    const spells = await Promise.all(
      matches.map((match) => toSpellResolutionInputFromUtility(match)),
    );

    return spells.filter((spell): spell is SpellResolutionInput => spell !== null);
  } catch (error) {
    warnSpellLookupDebug("WFRP helper lookup failed.", error);

    return [];
  }
}

async function toSpellResolutionInputFromUtility(
  match: unknown,
): Promise<null | SpellResolutionInput> {
  if (typeof match === "string") {
    const item = await fromUuid(match);

    return isFoundryItem(item) && item.type === spellItemType
      ? toSpellResolutionInput(item, readSpellSourceLabel(item))
      : null;
  }

  if (isFoundryItem(match)) {
    return match.type === spellItemType
      ? toSpellResolutionInput(match, readSpellSourceLabel(match))
      : null;
  }

  if (readStringPath(match, ["type"]) !== spellItemType) {
    return null;
  }

  const name = readStringPath(match, ["name"]);

  if (!name) {
    return null;
  }

  return {
    img: readStringPath(match, ["img"]) || readStringPath(match, ["thumb"]),
    name,
    sourceLabel: readSpellSourceLabelFromUuid(readStringPath(match, ["uuid"]), "WFRP Item Lookup"),
    system: readUnknownPath(match, ["system"]),
    uuid: readStringPath(match, ["uuid"]),
  };
}

function readWarhammerItemUtility(): null | WarhammerItemUtility {
  const findAllItems = readUnknownPath(globalThis, ["warhammer", "utility", "findAllItems"]);

  return typeof findAllItems === "function"
    ? { findAllItems: findAllItems as WarhammerFindAllItems }
    : null;
}
