import type {
  SpeciesOption,
  SpeciesTableSourceDraft,
  SpeciesTableSourceLoad,
  SpeciesTableSourceRow,
} from "../../../../types/species/index";

import {
  parseSpeciesTableDescription,
  resolveSpeciesTableKey,
  speciesTableWeightFromSource,
} from "../../../functions/species-table/source";
import {
  isRecord,
  readStringPath,
  readUnknownPath,
} from "../../../functions/shared/object-readers";
import { WFRP4E_SYSTEM_ID } from "../../../constants";
import { isManagedSpeciesTable } from "./persistence";

const SPECIES_TABLE_KEY = "species";
const TABLE_SETTINGS_KEY = "tableSettings";

export async function loadSpeciesTableSource(
  options: SpeciesOption[],
): Promise<SpeciesTableSourceLoad> {
  const tables = game.tables?.contents ?? [];
  const registeredIds = loadRegisteredSpeciesTableIds();
  const managedTables = tables.filter(isManagedSpeciesTable);
  const table = selectSpeciesTable(tables, managedTables, registeredIds);

  return {
    draft: table
      ? loadTableDraft(table, options, registeredIds[0] === table.id)
      : createNewTableDraft(),
    runtimeOptions: options,
  };
}

function loadRegisteredSpeciesTableIds(): string[] {
  const settings = game.settings.get(WFRP4E_SYSTEM_ID, TABLE_SETTINGS_KEY);
  const value = isRecord(settings) ? settings[SPECIES_TABLE_KEY] : undefined;

  return typeof value === "string"
    ? value
        .split(",")
        .map((id) => id.trim())
        .filter(Boolean)
    : [];
}

function selectSpeciesTable(
  tables: FoundryRollTableDocument[],
  managedTables: FoundryRollTableDocument[],
  registeredIds: string[],
): FoundryRollTableDocument | undefined {
  if (managedTables.length > 1) {
    const registeredManaged = managedTables.filter((table) => registeredIds[0] === table.id);

    if (registeredManaged.length === 1) {
      return registeredManaged[0];
    }

    throw new Error(
      "Multiple Species Builder-managed Species tables exist. Remove the duplicate and reload.",
    );
  }

  if (managedTables[0]) {
    return managedTables[0];
  }

  for (const id of registeredIds) {
    const registered = tables.find((table) => table.id === id);

    if (registered) {
      return registered;
    }
  }

  return tables.find((table) => table.getFlag(WFRP4E_SYSTEM_ID, "key") === SPECIES_TABLE_KEY);
}

function loadTableDraft(
  table: FoundryRollTableDocument,
  options: SpeciesOption[],
  isRegistered: boolean,
): SpeciesTableSourceDraft {
  const source = table.toObject();
  const results = Array.isArray(source["results"]) ? source["results"] : [];
  const rows = results.flatMap((result) => loadTableRow(result, options));

  rows.sort((left, right) => resultRangeStart(left.source) - resultRangeStart(right.source));

  return {
    isRegistered,
    name: table.name,
    ownership: isManagedSpeciesTable(table) ? "managed" : "external",
    requiresLinkRepair: rows.some((entry) => entry.requiresLinkRepair),
    rows: rows.map(({ row }) => row),
    tableId: table.id,
  };
}

function loadTableRow(
  source: unknown,
  options: SpeciesOption[],
): Array<{
  requiresLinkRepair: boolean;
  row: SpeciesTableSourceRow;
  source: unknown;
}> {
  if (!isRecord(source)) {
    return [];
  }

  const name = readStringPath(source, ["name"]);
  const description = readStringPath(source, ["description"]);
  const link = parseSpeciesTableDescription(description);
  const flaggedKey = readStringPath(source, ["flags", WFRP4E_SYSTEM_ID, "species"]);
  const documentUuid = readStringPath(source, ["documentUuid"]);
  const effectiveName = link?.label || name;
  const speciesKey = resolveSpeciesTableKey(flaggedKey, effectiveName, options);
  const resultId = readStringPath(source, ["_id"]);
  const type = readStringPath(source, ["type"]);

  return [
    {
      requiresLinkRepair:
        type === "document"
          ? !documentUuid
          : !link || link.label !== name.trim() || type !== "text",
      row: {
        ...(documentUuid || link ? { journalUuid: documentUuid || link!.uuid } : {}),
        name: effectiveName,
        ...(resultId ? { resultId } : {}),
        speciesKey,
        weight: speciesTableWeightFromSource(source),
      },
      source,
    },
  ];
}

function resultRangeStart(source: unknown): number {
  const range = readUnknownPath(source, ["range"]);
  const start = Array.isArray(range) ? Number(range[0]) : 0;

  return Number.isInteger(start) ? start : 0;
}

function createNewTableDraft(): SpeciesTableSourceDraft {
  return {
    isRegistered: false,
    name: "Species",
    ownership: "new",
    requiresLinkRepair: false,
    rows: [],
  };
}
