<script setup lang="ts">
import type { GrantItemReference } from "../../../../types/item-grants";
import DocumentDrop from "../../shared/view/components/DocumentDrop.vue";
defineProps<{ items: GrantItemReference[]; title: string }>();
defineEmits<{ dropData: [data: string]; remove: [uuid: string] }>();
</script>

<template>
  <DocumentDrop
    :title="title"
    description="Drop an Item to add it to this list."
    variant="compact"
    @drop-data="$emit('dropData', $event)"
  />
  <ul class="dui-list">
    <li v-for="item in items" :key="item.uuid" class="dui-list-row">
      <span class="dui-list-col-grow">{{ item.name }}</span>
      <button
        type="button"
        class="dui-btn dui-btn-sm dui-btn-ghost"
        :aria-label="`Remove ${item.name}`"
        @click="$emit('remove', item.uuid)"
      >
        Remove
      </button>
    </li>
  </ul>
</template>
