import { storeToRefs } from "pinia";
import { computed, type Ref } from "vue";

import type { NpcBuilderBridge } from "../../../../../types/npc-builder";

import {
  createImmediatePortraitCandidates,
  getPortraitSearchTerms,
} from "../../functions/portrait-candidates";
import { createPriorityPortraitFolderPaths } from "../../../../functions/portrait-gallery";
import { createPortraitGalleryWorkflow } from "../../../../state/portrait-gallery/workflow";
import { useNpcBuilderStore } from "..";

export function createPortraitCandidatesWorkflow(
  bridge: NpcBuilderBridge,
  errorMessage: Ref<string>,
) {
  const store = useNpcBuilderStore();
  const {
    careers,
    customPortraitSearchTerms,
    finalPortraitPath,
    portraitSourceTagSections,
    portraitTermSections,
    selectedBaseActor,
    selectedPortraitPath,
    settings,
  } = storeToRefs(store);
  const immediateCandidates = computed(() =>
    createImmediatePortraitCandidates({
      careers: careers.value,
      selectedBaseActor: selectedBaseActor.value,
    }),
  );
  const baseSearchTerms = computed(() =>
    getPortraitSearchTerms({
      careers: careers.value,
      selectedBaseActor: selectedBaseActor.value,
    }),
  );
  const priorityFolderPaths = computed(() =>
    createPriorityPortraitFolderPaths({
      configuredFolders: settings.value.prioritizedPortraitFolders,
      hasCareer: careers.value.length > 0,
    }),
  );
  const workflow = createPortraitGalleryWorkflow({
    activePortraitPath: finalPortraitPath,
    baseSearchTerms,
    errorMessage,
    excludeFullyTransparentImages: computed(
      () => settings.value.excludeFullyTransparentPortraitAssets,
    ),
    excludedReferenceImagePaths: computed(() => settings.value.excludedPortraitReferenceImages),
    filterState: {
      addCustomPortraitSearchTerm: store.addCustomPortraitSearchTerm,
      customPortraitSearchTerms,
      portraitSourceTagSections,
      portraitTermSections,
      retainAvailablePortraitFilterTerms: store.retainAvailablePortraitFilterTerms,
      setPortraitSourceTagSection: store.setPortraitSourceTagSection,
      setPortraitTermSection: store.setPortraitTermSection,
    },
    hasSubject: computed(() => Boolean(selectedBaseActor.value) || careers.value.length > 0),
    immediateCandidates,
    includeCompendiumAssets: computed(() => settings.value.searchCompendiumPortraitAssets),
    includeFilePickerAssets: computed(() => settings.value.searchFoundryPortraitAssets),
    pinnedPortraitPath: selectedPortraitPath,
    priorityFolderPaths,
    provider: {
      filterPortraitCandidates: bridge.filterPortraitCandidates,
      listPortraitCandidates: bridge.listFoundryPortraitCandidates,
    },
    searchErrorMessage: "The NPC Builder could not finish searching for portraits.",
    selectPortrait: (candidate) => store.selectPortrait(candidate.img),
  });
  const compactPortraitCandidates = computed(() => workflow.portraitCandidates.value.slice(0, 4));
  const hiddenPortraitCandidateCount = computed(() =>
    Math.max(0, workflow.portraitCandidates.value.length - compactPortraitCandidates.value.length),
  );

  return {
    ...workflow,
    compactPortraitCandidates,
    hiddenPortraitCandidateCount,
  };
}
