<script setup lang="ts">
import { computed } from "vue";
import { openEffectBuilders } from "../../../wfrp/effect-builders/open";
import { useSpeciesItemStore } from "../state";
const props = defineProps<{ uuid: string; editable: boolean }>();
const store = useSpeciesItemStore(props.uuid);
const groups = computed(() => [
  {
    name: "Temporary Effects",
    entries: store.effects.filter((effect) => effect.temporary && !effect.disabled),
  },
  {
    name: "Effects",
    entries: store.effects.filter((effect) => !effect.temporary && !effect.disabled),
  },
  { name: "Disabled Effects", entries: store.effects.filter((effect) => effect.disabled) },
]);
</script>

<template>
  <p v-if="store.dirty">Save or reload Item changes before editing effects.</p>
  <template v-for="group in groups" :key="group.name">
    <fieldset
      v-if="group.entries.length || group.name === 'Effects'"
      class="dui-fieldset"
      :disabled="!editable || store.dirty"
    >
      <legend class="dui-fieldset-legend">{{ group.name }}</legend>
      <div v-if="group.name === 'Effects'" class="app:flex app:flex-wrap app:gap-2">
        <button type="button" class="dui-btn dui-btn-sm" @click="store.effectAction('create')">
          Add Effect
        </button>
        <button type="button" class="dui-btn dui-btn-sm" @click="openEffectBuilders(uuid)">
          Effect Builders
        </button>
      </div>
      <p v-if="!group.entries.length">No effects.</p>
      <div v-if="group.entries.length" class="app:max-w-full app:overflow-x-auto">
        <table class="dui-table dui-table-sm">
          <thead>
            <tr>
              <th scope="col">Effect</th>
              <th scope="col">Type</th>
              <th scope="col"><span class="app:sr-only">Actions</span></th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="effect in group.entries" :key="effect.id">
              <td>
                <button
                  type="button"
                  class="dui-btn dui-btn-sm dui-btn-ghost app:h-auto app:whitespace-normal"
                  @click="store.effectAction('edit', effect.id)"
                >
                  {{ effect.name }}
                </button>
              </td>
              <td>{{ effect.type }}</td>
              <td>
                <div class="app:flex app:flex-wrap app:gap-2">
                  <button
                    type="button"
                    class="dui-btn dui-btn-sm"
                    @click="store.effectAction('toggle', effect.id)"
                  >
                    {{ effect.disabled ? "Enable" : "Disable" }}
                  </button>
                  <button
                    type="button"
                    class="dui-btn dui-btn-sm"
                    :aria-label="`Delete ${effect.name}`"
                    @click="store.effectAction('delete', effect.id)"
                  >
                    Delete
                  </button>
                </div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </fieldset>
  </template>
</template>
