<script setup lang="ts">
import { nextTick, ref, useId } from "vue";
import { WOUND_FORMULA_KEYWORDS } from "../../../functions/effect-builders/wound-formula-keywords";
import { useEffectBuilderStore } from "../state";
const props = defineProps<{ id: string }>();
const store = useEffectBuilderStore(props.id);
const fieldId = `${props.id}-${useId()}`;
const textarea = ref<HTMLTextAreaElement>();
const tokens = [
  ...WOUND_FORMULA_KEYWORDS,
  "{Strength}",
  "[Toughness]",
  "{Endurance}",
  "[Endurance]",
];

async function insertToken(token: string): Promise<void> {
  const field = textarea.value;
  const start = field?.selectionStart ?? store.draft.formula.length;
  const end = field?.selectionEnd ?? start;
  store.draft.formula = `${store.draft.formula.slice(0, start)}${token}${store.draft.formula.slice(end)}`;
  await nextTick();
  field?.focus();
  field?.setSelectionRange(start + token.length, start + token.length);
}
</script>

<template>
  <fieldset class="dui-fieldset">
    <legend class="dui-fieldset-legend">Wound calculation</legend>
    <label :for="fieldId" class="dui-label">Formula</label>
    <textarea
      :id="fieldId"
      ref="textarea"
      v-model="store.draft.formula"
      aria-label="Formula"
      class="dui-textarea app:w-full"
      rows="3"
      @dragover.prevent
      @drop.prevent="insertToken($event.dataTransfer?.getData('text/plain') ?? '')"
    />
    <p>
      Use <code>{Name}</code> for a characteristic or Skill total and <code>[Name]</code> for its
      bonus. For example: <code>[Endurance] + 2 * @tb</code>.
    </p>
    <p>
      <code>{Endurance|Strength}</code> uses Strength for that Skill. Arithmetic and
      <code>Math.floor</code>, <code>Math.ceil</code>, <code>Math.min</code>, and
      <code>Math.max</code> are supported.
    </p>
    <details class="dui-collapse dui-collapse-arrow">
      <summary class="dui-collapse-title">Insert formula tokens</summary>
      <div class="dui-collapse-content">
        <p>Click a token to insert it at the cursor, or drag it into the formula.</p>
        <div class="app:flex app:flex-wrap app:gap-1">
          <button
            v-for="token in tokens"
            :key="token"
            type="button"
            class="dui-btn dui-btn-xs"
            draggable="true"
            @click="insertToken(token)"
            @dragstart="$event.dataTransfer?.setData('text/plain', token)"
          >
            {{ token }}
          </button>
        </div>
      </div>
    </details>
  </fieldset>
</template>
