import type {
  NpcAdvancementDraftEntry,
  NpcAdvancementKind,
} from "../../../../../types/npc-builder";

export interface NpcAdvancementCurrentChange {
  current: number;
  kind: NpcAdvancementKind;
  name: string;
}

export interface NpcAdvancementTotalChange {
  kind: NpcAdvancementKind;
  name: string;
  total: number;
}

export function getAdvancementStep(advancement: Pick<NpcAdvancementDraftEntry, "kind">): number {
  return advancement.kind === "talent" ? 1 : 5;
}

export function getAdvancementTotal(advancement: NpcAdvancementDraftEntry): number {
  return Math.max(advancement.minimumTotal, advancement.baseValue + advancement.current);
}

export function getAdjustedAdvancementTotal(
  advancement: NpcAdvancementDraftEntry,
  direction: -1 | 1,
): number {
  return getAdvancementTotal(advancement) + direction * getAdvancementStep(advancement);
}

export function getTalentRanks(advancement: NpcAdvancementDraftEntry): number {
  return getAdvancementTotal(advancement);
}

export function canMaximizeTalent(advancement: NpcAdvancementDraftEntry): boolean {
  const maximum = advancement.talentMaximumValue;

  return typeof maximum === "number" && getTalentRanks(advancement) < maximum;
}

export function getMaximizedTalentTotals(
  advancements: NpcAdvancementDraftEntry[],
): NpcAdvancementTotalChange[] {
  return advancements
    .filter((advancement) => advancement.kind === "talent" && canMaximizeTalent(advancement))
    .map((advancement) => ({
      kind: advancement.kind,
      name: advancement.name,
      total: advancement.talentMaximumValue as number,
    }));
}

export function reconcileAdvancementCurrents(
  currentAdvancements: NpcAdvancementDraftEntry[],
  nextAdvancements: NpcAdvancementDraftEntry[],
): NpcAdvancementCurrentChange[] {
  const currentByKey = new Map(
    currentAdvancements.map((advancement) => [getAdvancementIdentity(advancement), advancement]),
  );
  const changes: NpcAdvancementCurrentChange[] = [];

  for (const nextAdvancement of nextAdvancements) {
    const currentAdvancement = currentByKey.get(getAdvancementIdentity(nextAdvancement));

    if (!currentAdvancement || currentAdvancement.current === nextAdvancement.current) {
      continue;
    }

    changes.push({
      current: nextAdvancement.current,
      kind: currentAdvancement.kind,
      name: currentAdvancement.name,
    });
  }

  return changes;
}

export function findAdvancement(
  advancements: NpcAdvancementDraftEntry[],
  change: Pick<NpcAdvancementCurrentChange, "kind" | "name">,
): NpcAdvancementDraftEntry | null {
  return (
    advancements.find(
      (advancement) => advancement.kind === change.kind && advancement.name === change.name,
    ) ?? null
  );
}

function getAdvancementIdentity(
  advancement: Pick<NpcAdvancementDraftEntry, "kind" | "name">,
): string {
  return `${advancement.kind}:${advancement.name}`;
}
