import { isFoundryActor } from "../../foundry/document-guards";
import { logWarning } from "../../foundry/logging";
import { openActorPortraitGalleryForDocument } from "./open";

interface ActorHeaderControl {
  action: string;
  icon: string;
  label: string;
}

interface ActorSheetActionHost {
  document?: unknown;
  element?: unknown;
  options?: {
    actions?: Record<string, (this: ActorSheetActionHost) => void>;
  };
}

const action = "openWfrpCustomizerPortraitGallery";
const buttonClass = "wfrp4e-customizer-actor-portrait-gallery-header";
const headerControlHooks = [
  "getHeaderControlsActorSheetWFRP4eCharacter",
  "getHeaderControlsActorSheetWFRP4eNPC",
  "getHeaderControlsActorSheetWFRP4eCreature",
  "getHeaderControlsStandardWFRP4eActorSheet",
  "getHeaderControlsBaseWFRP4eActorSheet",
  "getHeaderControlsWarhammerActorSheetV2",
];
const renderHooks = [
  "renderActorSheetWFRP4eCharacter",
  "renderActorSheetWFRP4eNPC",
  "renderActorSheetWFRP4eCreature",
  "renderStandardWFRP4eActorSheet",
  "renderBaseWFRP4eActorSheet",
  "renderWarhammerActorSheetV2",
];
let hasRegisteredHooks = false;

export function registerActorPortraitGallerySheetHooks(): void {
  if (hasRegisteredHooks) {
    return;
  }

  hasRegisteredHooks = true;

  for (const hook of headerControlHooks) {
    Hooks.on(hook, addActorHeaderControl);
  }

  for (const hook of renderHooks) {
    Hooks.on(hook, mountFallbackHeaderButton);
  }
}

function addActorHeaderControl(application: unknown, controls: unknown): void {
  const actor = getActorSheetDocument(application);

  if (!actor || !Array.isArray(controls) || actor.isOwner === false) {
    return;
  }

  const headerControls = controls as ActorHeaderControl[];

  if (!headerControls.some((control) => control.action === action)) {
    headerControls.push({
      action,
      icon: "fa-solid fa-images",
      label: "Choose Portrait & Token",
    });
  }

  const host = application as ActorSheetActionHost;
  host.options ??= {};
  host.options.actions ??= {};
  host.options.actions[action] = function () {
    const renderedActor = getActorSheetDocument(this);

    if (renderedActor) {
      void openGallery(renderedActor);
    }
  };
}

function mountFallbackHeaderButton(application: unknown): void {
  const actor = getActorSheetDocument(application);
  const element = getActorSheetElement(application);

  if (!actor || !element || actor.isOwner === false) {
    return;
  }

  const header = element.querySelector<HTMLElement>(".window-header");

  if (!header || header.querySelector(`.${buttonClass}, [data-action="${action}"]`)) {
    return;
  }

  const button = document.createElement("button");
  button.type = "button";
  button.classList.add(buttonClass, "header-control", "icon", "fa-solid", "fa-images");
  button.dataset["action"] = action;
  button.dataset["tooltip"] = "Choose Portrait & Token";
  button.ariaLabel = `Choose a portrait and prototype token for ${actor.name}`;
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    void openGallery(actor);
  });

  const insertionPoint =
    header.querySelector('[data-action="toggleControls"]') ??
    header.querySelector('[data-action="close"]');

  header.insertBefore(button, insertionPoint);
}

function getActorSheetDocument(application: unknown): FoundryActorDocument | null {
  if (typeof application !== "object" || application === null) {
    return null;
  }

  const document = "document" in application ? application.document : undefined;
  const actor = "actor" in application ? application.actor : undefined;

  return isFoundryActor(document) ? document : isFoundryActor(actor) ? actor : null;
}

function getActorSheetElement(application: unknown): HTMLElement | null {
  if (typeof application !== "object" || application === null || !("element" in application)) {
    return null;
  }

  return application.element instanceof HTMLElement ? application.element : null;
}

async function openGallery(actor: FoundryActorDocument): Promise<void> {
  try {
    await openActorPortraitGalleryForDocument(actor);
  } catch (error) {
    logWarning("wfrp4e-customizer-apps | Actor portrait gallery could not be opened.", error);
    ui.notifications?.warn?.(
      "The portrait gallery could not be opened. See the console for details.",
    );
  }
}
