import type {
  NpcTrappingMatchKind,
  NpcTrappingResolution,
  NpcTrappingResolutionCandidate,
} from "../../../../types/npc-builder";

export interface TrappingResolutionItemInput {
  itemType: string;
  name: string;
  sourceLabel: string;
  uuid: string;
}

export function createFallbackTrappingResolution(
  name: string,
  itemType = "trapping",
): NpcTrappingResolution {
  return {
    candidates: [],
    searchTerms: getTrappingSearchTerms(name),
    selectedCandidateUuid: "",
    selectedItemType: itemType,
    selectedName: name.trim(),
    status: "fallback",
  };
}

export function createMatchedTrappingResolution(options: {
  itemType: string;
  name: string;
  uuid: string;
}): NpcTrappingResolution {
  return {
    candidates: [
      {
        itemType: options.itemType,
        matchKind: "exact",
        name: options.name,
        searchTerm: options.name,
        sourceLabel: "Dropped item",
        uuid: options.uuid,
      },
    ],
    searchTerms: [options.name],
    selectedCandidateUuid: options.uuid,
    selectedItemType: options.itemType,
    selectedName: options.name,
    status: "matched",
  };
}

export function createUnresolvedTrappingResolution(name: string): NpcTrappingResolution {
  return {
    candidates: [],
    searchTerms: getTrappingSearchTerms(name),
    selectedCandidateUuid: "",
    selectedItemType: "trapping",
    selectedName: name.trim(),
    status: "unresolved",
  };
}

export function resolveTrappingCandidates(
  name: string,
  items: TrappingResolutionItemInput[],
): NpcTrappingResolution {
  const searchTerms = getTrappingSearchTerms(name);
  const candidates = collectCandidates(searchTerms, items);
  const exactCandidates = candidates.filter((candidate) => candidate.matchKind === "exact");

  if (exactCandidates.length === 1) {
    return createSelectedResolution("matched", searchTerms, exactCandidates[0]);
  }

  if (exactCandidates.length > 1) {
    return createSelectedResolution("ambiguous", searchTerms, exactCandidates[0], {
      candidates,
    });
  }

  if (candidates.length) {
    return {
      candidates,
      searchTerms,
      selectedCandidateUuid: "",
      selectedItemType: "trapping",
      selectedName: name.trim(),
      status: "ambiguous",
    };
  }

  return createFallbackTrappingResolution(name);
}

export function getTrappingSearchTerms(name: string): string[] {
  const terms = name
    .split(/\s+or\s+/i)
    .map((term) => term.trim())
    .filter(Boolean);

  return terms.length ? uniqueStrings(terms) : [name.trim()].filter(Boolean);
}

export function getTrappingMatchKind(
  searchTerm: string,
  itemName: string,
): NpcTrappingMatchKind | null {
  if (normalizeExact(searchTerm) === normalizeExact(itemName)) {
    return "exact";
  }

  const normalizedSearchTerm = normalizeLoose(searchTerm);
  const normalizedItemName = normalizeLoose(itemName);

  if (!normalizedSearchTerm || !normalizedItemName) {
    return null;
  }

  if (normalizedSearchTerm === normalizedItemName) {
    return "near";
  }

  if (
    normalizedSearchTerm.includes(normalizedItemName) ||
    normalizedItemName.includes(normalizedSearchTerm)
  ) {
    return "near";
  }

  const searchTokens = normalizedSearchTerm.split(" ");
  const itemTokens = new Set(normalizedItemName.split(" "));

  if (searchTokens.every((token) => itemTokens.has(token))) {
    return "near";
  }

  return null;
}

function collectCandidates(
  searchTerms: string[],
  items: TrappingResolutionItemInput[],
): NpcTrappingResolutionCandidate[] {
  const candidatesByUuid = new Map<string, NpcTrappingResolutionCandidate>();

  for (const searchTerm of searchTerms) {
    for (const item of items) {
      const matchKind = getTrappingMatchKind(searchTerm, item.name);

      if (!matchKind) {
        continue;
      }

      const existing = candidatesByUuid.get(item.uuid);

      if (existing?.matchKind === "exact") {
        continue;
      }

      candidatesByUuid.set(item.uuid, {
        itemType: item.itemType,
        matchKind,
        name: item.name,
        searchTerm,
        sourceLabel: item.sourceLabel,
        uuid: item.uuid,
      });
    }
  }

  return [...candidatesByUuid.values()].sort(compareCandidates);
}

function compareCandidates(
  left: NpcTrappingResolutionCandidate,
  right: NpcTrappingResolutionCandidate,
): number {
  if (left.matchKind !== right.matchKind) {
    return left.matchKind === "exact" ? -1 : 1;
  }

  return left.name.localeCompare(right.name);
}

function createSelectedResolution(
  status: "ambiguous" | "matched",
  searchTerms: string[],
  selectedCandidate: NpcTrappingResolutionCandidate | undefined,
  options: {
    candidates?: NpcTrappingResolutionCandidate[];
  } = {},
): NpcTrappingResolution {
  return {
    candidates: options.candidates ?? (selectedCandidate ? [selectedCandidate] : []),
    searchTerms,
    selectedCandidateUuid: selectedCandidate?.uuid ?? "",
    selectedItemType: selectedCandidate?.itemType ?? "trapping",
    selectedName: selectedCandidate?.name ?? "",
    status,
  };
}

function normalizeExact(value: string): string {
  return value.trim().toLocaleLowerCase().replaceAll(/\s+/g, " ");
}

function normalizeLoose(value: string): string {
  return normalizeExact(value)
    .replaceAll("&", " and ")
    .replaceAll(/[(),.:;[\]]/g, " ")
    .replaceAll(/\b(a|an|the|some|pair of|pairs of)\b/g, " ")
    .split(/\s+/)
    .map(singularizeToken)
    .filter(Boolean)
    .join(" ");
}

function singularizeToken(token: string): string {
  if (token.endsWith("ies") && token.length > 4) {
    return `${token.slice(0, -3)}y`;
  }

  if (token.endsWith("s") && !token.endsWith("ss") && token.length > 3) {
    return token.slice(0, -1);
  }

  return token;
}

function uniqueStrings(values: string[]): string[] {
  return [...new Set(values)];
}
