<script setup lang="ts">
import { computed } from "vue";

import type {
  NpcActorCombatProfile,
  NpcCombinedProfilePlan,
  NpcMountTraitContribution,
} from "../../../../../../types/npc-builder";

import { NPC_ACTOR_SIZE_LABELS } from "../../../functions/combined-profile";
import NpcBuilderSection from "../NpcBuilderSection.vue";

const props = defineProps<{
  mount: NpcActorCombatProfile;
  plan: NpcCombinedProfilePlan;
  rider: NpcActorCombatProfile;
}>();

const includedTraits = computed(() => props.plan.traits.filter((trait) => trait.included));
const excludedTraits = computed(() => props.plan.traits.filter((trait) => !trait.included));
const profileRows = computed(() => [
  {
    field: "Strength",
    mount: props.mount.characteristics.strength,
    result: props.plan.strength,
    rider: props.rider.characteristics.strength,
    rule: "Rider",
  },
  {
    field: "Toughness",
    mount: props.mount.characteristics.toughness,
    result: props.plan.toughness,
    rider: props.rider.characteristics.toughness,
    rule: "Higher",
  },
  {
    field: "Initiative",
    mount: props.mount.characteristics.initiative,
    result: props.plan.initiative,
    rider: props.rider.characteristics.initiative,
    rule: "Higher",
  },
  {
    field: "Movement",
    mount: props.mount.movement,
    result: props.plan.movement,
    rider: props.rider.movement,
    rule: "Mount",
  },
  {
    field: "Wounds",
    mount: props.mount.wounds,
    result: props.plan.wounds,
    rider: props.rider.wounds,
    rule: "Higher + 25% lower",
  },
  {
    field: "Size",
    mount: NPC_ACTOR_SIZE_LABELS[props.mount.size],
    result: NPC_ACTOR_SIZE_LABELS[props.plan.size],
    rider: NPC_ACTOR_SIZE_LABELS[props.rider.size],
    rule: "Larger",
  },
]);

function traitLabel(trait: NpcMountTraitContribution): string {
  return trait.fixedDamage === null
    ? trait.outputName
    : `${trait.outputName} (fixed Damage ${trait.fixedDamage})`;
}
</script>

<template>
  <NpcBuilderSection
    description="This preview uses the Actors' current prepared values. The build recalculates after applying the rider's Career advances."
    number="2"
    title="Combined Profile Preview"
  >
    <div class="app:max-w-full app:overflow-x-auto">
      <table class="dui-table dui-table-sm">
        <thead>
          <tr>
            <th>Field</th>
            <th>Rider</th>
            <th>Mount</th>
            <th>Combined</th>
            <th>Rule</th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="row in profileRows" :key="row.field">
            <th>{{ row.field }}</th>
            <td>{{ row.rider }}</td>
            <td>{{ row.mount }}</td>
            <td>{{ row.result }}</td>
            <td>{{ row.rule }}</td>
          </tr>
        </tbody>
      </table>
    </div>

    <p class="dui-alert">
      Charge attacks gain +{{ plan.chargeStrengthBonus }} Damage from the mount's Strength Bonus.
      The combined profile also gains at least Armour (1).
    </p>
  </NpcBuilderSection>

  <NpcBuilderSection
    description="Mount attack damage is frozen before the traits are copied to the rider."
    number="3"
    title="Mount Traits"
  >
    <div class="app:flex app:flex-wrap app:gap-2">
      <span v-for="trait in includedTraits" :key="trait.sourceUuid" class="dui-badge dui-badge-sm">
        {{ traitLabel(trait) }}
      </span>
    </div>

    <p v-if="!includedTraits.length">The mount contributes no traits.</p>

    <div v-if="excludedTraits.length" class="app:grid app:gap-2">
      <p><strong>Removed or consolidated</strong></p>
      <p
        v-for="trait in excludedTraits"
        :key="trait.sourceUuid"
        class="dui-alert dui-alert-warning"
      >
        <strong>{{ trait.name }}:</strong> {{ trait.reason }}
      </p>
    </div>
  </NpcBuilderSection>
</template>
