import { type App, type Component, createApp } from "vue";
import { pinia } from "../../state/pinia";
import { DOCUMENT_DROP_BRIDGE_KEY } from "../../../types/foundry/document-drop";
import { foundryDocumentDropBridge } from "../document-drop";

export class VueApplicationMount {
  #app: App<Element> | undefined;

  createRoot(): HTMLElement {
    const root = document.createElement("div");
    root.classList.add("wfrp4e-customizer-apps-root");
    root.dataset["theme"] = "wfrp4e-customizer-apps";
    return root;
  }

  mount(
    root: HTMLElement,
    content: HTMLElement,
    component: Component,
    props: Record<string, unknown>,
  ): void {
    this.unmount();
    content.classList.add("wfrp4e-customizer-apps-app");
    content.replaceChildren(root);
    this.#app = createApp(component, props);
    this.#app.use(pinia);
    this.#app.provide(DOCUMENT_DROP_BRIDGE_KEY, foundryDocumentDropBridge);
    this.#app.mount(root);
  }

  unmount(): void {
    this.#app?.unmount();
    this.#app = undefined;
  }
}
