import type {
  SpeciesGrantItemReference,
  SpeciesLinkedItemName,
} from "../../../types/species/index";

export function formatItemReferenceName(item: SpeciesGrantItemReference): string {
  return formatSpecifiedName(item.name, item.specification);
}

export function formatLinkedItemName(row: SpeciesLinkedItemName): string {
  const name = row.name.trim();

  if (!row.item) {
    return name;
  }

  if (!name) {
    return formatItemReferenceName(row.item);
  }

  if (!hasParentheticalSuffix(name)) {
    if (row.item.specification) {
      return formatSpecifiedName(name, row.item.specification);
    }

    if (hasParentheticalSuffix(row.item.name) && getBaseName(name) === getBaseName(row.item.name)) {
      return row.item.name.trim();
    }
  }

  return name;
}

export function formatSpecifiedName(name: string, specification: string | undefined): string {
  const trimmedName = name.trim();
  const trimmedSpecification = specification?.trim();

  if (!trimmedName || !trimmedSpecification) {
    return trimmedName;
  }

  const existingSpecification = readParentheticalSuffix(trimmedName);

  if (existingSpecification) {
    return trimmedName;
  }

  return `${trimmedName} (${trimmedSpecification})`;
}

export function readParentheticalSuffix(name: string): string {
  return /\(([^()]*)\)\s*$/.exec(name.trim())?.[1]?.trim() ?? "";
}

function hasParentheticalSuffix(name: string): boolean {
  return /\([^()]*\)\s*$/.test(name.trim());
}

function getBaseName(name: string): string {
  return name.split("(")[0]?.trim().toLocaleLowerCase() ?? "";
}
