import type { SpeciesEffectSource } from "../../../../types/species/item";
import { isRecord } from "../../../functions/shared/object-readers";

export function readSpeciesEffectSources(value: unknown): SpeciesEffectSource[] {
  if (value === undefined) return [];
  if (!Array.isArray(value)) throw new Error("Species effects must be embedded Active Effects.");
  return value.map((effect: unknown) => {
    if (!isRecord(effect) || typeof effect["_id"] !== "string")
      throw new Error("Species effects must have Foundry document IDs.");
    return { ...structuredClone(effect), _id: effect["_id"] };
  });
}
