<script setup lang="ts">
import type { NpcBuilderMegaMenuGroup } from "./megamenu-types";
import type { NpcBuilderActivePage } from "./types";

import { getPageLabel } from "./types";

defineProps<{
  activePage: NpcBuilderActivePage;
  groups: NpcBuilderMegaMenuGroup[];
}>();

const emit = defineEmits<{
  pageSelect: [page: NpcBuilderActivePage, event: MouseEvent];
}>();
</script>

<template>
  <span class="dui-megamenu-active" />

  <template v-for="group in groups" :key="group.key">
    <button
      v-if="'page' in group"
      :aria-current="group.isActive ? 'page' : undefined"
      type="button"
      @click="emit('pageSelect', group.page, $event)"
    >
      {{ group.label }}
    </button>
    <template v-else>
      <button
        :aria-current="group.isActive ? 'page' : undefined"
        :popovertarget="group.popoverId"
        type="button"
      >
        {{ group.label }}
      </button>
      <div :id="group.popoverId" popover>
        <ul class="dui-menu app:min-w-56 app:p-2" :class="group.columnsClass">
          <li v-for="item in group.pages" :key="item.page">
            <button
              :class="{ 'dui-menu-active': activePage === item.page }"
              type="button"
              @click="emit('pageSelect', item.page, $event)"
            >
              {{ getPageLabel(item.page) }}
            </button>
          </li>
        </ul>
      </div>
    </template>
  </template>
</template>
