import { MODULE_ID } from "../../constants";
import { KEEP_COMPENDIUMS_TIDY_SETTING } from "./settings";
import type {
  FoundryFolder,
  FoundryGame,
  FoundryPackFolder,
} from "../../../types/foundry/compendium-sidebar";

import {
  descendantIds,
  declaredPackIds,
  folderContainsOwnPack,
  folderContainsForeignPack,
  assertUniqueDeclaration,
} from "../../functions/compendiums/folders";

/** Repair only this module's declared Compendium sidebar hierarchy and pack locations. */
export async function tidyCompendiumSidebar(
  currentGame: FoundryGame,
  createFolder: (data: Record<string, unknown>) => Promise<FoundryFolder | null>,
): Promise<void> {
  if (currentGame.user.isGM !== true || currentGame.user.isActiveGM !== true) return;
  const module = currentGame.modules.get(MODULE_ID);
  if (!module) throw new Error(`Foundry module registry entry was not found for ${MODULE_ID}.`);
  const specs = Array.from(module.packFolders ?? []);
  assertUniqueDeclaration(specs);
  if (specs.length === 0) return;
  for (const spec of specs) {
    for (const packId of declaredPackIds(spec, MODULE_ID)) {
      if (!currentGame.packs.has(packId))
        throw new Error(`Declared Compendium ${packId} was not found.`);
    }
  }
  const folders = Array.from(currentGame.folders).filter((folder) => folder.type === "Compendium");

  async function reconcile(spec: FoundryPackFolder, parent: FoundryFolder | null): Promise<void> {
    const color = spec.color === undefined ? undefined : (spec.color?.toString() ?? null);
    const expectedIds = declaredPackIds(spec, MODULE_ID);
    const siblings = folders.filter(
      (folder) => folder.name === spec.name && (folder.folder?.id ?? null) === (parent?.id ?? null),
    );
    if (siblings.length > 1)
      throw new Error(
        `Ambiguous Compendium folder named ${spec.name} under ${parent?.name ?? "root"}.`,
      );
    let folder: FoundryFolder | null | undefined = siblings[0];
    if (folder && folderContainsForeignPack(MODULE_ID, folder, folders, currentGame.packs))
      throw new Error(`Compendium folder ${spec.name} contains another package's packs.`);
    if (!folder) {
      const displaced = folders.filter(
        (candidate) =>
          candidate.name === spec.name &&
          folderContainsOwnPack(candidate, folders, currentGame.packs, expectedIds),
      );
      if (displaced.length > 1)
        throw new Error(`Ambiguous displaced Compendium folder named ${spec.name}.`);
      folder = displaced[0];
      if (folder) {
        if (parent && descendantIds(folder, folders).has(parent.id))
          throw new Error(`Moving ${spec.name} under ${parent.name} would make a folder cycle.`);
        const parentId = parent?.id ?? null;
        const updated = await folder.update({ folder: parentId });
        if (updated === undefined && (folder.folder?.id ?? null) !== parentId)
          throw new Error(
            `Could not move Compendium folder ${spec.name}; the update was not applied.`,
          );
      } else {
        folder = await createFolder({
          name: spec.name,
          type: "Compendium",
          folder: parent?.id ?? null,
          sorting: spec.sorting,
          ...(color ? { color } : {}),
        });
        if (!folder) throw new Error(`Could not create Compendium folder ${spec.name}.`);
        folders.push(folder);
      }
    }
    const changes: Record<string, unknown> = {};
    if (folder.sorting !== spec.sorting) changes["sorting"] = spec.sorting;
    if (color !== undefined && (folder.color?.toString() ?? null) !== color)
      changes["color"] = color;
    if (Object.keys(changes).length > 0) {
      const updated = await folder.update(changes);
      // An unchanged update is harmless if the folder already has the requested metadata.
      if (
        updated === undefined &&
        (folder.sorting !== spec.sorting ||
          (color !== undefined && (folder.color?.toString() ?? null) !== color))
      )
        throw new Error(
          `Could not configure Compendium folder ${spec.name}; the update was not applied.`,
        );
    }

    for (const name of spec.packs) {
      const packId = `${MODULE_ID}.${name}`;
      const pack = currentGame.packs.get(packId);
      if (!pack) throw new Error(`Declared Compendium ${packId} was not found.`);
      if (pack.folder?.id !== folder.id) await pack.setFolder(folder);
    }
    for (const child of spec.folders) await reconcile(child, folder);
  }

  for (const spec of specs) await reconcile(spec, null);
}

export async function tidyCompendiumSidebarIfEnabled(): Promise<void> {
  if (!game.user?.isGM || game.users?.activeGM?.id !== game.user.id) return;
  if (game.settings.get(MODULE_ID, KEEP_COMPENDIUMS_TIDY_SETTING) !== true) return;
  // Foundry collections iterate documents, while packs.get addresses collection identifiers.
  // This narrow host shape is isolated here; no live documents enter workflow stores.
  const host = game as unknown as Omit<FoundryGame, "user">;
  await tidyCompendiumSidebar(
    {
      modules: host.modules,
      packs: host.packs,
      folders: host.folders,
      user: { isGM: true, isActiveGM: true },
    },
    (data) =>
      Folder.create(data as FoundryFolderSource) as unknown as Promise<FoundryFolder | null>,
  );
}
