import { isRecord, readStringPath } from "../functions/shared/object-readers";

export function getCompendiumIndexEntryUuid(
  pack: FoundryCompendiumCollection,
  entry: FoundryCompendiumIndexEntry,
): string {
  if (entry.uuid) {
    return entry.uuid;
  }

  if (entry._id && pack.getUuid) {
    return pack.getUuid(entry._id);
  }

  return "";
}

export function isItemCompendiumPack(pack: FoundryCompendiumCollection): boolean {
  return (
    pack.documentName === "Item" ||
    readStringPath(pack, ["metadata", "type"]) === "Item" ||
    readStringPath(pack, ["metadata", "documentName"]) === "Item"
  );
}

export function isActorCompendiumPack(pack: FoundryCompendiumCollection): boolean {
  return (
    pack.documentName === "Actor" ||
    readStringPath(pack, ["metadata", "type"]) === "Actor" ||
    readStringPath(pack, ["metadata", "documentName"]) === "Actor"
  );
}

export function isRollTableCompendiumPack(pack: FoundryCompendiumCollection): boolean {
  return (
    pack.documentName === "RollTable" ||
    readStringPath(pack, ["metadata", "type"]) === "RollTable" ||
    readStringPath(pack, ["metadata", "documentName"]) === "RollTable"
  );
}

export function readCompendiumIndexEntries(
  index: FoundryCompendiumIndex,
): FoundryCompendiumIndexEntry[] {
  if (Array.isArray(index)) {
    return index.filter(isCompendiumIndexEntry);
  }

  if (isRecord(index) && Array.isArray(index.contents)) {
    return index.contents.filter(isCompendiumIndexEntry);
  }

  if (!isIterable(index)) {
    return [];
  }

  return [...index].flatMap((entry) => {
    const maybeEntry: unknown = Array.isArray(entry) ? entry[1] : entry;

    return isCompendiumIndexEntry(maybeEntry) ? [maybeEntry] : [];
  });
}

export function yieldToFoundry(): Promise<void> {
  return new Promise((resolve) => {
    globalThis.setTimeout(resolve, 0);
  });
}

function isCompendiumIndexEntry(value: unknown): value is FoundryCompendiumIndexEntry {
  return isRecord(value);
}

function isIterable(value: unknown): value is Iterable<unknown> {
  return isRecord(value) && Symbol.iterator in value;
}
