import { actorSpeciesStartingProfile } from "./profile";
import { effectiveActorSpecies, ownedSpecies } from "./owned";
import { speciesActorSource } from "../documents/actor-source";

const pendingDrops = new WeakSet<FoundryActorDocument>();

/** Only the sheet's drop path prompts. Chargen and ordinary Item creation retain their profiles. */
export async function dropActorSpecies(actor: FoundryActorDocument, item: FoundryItemDocument) {
  if (!actor.isOwner) throw new Error("You cannot change this Actor's Species.");
  if (actor.items?.contents.some((owned) => owned.uuid === item.uuid)) return;
  if (pendingDrops.has(actor)) return;
  if (ownedSpecies(actor))
    throw new Error("Remove the Actor's existing Species Item before dropping another Species.");
  pendingDrops.add(actor);
  try {
    if (game.user && !item.testUserPermission(game.user, "OBSERVER"))
      throw new Error(`You do not have permission to read ${item.name}.`);
    const record = await effectiveActorSpecies(item);
    const source = speciesActorSource(item, record);
    const created = await actor.createEmbeddedDocuments("Item", [source]);
    if (!created.length) return;
    const apply = await foundry.applications.api.DialogV2.confirm({
      window: { title: "Apply Species Characteristics" },
      content:
        "<p>Apply this Species Item's starting characteristics and Movement?</p>" +
        "<p>This replaces initial characteristic values and Movement. Advances and modifiers are kept. " +
        "Choosing No keeps your current profile; the Species Item and its effects remain on the Actor.</p>",
      rejectClose: false,
    });
    // The Item can be removed while the non-modal prompt is open.
    if (apply && actor.items?.contents.includes(created[0] as FoundryItemDocument))
      await actor.update(actorSpeciesStartingProfile(actor, record.system));
    return created;
  } finally {
    pendingDrops.delete(actor);
  }
}
