import type {
  SpeciesTableSourceDraft,
  SpeciesTableSourceRow,
} from "../../../../types/species/index";

import { isRecord, readStringPath } from "../../../functions/shared/object-readers";
import { MODULE_ID } from "../../../constants";

export const GENERATED_SPECIES_JOURNAL_FLAG = "generatedSpeciesJournal";

const GENERATED_JOURNAL_FOLDER_NAME = "WFRP Customizer Species Journals";

export async function ensureSpeciesTableJournalLinks(
  draft: SpeciesTableSourceDraft,
): Promise<SpeciesTableSourceDraft> {
  const journals = game.journal?.contents ?? [];
  const generatedByKey = indexGeneratedJournals(journals);
  let folder: FoundryFolderDocument | undefined;
  const rows: SpeciesTableSourceRow[] = [];

  for (const row of draft.rows) {
    const existingUuid = reusableExistingUuid(row.journalUuid, row.speciesKey, journals);
    let journalUuid = existingUuid || generatedByKey.get(row.speciesKey)?.uuid;

    if (!journalUuid) {
      folder ??= await ensureGeneratedJournalFolder();
      const journal = await JournalEntry.create({
        flags: {
          [MODULE_ID]: {
            [GENERATED_SPECIES_JOURNAL_FLAG]: { speciesKey: row.speciesKey },
          },
        },
        folder: folder.id,
        name: row.name.trim(),
        pages: [],
      });

      if (!journal) {
        throw new Error(`Foundry did not create the Journal Entry for species "${row.name}".`);
      }

      generatedByKey.set(row.speciesKey, journal);
      journalUuid = journal.uuid;
    }

    rows.push({ ...row, journalUuid });
  }

  return { ...draft, requiresLinkRepair: false, rows };
}

function indexGeneratedJournals(
  journals: FoundryJournalEntryDocument[],
): Map<string, FoundryJournalEntryDocument> {
  const generatedByKey = new Map<string, FoundryJournalEntryDocument>();

  for (const journal of journals) {
    const speciesKey = generatedSpeciesKey(journal);

    if (!speciesKey) {
      continue;
    }
    if (generatedByKey.has(speciesKey)) {
      throw new Error(
        `Multiple Species Builder Journals exist for "${speciesKey}". Remove the duplicate and retry.`,
      );
    }

    generatedByKey.set(speciesKey, journal);
  }

  return generatedByKey;
}

function reusableExistingUuid(
  rawUuid: string | undefined,
  speciesKey: string,
  journals: FoundryJournalEntryDocument[],
): string {
  const uuid = rawUuid?.trim() ?? "";

  if (!uuid) {
    return "";
  }

  const worldJournal = journals.find((journal) => journal.uuid === uuid);

  if (!worldJournal) {
    return uuid.startsWith("JournalEntry.") && uuid.split(".").length === 2 ? "" : uuid;
  }

  const generatedKey = generatedSpeciesKey(worldJournal);

  return generatedKey && generatedKey !== speciesKey ? "" : uuid;
}

function generatedSpeciesKey(journal: FoundryJournalEntryDocument): string {
  const flag = journal.getFlag(MODULE_ID, GENERATED_SPECIES_JOURNAL_FLAG);

  return isRecord(flag) ? readStringPath(flag, ["speciesKey"]).trim() : "";
}

async function ensureGeneratedJournalFolder(): Promise<FoundryFolderDocument> {
  const existing = game.folders.contents.find(
    (folder) => folder.type === "JournalEntry" && folder.name === GENERATED_JOURNAL_FOLDER_NAME,
  );

  if (existing) {
    return existing;
  }

  const folder = await Folder.create({
    name: GENERATED_JOURNAL_FOLDER_NAME,
    type: "JournalEntry",
  });

  if (!folder) {
    throw new Error("Foundry did not create the generated Species Journal folder.");
  }

  return folder;
}
