import type { NpcCareerSummary } from "../../types/npc-builder";

import { extractCareerGrants } from "../apps/npc-builder/functions/extract-career-grants";
import { readUnknownPath } from "../functions/shared/object-readers";
import {
  getCompendiumIndexEntryUuid,
  isItemCompendiumPack,
  readCompendiumIndexEntries,
  yieldToFoundry,
} from "../foundry/compendiums";
import { logWarning } from "../foundry/logging";
import { toCareerSummary } from "./career-summary";

const careerIndexFields = [
  "name",
  "type",
  "img",
  "system.careergroup.value",
  "system.characteristics",
  "system.level.value",
  "system.skills",
  "system.talents",
  "system.trappings",
];

const careerIndex = new Map<string, NpcCareerSummary>();
let indexingPromise: null | Promise<void> = null;

export function startCareerIndexing(): Promise<void> {
  if (indexingPromise) {
    return indexingPromise;
  }

  careerIndex.clear();

  indexingPromise = buildCareerIndex().catch((error: unknown) => {
    // Failed partial indexes must never be used as complete Career histories.
    careerIndex.clear();
    indexingPromise = null;
    logWarning("wfrp4e-customizer-apps | Career indexing failed.", error);
    throw error;
  });

  return indexingPromise;
}

export async function findLowerTierCareerCandidates(
  career: NpcCareerSummary,
): Promise<NpcCareerSummary[]> {
  if (!career.careerGroup || career.level === null) {
    return [];
  }

  await startCareerIndexing();

  return [...careerIndex.values()]
    .filter((candidate) => isLowerTierCareerCandidate(candidate, career))
    .sort(sortCareerCandidates);
}

async function buildCareerIndex(): Promise<void> {
  indexWorldCareers();
  await yieldToFoundry();

  for (const pack of game.packs ?? []) {
    if (!isItemCompendiumPack(pack) || !pack.getIndex) {
      continue;
    }

    const index = await pack.getIndex({ fields: careerIndexFields });

    for (const entry of readCompendiumIndexEntries(index)) {
      const careerSummary = toCareerSummaryFromIndex(pack, entry);

      if (careerSummary) {
        careerIndex.set(careerSummary.uuid, careerSummary);
      }
    }

    await yieldToFoundry();
  }
}

function indexWorldCareers(): void {
  for (const item of game.items?.contents ?? []) {
    if (item.type === "career") {
      careerIndex.set(item.uuid, toCareerSummary(item));
    }
  }
}

function toCareerSummaryFromIndex(
  pack: FoundryCompendiumCollection,
  entry: FoundryCompendiumIndexEntry,
): NpcCareerSummary | null {
  const uuid = getCompendiumIndexEntryUuid(pack, entry);

  if (entry.type !== "career" || !entry.name || !uuid) {
    return null;
  }

  const system = readUnknownPath(entry, ["system"]);

  return {
    careerGroup: getCareerGroupFromIndex(entry),
    grants: extractCareerGrants(system),
    img: entry.img ?? "",
    level: getCareerLevelFromIndex(entry),
    name: entry.name,
    uuid,
  };
}

function getCareerGroupFromIndex(entry: FoundryCompendiumIndexEntry): string {
  const value = readUnknownPath(entry, ["system", "careergroup", "value"]);

  return typeof value === "string" ? value.trim() : "";
}

function getCareerLevelFromIndex(entry: FoundryCompendiumIndexEntry): null | number {
  const value = readUnknownPath(entry, ["system", "level", "value"]);
  const level = Number(value);

  return Number.isFinite(level) ? level : null;
}

function isLowerTierCareerCandidate(
  candidate: NpcCareerSummary,
  career: NpcCareerSummary,
): boolean {
  return (
    candidate.uuid !== career.uuid &&
    candidate.level !== null &&
    career.level !== null &&
    candidate.level < career.level &&
    normalizeName(candidate.careerGroup) === normalizeName(career.careerGroup)
  );
}

function normalizeName(value: string): string {
  return value.trim().toLocaleLowerCase();
}

function sortCareerCandidates(left: NpcCareerSummary, right: NpcCareerSummary): number {
  const leftLevel = left.level ?? 0;
  const rightLevel = right.level ?? 0;

  if (leftLevel !== rightLevel) {
    return leftLevel - rightLevel;
  }

  return left.name.localeCompare(right.name);
}
