<script setup lang="ts">
import { storeToRefs } from "pinia";
import { ref } from "vue";

import type { NpcBuilderBridge } from "../../../../../types/npc-builder";
import type { NpcBuilderBuildPage } from "../NpcBuilderApp/types";

import { useNpcBuilderStore } from "../../state";
import BaseActorPanel from "./NpcBuilderBuildTab/BaseActorPanel.vue";
import BuildSidebar from "./NpcBuilderBuildTab/BuildSidebar.vue";
import CareerQueuePanel from "./NpcBuilderBuildTab/CareerQueuePanel.vue";
import NpcBuilderSection from "./NpcBuilderSection.vue";
import PortraitGallery from "./NpcBuilderBuildTab/PortraitGallery.vue";
import QuickCareerPanel from "./NpcBuilderBuildTab/QuickCareerPanel.vue";
import TraitButtonGroup from "./NpcBuilderBuildTab/TraitButtonGroup.vue";
import { useBaseActorSelection } from "./NpcBuilderBuildTab/useBaseActorSelection";
import { useBuildPreview } from "./NpcBuilderBuildTab/useBuildPreview";
import { useBuildTraits } from "./NpcBuilderBuildTab/useBuildTraits";
import { useCareerQueue } from "./NpcBuilderBuildTab/useCareerQueue";
import { usePortraitCandidates } from "./NpcBuilderBuildTab/usePortraitCandidates";

const props = defineProps<{
  bridge: NpcBuilderBridge;
  isLoadingActors: boolean;
  isLoadingBaseDraft: boolean;
  page: NpcBuilderBuildPage;
}>();

const store = useNpcBuilderStore();
const {
  actorName,
  advancements,
  careers,
  estimatedNpcXp,
  finalActorName,
  finalCareer,
  finalPortraitPath,
  grantTotals,
  selectedBaseActor,
  selectedSpells,
  suggestedActorName,
  traits,
} = storeToRefs(store);

const errorMessage = ref("");

const { actorFilter, filteredActors, selectedBaseActorSelectValue } = useBaseActorSelection(
  props.bridge,
  errorMessage,
);

const {
  clearCareerDragState,
  draggedCareerIndex,
  dragOverCareerIndex,
  handleCareerDragOver,
  handleCareerDragStart,
  handleCareerDrop,
  moveCareer,
  removeCareer,
  setCareerQuantity,
  setDragOverCareerIndex,
} = useCareerQueue();

const { displayedQuickTraitOptions, optionalTraitOptions, toggleOptionalTrait, toggleQuickTrait } =
  useBuildTraits();

const {
  buildPreviewStatus,
  buildPreviewWarnings,
  careerItemCount,
  editedAdvanceCount,
  fallbackTrappingCount,
  ignoredTrappingCount,
  visibleTrappingCount,
} = useBuildPreview();

const {
  addPortraitSearchTerm,
  compactPortraitCandidates,
  hiddenPortraitCandidateCount,
  isLoadingPortraitCandidates,
  isPortraitGalleryOpen,
  portraitCandidates,
  portraitFilterTags,
  portraitSearchProgress,
  portraitSearchProgressLabel,
  portraitSearchProgressValue,
  portraitSearchTerms,
  selectedPortraitCandidate,
  selectedPortraitCandidateKey,
  selectPortrait,
  selectPortraitFromGallery,
  setPortraitFilterTagSection,
} = usePortraitCandidates(props.bridge, errorMessage);
</script>

<template>
  <section class="app:grid app:gap-3">
    <div
      class="app:grid app:items-start app:gap-3 md:app:grid-cols-[minmax(0,1fr)_minmax(17rem,22rem)]"
    >
      <div class="app:grid app:min-w-0 app:gap-3">
        <BaseActorPanel
          v-if="page === 'build-quick' || page === 'build-actor'"
          :actor-filter="actorFilter"
          :description="
            page === 'build-quick'
              ? 'Choose the base statblock for this fast NPC draft.'
              : 'Choose the base statblock before reviewing detailed build pages.'
          "
          :error-message="errorMessage"
          :filtered-actors="filteredActors"
          :is-loading-actors="isLoadingActors"
          :is-loading-base-draft="isLoadingBaseDraft"
          :number="page === 'build-quick' ? '1' : ''"
          :selected-base-actor="selectedBaseActor"
          :selected-base-actor-uuid="selectedBaseActorSelectValue"
          @actor-filter-change="actorFilter = $event"
          @base-actor-change="selectedBaseActorSelectValue = $event"
        />

        <QuickCareerPanel
          v-if="page === 'build-quick'"
          :careers="careers"
          :final-career="finalCareer"
          @clear-careers="store.clearCareers"
        />

        <NpcBuilderSection
          v-if="page === 'build-quick'"
          description="Apply optional base traits and configured quick traits to the draft."
          number="3"
          title="Quick Traits"
        >
          <TraitButtonGroup
            :caption="`${optionalTraitOptions.length} from base statblock`"
            :traits="optionalTraitOptions"
            title="Optional Traits"
            @toggle-trait="toggleOptionalTrait"
          />

          <TraitButtonGroup
            :caption="`${displayedQuickTraitOptions.length} configured`"
            :traits="displayedQuickTraitOptions"
            title="Quick Traits"
            @toggle-trait="toggleQuickTrait"
          />
        </NpcBuilderSection>

        <CareerQueuePanel
          v-if="page === 'build-careers'"
          :careers="careers"
          :drag-over-career-index="dragOverCareerIndex"
          :dragged-career-index="draggedCareerIndex"
          @career-drag-end="clearCareerDragState"
          @career-drag-enter="setDragOverCareerIndex"
          @career-drag-over="handleCareerDragOver"
          @career-drag-start="handleCareerDragStart"
          @career-drop-on-row="handleCareerDrop"
          @career-quantity-input="setCareerQuantity"
          @move-career="moveCareer"
          @remove-career="removeCareer"
        />
      </div>

      <BuildSidebar
        class="app:min-w-0"
        :actor-name="actorName"
        :advancement-count="advancements.length"
        :build-preview-status="buildPreviewStatus"
        :build-preview-warnings="buildPreviewWarnings"
        :career-item-count="careerItemCount"
        :compact-portrait-candidates="compactPortraitCandidates"
        :edited-advance-count="editedAdvanceCount"
        :estimated-npc-xp="estimatedNpcXp"
        :fallback-trapping-count="fallbackTrappingCount"
        :final-actor-name="finalActorName"
        :final-career="finalCareer"
        :final-portrait-path="finalPortraitPath"
        :grant-totals="grantTotals"
        :hidden-portrait-candidate-count="hiddenPortraitCandidateCount"
        :ignored-trapping-count="ignoredTrappingCount"
        :is-loading-portrait-candidates="isLoadingPortraitCandidates"
        :portrait-candidates="portraitCandidates"
        :portrait-search-progress="portraitSearchProgress"
        :portrait-search-progress-label="portraitSearchProgressLabel"
        :portrait-search-progress-value="portraitSearchProgressValue"
        :selected-base-actor="selectedBaseActor"
        :selected-portrait-candidate="selectedPortraitCandidate"
        :selected-portrait-candidate-key="selectedPortraitCandidateKey"
        :selected-spell-count="selectedSpells.length"
        :suggested-actor-name="suggestedActorName"
        :trait-count="traits.length"
        :visible-trapping-count="visibleTrappingCount"
        @actor-name-change="actorName = $event"
        @open-portrait-gallery="isPortraitGalleryOpen = true"
        @select-portrait="selectPortrait"
      />
    </div>

    <PortraitGallery
      :is-loading-portrait-candidates="isLoadingPortraitCandidates"
      :open="isPortraitGalleryOpen"
      :portrait-candidates="portraitCandidates"
      :portrait-filter-tags="portraitFilterTags"
      :portrait-search-progress-label="portraitSearchProgressLabel"
      :portrait-search-progress-value="portraitSearchProgressValue"
      :portrait-search-terms="portraitSearchTerms"
      :selected-portrait-candidate-key="selectedPortraitCandidateKey"
      @create-search-term="addPortraitSearchTerm"
      @close="isPortraitGalleryOpen = false"
      @filter-tag-section-change="setPortraitFilterTagSection"
      @select-portrait="selectPortraitFromGallery"
    />
  </section>
</template>
