<script setup lang="ts">
import NpcBuilderSection from "../NpcBuilderSection.vue";

defineProps<{
  allowCharacteristics: boolean;
  allowSkills: boolean;
  allowTalents: boolean;
  allowTraits: boolean;
  allowTrappings: boolean;
  showAdvancementFeatures?: boolean;
  showTraitFeature?: boolean;
  showTrappingFeature?: boolean;
}>();

const emit = defineEmits<{
  allowCharacteristicsChange: [value: boolean];
  allowSkillsChange: [value: boolean];
  allowTalentsChange: [value: boolean];
  allowTraitsChange: [value: boolean];
  allowTrappingsChange: [value: boolean];
}>();

function checkboxValue(event: Event): boolean {
  const input = event.target as HTMLInputElement | null;

  return Boolean(input?.checked);
}
</script>

<template>
  <NpcBuilderSection
    description="Choose which base-only data is included in the editable draft."
    title="Base Actor Features"
  >
    <label v-if="showAdvancementFeatures !== false" class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="allowCharacteristics"
        type="checkbox"
        @change="emit('allowCharacteristicsChange', checkboxValue($event))"
      />
      <span>Show base actor characteristics</span>
    </label>
    <label v-if="showAdvancementFeatures !== false" class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="allowSkills"
        type="checkbox"
        @change="emit('allowSkillsChange', checkboxValue($event))"
      />
      <span>Show base actor skills</span>
    </label>
    <label v-if="showAdvancementFeatures !== false" class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="allowTalents"
        type="checkbox"
        @change="emit('allowTalentsChange', checkboxValue($event))"
      />
      <span>Show base actor talents</span>
    </label>
    <label v-if="showTrappingFeature" class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="allowTrappings"
        type="checkbox"
        @change="emit('allowTrappingsChange', checkboxValue($event))"
      />
      <span>Show base actor trappings</span>
    </label>
    <label v-if="showTraitFeature !== false" class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="allowTraits"
        type="checkbox"
        @change="emit('allowTraitsChange', checkboxValue($event))"
      />
      <span>Show base actor traits</span>
    </label>
  </NpcBuilderSection>
</template>
