import { defineStore } from "pinia";
import { computed, ref, watch } from "vue";
import type {
  SpeciesItemDraft,
  SpeciesItemEffect,
  SpeciesItemSheetBridge,
  SpeciesItemSystem,
} from "../../../../types/species/item";
import type { WfrpCharacteristicKey } from "../../../../types/wfrp4e/characteristics";
import { decodeTalentChoices, encodeTalentChoices } from "../../../functions/species-item/choices";
import {
  createSpeciesItemSystem,
  emptySpeciesReference,
} from "../../../functions/species-item/system";

export function useSpeciesItemStore(uuid: string) {
  return defineStore(`species-item:${uuid}`, () => {
    const draft = ref<SpeciesItemDraft>({
      name: "",
      img: "icons/svg/mystery-man.svg",
      system: createSpeciesItemSystem(),
    });
    const saved = ref("");
    const tab = ref<"description" | "details" | "effects">("description");
    const revision = ref(0);
    const isGM = ref(false);
    const effects = ref<SpeciesItemEffect[]>([]);
    const error = ref("");
    const message = ref("");
    const isSaving = ref(false);
    const isLoaded = ref(false);
    const editingTalents = ref(false);
    const parent = ref<SpeciesItemSystem | null>(null);
    let bridge: SpeciesItemSheetBridge;
    watch(
      () => draft.value.system.subspeciesOf,
      async (reference, _, onCleanup) => {
        let current = true;
        onCleanup(() => {
          current = false;
        });
        parent.value = null;
        try {
          const resolved = await bridge.loadParent(reference);
          if (current) parent.value = resolved;
        } catch (cause) {
          if (current) error.value = errorMessage(cause);
        }
      },
    );
    const dirty = computed(() => JSON.stringify(draft.value) !== saved.value);
    const grants = computed(() => {
      try {
        return decodeTalentChoices(draft.value.system.talents.choices);
      } catch {
        return [];
      }
    });
    const talentSummary = computed(() =>
      grants.value
        .map((grant) => grant.choices.map((choice) => choice.name).join(" or "))
        .join(", "),
    );

    function configure(value: SpeciesItemSheetBridge): void {
      if (isLoaded.value && dirty.value) return;
      bridge = value;
      isGM.value = bridge.isGM;
      reload();
    }
    function reload(): void {
      try {
        draft.value = bridge.load();
        saved.value = JSON.stringify(draft.value);
        isLoaded.value = true;
        effects.value = bridge.effects();
        revision.value += 1;
        error.value = "";
        message.value = "";
      } catch (cause) {
        error.value = errorMessage(cause);
        isLoaded.value = false;
      }
    }
    async function save(): Promise<void> {
      isSaving.value = true;
      error.value = "";
      try {
        bridge.flushNotes();
        draft.value = await bridge.save(
          JSON.parse(JSON.stringify(draft.value)) as SpeciesItemDraft,
        );
        saved.value = JSON.stringify(draft.value);
        revision.value += 1;
        message.value = "Saved Species Item. Refresh Foundry to update character generation.";
      } catch (cause) {
        error.value = errorMessage(cause);
      } finally {
        isSaving.value = false;
      }
    }
    function setStatistic(field: "fate" | "resilience" | "extra" | "movement", text: string): void {
      draft.value.system[field] = text === "" ? null : Number(text);
    }
    function setCharacteristic(
      key: WfrpCharacteristicKey,
      field: "base" | "dice",
      text: string,
    ): void {
      const value = draft.value.system.characteristics[key] ?? { base: null, dice: null };
      value[field] = text === "" ? null : Number(text);
      draft.value.system.characteristics[key] = value;
    }
    function editTalent(group: number, option: number, name: string): void {
      const next = JSON.parse(JSON.stringify(grants.value)) as typeof grants.value;
      next[group]!.choices[option] = { name };
      draft.value.system.talents.choices = encodeTalentChoices(next);
    }
    function addTalent(group?: number): void {
      const next = [...grants.value];
      if (group === undefined) next.push({ choices: [{ name: "New Talent" }] });
      else next[group]!.choices.push({ name: "Alternative Talent" });
      draft.value.system.talents.choices = encodeTalentChoices(next);
    }
    function removeTalent(group: number): void {
      draft.value.system.talents.choices = encodeTalentChoices(
        grants.value.filter((_, index) => index !== group),
      );
    }
    function clearParent(): void {
      draft.value.system.subspeciesOf = emptySpeciesReference();
    }
    async function drop(
      data: string,
      target: "parent" | "skills" | "talents" | keyof SpeciesItemSystem["tables"],
    ): Promise<void> {
      try {
        const { type, reference } = await bridge.resolveDrop(data);
        if (target === "parent") {
          if (!type.endsWith("species") || reference.uuid === uuid)
            throw new Error("Choose a different Species Item as the parent.");
          draft.value.system.subspeciesOf = reference;
        } else if (target === "skills" && type === "skill")
          draft.value.system.skills.list.push(reference.name);
        else if (target === "talents" && type === "talent")
          draft.value.system.talents.choices = encodeTalentChoices([
            ...grants.value,
            { choices: [{ name: reference.name, item: { ...reference, type: "talent" } }] },
          ]);
        else if (type === "RollTable" && target !== "skills")
          draft.value.system.tables[target] = reference;
        else throw new Error("This document does not match the selected field.");
        error.value = "";
      } catch (cause) {
        error.value = errorMessage(cause);
      }
    }
    const choiceWarning = computed(() => {
      try {
        decodeTalentChoices(draft.value.system.talents.choices);
        return "";
      } catch (cause) {
        return errorMessage(cause);
      }
    });
    async function openReference(uuid: string): Promise<void> {
      try {
        await bridge.openReference(uuid);
      } catch (cause) {
        error.value = errorMessage(cause);
      }
    }
    function chooseImage(): void {
      bridge.chooseImage(draft.value.img, (path) => {
        draft.value.img = path;
      });
    }
    const mountNotes: SpeciesItemSheetBridge["mountNotes"] = (...args) =>
      bridge.mountNotes(...args);
    const editNotes: SpeciesItemSheetBridge["editNotes"] = (field) => bridge.editNotes(field);
    async function effectAction(
      action: "create" | "edit" | "toggle" | "delete",
      id?: string,
    ): Promise<void> {
      if (dirty.value) {
        error.value = "Save or reload Item changes before editing effects.";
        return;
      }
      try {
        await bridge.effectAction(action, id);
        reload();
      } catch (cause) {
        error.value = errorMessage(cause);
      }
    }
    return {
      draft,
      parent,
      tab,
      revision,
      isGM,
      effects,
      choiceWarning,
      chooseImage,
      mountNotes,
      editNotes,
      effectAction,
      openReference,
      dirty,
      error,
      grants,
      talentSummary,
      editingTalents,
      isLoaded,
      isSaving,
      message,
      configure,
      reload,
      save,
      setStatistic,
      setCharacteristic,
      editTalent,
      addTalent,
      removeTalent,
      clearParent,
      drop,
    };
  })();
}
function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
