import type { NpcXpActorProfile, NpcXpNamedValue } from "../../../../types/npc-builder";

import { readNumberFromPaths } from "../../../functions/shared/object-readers";
import {
  WFRP_CHARACTERISTIC_NAMES,
  type WfrpCharacteristicKey,
} from "../../../../types/wfrp4e/characteristics";
import { readStoredCharacteristicValue } from "../xp-source-values";

export function createNpcXpActorProfile(actor: FoundryActorDocument): NpcXpActorProfile {
  const actorSource = actor.toObject();
  const characteristics: Partial<Record<WfrpCharacteristicKey, number>> = {};

  for (const key of Object.keys(WFRP_CHARACTERISTIC_NAMES)) {
    const characteristicKey = key as WfrpCharacteristicKey;

    characteristics[characteristicKey] = readStoredCharacteristicValue(
      actorSource["system"],
      characteristicKey,
    );
  }

  return {
    characteristics,
    skills: readXpItems(actor, "skill"),
    talents: readXpItems(actor, "talent"),
  };
}

function readXpItems(actor: FoundryActorDocument, type: "skill" | "talent"): NpcXpNamedValue[] {
  return (
    actor.items?.contents
      .filter((item) => item.type === type)
      .map((item) => ({
        name: item.name,
        value:
          type === "skill"
            ? readSkillContribution(item.toObject()["system"])
            : readTalentRanks(item.toObject()["system"]),
      })) ?? []
  );
}

function readSkillContribution(system: unknown): number {
  return (
    readNumberFromPaths(system, [["advances", "value"], ["advances"]]) +
    readNumberFromPaths(system, [["modifier", "value"], ["modifier"]])
  );
}

function readTalentRanks(system: unknown): number {
  return readNumberFromPaths(system, [["advances", "value"], ["advances"]]);
}
