import { compileSpeciesSelection } from "../../../functions/species-chargen/selection";
import { speciesItemHasParent } from "../../../functions/species-item/identity";
import { isSpeciesItem, readSpeciesItem } from "../documents/adapter";
import { resolveSpeciesReference } from "../../species-table/items";

export function ownedSpecies(actor: FoundryActorDocument): FoundryItemDocument | undefined {
  return actor.items?.contents.find(isSpeciesItem);
}

export async function effectiveActorSpecies(item: FoundryItemDocument) {
  const record = readSpeciesItem(item);
  // Actor copies already contain effective inherited values, even if the source parent is gone.
  if (item.actor) return record;
  if (!speciesItemHasParent(record)) return record;
  const parent = readSpeciesItem(await resolveSpeciesReference(record.system.subspeciesOf));
  if (speciesItemHasParent(parent)) throw new Error("Nested Species parents are not supported.");
  return compileSpeciesSelection(record, parent);
}
