import type { Component } from "vue";

import WorkbenchApp from "./WorkbenchApp.vue";
import { MODULE_ID, MODULE_TITLE } from "../../../constants";
import { NpcBuilderApplication } from "../../npc-builder/view/NpcBuilderApplication";
import { openEffectBuilders } from "../../../wfrp/effect-builders/open";
import { openSpeciesTableEditor } from "../../species-table/view/SpeciesTableApplication";
import { FoundryVueApplication } from "../../../foundry/apps/FoundryVueApplication";

export class WorkbenchApplication extends FoundryVueApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-workbench`,
    classes: [MODULE_ID, "wfrp4e-customizer-workbench"],
    position: {
      height: "auto",
      width: 640,
    },
    window: {
      icon: "fa-solid fa-screwdriver-wrench",
      title: MODULE_TITLE,
    },
  };

  protected override getVueComponent(): Component {
    return WorkbenchApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    return {
      openNpcBuilder: () => new NpcBuilderApplication().render(true),
      openEffectBuilders: () => openEffectBuilders(),
      openSpeciesTableEditor,
    };
  }
}
