import { MODULE_ID } from "../../constants";
import { hasNativeSpeciesSupport } from "../species-item/documents/migration";
import { useDefaultSpeciesTable } from "./default-table";
import { inspectConfiguredSpeciesTable } from "./table-policy";

export const SPECIES_TABLE_REMINDER_SETTING = "hideInvalidSpeciesTableReminder";
let offered = false;
let pending: Promise<boolean> | undefined;

export function registerSpeciesTableReminderSetting(): void {
  game.settings.register(MODULE_ID, SPECIES_TABLE_REMINDER_SETTING, {
    name: "Hide invalid Species table reminder",
    scope: "client",
    config: true,
    type: Boolean,
    default: false,
  });
}

export function offerDefaultSpeciesTable(): Promise<boolean> {
  if (pending) return pending;
  if (
    !game.user?.isGM ||
    hasNativeSpeciesSupport() ||
    offered ||
    game.settings.get(MODULE_ID, SPECIES_TABLE_REMINDER_SETTING) === true
  )
    return Promise.resolve(false);
  if (game.users?.activeGM && game.users.activeGM.id !== game.user.id)
    return Promise.resolve(false);
  pending = showReminder()
    .catch((error: unknown) => {
      ui.notifications?.error(error instanceof Error ? error.message : String(error));
      return false;
    })
    .finally(() => {
      pending = undefined;
    });
  return pending;
}

async function showReminder(): Promise<boolean> {
  if ((await inspectConfiguredSpeciesTable()).valid) return false;
  offered = true;
  let form: HTMLFormElement | null = null;
  const answer = await foundry.applications.api.DialogV2.wait<{
    replace: boolean;
    suppress: boolean;
  }>({
    window: { title: "Species table needs Species Items" },
    content:
      "<p>Character creation requires a Species table whose results are all Species Items. " +
      "The current table cannot be used for species rolls.</p>" +
      "<p>Use the supplied default table? It has Human 90%, Halfling 4%, Dwarf 4%, " +
      "High Elf 1%, and Wood Elf 1%. Your current table will be kept.</p>" +
      '<label><input type="checkbox" name="suppress"> Don’t show this reminder again</label>',
    buttons: [
      {
        action: "replace",
        label: "Use Default Table",
        callback: (_event, button) => response(true, button.form),
      },
      {
        action: "later",
        label: "Not Now",
        default: true,
        callback: (_event, button) => response(false, button.form),
      },
    ],
    // ApplicationV2 clears dialog.element before the close event; retain the rendered form.
    render: (_event, dialog) => {
      form = dialog.element.querySelector("form");
    },
    close: () => response(false, form),
    rejectClose: false,
  });
  if (answer?.suppress) await game.settings.set(MODULE_ID, SPECIES_TABLE_REMINDER_SETTING, true);
  if (!answer?.replace) return false;
  await useDefaultSpeciesTable();
  ui.notifications?.info("Character creation now uses a Species Item table.");
  return true;
}

function response(replace: boolean, form: HTMLFormElement | null) {
  return {
    replace,
    suppress: form?.querySelector<HTMLInputElement>('[name="suppress"]')?.checked === true,
  };
}
