import { applicationElement } from "../../foundry/application-element";
import type {
  LegacyChargenData,
  LegacySpeciesStageConstructor,
} from "../../../types/species/chargen";
import { isRecord } from "../../functions/shared/object-readers";
import { speciesStagePreview } from "../../functions/species-chargen/preview";
import { speciesRollBonus } from "../../functions/species-chargen/roll-bonus";
import { itemUuidFromResult, rollSpeciesTable } from "./choices";
import { inspectConfiguredSpeciesTable } from "./table-policy";
import { offerDefaultSpeciesTable } from "./table-reminder";
import type { SpeciesChargenSession } from "./session";

export function createItemSpeciesStage(
  Base: LegacySpeciesStageConstructor,
  session: SpeciesChargenSession,
) {
  return class ItemSpeciesStage extends Base {
    private tableValid = false;
    private tableReason = "";
    private reminderStarted = false;

    constructor(data: LegacyChargenData, options: Record<string, unknown>) {
      super(data, options);
      const hasItem = !!data.customizerSpecies?.selection;
      this.context.species = hasItem ? (data.species ?? "") : "";
      this.context.subspecies = "";
      this.context.exp = hasItem ? (data.exp["species"] ?? 0) : 0;
      this.context.roll = data.customizerSpecies?.roll;
    }

    override async getData(): Promise<Record<string, unknown>> {
      await session.ready;
      this.refreshBonus();
      const table = await inspectConfiguredSpeciesTable();
      this.tableValid = table.valid;
      this.tableReason = table.reason;
      if (!table.valid && !this.reminderStarted) {
        this.reminderStarted = true;
        void offerDefaultSpeciesTable().then((updated) => {
          if (updated && !session.closed) this.render(true);
        });
      }
      // Native Species.getData throws without a table. Item previews and drops must still work.
      const record = session.selection?.record;
      return {
        data: this.data,
        context: this.context,
        species: table.choices,
        speciesDisplay: record?.name ?? "",
        ...(record ? { preview: speciesStagePreview(record) } : {}),
      };
    }

    override activateListeners(html: unknown): void {
      super.activateListeners(html);
      const element = applicationElement(html);
      if (!element) return;
      if (!this.tableValid) {
        element.querySelector('[data-button="onRollSpecies"]')?.remove();
        const notice = document.createElement("p");
        notice.textContent = `${this.tableReason} Species rolls are unavailable; you can still drop a Species Item.`;
        element.querySelector(".select-species")?.append(notice);
      }
      const help = document.createElement("p");
      help.textContent =
        "Drop a Species Item here to choose it. Returning to your rolled species or choosing its subspecies restores the 20 XP bonus. The Item and its effects will be added to your character.";
      element.querySelector(".chargen-content")?.prepend(help);
      element.addEventListener("dragover", (event) => event.preventDefault());
      element.addEventListener("drop", (event) => {
        event.preventDefault();
        event.stopPropagation();
        void this.runSelection(async () => {
          const payload: unknown = JSON.parse(event.dataTransfer?.getData("text/plain") || "{}");
          if (!isRecord(payload) || typeof payload["uuid"] !== "string")
            throw new Error("Drop a world or compendium Species Item.");
          await this.chooseItem(payload["uuid"]);
        });
      });
    }

    async selectSpeciesItem(uuid: string): Promise<void> {
      await this.runSelection(() => this.chooseItem(uuid));
    }

    private async chooseItem(uuid: string): Promise<void> {
      await session.select(uuid);
      if (session.closed) return;
      this.refreshBonus();
      this.context.choose = session.key;
      this.setSpecies(session.key);
      this.updateMessage("Chosen", { chosen: session.selection!.record.name });
    }

    override async onSelectSpecies(event: { currentTarget: HTMLElement }): Promise<void> {
      const key = event.currentTarget.dataset["species"] ?? "";
      await this.runSelection(async () => {
        const table = await inspectConfiguredSpeciesTable();
        if (!table.valid || !table.choices[key])
          throw new Error(table.reason || "Choose a Species Item from the current table.");
        await this.chooseItem(key.slice(5));
      });
    }

    override async onRollSpecies(event: Event): Promise<void> {
      event.stopPropagation();
      await this.runSelection(async () => {
        session.assertUnlocked();
        if (this.context.roll)
          throw new Error("Species has already been rolled for this character.");
        const roll = await rollSpeciesTable();
        // Retain the roll even if its referenced Item is missing; retrying must not grant a reroll.
        this.context.roll = roll;
        const uuid = itemUuidFromResult(roll["object"] as Record<string, unknown>);
        if (!uuid) throw new Error("The rolled result must be a Species Item.");
        this.data.customizerSpecies = {
          ...this.data.customizerSpecies,
          roll,
          rollIdentity: [uuid],
        };
        await session.select(uuid);
        if (session.closed) return;
        this.data.customizerSpecies.rollIdentity = session.selection!.identity!.self;
        this.context.exp = 20;
        this.context.choose = false;
        this.setSpecies(session.key);
        this.updateMessage("Rolled", { rolled: roll["name"] });
      });
    }

    override onSelectSubspecies(): void {
      ui.notifications?.warn?.("Choose or drop the subspecies' own Species Item.");
    }

    override async validate(): Promise<boolean> {
      if (session.busy) {
        ui.notifications?.warn?.("Wait for the Species Item to finish loading.");
        return false;
      }
      if (!session.selection || this.context.species !== session.key) {
        ui.notifications?.warn?.("Choose or drop a Species Item before continuing.");
        return false;
      }
      return super.validate();
    }

    override _updateObject(event: unknown, formData: unknown): void {
      if (!session.selection || this.context.species !== session.key)
        throw new Error("A Species Item must be selected before submitting this stage.");
      this.refreshBonus();
      session.commit();
      this.data.customizerSpecies = { ...this.data.customizerSpecies, roll: this.context.roll };
      super._updateObject(event, formData);
    }

    private refreshBonus(): void {
      const result = this.context.roll?.["object"];
      const uuid = isRecord(result) ? itemUuidFromResult(result) : undefined;
      const rolled = this.data.customizerSpecies?.rollIdentity ?? (uuid ? [uuid] : []);
      this.context.exp = this.context.roll ? speciesRollBonus(session.selection, rolled) : 0;
    }

    private async runSelection(action: () => Promise<void>): Promise<void> {
      if (session.busy || session.closed) return;
      session.busy = true;
      try {
        await session.ready;
        await action();
      } catch (error) {
        ui.notifications?.error(error instanceof Error ? error.message : String(error));
      } finally {
        session.busy = false;
        if (!session.closed) this.render(true);
      }
    }
  };
}
