import { readNumberFromPaths } from "../../functions/shared/object-readers";
import type { WfrpCharacteristicKey } from "../../../types/wfrp4e/characteristics";

export function readStoredCharacteristicValue(system: unknown, key: WfrpCharacteristicKey): number {
  return (
    readNumberFromPaths(system, [
      ["characteristics", key, "initial", "value"],
      ["characteristics", key, "initial"],
    ]) +
    readNumberFromPaths(system, [
      ["characteristics", key, "modifier", "value"],
      ["characteristics", key, "modifier"],
    ]) +
    readNumberFromPaths(system, [
      ["characteristics", key, "advances", "value"],
      ["characteristics", key, "advances"],
    ])
  );
}
