import type { SpeciesItemRecord } from "../../../types/species/item";
import { inheritSpeciesSystem } from "../species-item/inheritance";

/** Match upstream's immediate-parent inheritance, retaining a self-contained actor copy. */
export function compileSpeciesSelection(
  item: SpeciesItemRecord,
  parent?: SpeciesItemRecord,
): SpeciesItemRecord {
  const effective = structuredClone(item);
  if (!parent) return effective;
  effective.system = inheritSpeciesSystem(item.system, parent.system);
  for (const field of ["career", "talents", "eye", "hair"] as const) {
    const reference = item.system.tables[field];
    if (!reference.uuid && !reference.id)
      effective.system.tables[field] = structuredClone(parent.system.tables[field]);
  }
  if (!item.effects.length) effective.effects = structuredClone(parent.effects);
  return effective;
}

/** v14 document results and existing UUID-link text results both retain Item identity. */
export function speciesResultUuid(source: Record<string, unknown>): string | undefined {
  if (typeof source["documentUuid"] === "string" && source["documentUuid"])
    return source["documentUuid"];
  const description = typeof source["description"] === "string" ? source["description"] : "";
  return /@UUID\[([^\]]+)\]/u.exec(description)?.[1];
}

export function isSpeciesItemUuid(uuid: string): boolean {
  return uuid.startsWith("Item.") || (uuid.startsWith("Compendium.") && uuid.includes(".Item."));
}
