export function toSpellResolutionInput(item: FoundryItemDocument, sourceLabel: string) {
  return {
    img: item.img ?? "",
    name: item.name,
    sourceLabel,
    system: item.system,
    uuid: item.uuid,
  };
}

export function readSpellSourceLabel(item: FoundryItemDocument): string {
  if (/^item\./i.test(item.uuid)) {
    return "World";
  }

  return readSpellSourceLabelFromUuid(item.uuid, "WFRP Item Lookup");
}

export function readSpellSourceLabelFromUuid(uuid: string, fallback: string): string {
  const collection = /^Compendium\.([^.]+\.[^.]+)\./.exec(uuid)?.[1];

  if (!collection) {
    return fallback;
  }

  const pack = [...(game.packs ?? [])].find((candidate) => {
    return candidate.collection === collection;
  });

  return pack?.title ?? collection;
}
