import { isRecord } from "../../functions/shared/object-readers";

type CanSwapRolls = (draggedCharacteristic: string, targetCharacteristic: string) => boolean;

const feedbackAttribute = "data-wfrp4e-customizer-roll-swap-feedback";
const feedbackSelector = `[${feedbackAttribute}="blocked"]`;
const originalTargetStates = new WeakMap<HTMLElement, OriginalTargetState>();

interface OriginalTargetState {
  ariaDisabled: string | null;
  borderColor: string;
  borderColorPriority: string;
  hadDisabledClass: boolean;
}

export function installChargenRollSwapFeedback(html: unknown, canSwap: CanSwapRolls): void {
  const root = rootElementFromHtml(html);

  if (!root) {
    return;
  }

  for (const rollElement of rollElements(root)) {
    rollElement.addEventListener("dragstart", () => {
      const characteristic = rollElement.dataset["ch"];

      if (characteristic) {
        showRollSwapFeedback(root, characteristic, canSwap);
      }
    });

    rollElement.addEventListener("dragend", () => {
      clearRollSwapFeedback(root);
    });

    rollElement.addEventListener("drop", () => {
      clearRollSwapFeedback(root);
    });
  }
}

function showRollSwapFeedback(
  root: HTMLElement,
  draggedCharacteristic: string,
  canSwap: CanSwapRolls,
): void {
  clearRollSwapFeedback(root);

  for (const rollElement of rollElements(root)) {
    const targetCharacteristic = rollElement.dataset["ch"];

    if (!targetCharacteristic) {
      continue;
    }

    if (
      targetCharacteristic === draggedCharacteristic ||
      canSwap(draggedCharacteristic, targetCharacteristic)
    ) {
      continue;
    }

    disableRollSwapTarget(rollElement);
  }
}

function disableRollSwapTarget(rollElement: HTMLElement): void {
  originalTargetStates.set(rollElement, {
    ariaDisabled: rollElement.getAttribute("aria-disabled"),
    borderColor: rollElement.style.getPropertyValue("border-color"),
    borderColorPriority: rollElement.style.getPropertyPriority("border-color"),
    hadDisabledClass: rollElement.classList.contains("disabled"),
  });

  rollElement.setAttribute(feedbackAttribute, "blocked");
  rollElement.setAttribute("aria-disabled", "true");
  rollElement.classList.add("disabled");
  rollElement.style.setProperty("border-color", "transparent");
}

function clearRollSwapFeedback(root: HTMLElement): void {
  for (const rollElement of root.querySelectorAll<HTMLElement>(feedbackSelector)) {
    const originalState = originalTargetStates.get(rollElement);

    if (!originalState) {
      continue;
    }

    if (!originalState.hadDisabledClass) {
      rollElement.classList.remove("disabled");
    }

    restoreAttribute(rollElement, "aria-disabled", originalState.ariaDisabled);
    restoreStyleProperty(
      rollElement,
      "border-color",
      originalState.borderColor,
      originalState.borderColorPriority,
    );
    rollElement.removeAttribute(feedbackAttribute);
    originalTargetStates.delete(rollElement);
  }
}

function restoreAttribute(element: HTMLElement, name: string, value: string | null): void {
  if (value === null) {
    element.removeAttribute(name);
    return;
  }

  element.setAttribute(name, value);
}

function restoreStyleProperty(
  element: HTMLElement,
  property: string,
  value: string,
  priority: string,
): void {
  if (!value) {
    element.style.removeProperty(property);
    return;
  }

  element.style.setProperty(property, value, priority);
}

function rollElements(root: HTMLElement): HTMLElement[] {
  return [...root.querySelectorAll<HTMLElement>(".ch-roll.ch-drag")];
}

function rootElementFromHtml(html: unknown): HTMLElement | undefined {
  if (html instanceof HTMLElement) {
    return html;
  }

  if (!isRecord(html)) {
    return undefined;
  }

  const firstElement = html["0"];

  return firstElement instanceof HTMLElement ? firstElement : undefined;
}
