import type { NpcBuilderSettings } from "../../../types/npc-builder";

import { createDefaultNpcBuilderSettings } from "../../apps/npc-builder/functions/default-npc-builder-settings";
import { normalizeNpcBuilderSettings } from "../../apps/npc-builder/functions/normalize-npc-builder-settings";
import {
  defineFoundryObjectSetting,
  loadObjectSetting,
  registerObjectSetting,
  saveObjectSetting,
} from "../../foundry/settings/foundry-setting-adapter";

const NPC_BUILDER_SETTINGS_KEY = "npcBuilderSettings";

const defaultNpcBuilderSettings = createDefaultNpcBuilderSettings();

const npcBuilderSettingsDefinition = defineFoundryObjectSetting({
  defaultValue: defaultNpcBuilderSettings,
  key: NPC_BUILDER_SETTINGS_KEY,
  name: "NPC Builder Settings",
  normalize: normalizeNpcBuilderSettings,
});

export function registerNpcBuilderSettings(): void {
  registerObjectSetting(npcBuilderSettingsDefinition);
}

export function loadNpcBuilderSettings(): NpcBuilderSettings {
  return loadObjectSetting(npcBuilderSettingsDefinition);
}

export async function saveNpcBuilderSettings(
  settings: NpcBuilderSettings,
): Promise<NpcBuilderSettings> {
  return await saveObjectSetting(npcBuilderSettingsDefinition, settings);
}
