import type {
  PortraitCandidate,
  PortraitCandidateExclusionOptions,
  PortraitSearchProgressHandler,
} from "../../../types/portrait-gallery";

import { normalizePortraitFolderPaths } from "../../functions/portrait-gallery";

interface PortraitAssetInspection {
  fullyTransparent: boolean;
  loadable: boolean;
  pixelSignature: string;
}

type PortraitAssetInspector = (path: string) => Promise<PortraitAssetInspection>;

const inspectionCache = new Map<string, Promise<PortraitAssetInspection>>();
const portraitInspectionConcurrency = 6;
const portraitLoadTimeoutMilliseconds = 15_000;

export async function filterExcludedPortraitCandidates(
  candidates: PortraitCandidate[],
  options: PortraitCandidateExclusionOptions,
  onProgress?: PortraitSearchProgressHandler,
  inspectAsset: PortraitAssetInspector = inspectPortraitAsset,
): Promise<PortraitCandidate[]> {
  const referencePaths = normalizePortraitFolderPaths(options.excludedReferenceImagePaths);
  const excludedPathKeys = new Set(referencePaths.map(normalizePathKey));
  const excludedSignatures = new Set<string>();

  for (const path of referencePaths) {
    const inspection = await inspectAsset(path);

    if (inspection.loadable && inspection.pixelSignature) {
      excludedSignatures.add(inspection.pixelSignature);
    }
  }

  const inspections = new Array<PortraitCandidate | null>(candidates.length).fill(null);
  let includedCount = 0;
  let nextIndex = 0;
  let processedCount = 0;

  emitInspectionProgress(onProgress, 0, 0, candidates.length);

  async function inspectNextCandidate(): Promise<void> {
    while (nextIndex < candidates.length) {
      const index = nextIndex;
      // The loop reserves an index only while it is inside this fixed array.
      const candidate = candidates[index]!;

      nextIndex += 1;

      if (!excludedPathKeys.has(normalizePathKey(candidate.img))) {
        const inspection = await inspectAsset(candidate.img);
        const shouldInclude =
          inspection.loadable &&
          (!options.excludeFullyTransparentImages || !inspection.fullyTransparent) &&
          (!inspection.pixelSignature || !excludedSignatures.has(inspection.pixelSignature));

        if (shouldInclude) {
          inspections[index] = candidate;
          includedCount += 1;
        }
      }

      processedCount += 1;
      emitInspectionProgress(onProgress, includedCount, processedCount, candidates.length);
    }
  }

  const workerCount = Math.min(portraitInspectionConcurrency, candidates.length);

  await Promise.all(Array.from({ length: workerCount }, inspectNextCandidate));

  return inspections.filter((candidate): candidate is PortraitCandidate => candidate !== null);
}

async function inspectPortraitAsset(path: string): Promise<PortraitAssetInspection> {
  const key = normalizePathKey(path);
  const cachedInspection = inspectionCache.get(key);

  if (cachedInspection) {
    return await cachedInspection;
  }

  const inspection = loadAndInspectPortraitAsset(path);

  inspectionCache.set(key, inspection);
  return await inspection;
}

async function loadAndInspectPortraitAsset(path: string): Promise<PortraitAssetInspection> {
  const image = await loadPortraitImage(path);

  if (!image) {
    return { fullyTransparent: false, loadable: false, pixelSignature: "" };
  }

  try {
    const canvasElement = document.createElement("canvas");

    canvasElement.width = image.naturalWidth;
    canvasElement.height = image.naturalHeight;

    const context = canvasElement.getContext("2d", { willReadFrequently: true });

    if (!context) {
      return { fullyTransparent: false, loadable: true, pixelSignature: "" };
    }

    context.drawImage(image, 0, 0);

    const pixels = context.getImageData(0, 0, canvasElement.width, canvasElement.height).data;
    let fullyTransparent = true;

    for (let index = 0; index < pixels.length; index += 4) {
      if (pixels[index + 3] === 0) {
        pixels[index] = 0;
        pixels[index + 1] = 0;
        pixels[index + 2] = 0;
      } else {
        fullyTransparent = false;
      }
    }

    return {
      fullyTransparent,
      loadable: true,
      pixelSignature: await createPixelSignature(canvasElement.width, canvasElement.height, pixels),
    };
  } catch {
    // A cross-origin image can be displayable while its canvas pixels remain protected.
    return { fullyTransparent: false, loadable: true, pixelSignature: "" };
  }
}

function loadPortraitImage(path: string): Promise<HTMLImageElement | null> {
  return new Promise((resolve) => {
    const image = new Image();
    const timeout = setTimeout(() => finish(null), portraitLoadTimeoutMilliseconds);

    function finish(result: HTMLImageElement | null): void {
      clearTimeout(timeout);
      image.onload = null;
      image.onerror = null;
      resolve(result);
    }

    image.onload = () => {
      finish(image.naturalWidth > 0 && image.naturalHeight > 0 ? image : null);
    };
    image.onerror = () => finish(null);
    image.src = path;
  });
}

async function createPixelSignature(
  width: number,
  height: number,
  pixels: Uint8ClampedArray<ArrayBuffer>,
): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", pixels);
  const digestBytes = new Uint8Array(digest);
  const hash = [...digestBytes].map((byte) => byte.toString(16).padStart(2, "0")).join("");

  return `${width}x${height}:${hash}`;
}

function emitInspectionProgress(
  onProgress: PortraitSearchProgressHandler | undefined,
  candidatesFound: number,
  processedImages: number,
  totalImages: number,
): void {
  onProgress?.({
    candidatesFound,
    currentLocation: `Checking images ${processedImages}/${totalImages}`,
    directoriesVisited: processedImages,
    maxDirectories: totalImages,
    phase: "image-validation",
  });
}

function normalizePathKey(path: string): string {
  return path.trim().replaceAll("\\", "/").toLocaleLowerCase();
}
