import type { SpeciesItemReference } from "../../../../types/species/item";
import { speciesResultUuid } from "../../../functions/species-chargen/selection";
import { isRecord } from "../../../functions/shared/object-readers";
import { assertFoundryItem } from "../../../foundry/document-guards";
import { resolveChargenTable } from "../../species-chargen/tables";
import { findSpeciesGrant } from "./grant";

export async function randomSpeciesTalent(reference: SpeciesItemReference) {
  const table =
    (await resolveChargenTable(reference)) ?? game.wfrp4e?.tables?.findTable?.("talents");
  if (!isRecord(table) || typeof table["roll"] !== "function")
    throw new Error("The Species random Talent table is unavailable.");
  const roll: unknown = await table["roll"]({ recursive: true });
  const results = isRecord(roll) ? roll["results"] : undefined;
  if (!Array.isArray(results) || results.length !== 1)
    throw new Error("The Species Talent table must return one Talent per roll.");
  const result = results[0];
  if (!isRecord(result) || typeof result["toObject"] !== "function")
    throw new Error("The Species Talent table returned an invalid result.");
  const source: unknown = result["toObject"]();
  if (!isRecord(source)) throw new Error("The Species Talent result has no data.");
  const uuid = speciesResultUuid(source);
  const name = source["name"];
  if (!uuid && (typeof name !== "string" || !name.trim()))
    throw new Error("The Species Talent result has no Item link or Talent name.");
  const item = uuid
    ? assertFoundryItem(await fromUuid(uuid), "The rolled Talent Item is unavailable.")
    : await findSpeciesGrant(name as string, "talent");
  if (item.type !== "talent") throw new Error("The Species Talent table result is not a Talent.");
  return item;
}
