import type { NpcXpEstimateResult } from "../../../../types/npc-builder";

import { isFoundryActor } from "../../../foundry/document-guards";
import { logWarning } from "../../../foundry/logging";
import { estimateNpcXpForActor } from "./estimate";

interface MountedXpDisplay {
  actor: FoundryActorDocument;
  container: HTMLElement;
  details: HTMLElement;
  generation: number;
  output: HTMLInputElement;
  root: HTMLElement;
}

const DISPLAY_SELECTOR = '[data-wfrp-customizer-npc-xp="true"]';
const mountedDisplays = new Set<MountedXpDisplay>();
let hasRegisteredHooks = false;
let refreshScheduled = false;

export function registerNpcEstimatedXpSheetHooks(): void {
  if (hasRegisteredHooks) {
    return;
  }

  hasRegisteredHooks = true;
  Hooks.on("renderApplicationV2", (application, html) => {
    if (!(html instanceof HTMLElement)) {
      return;
    }

    const actor = getRenderedNpcActor(application);

    if (!actor) {
      return;
    }

    mountXpDisplay(actor, html);
  });

  for (const hook of [
    "createActor",
    "updateActor",
    "deleteActor",
    "createItem",
    "updateItem",
    "deleteItem",
    "updateSetting",
  ]) {
    Hooks.on(hook, scheduleDisplayRefresh);
  }
}

function mountXpDisplay(actor: FoundryActorDocument, root: HTMLElement): void {
  const careersTab = root.matches('section[data-tab="careers"]')
    ? root
    : root.querySelector<HTMLElement>('section[data-tab="careers"]');

  if (!careersTab) {
    return;
  }

  careersTab.querySelector(DISPLAY_SELECTOR)?.remove();

  const display = createDisplay(actor, root);
  const careerList = careersTab.querySelector<HTMLElement>(".sheet-list.careers");

  if (careerList) {
    careersTab.insertBefore(display.container, careerList);
  } else {
    careersTab.append(display.container);
  }

  pruneMountedDisplays();
  void refreshDisplay(display);
  globalThis.setTimeout(() => {
    if (display.root.isConnected && display.root.contains(display.container)) {
      pruneMountedDisplays();
      mountedDisplays.add(display);
    }
  }, 0);
}

function createDisplay(actor: FoundryActorDocument, root: HTMLElement): MountedXpDisplay {
  const container = document.createElement("div");
  container.dataset["wfrpCustomizerNpcXp"] = "true";

  const formGroup = document.createElement("div");
  formGroup.classList.add("form-group");

  const label = document.createElement("label");
  label.textContent = "Estimated NPC XP";

  const formFields = document.createElement("div");
  formFields.classList.add("form-fields");

  const output = document.createElement("input");
  output.type = "text";
  output.readOnly = true;
  output.value = "Calculating…";

  const details = document.createElement("p");
  details.classList.add("notes");
  details.textContent = "Comparing this NPC with its species Actor.";

  formFields.append(output);
  formGroup.append(label, formFields);
  container.append(formGroup, details);

  return { actor, container, details, generation: 0, output, root };
}

async function refreshDisplay(display: MountedXpDisplay): Promise<void> {
  const generation = ++display.generation;
  display.output.value = "Calculating…";

  try {
    const result = await estimateNpcXpForActor(display.actor);

    if (generation === display.generation && display.root.contains(display.container)) {
      renderEstimate(display, result);
    }
  } catch (error) {
    if (generation === display.generation && display.root.contains(display.container)) {
      display.output.value = "Unavailable";
      display.details.textContent = "XP calculation failed; see the console for details.";
    }

    logWarning("wfrp4e-customizer-apps | NPC XP calculation failed.", error);
  }
}

function renderEstimate(display: MountedXpDisplay, result: NpcXpEstimateResult): void {
  if (result.status === "missing-species") {
    display.output.value = "Unavailable";
    display.details.textContent = "Set this NPC's Species to select a baseline Actor.";
    return;
  }

  if (result.status === "baseline-not-found") {
    display.output.value = "Unavailable";
    display.details.textContent = `No Actor named “${result.species}” was found.`;
    return;
  }

  const { breakdown } = result;
  display.output.value = `${breakdown.total.toLocaleString()} XP`;
  display.details.textContent = [
    `${result.baselineName} (${result.baselineSource})`,
    `Characteristics ${breakdown.characteristics.toLocaleString()}`,
    `Skills ${breakdown.skills.toLocaleString()}`,
    `Talents ${breakdown.talents.toLocaleString()}`,
  ].join(" · ");
}

function getRenderedNpcActor(application: unknown): FoundryActorDocument | null {
  if (typeof application !== "object" || application === null) {
    return null;
  }

  const actor = "actor" in application ? application.actor : undefined;
  const document = "document" in application ? application.document : undefined;
  const renderedActor = isFoundryActor(actor) ? actor : isFoundryActor(document) ? document : null;

  return renderedActor?.type === "npc" ? renderedActor : null;
}

function scheduleDisplayRefresh(): void {
  if (refreshScheduled) {
    return;
  }

  refreshScheduled = true;
  globalThis.setTimeout(() => {
    refreshScheduled = false;
    pruneMountedDisplays();

    for (const display of mountedDisplays) {
      void refreshDisplay(display);
    }
  }, 0);
}

function pruneMountedDisplays(): void {
  for (const display of mountedDisplays) {
    if (!display.root.isConnected || !display.root.contains(display.container)) {
      mountedDisplays.delete(display);
    }
  }
}
