import type {
  NpcAdvancementDraftEntry,
  NpcAdvancementKind,
  NpcAdvancementSourceSummary,
  NpcCareerQueueEntry,
  NpcTalentMaximumSummary,
} from "../../../../../types/npc-builder";
import type { WfrpCharacteristicKey } from "../../../../../types/wfrp4e/characteristics";

import { getSkillGrantOccurrences } from "../skill-specialization";
import {
  advancementKey,
  CAREER_ADVANCE_STEP,
  careerLevelAdvanceValue,
  careerLevelLabel,
  normalizeQuantity,
  sumSourceCounts,
  uniqueNames,
} from "../draft-helpers";
import { createExtraTimeSources, limitSourcesToCount } from "./source-counts";
import { getCappedAutomatedTalentRanks } from "./talent-maximums";

interface CareerGrantContext {
  careers: NpcCareerQueueEntry[];
  entries: Map<string, NpcAdvancementDraftEntry>;
  skillGrantResolutions: Record<string, string>;
  talentMaximums: Record<string, NpcTalentMaximumSummary>;
}

interface TalentGrantContext extends CareerGrantContext {
  characteristicTotals: Partial<Record<WfrpCharacteristicKey, number>>;
}

export function addCareerAdvanceStepAdvancements(
  context: CareerGrantContext,
  kind: "characteristic" | "skill",
): void {
  // Characteristics and skills use the highest Career level as their
  // baseline. Extra quantities of a Career represent extra time there and
  // add another fixed advance step without replacing the highest baseline.
  const careerAdvancements = new Map<
    string,
    {
      extraSources: NpcAdvancementSourceSummary[];
      highestLevel: number;
      highestLevelSource: string;
      name: string;
    }
  >();

  for (const career of context.careers) {
    const names = uniqueNames(readCareerGrantNames(career, kind, context.skillGrantResolutions));
    const levelValue = careerLevelAdvanceValue(career);
    const level = levelValue / CAREER_ADVANCE_STEP;
    const extraCareerCount = Math.max(0, normalizeQuantity(career.quantity) - 1);
    const extraValue = extraCareerCount * CAREER_ADVANCE_STEP;

    for (const name of names) {
      const key = advancementKey(kind, name);
      const existing = careerAdvancements.get(key);

      if (existing) {
        if (level > existing.highestLevel) {
          existing.highestLevel = level;
          existing.highestLevelSource = careerLevelLabel(career);
        }

        if (extraValue > 0) {
          existing.extraSources.push({
            count: extraValue,
            kind: "career",
            label: `${career.name} extra time`,
          });
        }

        continue;
      }

      careerAdvancements.set(key, {
        extraSources: createExtraTimeSources(career.name, extraValue),
        highestLevel: level,
        highestLevelSource: careerLevelLabel(career),
        name,
      });
    }
  }

  for (const careerAdvancement of careerAdvancements.values()) {
    const careerValue =
      careerAdvancement.highestLevel * CAREER_ADVANCE_STEP +
      sumSourceCounts(careerAdvancement.extraSources);

    applyCareerAdvancement(context, {
      careerValue,
      kind,
      name: careerAdvancement.name,
      sources: [
        {
          count: careerAdvancement.highestLevel * CAREER_ADVANCE_STEP,
          kind: "career",
          label: careerAdvancement.highestLevelSource,
        },
        ...careerAdvancement.extraSources,
      ],
    });
  }
}

export function addCareerTalentAdvancements(context: TalentGrantContext): void {
  // Talents behave like ranks: the first matching Career grants one rank and
  // extra Career quantities add ranks instead of level-based advance steps.
  const talentAdvancements = new Map<
    string,
    {
      extraSources: NpcAdvancementSourceSummary[];
      firstSource: string;
      name: string;
    }
  >();

  for (const career of context.careers) {
    const names = uniqueNames(
      readCareerGrantNames(career, "talent", context.skillGrantResolutions),
    );
    const extraRanks = Math.max(0, normalizeQuantity(career.quantity) - 1);

    for (const name of names) {
      const key = advancementKey("talent", name);
      const existing = talentAdvancements.get(key);

      if (existing) {
        if (extraRanks > 0) {
          existing.extraSources.push({
            count: extraRanks,
            kind: "career",
            label: `${career.name} extra time`,
          });
        }

        continue;
      }

      talentAdvancements.set(key, {
        extraSources: createExtraTimeSources(career.name, extraRanks),
        firstSource: career.name,
        name,
      });
    }
  }

  for (const talentAdvancement of talentAdvancements.values()) {
    const careerValue = 1 + sumSourceCounts(talentAdvancement.extraSources);

    applyCareerAdvancement(
      context,
      {
        careerValue,
        kind: "talent",
        name: talentAdvancement.name,
        sources: [
          {
            count: 1,
            kind: "career",
            label: talentAdvancement.firstSource,
          },
          ...talentAdvancement.extraSources,
        ],
      },
      context.characteristicTotals,
    );
  }
}

function applyCareerAdvancement(
  context: CareerGrantContext,
  advancement: Pick<NpcAdvancementDraftEntry, "careerValue" | "kind" | "name" | "sources">,
  characteristicTotals: Partial<Record<WfrpCharacteristicKey, number>> = {},
): void {
  const key = advancementKey(advancement.kind, advancement.name);
  const existing = context.entries.get(key);

  if (existing) {
    const baseTalentAlreadyHasFirstGrant =
      advancement.kind === "talent" && existing.includedFromBase;
    const careerSources = baseTalentAlreadyHasFirstGrant
      ? advancement.sources.slice(1)
      : advancement.sources;
    const careerValue =
      advancement.kind === "talent"
        ? getCappedAutomatedTalentRanks(
            existing,
            sumSourceCounts(careerSources),
            characteristicTotals,
            context.talentMaximums,
          )
        : advancement.careerValue;

    existing.careerValue = careerValue;
    existing.includedFromCareer = true;
    existing.sources = [
      ...existing.sources.filter((source) => source.kind === "base"),
      ...limitSourcesToCount(careerSources, careerValue),
    ];
    return;
  }

  const entry: NpcAdvancementDraftEntry = {
    baseAdvances: 0,
    baseValue: 0,
    careerValue: advancement.careerValue,
    current: advancement.careerValue,
    includedFromBase: false,
    includedFromCareer: true,
    includedFromCustom: false,
    kind: advancement.kind,
    minimumCurrent: 0,
    minimumTotal: 0,
    name: advancement.name,
    sources: advancement.sources,
  };

  if (advancement.kind === "talent") {
    entry.careerValue = getCappedAutomatedTalentRanks(
      entry,
      advancement.careerValue,
      characteristicTotals,
      context.talentMaximums,
    );
    entry.current = entry.careerValue;
    entry.sources = limitSourcesToCount(advancement.sources, entry.careerValue);
  }

  context.entries.set(key, {
    ...entry,
  });
}

function readCareerGrantNames(
  career: NpcCareerQueueEntry,
  kind: NpcAdvancementKind,
  skillGrantResolutions: Record<string, string>,
): string[] {
  if (kind === "characteristic") {
    return career.grants.characteristics;
  }

  if (kind === "skill") {
    return getSkillGrantOccurrences(career.uuid, career.grants.skills).map(
      (occurrence) => skillGrantResolutions[occurrence.resolutionKey] || occurrence.originalName,
    );
  }

  return career.grants.talents;
}
