<script setup lang="ts">
import { storeToRefs } from "pinia";
import { computed, onMounted, ref } from "vue";

import type { NpcBuilderBridge } from "../../../../../types/npc-builder";

import { useNpcBuilderStore } from "../../state";
import NpcBuilderSection from "./NpcBuilderSection.vue";
import { blankItemOptionValue } from "./NpcBuilderTrappingsTab/constants";
import TrappingsTable from "./NpcBuilderTrappingsTab/TrappingsTable.vue";

const props = defineProps<{
  bridge: NpcBuilderBridge;
}>();

const store = useNpcBuilderStore();
const { trappings } = storeToRefs(store);
const errorMessage = ref("");
const isResolving = ref(false);

const unresolvedTrappings = computed(() =>
  trappings.value.filter(
    (trapping) => !trapping.ignored && trapping.resolution.status === "unresolved",
  ),
);

onMounted(() => {
  void resolveUnresolvedTrappings();
});

function setTrappingQuantity(key: string, event: Event): void {
  const input = event.target as HTMLInputElement | null;

  if (input) {
    store.setTrappingQuantity(key, Number(input.value));
  }
}

function setTrappingUsed(key: string, event: Event): void {
  const input = event.target as HTMLInputElement | null;

  if (input) {
    store.setTrappingIgnored(key, !input.checked);
  }
}

function setSelectedResolution(key: string, event: Event): void {
  const input = event.target as HTMLSelectElement | null;

  if (!input?.value) {
    return;
  }

  if (input.value === blankItemOptionValue) {
    store.setTrappingFallback(key);
    return;
  }

  store.selectTrappingResolutionCandidate(key, input.value);
}

async function resolveUnresolvedTrappings(): Promise<void> {
  if (!unresolvedTrappings.value.length) {
    return;
  }

  isResolving.value = true;
  errorMessage.value = "";

  try {
    for (const trapping of unresolvedTrappings.value) {
      store.setTrappingResolution(trapping.key, await props.bridge.resolveTrapping(trapping.name));
    }
  } catch (error) {
    errorMessage.value = toErrorMessage(error);
  } finally {
    isResolving.value = false;
  }
}

function toErrorMessage(error: unknown): string {
  return error instanceof Error
    ? error.message
    : "The NPC Builder could not resolve that Trapping drop.";
}
</script>

<template>
  <NpcBuilderSection
    description="Review the Items that will be embedded in the generated NPC."
    title="Trappings"
  >
    <div class="dui-card-actions">
      <button
        class="dui-btn dui-btn-sm"
        :disabled="isResolving || !unresolvedTrappings.length"
        type="button"
        @click="resolveUnresolvedTrappings"
      >
        {{ isResolving ? "Resolving..." : "Resolve Trappings" }}
      </button>
      <span v-if="unresolvedTrappings.length"> {{ unresolvedTrappings.length }} unresolved </span>
    </div>

    <p v-if="errorMessage" class="dui-alert dui-alert-error" role="alert">
      {{ errorMessage }}
    </p>

    <TrappingsTable
      :trappings="trappings"
      @quantity-input="setTrappingQuantity"
      @remove-custom-trapping="store.removeCustomTrapping"
      @resolution-change="setSelectedResolution"
      @use-change="setTrappingUsed"
    />
  </NpcBuilderSection>
</template>
