import type {
  PortraitCandidate,
  PortraitCandidateSource,
  PortraitFilterSection,
  PortraitSearchProgress,
} from "../../../types/portrait-gallery";

import { getPortraitCandidateFilterSource } from "./source-filters";

export {
  createPriorityPortraitFilterSource,
  getPortraitCandidateFilterSource,
  getPortraitSourceGroupLabel,
  listPortraitCandidateFilterSources,
} from "./source-filters";
export { mergePortraitCandidateCollection, uniquePortraitCandidates } from "./candidate-collection";

const stopWords = new Set(["and", "any", "the", "with", "without", "of", "or", "npc"]);
const portraitFilterDragDataPrefix = "portrait-gallery-filter:";

export const wfrpCoreCareerPortraitFolder = "modules/wfrp4e-core/art/careers";
export const defaultPriorityPortraitFolders = [
  "modules/wfrp4e-core/art/bestiary",
  "modules/wfrp4e-core/tokens",
  "modules/wfrp4e-core/tokens/popout",
];
export const defaultExcludedPortraitReferenceImages = ["systems/wfrp4e/tokens/unknown.png"];

export const portraitFilterTagDragMimeType = "application/x-wfrp4e-customizer-portrait-filter-tag";

export function parsePortraitSearchInput(value: string): string[] {
  return uniqueStrings(
    tokenizeSearchTerm(value).filter((term) => term.length >= 3 && !stopWords.has(term)),
  );
}

export function createPortraitSearchTerms(values: string[]): string[] {
  return uniqueStrings(values.flatMap(parsePortraitSearchInput));
}

export function parsePortraitFolderInput(value: string): string[] {
  return normalizePortraitFolderPaths(value.split(/\r?\n/u));
}

export function normalizePortraitFolderPaths(value: unknown): string[] {
  if (!Array.isArray(value)) {
    return [];
  }

  const seen = new Set<string>();
  const paths: string[] = [];

  for (const entry of value) {
    if (typeof entry !== "string") {
      continue;
    }

    const path = entry
      .trim()
      .replaceAll("\\", "/")
      .replace(/^\/+|\/+$/gu, "");
    const key = path.toLocaleLowerCase();

    if (path && !seen.has(key)) {
      seen.add(key);
      paths.push(path);
    }
  }

  return paths;
}

export function createPriorityPortraitFolderPaths(options: {
  configuredFolders: string[];
  hasCareer: boolean;
}): string[] {
  return normalizePortraitFolderPaths([
    ...(options.hasCareer ? [wfrpCoreCareerPortraitFolder] : []),
    ...defaultPriorityPortraitFolders,
    ...options.configuredFolders,
  ]);
}

export function getActivePortraitSearchTerms(
  searchTerms: string[],
  disabledSearchTerms: string[],
): string[] {
  const disabledTerms = new Set(disabledSearchTerms);

  return searchTerms.filter((term) => !disabledTerms.has(term));
}

export function getPortraitTermsInSection(
  searchTerms: string[],
  termSections: Record<string, PortraitFilterSection>,
  section: PortraitFilterSection,
): string[] {
  return searchTerms.filter((term) => (termSections[term] ?? "search") === section);
}

export function doesPortraitTextMatch(value: string, searchTerms: string[]): boolean {
  const normalizedValue = normalizeSearchText(value);

  return Boolean(normalizedValue && searchTerms.some((term) => normalizedValue.includes(term)));
}

export function doesPortraitCandidateMatchFilters(
  candidate: PortraitCandidate,
  filters: {
    mustExcludeSources: string[];
    mustExcludeTerms: string[];
    mustIncludeSources: string[];
    mustIncludeTerms: string[];
  },
): boolean {
  const searchableText = getCandidateSearchText(candidate);
  const source = getPortraitCandidateFilterSource(candidate);
  const matchesIncludedSource =
    filters.mustIncludeSources.length === 0 ||
    (source !== null && filters.mustIncludeSources.includes(source.value));
  const matchesExcludedSource =
    source !== null && filters.mustExcludeSources.includes(source.value);

  return (
    filters.mustIncludeTerms.every((term) => searchableText.includes(term)) &&
    filters.mustExcludeTerms.every((term) => !searchableText.includes(term)) &&
    matchesIncludedSource &&
    !matchesExcludedSource
  );
}

export function createPortraitFilterTagDragData(tagId: string): string {
  return `${portraitFilterDragDataPrefix}${tagId}`;
}

export function readPortraitFilterTagDragId(data: string): string | null {
  return data.startsWith(portraitFilterDragDataPrefix)
    ? data.slice(portraitFilterDragDataPrefix.length)
    : null;
}

export function shouldSearchForPortraits(options: {
  hasEnabledSource: boolean;
  hasSubject: boolean;
  searchTerms: string[];
}): boolean {
  return options.hasEnabledSource && options.hasSubject && options.searchTerms.length > 0;
}

export function getPortraitSearchProgressValue(progress: PortraitSearchProgress | null): number {
  if (!progress) {
    return 0;
  }

  if (progress.maxDirectories <= 0) {
    return progress.phase === "ready" ? 100 : 4;
  }

  return Math.min(100, Math.round((progress.directoriesVisited / progress.maxDirectories) * 100));
}

export function getPortraitSearchProgressLabel(progress: PortraitSearchProgress | null): string {
  if (!progress) {
    return "";
  }

  if (progress.phase === "ready") {
    return `${progress.candidatesFound} options found`;
  }

  if (progress.phase !== "filesystem") {
    return progress.currentLocation;
  }

  if (progress.maxDirectories <= 0) {
    return `${progress.directoriesVisited} directories - ${progress.currentLocation}`;
  }

  return `${progress.directoriesVisited}/${progress.maxDirectories} directories - ${progress.currentLocation}`;
}

export function getPortraitCandidateTitle(candidate: PortraitCandidate): string {
  return `${candidate.label}\n${candidate.img}`;
}

export function getPortraitCandidateAriaLabel(candidate: PortraitCandidate): string {
  return `Use ${candidate.label} (${getPortraitCandidateSourceLabel(candidate)})`;
}

export function getPortraitCandidateSourceLabel(candidate: PortraitCandidate): string {
  const labels: Record<PortraitCandidateSource, string> = {
    "base-actor": "Actor Portrait",
    "base-token": "Prototype Token",
    "career": "Career",
    "foundry-asset": "Foundry",
    "web": "Web",
  };

  return candidate.sourceLabel ?? labels[candidate.source];
}

function getCandidateSearchText(candidate: PortraitCandidate): string {
  return normalizeSearchText(
    [candidate.label, candidate.img, candidate.sourceLabel ?? ""].filter(Boolean).join(" "),
  );
}

function normalizeSearchText(value: string): string {
  return value
    .trim()
    .toLocaleLowerCase()
    .replaceAll(/[_-]/g, " ")
    .replaceAll(/[(),.:;[\]]/g, " ")
    .replaceAll(/\s+/g, " ");
}

function tokenizeSearchTerm(term: string): string[] {
  return normalizeSearchText(term).split(" ").filter(Boolean);
}

function uniqueStrings(values: string[]): string[] {
  return [...new Set(values)];
}
