import type {
  SpeciesTableSourceDraft,
  SpeciesTableSourceRow,
} from "../../../../types/species/index";

import {
  buildSpeciesTableSource,
  MANAGED_SPECIES_TABLE_FLAG,
} from "../../../functions/species-table/source";
import { isRecord, readStringPath } from "../../../functions/shared/object-readers";
import { MODULE_ID, WFRP4E_SYSTEM_ID } from "../../../constants";
import { applyRollTableResultChanges } from "../../../foundry/roll-table-results";
import { ensureSpeciesTableJournalLinks } from "./journals";

const SPECIES_TABLE_KEY = "species";
const TABLE_SETTINGS_KEY = "tableSettings";

export async function upsertManagedSpeciesTable(
  draft: SpeciesTableSourceDraft,
): Promise<FoundryRollTableDocument> {
  const linkedDraft = await ensureSpeciesTableJournalLinks(draft);
  const source = buildSpeciesTableSource(linkedDraft, MODULE_ID);

  return draft.ownership === "managed"
    ? await updateManagedTable(linkedDraft, source)
    : await createManagedTable(linkedDraft, source);
}

export async function registerSpeciesTable(tableId: string): Promise<void> {
  const settings = game.settings.get(WFRP4E_SYSTEM_ID, TABLE_SETTINGS_KEY);

  if (!isRecord(settings)) {
    throw new Error("WFRP table settings are unavailable; the Species table was not registered.");
  }

  await game.settings.set(WFRP4E_SYSTEM_ID, TABLE_SETTINGS_KEY, {
    ...settings,
    [SPECIES_TABLE_KEY]: tableId,
  });
}

export function isManagedSpeciesTable(table: FoundryRollTableDocument): boolean {
  return table.getFlag(MODULE_ID, MANAGED_SPECIES_TABLE_FLAG) === true;
}

async function createManagedTable(
  draft: SpeciesTableSourceDraft,
  source: Record<string, unknown>,
): Promise<FoundryRollTableDocument> {
  if (draft.ownership === "external") {
    const sourceTable = draft.tableId ? game.tables?.get(draft.tableId) : undefined;

    if (!sourceTable || isManagedSpeciesTable(sourceTable)) {
      throw new Error("The source Species table changed. Reload before saving a managed copy.");
    }
  }

  if ((game.tables?.contents ?? []).some(isManagedSpeciesTable)) {
    throw new Error("A managed Species table already exists. Reload before saving.");
  }

  const table = await RollTable.create(source);

  if (!table) {
    throw new Error("Foundry did not create the managed Species table.");
  }

  return table;
}

async function updateManagedTable(
  draft: SpeciesTableSourceDraft,
  source: Record<string, unknown>,
): Promise<FoundryRollTableDocument> {
  const table = draft.tableId ? game.tables?.get(draft.tableId) : undefined;

  if (!table || !isManagedSpeciesTable(table)) {
    throw new Error("The managed Species table changed. Reload before saving again.");
  }

  const resultSources = Array.isArray(source["results"]) ? source["results"].filter(isRecord) : [];

  await table.update({
    displayRoll: source["displayRoll"],
    [`flags.${MODULE_ID}.${MANAGED_SPECIES_TABLE_FLAG}`]: true,
    [`flags.${WFRP4E_SYSTEM_ID}.key`]: SPECIES_TABLE_KEY,
    formula: source["formula"],
    name: source["name"],
    replacement: source["replacement"],
  });
  await reconcileResults(table, draft.rows, resultSources);

  return table;
}

async function reconcileResults(
  table: FoundryRollTableDocument,
  rows: SpeciesTableSourceRow[],
  resultSources: Record<string, unknown>[],
): Promise<void> {
  const tableSource = table.toObject();
  const existingSources = Array.isArray(tableSource["results"])
    ? tableSource["results"].filter(isRecord)
    : [];
  const existingIds = new Set(existingSources.map((source) => readStringPath(source, ["_id"])));
  const usedIds = new Set<string>();
  const updates: Record<string, unknown>[] = [];
  const creates: Record<string, unknown>[] = [];

  resultSources.forEach((source, index) => {
    const matchedId = findResultId(rows[index], existingSources, existingIds, usedIds);

    if (matchedId) {
      usedIds.add(matchedId);
      updates.push({ ...source, _id: matchedId });
    } else {
      creates.push(source);
    }
  });

  const deletedIds = [...existingIds].filter((id) => id && !usedIds.has(id));

  await applyRollTableResultChanges(table, { creates, deletedIds, updates });
}

function findResultId(
  row: SpeciesTableSourceRow | undefined,
  existingSources: Record<string, unknown>[],
  existingIds: Set<string>,
  usedIds: Set<string>,
): string {
  if (row?.resultId && existingIds.has(row.resultId) && !usedIds.has(row.resultId)) {
    return row.resultId;
  }

  const matched = existingSources.find(
    (source) =>
      readStringPath(source, ["flags", WFRP4E_SYSTEM_ID, "species"]) === row?.speciesKey &&
      !usedIds.has(readStringPath(source, ["_id"])),
  );

  return matched ? readStringPath(matched, ["_id"]) : "";
}
