import type { SpeciesItemRecord } from "../../../types/species/item";
import { decodeCharacteristics } from "../species-item/system";
import { decodeTalentChoices } from "../species-item/choices";

export function speciesStagePreview(item: SpeciesItemRecord) {
  const { system } = item;
  return {
    characteristics: decodeCharacteristics(system),
    movement: system.movement ?? undefined,
    fate: system.fate ?? undefined,
    resilience: system.resilience ?? undefined,
    extra: system.extra ?? undefined,
    // Native preview templates use triple braces for these names.
    skills: system.skills.list.map(escapeName),
    talents: decodeTalentChoices(system.talents.choices).map((grant) =>
      grant.choices.map((choice) => escapeName(choice.name)).join(" or "),
    ),
    randomTalents: [
      {
        name: item.system.tables.talents.name || "Talents",
        count: item.system.talents.random ?? 0,
      },
    ],
  };
}

function escapeName(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}
