import { registerCompendiumSidebarSetting } from "../foundry/compendiums/settings";
import { tidyCompendiumSidebarIfEnabled } from "../foundry/compendiums/tidy";
import { registerSpeciesItemChargen } from "../wfrp/species-chargen";
import { offerDefaultSpeciesTable } from "../wfrp/species-chargen/table-reminder";
import { registerSpeciesActorSheet } from "../wfrp/species-item/actor-sheet";
import { registerNpcBuilderActorDirectoryButton } from "../wfrp/npc-builder/register-actor-directory-button";
import { registerActorPortraitGallerySheetHooks } from "../wfrp/actor-portrait-gallery/register-actor-sheet-button";
import { registerNpcEstimatedXpSheetHooks } from "../wfrp/npc-builder/estimated-xp";
import { registerSpeciesChargenSwapGuard } from "../wfrp/species-chargen/roll-swap-guard";
import { registerSpeciesItemSheet } from "./species-sheet";
import { registerSpeciesItemModel } from "../wfrp/species-item/documents/model";
import {
  hasNativeSpeciesSupport,
  migrateSpeciesItemsToNative,
} from "../wfrp/species-item/documents/migration";
import { MODULE_ID, WFRP4E_SYSTEM_ID } from "../constants";
import { logInfo, logWarning } from "../foundry/logging";
import { registerModuleMenus } from "../foundry/register-module-menus";
import { registerModuleSettings } from "../foundry/register-module-settings";
import { startCareerIndexing } from "../wfrp/career-index";
import { registerWfrpItemEffectDropHooks } from "../wfrp/item-effect-drops";
import { startSkillSpecializationIndexing } from "../wfrp/skill-specializations";
import { registerModuleApi } from "../foundry/api/register-module-api";

export function registerModuleHooks(): void {
  Hooks.once("init", () => {
    logInfo(`${MODULE_ID} | Initializing`);
    registerModuleSettings();

    if (game.system.id === WFRP4E_SYSTEM_ID) {
      registerSpeciesItemModel();
      registerSpeciesItemSheet();
      registerSpeciesActorSheet();
      registerActorPortraitGallerySheetHooks();
      registerNpcEstimatedXpSheetHooks();
      if (!hasNativeSpeciesSupport()) {
        registerSpeciesChargenSwapGuard();
        registerSpeciesItemChargen();
      }
      registerWfrpItemEffectDropHooks();
    }

    registerModuleMenus();
    registerNpcBuilderActorDirectoryButton();
  });

  Hooks.once("setup", registerCompendiumSidebarSetting);

  Hooks.once("ready", () => {
    if (game.system.id !== WFRP4E_SYSTEM_ID) {
      logWarning(
        `${MODULE_ID} | Loaded outside ${WFRP4E_SYSTEM_ID}; skipping module API registration.`,
      );
      return;
    }

    return completeWfrpReadyLifecycle();
  });
}

async function completeWfrpReadyLifecycle(): Promise<void> {
  try {
    await migrateSpeciesItemsToNative();
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown runtime adaptation error.";

    logWarning(`${MODULE_ID} | Species Item migration failed: ${message}`);
    ui.notifications?.error(`Customizer initialization failed: ${message}`);
    // Do not expose the API or report readiness after a required runtime preparation fails.
    throw error;
  }

  try {
    await tidyCompendiumSidebarIfEnabled();
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    logWarning(`${MODULE_ID} | Compendium tidy failed: ${message}`);
    ui.notifications?.error(`Compendium folders could not be restored: ${message}`);
  }
  registerModuleApi();
  void offerDefaultSpeciesTable();
  void startCareerIndexing().catch(() => {
    ui.notifications?.error("Career indexing failed. Adding a Career will retry the index.");
  });
  void startSkillSpecializationIndexing();
  logInfo(`${MODULE_ID} | Ready`);
}
