import type {
  PortraitCandidate,
  PortraitFilterSource,
  PortraitSourceGroup,
} from "../../../types/portrait-gallery";

export function getPortraitCandidateFilterSource(
  candidate: PortraitCandidate,
): PortraitFilterSource | null {
  if (candidate.sourceFilter) {
    return candidate.sourceFilter;
  }

  return candidate.sourceGroup
    ? {
        label: getPortraitSourceGroupLabel(candidate.sourceGroup),
        value: candidate.sourceGroup,
      }
    : null;
}

export function listPortraitCandidateFilterSources(
  candidates: PortraitCandidate[],
): PortraitFilterSource[] {
  const sources = new Map<string, PortraitFilterSource>();

  for (const candidate of candidates) {
    const source = getPortraitCandidateFilterSource(candidate);

    if (source && !sources.has(source.value)) {
      sources.set(source.value, source);
    }
  }

  return [...sources.values()];
}

export function createPriorityPortraitFilterSource(path: string): PortraitFilterSource {
  const pathSegments = path.split("/").filter(Boolean);
  const context = pathSegments.slice(-2).join("/") || path;

  return {
    label: `Priority Folder: ${context}`,
    value: `priority-folder:${path.toLocaleLowerCase()}`,
  };
}

export function getPortraitSourceGroupLabel(sourceGroup: PortraitSourceGroup): string {
  const labels: Record<PortraitSourceGroup, string> = {
    "career": "Career",
    "compendiums": "Compendiums",
    "dig-down": "Dig Down",
    "priority-folders": "Priority Folders",
    "world": "World",
  };

  return labels[sourceGroup];
}
