import type { SpeciesSelection } from "../../../types/species/chargen";
import { compileSpeciesSelection } from "../../functions/species-chargen/selection";
import { speciesIdentityUuids } from "../../functions/species-chargen/roll-bonus";
import { readSpeciesItem } from "../species-item/documents/adapter";
import { speciesSourceFamily } from "../species-table/items";
import { speciesActorSource } from "../species-item/documents/actor-source";

export async function resolveChargenSpecies(uuid: string): Promise<SpeciesSelection> {
  const family = await speciesSourceFamily(uuid);
  const item = family[family.length - 1]!;
  const parent = family.length > 1 ? readSpeciesItem(family[0]!) : undefined;
  const record = compileSpeciesSelection(readSpeciesItem(item), parent);
  const source = speciesActorSource(item, record);
  return {
    uuid: item.uuid,
    record,
    source,
    identity: {
      self: [...new Set([uuid, ...speciesIdentityUuids(item.uuid, item.toObject())])],
      parent: family.length > 1 ? speciesIdentityUuids(family[0]!.uuid, family[0]!.toObject()) : [],
    },
  };
}
