import { computed, type ComputedRef, type Ref } from "vue";

import type {
  NpcAdvancementDraftEntry,
  NpcBuilderSettings,
  NpcSpellDraftEntry,
  NpcTraitDraftEntry,
} from "../../../../types/npc-builder";

import { deriveMagicGrants } from "../functions/spells/derive-magic-grants";
import {
  deriveNpcSpells,
  getSelectedNpcSpells,
  hydrateDetectedNpcSpells,
  planCustomSpellAddition,
} from "../functions/spells/derive-spells";

interface SpellStoreSliceContext {
  advancements: ComputedRef<NpcAdvancementDraftEntry[]>;
  customSpells: Ref<NpcSpellDraftEntry[]>;
  detectedSpells: Ref<NpcSpellDraftEntry[]>;
  magicLoreResolutions: Ref<Record<string, string>>;
  settings: Ref<NpcBuilderSettings>;
  spellSelectionOverrides: Ref<Record<string, boolean>>;
  traits: ComputedRef<NpcTraitDraftEntry[]>;
}

export function createSpellStoreSlice(context: SpellStoreSliceContext) {
  const {
    advancements,
    customSpells,
    detectedSpells,
    magicLoreResolutions,
    settings,
    spellSelectionOverrides,
    traits,
  } = context;

  const magicGrants = computed(() =>
    deriveMagicGrants({
      advancements: advancements.value,
      loreResolutions: magicLoreResolutions.value,
      traits: traits.value,
    }),
  );

  const hasMagicAccess = computed(() => magicGrants.value.length > 0);

  const spells = computed(() =>
    deriveNpcSpells({
      autoSelectDetectedSpells: settings.value.autoSelectGrantedSpells,
      customSpells: customSpells.value,
      detectedSpells: detectedSpells.value,
      selectionOverrides: spellSelectionOverrides.value,
    }),
  );

  const selectedSpells = computed(() => getSelectedNpcSpells(spells.value));

  function addCustomSpell(spell: NpcSpellDraftEntry): void {
    const result = planCustomSpellAddition({
      customSpells: customSpells.value,
      detectedSpells: detectedSpells.value,
      spell,
    });

    if (result.selectedDetectedSpellKey) {
      spellSelectionOverrides.value[result.selectedDetectedSpellKey] = true;
      return;
    }

    customSpells.value = result.customSpells;
  }

  function hydrateDetectedSpells(nextSpells: NpcSpellDraftEntry[]): void {
    detectedSpells.value = hydrateDetectedNpcSpells({
      autoSelectDetectedSpells: settings.value.autoSelectGrantedSpells,
      selectionOverrides: spellSelectionOverrides.value,
      spells: nextSpells,
    });
  }

  function removeCustomSpell(key: string): void {
    customSpells.value = customSpells.value.filter((entry) => entry.key !== key);
    delete spellSelectionOverrides.value[key];
  }

  function setSpellSelected(key: string, selected: boolean): void {
    spellSelectionOverrides.value[key] = selected;
  }

  function setMagicGrantLoreResolution(resolutionKey: string, lore: string): void {
    const trimmedLore = lore.trim();

    if (!trimmedLore) {
      delete magicLoreResolutions.value[resolutionKey];
      return;
    }

    magicLoreResolutions.value[resolutionKey] = trimmedLore;
  }

  return {
    addCustomSpell,
    hasMagicAccess,
    hydrateDetectedSpells,
    magicGrants,
    removeCustomSpell,
    selectedSpells,
    setMagicGrantLoreResolution,
    setSpellSelected,
    spells,
  };
}
