import {
  NpcActorSizeKey,
  type NpcActorCombatProfile,
  type NpcCombinedProfilePlan,
} from "../../../../../types/npc-builder";

import { planMountTraitContributions } from "./traits";

const SIZE_ORDER: NpcActorSizeKey[] = [
  NpcActorSizeKey.Tiny,
  NpcActorSizeKey.Little,
  NpcActorSizeKey.Small,
  NpcActorSizeKey.Average,
  NpcActorSizeKey.Large,
  NpcActorSizeKey.Enormous,
  NpcActorSizeKey.Monstrous,
];

export const NPC_ACTOR_SIZE_LABELS: Record<NpcActorSizeKey, string> = {
  [NpcActorSizeKey.Average]: "Average",
  [NpcActorSizeKey.Enormous]: "Enormous",
  [NpcActorSizeKey.Large]: "Large",
  [NpcActorSizeKey.Little]: "Little",
  [NpcActorSizeKey.Monstrous]: "Monstrous",
  [NpcActorSizeKey.Small]: "Small",
  [NpcActorSizeKey.Tiny]: "Tiny",
};

export function calculateCombinedProfile(
  rider: NpcActorCombatProfile,
  mount: NpcActorCombatProfile,
): NpcCombinedProfilePlan {
  return {
    chargeStrengthBonus: Math.max(
      mount.characteristics.strengthBonus - rider.characteristics.strengthBonus,
      0,
    ),
    initiative: Math.max(rider.characteristics.initiative, mount.characteristics.initiative),
    movement: mount.movement,
    size: largerSize(rider.size, mount.size),
    strength: rider.characteristics.strength,
    toughness: Math.max(rider.characteristics.toughness, mount.characteristics.toughness),
    traits: planMountTraitContributions(mount.traits),
    wounds: combinedWounds(rider.wounds, mount.wounds),
  };
}

export function combinedWounds(riderWounds: number, mountWounds: number): number {
  const higher = Math.max(riderWounds, mountWounds);
  const lower = Math.min(riderWounds, mountWounds);

  return Math.max(1, higher + Math.ceil(lower * 0.25));
}

export function largerSize(left: NpcActorSizeKey, right: NpcActorSizeKey): NpcActorSizeKey {
  return sizeIndex(right) > sizeIndex(left) ? right : left;
}

function sizeIndex(size: NpcActorSizeKey): number {
  return SIZE_ORDER.indexOf(size);
}
