<script setup lang="ts">
import { onMounted } from "vue";

import type { NpcBuilderBridge, NpcSpellDraftEntry } from "../../../../../types/npc-builder";

import { createNpcBuilderSpellsWorkflow } from "../../state/workflows/spells-workflow";
import MagicLoreResolutionPromptContent from "./MagicLoreResolutionPromptContent.vue";
import NpcBuilderDialog from "./NpcBuilderDialog.vue";
import MagicAccessPanel from "./NpcBuilderSpellsTab/MagicAccessPanel.vue";
import SpellSelectionPanel from "./NpcBuilderSpellsTab/SpellSelectionPanel.vue";

const props = defineProps<{
  bridge: NpcBuilderBridge;
}>();

const {
  ambiguousGrants,
  confirmMagicLorePrompt,
  dismissMagicLorePrompt,
  errorMessage,
  handleSpellDrop,
  initialize,
  isLoadingLoreOptions,
  isLoadingSpells,
  loadDetectedSpells,
  magicGrants,
  openMagicLorePrompt,
  pendingMagicLorePrompt,
  removeCustomSpell,
  resolvedGrantCount,
  selectedSpells,
  setSpellSelected: setSpellSelection,
  spells,
} = createNpcBuilderSpellsWorkflow(props.bridge);

onMounted(() => {
  initialize();
});

function setSpellSelected(spell: NpcSpellDraftEntry, event: Event): void {
  const input = event.target as HTMLInputElement | null;

  if (input) {
    setSpellSelection(spell.key, input.checked);
  }
}
</script>

<template>
  <section>
    <NpcBuilderDialog
      :open="pendingMagicLorePrompt !== null"
      title="Resolve Magic Lores"
      @close="dismissMagicLorePrompt"
    >
      <MagicLoreResolutionPromptContent
        v-if="pendingMagicLorePrompt"
        :prompt="pendingMagicLorePrompt"
        @apply-lores="confirmMagicLorePrompt"
        @keep-unresolved="dismissMagicLorePrompt"
      />
    </NpcBuilderDialog>

    <MagicAccessPanel
      :ambiguous-grant-count="ambiguousGrants.length"
      :is-loading-lore-options="isLoadingLoreOptions"
      :magic-grants="magicGrants"
      @resolve-lores="openMagicLorePrompt"
    />

    <div class="dui-divider" />

    <SpellSelectionPanel
      :ambiguous-grant-count="ambiguousGrants.length"
      :error-message="errorMessage"
      :is-loading-spells="isLoadingSpells"
      :resolved-grant-count="resolvedGrantCount"
      :selected-spell-count="selectedSpells.length"
      :spells="spells"
      @refresh-spells="loadDetectedSpells"
      @remove-custom-spell="removeCustomSpell"
      @spell-drop="handleSpellDrop"
      @spell-selected-change="setSpellSelected"
    />
  </section>
</template>
