import type {
  SpeciesActorSheet,
  SpeciesSheetAction,
} from "../../../../types/foundry/actor-species";
import { isRecord } from "../../../functions/shared/object-readers";
import { isFoundryActor, isFoundryItem } from "../../../foundry/document-guards";
import { isSpeciesItem } from "../documents/adapter";
import { dropActorSpecies } from "./drop";
import { ownedSpecies } from "./owned";
import { randomizeActorSpecies } from "./randomize";

const installedSheets = new WeakSet<object>();

export function installSpeciesNameGetter(prototype: object): void {
  const descriptor = Object.getOwnPropertyDescriptor(prototype, "Species");
  if (!descriptor?.get) throw new Error("WFRP Actor Species getter is unavailable.");
  const original = descriptor.get;
  Object.defineProperty(prototype, "Species", {
    ...descriptor,
    get(this: FoundryActorDocument) {
      return ownedSpecies(this)?.name ?? original.call(this);
    },
  });
}

export function installSpeciesSheet(application: unknown, html: unknown): void {
  if (!isRecord(application) || !isFoundryActor(application["document"])) return;
  if (!isRecord(application["options"]) || !isRecord(application["options"]["actions"])) return;
  if (typeof application["_onDropItem"] !== "function") return;
  const sheet = application as unknown as SpeciesActorSheet;
  if (!installedSheets.has(sheet)) {
    wrapSheetActions(sheet);
    installedSheets.add(sheet);
  }
  if (!(html instanceof HTMLElement)) return;
  const input = html.querySelector<HTMLInputElement>("[data-action='editSpecies']");
  const item = ownedSpecies(sheet.document);
  if (input) input.readOnly = !!item;
  if (input && item) {
    input.value = item.name;
    input.readOnly = true;
    input.title = "Species comes from the owned Item. Open it from the sheet header menu to edit.";
  }
}

function wrapSheetActions(sheet: SpeciesActorSheet): void {
  const originalDrop = sheet._onDropItem;
  sheet._onDropItem = async function (data, event) {
    if (!isRecord(data) || typeof data["uuid"] !== "string")
      return originalDrop.call(this, data, event);
    try {
      const item = await fromUuid(data["uuid"]);
      if (isFoundryItem(item) && isSpeciesItem(item))
        return await dropActorSpecies(this.document, item);
    } catch (error) {
      reportError(error);
      return;
    }
    return originalDrop.call(this, data, event);
  };
  const originalRandomize = sheet.options.actions["randomize"];
  if (typeof originalRandomize !== "function") return;
  sheet.options.actions["randomize"] = async function (
    this: SpeciesActorSheet,
    event: Event,
    target: HTMLElement,
  ) {
    const item = ownedSpecies(this.document);
    if (!item) return (originalRandomize as SpeciesSheetAction).call(this, event, target);
    const element = target ?? event.target;
    if (!(element instanceof HTMLElement)) return;
    try {
      await randomizeActorSpecies(this.document, item, element.dataset["type"] ?? "");
    } catch (error) {
      reportError(error);
    }
  };
}

function reportError(error: unknown): void {
  // Native WFRP findSkill/findTalent throw localized strings when a document is missing.
  ui.notifications?.error(error instanceof Error ? error.message : String(error));
}
