import type { SpeciesEffectSource } from "../../../types/species/item";
import { isRecord } from "../shared/object-readers";

/** Read the declarative Actor changes without running Species scripts during a preview. */
export function speciesDetailFormulas(effects: SpeciesEffectSource[]): {
  age?: string;
  height?: string;
} {
  const formulas: { age?: string; height?: string } = {};
  for (const effect of effects) {
    if (effect["disabled"] === true) continue;
    const system = isRecord(effect["system"]) ? effect["system"] : {};
    const transfer = isRecord(system["transferData"]) ? system["transferData"] : {};
    if (transfer["type"] !== "document" || transfer["documentType"] !== "Actor") continue;
    // v14 stores changes in the effect model; older sources use the top-level array.
    const changes = system["changes"] ?? effect["changes"];
    if (!Array.isArray(changes)) continue;
    for (const change of changes) {
      if (!isRecord(change)) continue;
      const field =
        change["key"] === "flags.drowsy.ageFormula"
          ? "age"
          : change["key"] === "flags.drowsy.heightFormula"
            ? "height"
            : undefined;
      if (!field) continue;
      const value = change["value"];
      const formula =
        typeof value === "string"
          ? value.trim()
          : typeof value === "number" && Number.isFinite(value)
            ? String(value)
            : "";
      if (
        (change["type"] !== undefined ? change["type"] !== "override" : change["mode"] !== 5) ||
        !formula
      )
        throw new Error(`Species ${field} formula must be a nonempty Override effect change.`);
      if (formulas[field] !== undefined)
        throw new Error(`Species has more than one enabled ${field} formula. Keep one provider.`);
      formulas[field] = formula;
    }
  }
  return formulas;
}
