import { ref, type Ref } from "vue";

import type { NpcBuilderBridge, NpcCareerSummary } from "../../../../../types/npc-builder";
import type { NpcBuilderActiveTab } from "./types";

import {
  npcPortraitFilterTagDragMimeType,
  readPortraitFilterTagDragId,
} from "../../functions/portrait-candidates";
import { useNpcBuilderStore } from "../../state";
import { toErrorMessage } from "./errors";

export function useNpcBuilderApplicationDrop(
  bridge: NpcBuilderBridge,
  activePage: Ref<NpcBuilderActiveTab>,
  addCareer: (career: NpcCareerSummary, options?: { replaceQueue?: boolean }) => Promise<void>,
  errorMessage: Ref<string>,
) {
  const store = useNpcBuilderStore();
  const isApplicationDragOver = ref(false);

  function handleApplicationDragEnter(event: DragEvent): void {
    if (isInternalNpcBuilderDrag(event)) {
      return;
    }

    event.preventDefault();
    isApplicationDragOver.value = true;
  }

  function handleApplicationDragLeave(event: DragEvent): void {
    if (isInternalNpcBuilderDrag(event)) {
      return;
    }

    const target = event.currentTarget;
    const relatedTarget = event.relatedTarget;

    if (target instanceof Node && relatedTarget instanceof Node && target.contains(relatedTarget)) {
      return;
    }

    isApplicationDragOver.value = false;
  }

  function handleApplicationDragOver(event: DragEvent): void {
    if (isInternalNpcBuilderDrag(event)) {
      return;
    }

    event.preventDefault();
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = "copy";
    }
  }

  async function handleApplicationDrop(event: DragEvent): Promise<void> {
    if (isInternalNpcBuilderDrag(event)) {
      return;
    }

    event.preventDefault();
    isApplicationDragOver.value = false;
    errorMessage.value = "";

    try {
      const drop = await bridge.resolveApplicationDrop(
        event.dataTransfer?.getData("text/plain") ?? "",
      );

      if (drop.kind === "actor") {
        store.selectBaseActor(drop.actor);
      } else if (drop.kind === "career") {
        await addCareer(drop.career, { replaceQueue: activePage.value === "build-quick" });
      } else if (drop.kind === "advancement") {
        store.addCustomAdvancement(drop.advancement);
      } else if (drop.kind === "trapping") {
        store.addCustomTrapping(drop.trapping);
      } else if (drop.kind === "trait") {
        store.addCustomTrait(drop.trait);
      } else {
        store.addCustomSpell(drop.spell);
      }
    } catch (error) {
      errorMessage.value = toErrorMessage(error);
    }
  }

  return {
    handleApplicationDragEnter,
    handleApplicationDragLeave,
    handleApplicationDragOver,
    handleApplicationDrop,
    isApplicationDragOver,
  };
}

function isInternalNpcBuilderDrag(event: DragEvent): boolean {
  const dataTransfer = event.dataTransfer;
  const data = dataTransfer?.getData("text/plain") ?? "";
  const dragTypes = Array.from(dataTransfer?.types ?? []);

  return (
    data.startsWith("npc-builder-career:") ||
    readPortraitFilterTagDragId(data) !== null ||
    dragTypes.includes(npcPortraitFilterTagDragMimeType)
  );
}
