import type {
  NpcActorCombatProfile,
  NpcCombinedProfilePlan,
} from "../../../../../types/npc-builder";

export interface CombinedProfileTraitSourceInput {
  flagScope: string;
  mount: NpcActorCombatProfile;
  plan: NpcCombinedProfilePlan;
  rider: NpcActorCombatProfile;
}

export function buildCombinedProfileTraitSource({
  flagScope,
  mount,
  plan,
  rider,
}: CombinedProfileTraitSourceInput): Record<string, unknown> {
  const traitName = "Combined Profile";

  return {
    effects: [
      {
        changes: [],
        disabled: false,
        flags: {
          [flagScope]: {
            generatedCombinedProfileEffect: true,
          },
        },
        img: mount.img || "icons/svg/wing.svg",
        name: traitName,
        system: {
          scriptData: buildCombinedProfileScripts(flagScope, plan),
          transferData: {
            documentType: "Actor",
            type: "document",
          },
        },
        transfer: true,
      },
    ],
    flags: {
      [flagScope]: {
        generatedCombinedProfileTrait: {
          mountUuid: mount.uuid,
          riderUuid: rider.uuid,
        },
      },
    },
    img: mount.img || "icons/svg/wing.svg",
    name: traitName,
    system: {
      description: {
        value: buildCombinedProfileDescription(rider, mount, plan),
      },
      specification: {
        value: `${rider.name} + ${mount.name}`,
      },
    },
    type: "trait",
  };
}

function buildCombinedProfileScripts(
  flagScope: string,
  plan: NpcCombinedProfilePlan,
): Record<string, unknown>[] {
  const scripts: Record<string, unknown>[] = [
    {
      label: "Combined Profile Wounds",
      script: [
        "// Generated by Drowsy's WFRP4e Customizers.",
        `args.wounds = ${plan.wounds};`,
      ].join("\n"),
      trigger: "woundCalc",
    },
    {
      label: "Combined Profile Size",
      script: [
        "// Generated by Drowsy's WFRP4e Customizers.",
        `args.size = ${JSON.stringify(plan.size)};`,
      ].join("\n"),
      trigger: "calculateSize",
    },
  ];

  if (plan.chargeStrengthBonus > 0) {
    scripts.push({
      label: "Combined Profile Charge",
      script: buildChargeDamageScript(flagScope, plan.chargeStrengthBonus),
      trigger: "preRollTest",
    });
  }

  return scripts;
}

function buildChargeDamageScript(flagScope: string, chargeStrengthBonus: number): string {
  return [
    "// Generated by Drowsy's WFRP4e Customizers.",
    "const test = args.test;",
    "const attackType = test.item?.attackType || test.item?.system?.attackType || test.item?.system?.rollable?.attackType;",
    `const isMountAttack = Boolean(test.item?.flags?.[${JSON.stringify(flagScope)}]?.generatedMountTrait);`,
    "",
    'if (!test.preData.charging || attackType !== "melee" || isMountAttack) {',
    "  return;",
    "}",
    "",
    `test.preData.additionalDamage = Number(test.preData.additionalDamage || 0) + ${chargeStrengthBonus};`,
    "test.preData.other ||= [];",
    `test.preData.other.push("Combined Profile: +${chargeStrengthBonus} mount Strength Bonus on the charge");`,
  ].join("\n");
}

function buildCombinedProfileDescription(
  rider: NpcActorCombatProfile,
  mount: NpcActorCombatProfile,
  plan: NpcCombinedProfilePlan,
): string {
  return [
    "<p>Generated by Drowsy's WFRP4e Customizers. This Actor combines a rider and mount into one simplified NPC profile.</p>",
    `<p><strong>Rider:</strong> ${escapeHtml(rider.name)}<br><strong>Mount:</strong> ${escapeHtml(mount.name)}</p>`,
    `<p><strong>Movement:</strong> ${plan.movement}; <strong>Wounds:</strong> ${plan.wounds}; <strong>Charge SB:</strong> +${plan.chargeStrengthBonus}.</p>`,
    "<p>Mount attack Traits use fixed damage captured from the mount. Skittish and Bestial are removed.</p>",
  ].join("");
}

function escapeHtml(value: string): string {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
}
