import { validateSpeciesTableDraft } from "../../../functions/species-table/source";
import type {
  SpeciesTableDraft,
  SpeciesTableDrop,
  SpeciesTableOption,
} from "../../../../types/species/table";

export function addSpeciesTableDrop(draft: SpeciesTableDraft, drop: SpeciesTableDrop): void {
  const { option } = drop;
  let row = draft.rows.find((entry) => entry.speciesKey === option.key);
  if (row?.itemUuid && row.itemUuid !== option.itemUuid)
    throw new Error(`A different Species Item already uses “${option.key}” in this table.`);
  if (!row) {
    row = { speciesKey: option.key, name: option.label, weight: 1, sources: [] };
    draft.rows.push(row);
  }
  if (option.itemUuid) row.itemUuid = option.itemUuid;
  row.name = option.label;
  if (option.itemUuid) row.journalUuid = option.itemUuid;
  for (const source of drop.sources) {
    if (!row.sources.some((entry) => entry.uuid === source.uuid)) row.sources.push(source);
  }
}

export function speciesTableProblems(
  draft: SpeciesTableDraft,
  options: SpeciesTableOption[],
): string[] {
  const errors = validateSpeciesTableDraft(draft, options, true);
  if (!draft.name.trim()) errors.push("Enter a table name.");
  const total = draft.rows.reduce((sum, row) => sum + row.weight, 0);
  if (!Number.isSafeInteger(total)) errors.push("The total weight must be a safe whole number.");
  for (const row of draft.rows) {
    const canonical = options.find((option) => option.key === row.speciesKey);
    if (canonical && row.name !== canonical.label)
      errors.push(
        `“${row.name}” must use WFRP's species name “${canonical.label}”. Reload the editor.`,
      );
    if (!row.name.trim()) errors.push("Every species needs a name.");
    if (
      !row.itemUuid &&
      options.some(
        (option) => !option.itemUuid && option.key !== row.speciesKey && option.label === row.name,
      )
    )
      errors.push(`“${row.name}” also names another species. WFRP needs distinct species names.`);
  }
  return [...new Set(errors)];
}
