import type { SpeciesItemRecord } from "../../../types/species/item";
import { decodeCharacteristics } from "../species-item/system";
import { decodeTalentChoices } from "../species-item/choices";

/** Project only the selected, already-inherited Item into legacy chargen's config. */
export function speciesConfigForSelection(
  key: string,
  item: SpeciesItemRecord,
  formulas: { age?: string; height?: string },
  randomTalentKey: string,
): Record<string, Record<string, unknown>> {
  const { system } = item;
  const config: Record<string, Record<string, unknown>> = {
    species: { [key]: item.name },
    speciesSkills: { [key]: [...system.skills.list] },
    speciesTalents: {
      [key]: decodeTalentChoices(system.talents.choices).map((grant) =>
        grant.choices.map((choice) => choice.name).join(", "),
      ),
    },
  };
  const characteristics = decodeCharacteristics(system);
  if (characteristics) config["speciesCharacteristics"] = { [key]: characteristics };
  for (const [field, value] of Object.entries({
    speciesMovement: system.movement,
    speciesFate: system.fate,
    speciesRes: system.resilience,
    speciesExtra: system.extra,
  })) {
    if (value !== null) config[field] = { [key]: value };
  }
  if (system.talents.random !== null)
    config["speciesRandomTalents"] = { [key]: { [randomTalentKey]: system.talents.random } };
  if (formulas.age !== undefined) config["speciesAge"] = { [key]: formulas.age };
  if (formulas.height !== undefined)
    config["speciesHeight"] = { [key]: { feet: 0, inches: 0, die: formulas.height } };
  return config;
}
