import type { NpcCareerSummary } from "../../types/npc-builder";

import { extractCareerGrants } from "../apps/npc-builder/functions/extract-career-grants";
import { readStringPath, readUnknownPath } from "../functions/shared/object-readers";

export function toCareerSummary(item: FoundryItemDocument): NpcCareerSummary {
  return {
    careerGroup: getCareerGroup(item),
    grants: extractCareerGrants(item.system),
    img: item.img ?? "",
    level: getCareerLevel(item),
    name: item.name,
    uuid: item.uuid,
  };
}

function getCareerGroup(item: FoundryItemDocument): string {
  return readStringPath(item.system, ["careergroup", "value"]);
}

function getCareerLevel(item: FoundryItemDocument): null | number {
  const value = readUnknownPath(item.system, ["level", "value"]);
  const level = Number(value);

  return Number.isFinite(level) ? level : null;
}
