<script setup lang="ts">
import { useSpeciesItemStore } from "../state";
import { emptySpeciesReference } from "../../../functions/species-item/system";
import SpeciesItemReference from "./SpeciesItemReference.vue";
const props = defineProps<{ uuid: string; editable: boolean }>();
const store = useSpeciesItemStore(props.uuid);
const tables = [
  { key: "career", label: "Careers" },
  { key: "talents", label: "Talents" },
  { key: "eye", label: "Eye Colour" },
  { key: "hair", label: "Hair Colour" },
] as const;
</script>

<template>
  <fieldset class="dui-fieldset" :disabled="!editable">
    <legend class="app:sr-only">Tables</legend>
    <div class="dui-divider">Tables</div>
    <SpeciesItemReference
      v-for="table in tables"
      :key="table.key"
      :uuid="uuid"
      :label="table.label"
      :reference="store.draft.system.tables[table.key]"
      :editable="editable"
      @drop-data="store.drop($event, table.key)"
      @clear="store.draft.system.tables[table.key] = emptySpeciesReference()"
    />
  </fieldset>
</template>
