<script setup lang="ts">
import type { NpcAutoAdvanceStrategyDefinition } from "../../../../../../types/npc-builder";

import NpcBuilderSection from "../NpcBuilderSection.vue";

defineProps<{
  autoAdvanceStrategies: NpcAutoAdvanceStrategyDefinition[];
  canRunAutoAdvance: boolean;
  selectedAutoAdvanceStrategy: NpcAutoAdvanceStrategyDefinition | null;
  selectedAutoAdvanceStrategyId: string;
  targetXp: number;
}>();

const emit = defineEmits<{
  runAutoAdvance: [];
  strategyChange: [strategyId: string];
  targetXpChange: [targetXp: number];
}>();

function handleTargetXpInput(event: Event): void {
  const input = event.target as HTMLInputElement | null;

  emit("targetXpChange", Number(input?.value ?? 0));
}

function handleStrategyChange(event: Event): void {
  const select = event.target as HTMLSelectElement | null;

  emit("strategyChange", select?.value ?? "");
}
</script>

<template>
  <NpcBuilderSection
    description="Spend toward a target without exceeding it. Existing manual edits are preserved."
    number="4"
    title="Auto Advance"
  >
    <fieldset class="dui-fieldset">
      <legend class="dui-fieldset-legend">Target XP</legend>
      <input
        aria-label="Target XP"
        class="dui-input dui-input-sm"
        :value="targetXp"
        min="0"
        type="number"
        @input="handleTargetXpInput"
      />
    </fieldset>
    <fieldset class="dui-fieldset">
      <legend class="dui-fieldset-legend">Strategy</legend>
      <select
        aria-label="Auto advance strategy"
        class="dui-select dui-select-sm"
        :value="selectedAutoAdvanceStrategyId"
        @change="handleStrategyChange"
      >
        <option v-for="strategy in autoAdvanceStrategies" :key="strategy.id" :value="strategy.id">
          {{ strategy.name }}
        </option>
      </select>
    </fieldset>
    <p v-if="selectedAutoAdvanceStrategy">
      {{ selectedAutoAdvanceStrategy.description }}
    </p>
    <div class="dui-card-actions">
      <button
        class="dui-btn dui-btn-primary dui-btn-sm"
        :disabled="!canRunAutoAdvance"
        title="Advance rows as close to the target XP as possible without going over"
        type="button"
        @click="emit('runAutoAdvance')"
      >
        Auto Advance
      </button>
    </div>
  </NpcBuilderSection>
</template>
