import type { AttributeReference, FormulaKeyword } from "./compiler";

export function buildKeywordLines(usedKeywords: Set<FormulaKeyword>): string[] {
  const lines: string[] = [];

  if (usesAnyKeyword(usedKeywords, ["sb", "tb", "wpb"])) {
    lines.push(...keywordLines(usedKeywords, "sb", "preWoundArgs.sb"));
    lines.push(...keywordLines(usedKeywords, "tb", "preWoundArgs.tb"));
    lines.push(...keywordLines(usedKeywords, "wpb", "preWoundArgs.wpb"));
  }

  if (usesAnyKeyword(usedKeywords, ["sbMultiplier", "tbMultiplier", "wpbMultiplier"])) {
    lines.push("const multiplier = preWoundArgs.multiplier;");
    lines.push(...keywordLines(usedKeywords, "sbMultiplier", "multiplier.sb"));
    lines.push(...keywordLines(usedKeywords, "tbMultiplier", "multiplier.tb"));
    lines.push(...keywordLines(usedKeywords, "wpbMultiplier", "multiplier.wpb"));
  }

  if (usesAnyKeyword(usedKeywords, ["scale", "size"])) {
    lines.push(...buildSizeHelperLines());
    lines.push("const size = actorSizeStep();");
    lines.push(...keywordLines(usedKeywords, "scale", "2 ** size"));
  }

  if (usesAnyKeyword(usedKeywords, personalDetailKeywords)) {
    lines.push(...keywordLines(usedKeywords, "age", "Number(actor.system.details.age.value)"));
    lines.push(
      ...keywordLines(usedKeywords, "height", "Number(actor.system.details.height.value)"),
    );
    lines.push(
      ...keywordLines(usedKeywords, "weight", "Number(actor.system.details.weight.value)"),
    );
    lines.push(...buildStatusHelperLines(usedKeywords));
  }

  if (usesAnyKeyword(usedKeywords, statusKeywords)) {
    lines.push(...keywordLines(usedKeywords, "xp", "actor.system.details.experience.total"));
    lines.push(...keywordLines(usedKeywords, "fate", "actor.system.status.fate.value"));
    lines.push(...keywordLines(usedKeywords, "fortune", "actor.system.status.fortune.value"));
    lines.push(...keywordLines(usedKeywords, "resilience", "actor.system.status.resilience.value"));
    lines.push(...keywordLines(usedKeywords, "resolve", "actor.system.status.resolve.value"));
    lines.push(...keywordLines(usedKeywords, "corruption", "actor.system.status.corruption.value"));
    lines.push(...keywordLines(usedKeywords, "sin", "actor.system.status.sin.value"));
    lines.push(...keywordLines(usedKeywords, "advantage", "actor.system.status.advantage.value"));
  }

  if (usesAnyKeyword(usedKeywords, conditionKeywords)) {
    lines.push(...buildConditionHelperLines());

    for (const keyword of conditionKeywords) {
      lines.push(...keywordLines(usedKeywords, keyword, `conditionValue("${keyword}")`));
    }
  }

  return lines.length ? [...lines, ""] : [];
}

export function buildAttributeHelperLines(references: AttributeReference[]): string[] {
  const usesCharacteristics = references.length > 0;
  const usesSkills = references.some((reference) => reference.source === "skill");

  return [
    ...buildCharacteristicHelperLines(usesCharacteristics),
    ...buildSkillHelperLines(usesSkills),
  ];
}

export function buildAttributeReferenceLines(references: AttributeReference[]): string[] {
  return references.map((reference) => {
    if (reference.source === "characteristic") {
      return buildCharacteristicReferenceLine(reference);
    }

    return buildSkillReferenceLine(reference);
  });
}

function usesAnyKeyword(usedKeywords: Set<FormulaKeyword>, keywords: FormulaKeyword[]): boolean {
  return keywords.some((keyword) => usedKeywords.has(keyword));
}

function keywordLines(
  usedKeywords: Set<FormulaKeyword>,
  keyword: FormulaKeyword,
  value: string,
): string[] {
  return usedKeywords.has(keyword) ? [`const ${keyword} = ${value};`] : [];
}

function buildSizeHelperLines(): string[] {
  return [
    "function actorSizeStep() {",
    "  const sizeSteps = {",
    "    tiny: -3,",
    "    ltl: -2,",
    "    little: -2,",
    "    sml: -1,",
    "    small: -1,",
    "    avg: 0,",
    "    average: 0,",
    "    lrg: 1,",
    "    large: 1,",
    "    enor: 2,",
    "    enormous: 2,",
    "    mon: 3,",
    "    mnst: 3,",
    "    monstrous: 3,",
    "  };",
    "  return sizeSteps[actor.system.details.size.value.trim().toLocaleLowerCase()];",
    "}",
    "",
  ];
}

function buildCharacteristicHelperLines(usesCharacteristics: boolean): string[] {
  if (!usesCharacteristics) {
    return [];
  }

  return [
    "function characteristicTotal(key) {",
    "  const characteristic = actor.system.characteristics[key];",
    "  return characteristic.value;",
    "}",
    "",
    "function characteristicBonus(key) {",
    "  return actor.system.characteristics[key].bonus;",
    "}",
    "",
  ];
}

function buildSkillHelperLines(usesSkills: boolean): string[] {
  if (!usesSkills) {
    return [];
  }

  return [
    "function normalizedName(value) {",
    "  return value.trim().toLocaleLowerCase();",
    "}",
    "",
    "function findSkillItem(name, items) {",
    "  return items.find((item) => item.type === 'skill' && normalizedName(item.name) === normalizedName(name));",
    "}",
    "",
    "function skillAdvances(skill) {",
    "  return skill.system.advances.value;",
    "}",
    "",
    "function skillBaseName(name) {",
    "  return name.split('(')[0].trim();",
    "}",
    "",
    "function skillTotal(name, characteristicOverride) {",
    "  const actorSkill = findSkillItem(name, actor.items.contents);",
    "",
    "  if (actorSkill) {",
    "    const characteristicKey = characteristicOverride || actorSkill.system.characteristic.value;",
    "    return characteristicOverride ? characteristicTotal(characteristicKey) + skillAdvances(actorSkill) : actorSkill.system.total;",
    "  }",
    "",
    "  const worldSkill = findSkillItem(name, game.items.contents) || findSkillItem(skillBaseName(name), game.items.contents);",
    "",
    "  if (!worldSkill) {",
    "    return 0;",
    "  }",
    "",
    "  if (worldSkill.system.advanced.value !== 'bsc' && name === skillBaseName(name)) {",
    "    return 0;",
    "  }",
    "",
    "  return characteristicTotal(characteristicOverride || worldSkill.system.characteristic.value);",
    "}",
    "",
    "function skillBonus(name, characteristicOverride) {",
    "  return Math.floor(skillTotal(name, characteristicOverride) / 10);",
    "}",
    "",
  ];
}

function buildCharacteristicReferenceLine(reference: AttributeReference): string {
  const helper = reference.kind === "bonus" ? "characteristicBonus" : "characteristicTotal";

  return `const ${reference.variableName} = ${helper}(${JSON.stringify(reference.characteristicKey)});`;
}

function buildSkillReferenceLine(reference: AttributeReference): string {
  const helper = reference.kind === "bonus" ? "skillBonus" : "skillTotal";
  const override = reference.characteristicOverride
    ? JSON.stringify(reference.characteristicOverride)
    : "undefined";

  return `const ${reference.variableName} = ${helper}(${JSON.stringify(reference.name)}, ${override});`;
}

const personalDetailKeywords: FormulaKeyword[] = ["age", "height", "rank", "status", "weight"];
const statusKeywords: FormulaKeyword[] = [
  "advantage",
  "corruption",
  "fate",
  "fortune",
  "resilience",
  "resolve",
  "sin",
  "xp",
];
const conditionKeywords: FormulaKeyword[] = [
  "ablaze",
  "bleeding",
  "blinded",
  "broken",
  "deafened",
  "entangled",
  "fatigued",
  "poisoned",
  "stunned",
];

function buildStatusHelperLines(usedKeywords: Set<FormulaKeyword>): string[] {
  const lines: string[] = [];

  if (usedKeywords.has("status")) {
    lines.push(
      "function statusTierValue() {",
      "  const statusTiers = { brass: 1, silver: 2, gold: 3 };",
      "  const tier = actor.system.details.status.tier;",
      "  return statusTiers[String(tier).toLocaleLowerCase()] || Number(tier);",
      "}",
      "const status = statusTierValue();",
    );
  }

  lines.push(...keywordLines(usedKeywords, "rank", "Number(actor.system.details.status.standing)"));

  return lines;
}

function buildConditionHelperLines(): string[] {
  return [
    "function conditionValue(key) {",
    "  return actor.hasCondition(key)?.conditionValue || 0;",
    "}",
  ];
}
