import { buildEffectSource } from "../../apps/effect-builders/functions/build";
import type { EffectBuilderBridge, EffectBuilderDraft } from "../../../types/effect-builders";
import { speciesDetailFormulas } from "../../functions/species-chargen/detail-formulas";
import { readSpeciesEffectSources } from "../species-item/documents/effect-sources";
import { MODULE_ID } from "../../constants";
import { assertFoundryItem } from "../../foundry/document-guards";
import {
  editableEffectDestination,
  readTableReference,
  resolveEffectDrop,
  resolveEffectItemDrop,
  validateGrantTable,
} from "./documents";

export async function createBuiltEffect(
  destinationUuid: string,
  draft: EffectBuilderDraft,
): Promise<void> {
  const destination = editableEffectDestination(await fromUuid(destinationUuid));
  const source = buildEffectSource(draft, MODULE_ID);
  if (draft.kind === "age-height") {
    const existing = speciesDetailFormulas(
      readSpeciesEffectSources(destination.toObject()["effects"]),
    );
    for (const field of ["age", "height"] as const) {
      const formula = draft[field === "age" ? "ageFormula" : "heightFormula"].trim();
      if (!formula) continue;
      if (!Roll.validate(formula))
        throw new Error(`Invalid ${field} formula. Use a number or dice formula.`);
      if (existing[field] !== undefined)
        throw new Error(
          `This Item already has an enabled ${field} formula. Edit its existing effect instead.`,
        );
    }
  }
  const items =
    draft.kind === "grant"
      ? draft.items
      : draft.kind === "choice"
        ? draft.groups.flatMap((group) => group.items)
        : [];
  for (const item of items) {
    if (item.uuid === destinationUuid) throw new Error("An Item cannot grant itself.");
    assertFoundryItem(
      await fromUuid(item.uuid),
      `The granted Item ${item.name} is no longer available.`,
    );
  }
  if (draft.kind === "random") await validateGrantTable(draft.table!.uuid, destinationUuid);
  if (!destination.createEmbeddedDocuments)
    throw new Error("This Item cannot contain Active Effects.");
  await destination.createEmbeddedDocuments("ActiveEffect", [source]);
}

export const effectBuilderBridge: EffectBuilderBridge = {
  resolveItem: resolveEffectItemDrop,
  async resolveTable(data) {
    return readTableReference(await resolveEffectDrop(data));
  },
  create: createBuiltEffect,
  async openItem(uuid) {
    assertFoundryItem(await fromUuid(uuid)).sheet?.render(true);
  },
};
