<script setup lang="ts">
import type { NpcFolderSummary } from "../../../../../../types/npc-builder";

import FolderSetting from "./FolderSetting.vue";
import NpcBuilderSection from "../NpcBuilderSection.vue";

defineProps<{
  isBusy: boolean;
  itemFolders: NpcFolderSummary[];
  quickTraitFolderName: string;
  quickTraitFolderUuid: string;
}>();

const emit = defineEmits<{
  importRecommendedQuickTraits: [];
  quickTraitFolderNameChange: [name: string];
  quickTraitFolderUuidChange: [uuid: string];
  saveQuickTraitFolderName: [];
}>();
</script>

<template>
  <NpcBuilderSection
    description="Items in this folder become one-click Trait choices on the Build tab."
    number="2"
    title="Quick Traits"
  >
    <FolderSetting
      :create-name="quickTraitFolderName"
      :disabled="isBusy"
      :folders="itemFolders"
      :selected-uuid="quickTraitFolderUuid"
      default-option-label="No quick traits folder"
      folder-label="Quick traits folder"
      @create-name-change="emit('quickTraitFolderNameChange', $event)"
      @save-folder-name="emit('saveQuickTraitFolderName')"
      @selected-uuid-change="emit('quickTraitFolderUuidChange', $event)"
    />

    <div class="dui-card-actions">
      <button
        class="dui-btn dui-btn-sm"
        :disabled="isBusy || !quickTraitFolderUuid"
        type="button"
        @click="emit('importRecommendedQuickTraits')"
      >
        Import Recommended Quick Traits
      </button>
    </div>
  </NpcBuilderSection>
</template>
