import type {
  NpcAdvancementDraftEntry,
  NpcAdvancementKind,
  NpcAutoAdvanceNpc,
  NpcAutoAdvanceStrategyDefinition,
} from "../../../../types/npc-builder";

import { calculateAdvancementXp, calculateEstimatedNpcXp } from "./xp-cost";
import { getAdvancementStep, getAdvancementTotal } from "./advancements/advancement-actions";

interface AutoAdvancePassOptions {
  kinds: NpcAdvancementKind[];
  respectTalentMaximums: boolean;
}

const autoAdvanceStrategies = new Map<string, NpcAutoAdvanceStrategyDefinition>();

export function registerNpcAutoAdvanceStrategy(strategy: NpcAutoAdvanceStrategyDefinition): void {
  const id = strategy.id.trim();

  if (!id) {
    throw new Error("NPC auto-advance strategies must have an id.");
  }

  autoAdvanceStrategies.set(id, {
    ...strategy,
    id,
  });
}

export function listNpcAutoAdvanceStrategies(): NpcAutoAdvanceStrategyDefinition[] {
  return [...autoAdvanceStrategies.values()].sort((left, right) =>
    left.name.localeCompare(right.name),
  );
}

export function getNpcAutoAdvanceStrategy(id: string): NpcAutoAdvanceStrategyDefinition | null {
  return autoAdvanceStrategies.get(id) ?? null;
}

function skillMaster(npc: NpcAutoAdvanceNpc, targetXp: number): NpcAutoAdvanceNpc {
  return runAutoAdvancePass(npc, targetXp, {
    kinds: ["skill"],
    respectTalentMaximums: false,
  });
}

function giftedAndTalented(npc: NpcAutoAdvanceNpc, targetXp: number): NpcAutoAdvanceNpc {
  const advancedTalents = runAutoAdvancePass(npc, targetXp, {
    kinds: ["talent"],
    respectTalentMaximums: true,
  });

  return runAutoAdvancePass(advancedTalents, targetXp, {
    kinds: ["skill"],
    respectTalentMaximums: false,
  });
}

function allNatural(npc: NpcAutoAdvanceNpc, targetXp: number): NpcAutoAdvanceNpc {
  return runAutoAdvancePass(npc, targetXp, {
    kinds: ["characteristic"],
    respectTalentMaximums: false,
  });
}

function runAutoAdvancePass(
  npc: NpcAutoAdvanceNpc,
  targetXp: number,
  options: AutoAdvancePassOptions,
): NpcAutoAdvanceNpc {
  const target = Math.max(0, Math.floor(Number.isFinite(targetXp) ? targetXp : 0));
  const advancements = cloneAdvancements(npc.advancements);
  let currentXp = calculateEstimatedNpcXp(advancements).total;

  if (currentXp >= target) {
    return { advancements };
  }

  let advancedInPass = true;

  // This is intentionally a simple round-robin pass over copied rows. It keeps
  // strategy behavior predictable for GMs and lets the Vue layer decide how to
  // apply returned changes to the live Pinia draft.
  while (advancedInPass) {
    advancedInPass = false;

    for (const advancement of advancements) {
      if (!options.kinds.includes(advancement.kind)) {
        continue;
      }

      const nextAdvancement = getNextAdvancement(advancement, options);

      if (!nextAdvancement) {
        continue;
      }

      const xpDelta = calculateAdvancementXp(nextAdvancement) - calculateAdvancementXp(advancement);

      if (xpDelta <= 0 || currentXp + xpDelta > target) {
        continue;
      }

      advancement.current = nextAdvancement.current;
      currentXp += xpDelta;
      advancedInPass = true;
    }
  }

  return { advancements };
}

function getNextAdvancement(
  advancement: NpcAdvancementDraftEntry,
  options: AutoAdvancePassOptions,
): NpcAdvancementDraftEntry | null {
  if (
    options.respectTalentMaximums &&
    advancement.kind === "talent" &&
    !canIncreaseTalent(advancement)
  ) {
    return null;
  }

  return {
    ...advancement,
    current: advancement.current + getAdvancementStep(advancement),
  };
}

function canIncreaseTalent(advancement: NpcAdvancementDraftEntry): boolean {
  const maximum = advancement.talentMaximumValue;

  if (typeof maximum !== "number") {
    return false;
  }

  return getAdvancementTotal(advancement) < maximum;
}

function cloneAdvancements(advancements: NpcAdvancementDraftEntry[]): NpcAdvancementDraftEntry[] {
  return advancements.map((advancement) => ({
    ...advancement,
    sources: advancement.sources.map((source) => ({ ...source })),
  }));
}

registerNpcAutoAdvanceStrategy({
  description: "Cycles visible Skill rows evenly until no next skill increase fits the target XP.",
  id: "skill-master",
  name: "Skill Master",
  run: skillMaster,
});

registerNpcAutoAdvanceStrategy({
  description:
    "Raises visible Talent rows evenly up to known maximums, then spends any remaining XP like Skill Master.",
  id: "gifted-and-talented",
  name: "Gifted & Talented",
  run: giftedAndTalented,
});

registerNpcAutoAdvanceStrategy({
  description:
    "Cycles visible Characteristic rows evenly until no next characteristic increase fits the target XP.",
  id: "all-natural",
  name: "All Natural",
  run: allNatural,
});
