import type { LegacyChargen, SpeciesSelection } from "../../../types/species/chargen";
import { isRecord, readStringArrayPath } from "../../functions/shared/object-readers";
import { readSpeciesItemSystem, SPECIES_ITEM_TYPE } from "../species-item/documents/adapter";
import { readSpeciesEffectSources } from "../species-item/documents/effect-sources";
import { clearChargenConfig, createChargenConfigKey, prepareChargenConfig } from "./config";
import { resolveChargenSpecies } from "./resolve";

export class SpeciesChargenSession {
  readonly key = createChargenConfigKey();
  selection: SpeciesSelection | undefined;
  busy = false;
  closed = false;
  readonly ready: Promise<void>;

  constructor(readonly app: LegacyChargen) {
    this.ready = this.restore();
  }

  assertUnlocked(): void {
    if (this.app.stages.some((stage) => stage.key !== "species" && (stage.app || stage.complete)))
      throw new Error(
        "Species is locked after another stage has started. Start a new character to change species.",
      );
  }

  async select(uuid: string): Promise<void> {
    this.assertUnlocked();
    const selection = await resolveChargenSpecies(uuid);
    if (this.closed) return;
    await prepareChargenConfig(this.key, selection);
    if (this.closed) {
      clearChargenConfig(this.key);
      return;
    }
    this.selection = selection;
  }

  useLegacy(): void {
    this.assertUnlocked();
    this.selection = undefined;
    clearChargenConfig(this.key);
  }

  commit(): void {
    const data = this.app.data;
    if (this.selection) {
      data.customizerSpecies = { ...data.customizerSpecies, selection: this.selection };
      // Legacy chargen reads effect.changes getters, which are absent from v14 raw effect sources.
      data.items["species"] = [new Item(structuredClone(this.selection.source))];
      // Final Actor data must remain readable after this session's temporary config is released.
      data.misc["system.details.species.value"] = this.selection.record.name;
      data.misc["system.details.species.subspecies"] = "";
    } else {
      delete data.customizerSpecies?.selection;
      delete data.items["species"];
      delete data.misc["system.details.species.value"];
      delete data.misc["system.details.species.subspecies"];
    }
  }

  dispose(): void {
    this.closed = true;
    clearChargenConfig(this.key);
  }

  private async restore(): Promise<void> {
    const saved: unknown = this.app.data.customizerSpecies?.selection;
    if (saved === undefined) return;
    if (!isRecord(saved) || typeof saved["uuid"] !== "string" || !isRecord(saved["source"]))
      throw new Error("The saved Species selection is invalid. Start a new character.");
    const source = saved["source"];
    if (source["type"] !== SPECIES_ITEM_TYPE && source["type"] !== "species")
      throw new Error("The saved chargen Item is not a Species Item.");
    const selection: SpeciesSelection = {
      uuid: saved["uuid"],
      source,
      ...(isRecord(saved["identity"])
        ? {
            identity: {
              self: readStringArrayPath(saved["identity"], ["self"]),
              parent: readStringArrayPath(saved["identity"], ["parent"]),
            },
          }
        : {}),
      record: {
        id: saved["uuid"].split(".").at(-1)!,
        uuid: saved["uuid"],
        name: String(source["name"] ?? "Species"),
        img: String(source["img"] ?? ""),
        system: readSpeciesItemSystem(source["system"]),
        effects: readSpeciesEffectSources(source["effects"]),
      },
    };
    await prepareChargenConfig(this.key, selection);
    if (this.closed) return this.dispose();
    this.selection = selection;
    this.app.data.species = this.key;
    this.app.data.subspecies = "";
    this.commit();
  }
}
