import type { EffectBuilderDraft } from "../../../../types/effect-builders";
import { buildWfrpGrantItemsEffect } from "../../../functions/item-grants/wfrp-grant-effect";
import { buildGrantItemsScript } from "../../../functions/item-grants/script";
import { validateEffectFormula } from "./formula-validation";
import { buildChoiceSelectionScript } from "./choice";
import { buildRandomSelectionScript } from "./random";
import { buildAgeHeightEffect, detailFormulaProblems } from "./age-height";
import { buildWoundFormulaEffect } from "./wounds";

export function validateEffectDraft(draft: EffectBuilderDraft): string[] {
  const errors: string[] = [];
  if (!draft.name.trim()) errors.push("Enter an effect name.");
  if (draft.kind === "age-height") return [...errors, ...detailFormulaProblems(draft)];
  if (draft.kind === "wounds") {
    try {
      validateEffectFormula(draft.formula);
    } catch (error) {
      errors.push(error instanceof Error ? error.message : String(error));
    }
    return errors;
  }
  if (
    draft.recipe.lifetime === "linked-to-effect" &&
    draft.recipe.ownerAction === "delete-after-grant"
  )
    errors.push(
      "Self-removing source Items must grant copies that remain after the effect is removed.",
    );
  if (draft.kind === "grant" && !draft.items.length) errors.push("Add at least one Item to grant.");
  if (draft.kind === "random" && !draft.table) errors.push("Choose a RollTable.");
  if (
    (draft.kind === "random" || draft.kind === "choice") &&
    (!Number.isInteger(draft.count) || draft.count < 1 || draft.count > 100)
  )
    errors.push("Enter a whole number from 1 to 100.");
  if (draft.kind === "choice") {
    if (
      !draft.groups.length ||
      draft.groups.some((group) => !group.name.trim() || !group.items.length)
    )
      errors.push("Each choice needs a name and at least one Item.");
    if (draft.count > draft.groups.length)
      errors.push("The number of choices exceeds the available options.");
  }
  return errors;
}

export function buildEffectSource(
  draft: EffectBuilderDraft,
  flagScope: string,
): Record<string, unknown> {
  const errors = validateEffectDraft(draft);
  if (errors.length) throw new Error(errors.join(" "));
  const name = draft.name.trim();
  if (draft.kind === "age-height") return buildAgeHeightEffect(draft);
  if (draft.kind === "wounds") return buildWoundFormulaEffect(name, draft.formula);
  const source = buildWfrpGrantItemsEffect({
    effectName: name,
    flagScope,
    items: draft.items,
    recipe: draft.recipe,
  });
  if (draft.kind === "grant") return source;
  const selection =
    draft.kind === "random"
      ? buildRandomSelectionScript(draft.table!.uuid, draft.count)
      : buildChoiceSelectionScript(name, draft.groups, draft.count);
  return {
    ...source,
    description:
      draft.kind === "random"
        ? "<p>Grants Items rolled from a RollTable.</p>"
        : "<p>Grants the chosen Item options.</p>",
    flags: {},
    system: {
      transferData: { documentType: "Item", type: "document" },
      scriptData: [
        {
          label: name,
          trigger: "addItems",
          script: buildGrantItemsScript(selection, draft.recipe),
        },
      ],
    },
  };
}
