import type { SpeciesItemSystem } from "../../../types/species/item";

/** WFRP's starting profile convention treats each d10 as 5 (2d10 becomes 10). */
export function speciesStartingProfile(system: SpeciesItemSystem): Record<string, number> {
  const update: Record<string, number> = {};
  for (const [key, value] of Object.entries(system.characteristics)) {
    if (value.base !== null && value.dice !== null)
      update[`system.characteristics.${key}.initial`] = value.base + value.dice * 5;
  }
  if (system.movement !== null) update["system.details.move.value"] = system.movement;
  return update;
}

/** Preserve a customized profile, as native Randomize does, using this Species' dice. */
export function speciesRandomizationFormulas(
  system: SpeciesItemSystem,
  initial: Record<string, number>,
): Record<string, string> {
  const entries = Object.entries(system.characteristics).filter(
    ([key, value]) => key in initial && value.base !== null && value.dice !== null,
  );
  const average = speciesStartingProfile(system);
  const isStartingProfile = entries.every(
    ([key]) => initial[key] === average[`system.characteristics.${key}.initial`],
  );
  const formulas: Record<string, string> = {};
  for (const [key, value] of entries) {
    if (!(key in initial) || (!isStartingProfile && initial[key] === 0)) continue;
    const dice = value.dice!;
    const roll = dice === 0 ? "0" : `${dice}d10`;
    const field = isStartingProfile ? "initial" : "modifier";
    formulas[`system.characteristics.${key}.${field}`] = isStartingProfile
      ? `${roll}+${value.base}`
      : `${roll}-${dice * 5}`;
  }
  return formulas;
}
