<script setup lang="ts">
import type { NpcPortraitCandidate } from "../../../../../../types/npc-builder";
import type {
  NpcPortraitFilterSection,
  NpcPortraitFilterTag,
} from "../../../../../../types/npc-builder";

import NpcBuilderDialog from "../NpcBuilderDialog.vue";
import PortraitGallery from "../../../../shared/view/components/portrait-gallery/PortraitGallery.vue";

defineProps<{
  isLoadingPortraitCandidates: boolean;
  open: boolean;
  portraitCandidates: NpcPortraitCandidate[];
  portraitFilterTags: NpcPortraitFilterTag[];
  portraitSearchProgressLabel: string;
  portraitSearchProgressValue: number;
  portraitSearchTerms: string[];
  selectedPortraitCandidateKey: string;
}>();

const emit = defineEmits<{
  close: [];
  createSearchTerm: [value: string];
  filterTagSectionChange: [tag: NpcPortraitFilterTag, section: NpcPortraitFilterSection];
  selectPortrait: [candidate: NpcPortraitCandidate];
}>();
</script>

<template>
  <NpcBuilderDialog
    close-label="Done"
    :open="open"
    title="Choose an NPC Portrait"
    wide
    @close="emit('close')"
  >
    <PortraitGallery
      empty-message="No portraits are available yet. Choose a base Actor or queue a Career to start the search."
      :is-loading="isLoadingPortraitCandidates"
      :options="portraitCandidates"
      :progress-label="portraitSearchProgressLabel"
      :progress-value="portraitSearchProgressValue"
      :search-terms="portraitSearchTerms"
      :selected-option-key="selectedPortraitCandidateKey"
      :tags="portraitFilterTags"
      @create-search-term="emit('createSearchTerm', $event)"
      @filter-tag-section-change="(tag, section) => emit('filterTagSectionChange', tag, section)"
      @select-portrait="emit('selectPortrait', $event)"
    />
  </NpcBuilderDialog>
</template>
