import { isRecord } from "../../functions/shared/object-readers";
import {
  configuredSpeciesTable,
  inspectConfiguredSpeciesTable,
  speciesDocumentUuid,
} from "./table-policy";

export async function currentSpeciesChoices(): Promise<Record<string, string>> {
  return (await inspectConfiguredSpeciesTable()).choices;
}

export const itemUuidFromResult = speciesDocumentUuid;

export async function rollSpeciesTable(): Promise<Record<string, unknown>> {
  const table = configuredSpeciesTable();
  const state = await inspectConfiguredSpeciesTable();
  if (!state.valid) throw new Error(state.reason);
  // An async lookup must not approve a different table selected in the meantime.
  if (configuredSpeciesTable() !== table) throw new Error("The Species table changed. Try again.");
  const tables = game.wfrp4e?.tables;
  if (!tables?.rollTable) throw new Error("WFRP Species table rolling is unavailable.");
  const result = await tables.rollTable("species");
  if (!isRecord(result) || !isRecord(result["object"]))
    throw new Error("The Species table did not return a result.");
  const uuid = speciesDocumentUuid(result["object"]);
  if (!uuid || !state.choices[`item:${uuid}`])
    throw new Error("The rolled result is not one of the table's Species Items.");
  return result;
}
