import type { SpeciesItemSystem, SpeciesTalentChoiceNode } from "../../../types/species/item";
import type { SpeciesTalentGrant } from "../../../types/species/index";

import { formatLinkedItemName } from "./reference-names";

export function encodeTalentChoices(
  grants: SpeciesTalentGrant[],
): SpeciesItemSystem["talents"]["choices"] {
  const options: SpeciesItemSystem["talents"]["choices"]["options"] = [];
  const groups = grants.map((grant, group) => {
    const children = grant.choices.map((choice, index): SpeciesTalentChoiceNode => {
      const id = `talent-${group}-${index}`;
      options.push({
        id,
        name: formatLinkedItemName(choice),
        type: choice.item ? "item" : "placeholder",
        idType: choice.item ? "uuid" : "",
        documentId: choice.item?.uuid ?? "",
        diff: {},
        filters: [],
      });
      return { id, type: "option" };
    });
    return children.length === 1
      ? children[0]!
      : { id: `group-${group}`, type: "or" as const, options: children };
  });
  return { structure: { id: "root", type: "and", options: groups }, options, script: "" };
}

export function decodeTalentChoices(
  choices: SpeciesItemSystem["talents"]["choices"],
): SpeciesTalentGrant[] {
  if (choices.script.trim()) {
    throw new Error("Scripted Talent choices cannot be represented by legacy species config.");
  }
  const options = new Map(choices.options.map((option) => [option.id, option]));
  function visit(node: SpeciesTalentChoiceNode): SpeciesTalentGrant[] {
    if (node.type === "option") {
      const option = options.get(node.id);
      if (!option || !["item", "placeholder"].includes(option.type) || !option.name.trim()) {
        throw new Error(
          "Species Talent choices must refer to named Talents; filters and effects need chargen v2.",
        );
      }
      if (Object.keys(option.diff).length || option.filters.length) {
        throw new Error("Modified or filtered Talent choice documents require native chargen v2.");
      }
      const item =
        option.idType === "uuid" && option.documentId
          ? { name: option.name, uuid: option.documentId, type: "talent" as const }
          : undefined;
      return [{ choices: [{ name: option.name, ...(item ? { item } : {}) }] }];
    }
    const children = node.options ?? [];
    if (node.type === "and") return children.flatMap(visit);
    const alternatives = children.map(visit);
    if (alternatives.some((grants) => grants.length !== 1)) {
      throw new Error(
        "A choice between groups of Talents needs chargen v2 and cannot become a legacy either/or grant.",
      );
    }
    return alternatives.length
      ? [{ choices: alternatives.flatMap((grants) => grants[0]!.choices) }]
      : [];
  }
  return visit(choices.structure);
}
